window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_006"]={"n":"刘崧","dyn":"明","poems":[{"t":"再别同夫三首 其二","f":"七言绝句","c":["朝阳斋前桃李树，手栽清荫接比邻。","明年此地看花发，愁向东风忆故人。"]},{"t":"谩题","f":"七言绝句","c":["四郭青山处处同，客怀无计答秋风。","数家茅屋清溪上，千树蝉声落日中。"]},{"t":"题稚川山水","f":"七言绝句","c":["松下茆亭五月凉，汀沙云树晚苍苍。","行人无限秋风思，隔水青山似故乡。"]},{"t":"赠鹤林上人","f":"七言绝句","c":["日日涧边寻茯苓，岩扉长掩凤山青。","归来挂衲高林下，自剪芭蕉写佛经。"]},{"t":"寄万德躬","f":"七言律诗","c":["日暮山风吹女萝，故人舟楫定如何。","吕仙祠下寒砧急，帝子阁前秋水多。","闽海风尘鸣戍鼓，江湖烟雨暗渔蓑。","何时醉把黄花酒，听尔南征长短歌。"]},{"t":"寄范实夫","f":"七言律诗","c":["细雨柴门生远愁，向来诗帙若为酬。","林花落处频中酒，海燕飞时独倚楼。","北郭晚晴山更远，南塘春尽水争流。","可能相别还相忆，莫遣杨花笑白头。"]},{"t":"寄旷伯逵二首 其一","f":"七言律诗","c":["谢相园西石径斜，知君习隐暂为家。","有时出郭行芳草，长日临池看落花。","春去能忘诗共赋，客来应是酒频赊。","五年不见西山色，怅望浮云隐落霞。"]},{"t":"寄旷伯逵二首 其二","f":"七言律诗","c":["乱馀城郭怕经过，到处閒门长薜萝。","用世空悲闻道浅，入山偏喜识僧多。","醉归花径云生屐，樵罢松岩雪满蓑。","石上幽期春又暮，何时载酒听高歌。"]},{"t":"晚望","f":"五言律诗","c":["山气碧氤氲，深林带夕曛。","人归孤嶂晚，犬吠隔溪云。","杉竹何年种，烟尘此地分。","桃源宁异此，犹恐世人闻。"]},{"t":"赠徐山人","f":"七言律诗","c":["乱馀山水半凋残，江上逢君春正阑。","斗自指南天杳杳，星犹拱北夜漫漫。","汉陵帝子黄金盌，晋代神仙白玉棺。","回首风尘千里别，故园烟雨五峰寒。"]},{"t":"言志赠友人","f":"古风","c":["深山邃谷，虎豹所凭。","玄雾翳云，蛟龙斯升。","芸芸暮蜉，缉缉秋蝇。","嘅彼下士，志何由兴。","岁年云徂，冰雪侵凌。","眷彼皓首，含涕抚膺。","契予夙好，嘉尔友朋。","亦有旨酒，如溜如渑。","可以乐衎，高融咸登。","仰睇白日，翩其相仍。","道谊罔敦，忧患式增。","不曰尼父，饮水曲肱。","媚货附桓，圣人不能。","我行东原，以陟崚嶒。","言采荣木，手挽其藤。","素秋以风，霜露乃凝。","黄鹄斯举，天高气澄。","送子于迈，服子徽称。","理棹河湄，赪霞晨蒸。","何以益我，敦教而承。","友道之薄，噫其春冰。","尔弘其居，夕惕兢兢。","人亦有言，谷增而陵。","圣途云遐，气力曷胜。","勖尔踯躅，暨于鶱腾。"]},{"t":"题唐子华江居平远图","f":"古风","c":["宛其长洲，在彼中流。","上列灌木，旁引高丘。","彼君子居，于林之右。","言敞东轩，缅觌平岫。","盘石在渚，丛荫在门。","有风夏凉，维日冬温。","岂无方舟，可以游钓。","言曳其杖，于焉遐眺。","油油行云，靡靡逝波。","岁既晏矣，云如之何。","鸟鸣于谷，鱼丽于罶。","君子之居，君子之友。"]},{"t":"题宁都州学图","f":"古风","c":["出自西门，至于泮宫。","我游伊何，以观民风。","乃觏新殿，翼翼崇崇。","伊谁修之，维郑之功。","郑其戾止，弁巾俅俅。","爰率童冠，以咏以游。","属兹暮春，言眺中州。","慷当以歌，企彼前修。","何以乐此，薄写我心。","濯缨于泉，援琴于林。","求我良友，言陟云岑。","苒苒云木，交交鸣禽。","山则有石，川则有波。","君子维教，乃切乃磋。","翩其白驹，越于涧阿。","逝将去此，忧如之何。","日月于迈，山川逶迤。","怀君之来，方何为期。","爰绘于图，亦颂以诗。","归言观之，式慰尔思。"]},{"t":"题兰 其一","f":"古风","c":["山则有石，谷则有兰。","我思美人，兹之永叹。"]},{"t":"题兰 其二","f":"古风","c":["奕奕翠羽，翘翘紫蕤。","何以求之，山阿水涯。"]},{"t":"题兰 其三","f":"古风","c":["回风猗猗，白石皓皓。","山中无人，念此芳草。"]},{"t":"题兰 其四","f":"古风","c":["深林之幽，式闻其香。","安得佩之，蓉裾芰裳。"]},{"t":"书带轩诗为郑同夫赋","f":"古风","c":["读书何所，西山之阳。","崇轩朝跻，其云苍苍。","有草有草，垂带而厉。","匪伊垂之，君子所萟。","濯以甘雨，扬之谷风。","有蔚其苗，则靡所同。","人亦有言，匪韭匪薤。","不有君子，孰曰书带。","在昔孔圣，仰钻庖羲。","或韦其编，亦三绝之。","我乐我书，爰启其纽。","我其藏之，或系于肘。","相彼良苗，亦绵其藨。","譬之树兰，毋混彼艾萧。","我思不其，远而莫至。","宜尔孙子，是有是似。","尚勿剪薙之，以蕃厥世。"]},{"t":"七噫歌","f":"古风","c":["陟彼高丘，言望新城。","烟焰勃烈，金铁锵鸣噫。","豺虎狉狉，啖人肝脑。","阴风薄云，僵尸横道噫。","彼奔曷从，楫人相仇。","牵衣蹈河，骨肉漂流噫。","负载橐囊，牛羊交驰。","号哭振野，俘系累累噫。","孰繁生息，而玩厥虞。","城垒葺矣，而无人乎噫。","曰予有弟，孰往讯旃。","河不可冯，泪下如泉噫。","白日下照，幽幽其光。","孰诉上天，尔民卒痒噫。"]},{"t":"尚友斋为旷伯逵赋","f":"楚辞体","c":["繄予之生，乃后古人。","岂不尚友，远而莫因。","譬彼方夜，思见出日。","狂走大呼，秪益其疾。","及求吾心，夫岂远而。","昼读其书，夜梦见之。","我疑其生，世谓其死。","不曰斯今，亦有君子。","有鸟有鸟，鸣于高林。","彼君子兮，怀之好音。","视彼日月，滔滔其迈。","人而离居，曷云不戒。","闻子今日，涉江远来。","何以来思，赠之琼瑰。","穆穆其风，菀菀者柳。","何以永日，且以酌酒。","汎汎中流，招之以舟。","一日不见，余心则忧。","居则同襺，出则更屧。","云胡拒之，彼则有挟。","我友旷逵，友道则隆。","维彼所尚，实获我同。","蓬依于麻，禾乱于莠。","嗟尔君子，式尚尔友。"]},{"t":"观刘将军祃旗诗","f":"古风","c":["辛卯秋孟，吉维己酉。","藩使来筠，以饬我纠。","曰命尔枢，往禦群丑。","惟此群丑，善良是雠。","于彼南恩，于此新州。","?出蜮没，群嚣以咻。","将军承命，陈鞠我旅。","阅籍点行，颁令齐伍。","荷戈百千，来集如雨。","谷旦之祃，庚戌令辰。","赤日载熻，我服具陈。","拥旃设次，坛壝则神。","有畟者戈，氂毛蓬蓬。","缭以绵蕝，屹其在中。","兵刃旁合，杂沓其锋。","将军升坛，笳鼓三奏。","尔士尔卒，孰或敢后。","肥牲大樽，工祝在侑。","指撝六丁，呼召五方。","灵风飒然，我旆载扬。","杀气成云，荫于中央。","斩鸡磔牲，沥酒以血。","将军灌彻，大啖雄啜。","观者怆恻，行者忭悦。","我兵我旂，出于南门。","长刀在佩，雕弓在鞬。","群马振鸣，尘埃昼昏。","将军从容，衣不重甲。","顾盼流威，匪玩匪狎。","我勇方张，尔燕则洽。","于赫将军，幽并之豪。","世镇南土，服于弓刀。","岂恫而逸，惟贤斯劳。","昔戍封州，昔征漳境。","先登破围，枭黠受领。","藐焉西寇，曾足以骋。","何山无石，何海不波。","山高海深，我行如何。","蛮方既同，曷其还歌。","北瞻淮河，徭役棼泯。","嗟嗟海隅，乃试其蠢。","肆而殄之，天子所悯。","天子所悯，四方底绥。","将军秉虔，是究是思。","策勋有奇，视此颂诗。"]},{"t":"题画鱼四章","f":"古风","c":["我观于河，其鱼维鲭。","岂有泼泼，而困于笭。","我观于河，其鱼维鲌。","水深月寒，闻其瀺泎。","我观于河，其鱼维鳜。","群鲜则微，孰饮尔噬。","我观于河，其鱼维鲤。","雷雨斯作，一举万里。"]},{"t":"题九鸶图","f":"古风","c":["振振者鹭，在渚之薮。","我仪图之，其丽维九。","顾盼和鸣，八跱一飞。","昂首跂足，觊其具依。","彼飞而旋，亦念群处。","清风载飏，濯濯其羽。","乃㒽渚曲，维石巉㟽。","上延松梅，下翳丛筱。","爰得其所，游咏一方。","或群而飞，盖未可量。","嘉尔君子，洁白无二。","可仪于朝，亦簉于位。","嗟嗟百鸷，不如一鹗。","式咏振振，以继舞籥。"]},{"t":"南门司柝诗赠玉珊克温","f":"古风","c":["鸣柝何所，南门之下。","孰其司之，肃肃有仪。","出日自东，我柝既閒。","行道憧憧，我辟我关。","日之既夕，行道涤涤。","我时其闭，我柝载击。","柝声扬扬，万夫之防。","一息弗戒，予职之荒。","相彼高车，其禄有馀。","虑殚力劬，忧患是居。","我司我柝，是力是度。","贫卑之居，君子之乐。","古之抱关，亦有晨门。","勿果忘哉，敬尔司存。"]},{"t":"观澜","f":"古风","c":["子曷观乎，维水有澜。","其澜伊何，厥观实难。","我观河江，其量弗殚。","积石岷峨，本钜力完。","万折千支，潗湁瀰漫。","激为大波，溁为文湍。","其来无穷，其回无端。","既来既回，齐并汨攒。","如车之旋，如风之抟。","浩乎沛而，莫之或干。","相彼断港，潢污所敦。","漂浮几何，忽焉中乾。","有斐汤君，维学是安。","作亭浠厓，物无遁观。","临渊者危，望洋者叹。","卓彼孟轲，是仰是钻。","我诗于楹，永以弗刊。"]},{"t":"墨龙赞为萧时卿赋","f":"古风","c":["跃于墨池，见其鬣鬐。","雷动云从，而时雨之。"]},{"t":"比丘观音赞","f":"古风","c":["补陀如如，人天具瞻。","现真实相，不假庄严。","如莲得水，灌溉滋悦。","如水注瓶，表里洞彻。","光弥觉海，香满旃檀。","得大自在，作如是观。"]},{"t":"题镜面二水图","f":"古风","c":["此二水者，实本一源。","或翔而潮，或激而湍。","海阔风高，云蒸雾抟。","混然同归，庶无异观。"]},{"t":"题山云居图为樊都事仲郛赋","f":"楚辞体","c":["我居何所，南山之下。","油油者云，窈窈其阻。","衡门在阿，翳彼嘉林。","上有鸣鸟，怀之好音。","良晨载兴，游睇川沚。","榛蹊邈绵，有客戾止。","琴瑟在庭，清樽载罗。","扫地布席，援弦咏歌。","我歌我酬，白云在谷。","聊可为娱，孰云不足。","云之升矣，风或飏之。","曾于是处，而忘世为。","凄其渰矣，雨亦濡只。","群生烝烝，泽施曷已。","云敛而舒，山高以深。","彼君子兮，悠悠我心。"]},{"t":"门有车马客","f":"五言古诗","c":["门有车马客，光彩一何都。","谓从天上来，意气倾万夫。","银鞍耀流星，丹毂夹华月。","白马骄且驰，浮云递明灭。","鸣鞘赴咸阳，执戟趋承明。","二十事征战，三十成功名。","出护塞上军，入典禁中直。","五侯与七贵，调笑同出入。","相如早还蜀，季子终相秦。","如何衡门士，抱膝长苦辛。"]},{"t":"结客少年场","f":"古风","c":["结客少年场，少年本同调。","肝胆各自悬，持之以相照。","我有百鍊剑，五花骢，不敢自爱惜，拔剑赠马期相从。","憧憧车马都门道，花发鸟啼风日好。","颜朱鬓绿艳青春，第一成名须在早。","铜盘登坛歃血时，白日青天闻苦词。","男儿赌命报知己，莫遣衰老徒伤悲。","手持一尊酒，自唱马上歌。","目光棱棱发上指，年少无成将奈何。"]},{"t":"将进酒","f":"七言古诗","c":["高堂帟帐围暖烟，繁弦急管喧两筵。","主人敬客奉觞酒，再拜客前百千寿。","玻瓈鸭绿鹅乳黄，紫檀夜压松花香。","吴姬窈窕解歌舞，眉黛娇春凝煖光。","古来豪杰重然诺，意气相倾等山岳。","腰间自有双吴钩，换酒醉君君莫愁。"]},{"t":"芳树篇","f":"五言律诗","c":["芳树好容华，深深映狭斜。","二月三月时，千枝万枝花。","夜舞留琼佩，春游碍宝车。","折荣贻远者，含思独咨嗟。"]},{"t":"少年行","f":"五言律诗","c":["乍出建章宫，还过酒肆中。","听歌留宝剑，数雁试雕弓。","烟草一片绿，风花千点红。","马骄嘶不住，直骤渭城东。"]},{"t":"东方行","f":"七言绝句","c":["东方闪闪啼早鸦，美人愁眠隔窗纱。","桐叶树下人来往，银床辘轳梦中响。"]},{"t":"凤笙曲","f":"古风","c":["洪水荡八极，丹霞标五城。","仙人从东来，邀我吹凤笙。","凤凰双飞锦翼明，三十六管排峥嵘。","长风卷入碧云里，仙仗忽拥千霓旌。","六龙骋驾若木晴，仙乐沓奏天中京。","双成起舞韩众听，此曲似是升天行。","天门窈窕九陛平，闻有云雾雷鼓相砰鍧。","手招仙人驭奇气，乃是山中龙虎精。","张公鍊丹金液成，洞门石室馀秋声。","云中仙驾如可待，愿逐卢敖游太清。"]},{"t":"照镜曲","f":"七言古诗","c":["蟠螭双衔锦带红，妆台刻玉秋玲珑。","綵云忽开紫鸾舞，明月夜堕香奁中。","美人妆罢房栊香，鹦鹉呼寒帐中晓。","拍簇花迎笑靥开，低飞黛绿秋娥小。","满庭桃李各娇春，顾影含羞便恼人。","愁来独掩云屏宿，手持宝钗扣寒玉。","吴锦蜀粉暗消磨，泪满菱花奈别何。","不知昨夜愁深浅，但觉朝来华发多。"]},{"t":"空城雀 其一","f":"古风","c":["空城雀，鸣且飞，一朝驱入罗网去，云天有路何时归。"]},{"t":"空城雀 其二","f":"古风","c":["空城雀，飞且止，林栖有匹巢有子，分飞不知后生死。"]},{"t":"空城雀 其三","f":"古风","c":["空城雀，遭网罗，塌翼垂头憔悴多，不能高飞将奈何。"]},{"t":"古离别","f":"古风","c":["天苍苍，地靡靡，东西相距几万里。","日月来往朝夕间，游子一去何当还。","罗衣血泪红斑斑，芳尘掩镜愁朱颜。","昔时送别长安道，几见春风荡芳草。","金鞍锦鞯不可期，紫燕黄鹂坐中老。","知君自有心，贱妾空自怜。","一束锦字书，何能到君边。","海中珊瑚泥底藕，不见青天终不朽。"]},{"t":"漂母吟","f":"古风","c":["蛟龙失云雨，或与虾蟹俦。","壮士偶穷困，寄食何足羞。","淮河之水东北流，母心直为王孙忧。","黄金无光剑失色，白日又落城西头。","请君置鱼竿，进此盘中脯。","丈夫性命未可轻，君独胡为在尘土。","咸阳王气如云驰，垄上亦有呼兵儿。","风尘满眼慎所之，但愿王孙无饥时。"]},{"t":"江南弄","f":"七言律诗","c":["江浦晴云作水流，鸳鸯哺雏花满头。","沙堤十里寒溘溘，湘娥踏浆摇春愁。","菖蒲叶齐宝刀绿，佩鱼双剪琪花玉。","酸风吹雨不见人，一夜啼痕绣丛竹。"]},{"t":"姑苏曲","f":"七言古诗","c":["姑苏城头乌夜啼，姑苏台上风凄凄。","芙蓉露冷秋香死，美人夜泣双蛾低。","铜龙咽寒更漏促，手拨繁弦转红玉。","鸳鸯飞去屧廊空，犹唱吴宫旧时曲。","吴山青青吴殿荒，麋鹿来游春草长。","阖闾门户东风起，年年花落愁西子。"]},{"t":"鸳鸯吟","f":"古风","c":["鸳鸯尔何来，荡漾野塘水。","塘水污不流，双双乃自止。","云霞下照青黛光，弄影宛在塘中央，惜尔锦翼多文章。","翩翩游侠儿，款款治罗罬。","驱之向南飞，意欲投所设。","成汤昔好德，三面或解之。","尔独不用命，咫尺罹艰危。","洞庭潇湘，春风绿波。","芳草可哺，芙蓉可窠。","饮啄失所，吾将奈何。"]},{"t":"伤举郎词","f":"楚辞体","c":["有侄有侄兮出幼齿，筋骨充紧兮目光如水。","重城忽隳兮风尘起，掠尔家兮驱尔以徙。","短戈挥兮白刃指，母不得将兮父不得子。","拦道长号兮衣载褫，山路夜行兮泥没其趾。","汝书在床兮庭有遗履，汝归何时兮而拘于彼。","月光明明兮在地，鸿鹄之飞可以乘汝兮，盍归来兮故里。"]},{"t":"乌鸢叹","f":"古风","c":["乳鸭戏水中，三三五五群相聚。","乌鸢从东来，瞥然攫向空中去。","我无劲箭射飞鸢，仰视青天还自怜。"]},{"t":"白练带词","f":"古风","c":["白练带，长且美，飞来青树颠，宛转修竹里。","南园日暮无人来，一双下饮寒塘水。"]},{"t":"秋夜词","f":"古风","c":["林乌夜啼金井西，蟋蟀在户声相齐。","中天无云白露下，渐见梧桐青叶低。","幽闺此时愁独晓，兰灯双照蛾眉小。","歌声恐逐回风高，掩抑冰弦破清悄。","弦中语语心自伤，低头却看明月光。","罗衣一夜惜颜色，庭草明日沾秋霜。","甘心霜下草，秪在阶庭好。","不作白杨花，飞飞洛阳道。"]},{"t":"紫骝马","f":"古风","c":["郎骑紫骝马，来向门前下。","马尾捎赤云，银鞍色相射。","愿郎骑马去复来，珊瑚作鞭丝结??。","纵令远去玉关外，千里应须一日回。"]},{"t":"爱妾换马","f":"五言古诗","c":["请以白玉质，换君青云骢。","岂不重颜色，所悲道路穷。","朝驰月窟西，夕憩昆崙东。","一去关塞远，宁惜闺帷空。","美人闻马嘶，含涕出房栊。","爱移丈夫性，德称惭冶容。","素丝妾所理，薄奉羁与笼。","愿因承光景，流盼鞍辔中。","君行倘未已，千里仍相从。"]},{"t":"长相思","f":"古风","c":["长相思，乃在青天之外，碧海之湄。","我欲见之望不极，侧身太息涕涟洏。","昔与君别者，驱车临路岐。","车尘向南起，回风吹灭之。","君行遥遥，邈不可持。","含悲蓄愤，郁其累累。","瞻彼出月，弦望有时。","乃靡朝夕，如渴如饥。","落叶飘飖宁返枝，东流之水无还期。","重华一去万里绝，湘江秋竹何离离。","宁为懊恼曲，莫奏长相思。","思长意远君不知，妾心所陈多苦辞。"]},{"t":"荷叶黄","f":"古风","c":["荷叶黄，荷叶青，四月五月风日清。","荷叶青，荷叶黄，八月九月秋风凉。","越湖女儿颜似玉，隔船窥郎心眼熟。","赤尾鲤鱼花下游，白头鸳鸯露中宿。","欢会苦乖绝，岁月同飞杨。","王母不西游，蛾眉刷秋霜。","少年之乐乐未央，莫遣老大徒悲伤。","独不见，荷叶黄。"]},{"t":"乌夜啼赠友人别","f":"七言古诗","c":["华灯张筵促弦急，隔帘霜落风吹入。","琴中弹得乌夜啼，啼声夜寒高复低。","林乌何来飞拨剌，夜半哑哑声不歇。","姑苏城上拂黄云，铜雀枝边绕明月。","月行渐远声渐稀，扬彩各自东西飞。","东边日中有伴侣，看汝飞鸣日边去。"]},{"t":"祝船词","f":"七言古诗","c":["岸头击鼓人聚蚁，吉日挽船下江水。","新船龙行气势雄，头抢入水尾插空。","篙师跪拜祝船圣，牲纸前陈启神听。","沿江灵庙八十四，闻请齐来共欢庆。","五湖四海道路通，蛟蛇不逢无恶风。","大石低头小石卧，吕梁滟滪轻轻过。","吴粳蜀麻淮海鹾，大商满载黄金多。","年年早归谢神福，酒浇船头赛羊肉。"]},{"t":"春日出郊和杨公荣","f":"五言古诗","c":["閒居惜阳丽，延睇川原平。","忧端不自理，浊虑何由澄。","怡怡惠风畅，杲杲旭日明。","长怀杕杜叹，永眷伐木情。","顾影褰我裳，沈唫抚我楹。","林暄好鸟和，日暮浮云生。","蚤伤离索居，矧复世患婴。","素心在远道，何以遗芳馨。","侧闻集群彦，近作南郊行。","摅怀属觚翰，结欢逾弟兄。","委佩鸣双珰，轻裘粲三英。","意气重许与，片言山岳倾。","蹇独苦局促，不得聆清评。","宁逐车底尘，不随水中萍。","末途及攀援，终焉策华名。","弃繻去吴楚，驱马迈幽并。","所渝同心者，视此白水盟。"]},{"t":"古诗五章奉寄徐南卿邹致和二贤良五首 其一","f":"五言古诗","c":["凉风吹庭树，摵摵鸣未已。","中宵起彷徨，所思在君子。","君子昔言别，二月柳始青。","柳今成枯枝，白露泫以零。","合并良独难，日月行当晚。","自非木石心，谁得不怀远。"]},{"t":"古诗五章奉寄徐南卿邹致和二贤良五首 其二","f":"五言古诗","c":["携书出重门，拟寄南飞翼。","书中有深情，不道长相忆。","相忆不相见，思攀芳桂枝。","人言道路远，持此将安之。","岂无清夜梦，东渡章江水。","水深愁复迷，一夕思千里。"]},{"t":"古诗五章奉寄徐南卿邹致和二贤良五首 其三","f":"五言古诗","c":["江干秋气高，木落帝子渚。","永怀群彦集，清景契晤语。","山南与山北，乐子岂无所。","浮云日暮合，羌独久延伫。","翩翩双黄鹄，千里奋一举。","勿以遐我心，而多惮修阻。"]},{"t":"古诗五章奉寄徐南卿邹致和二贤良五首 其四","f":"五言古诗","c":["长林何逶迤，下荫清溪流。","芳苕戴坠露，黄鸟复鸣秋。","远色正苍苍，众木一何稠。","星垂水面白，云落岩口幽。","思得良友晤，可以汎方舟。"]},{"t":"古诗五章奉寄徐南卿邹致和二贤良五首 其五","f":"五言古诗","c":["峦峦山阴竹，结根广庭阿。","密雪掩茂叶，微风振纤柯。","秀色正周列，繁阴亦旁罗。","君子抱幽素，终然葆真和。","荧荧涧底花，靡靡园中莎。","及时讵不荣，晏岁当如何。"]},{"t":"陪郑同夫唐寅亮诸同志会饮管氏山亭分韵得出字","f":"五言古诗","c":["涉溪谒林祠，春日戒维吉。","閒情既怡荡，尘虑忽已失。","当筵揖群彦，玉雪动昭质。","登高属能赋，临水思散帙。","芳亭稍登宴，清醥屡浮溢。","幽怀契绸缪，玄论入靓密。","碧筱连深池，朱华耀初日。","川原何逶迤，山水亦荡潏。","仙游匪无悰，雅咏当有述。","泠泠风南至，皎皎月东出。","言志适所存，吾其舍鸣瑟。"]},{"t":"步虚拟词赠紫阳萧炼师","f":"五言古诗","c":["璿宫霁景澄，彤墀绿云上。","星联黄姑渚，露下仙人掌。","金文乍葳蕤，羽翿亦森爽。","翠林闪霞光，丹壑流清响。","□观群动根，大化何漭漭。","飞步凌紫清，玄幽契遐想。"]},{"t":"述怀八首奉柬白景和 其一","f":"五言古诗","c":["隆暑夏方炽，赤曦煽炎烟。","六街流景中，车马驱不前。","引睇西北隅，烦冲抱悁悁。","濯足沧海流，散发昆崙巅。","岂无琼树荫，思尔风泠然。"]},{"t":"述怀八首奉柬白景和 其二","f":"五言古诗","c":["穆穆羽人馆，肃肃君子居。","清风东南至，层构邃且虚。","左陈樽与壶，右列图与书。","燕休而翱游，其乐恒有馀。","乃知习静者，乘化本自如。"]},{"t":"述怀八首奉柬白景和 其三","f":"五言古诗","c":["闻君昔游宦，四牡戒南骋。","凌深陟庐阜，历险薄炎岭。","才名时共推，刚毅夙所秉。","竟辞金陵幕，旋理潇湘艇。","却卧山云深，清歌动吴郢。"]},{"t":"述怀八首奉柬白景和 其四","f":"五言古诗","c":["美人出南国，皎若琼树枝。","云日丽春服，光彩不可持。","粲粲白玉齿，宛宛青娥眉。","含情盼天末，独立以遐思。","当歌复不发，听者今为谁。"]},{"t":"述怀八首奉柬白景和 其五","f":"五言古诗","c":["汎舟越江湖，晤言属良友。","朝辞凤台侧，夕憩锦江口。","思采蒲与荷，游咏乐且久。","芳华隔秋浦，零悴复何有。","怀哉托绸缪，结佩以琼玖。"]},{"t":"述怀八首奉柬白景和 其六","f":"五言古诗","c":["琴瑟有正音，自异淫与哇。","高张弦易绝，低促声苦乖。","敢伤知者寡，自愧鲜所谐。","泠泠涧中泉，窈窈云际厓。","誓将千古意，托在君子怀。"]},{"t":"述怀八首奉柬白景和 其七","f":"五言古诗","c":["微生寡所资，素食在贫贱。","枯如枝上蜩，飘若梁间燕。","长缨非固违，短褐岂终恋。","荣名难强致，华采羞自衒。","独处衡门幽，悲歌泪如霰。"]},{"t":"述怀八首奉柬白景和 其八","f":"五言古诗","c":["鸿鹄乘天风，摇荡日已远。","声沈兰渚烟，影绝浮云巘。","高河入夕迥，列宿光烜烜。","岂不顾其群，前飞屡回转。","凄其霜露积，恻怆岁年晚。"]},{"t":"会饮曾氏西轩","f":"五言古诗","c":["莲塘水濊濊，凉气秋始旦。","西轩集朋俦，游咏日已半。","当阶缘碧藓，前垣出苍簳。","列席粲有华，飞觞急无算。","缅焉思远人，振筴方弭乱。","笳鼓横清江，烟尘翳南岸。","感之念时理，短曲不成按。","中心忽如醉，沈唫睇遥汉。","自非桃源邃，何以永乐衎。","穷居且终日，黾勉增慨叹。"]},{"t":"次王子启夜坐怀旷伯逵","f":"五言律诗","c":["褰帷惜良夜，起坐临清池。","窈窕月奁合，逶迤云佩垂。","虫响初寒候，乌啼欲曙时。","况复念良友，迟回劳所思。"]},{"t":"寄赠余元帅","f":"五言古诗","c":["客从舒城来，为言好舒城。","寇来不敢近，主将专雄兵。","舳舻亘长江，笳鼓中夜鸣。","流电激飞炮，浮云夹长旌。","前冲有游骑，士卒鱼丽行。","既战东城郛，复守北郭营。","开关忽纵击，入阵歘纵横。","献捷辕门下，日晏宾从盈。","饮至列绮食，回歌调玉笙。","怅然登高台，四顾但榛荆。","淮襄既荡析，江汉何由清。","击剑抉浮云，彷徨念周京。","至今戎服事，六载忧患并。","皇眷有嘉赉，思底东南平。","藩翰有如此，为君诵休声。","我实经丧乱，永怀仲宣情。","挥涕谢客言，感激此平生。","安得驾云翼，从之以东征。"]},{"t":"遐想亭诗为刘元善赋","f":"五言古诗","c":["登高望神州，邈矣何渺绵。","西穷弱水涯，东极扶桑巅。","剑阁连蜀栈，幽都涉水天。","巀嶪带衡岳，逶迤注秦川。","驾车安得驰，汎河苦无船。","君子畅玄览，构亭向林泉。","眷言寄遐想，临眺豁以宣。","高深亦何穷，古今浩无边。","岂但四海外，亦在千载前。","抚剑怀壮游，揽辔思高贤。","对酒不能饮，丘尘正骈阗。","下士伤局促，高人乃超然。","神情苟弗旷，跬步先尤愆。","窅窅天际云，悠悠海中仙。","茫茫安可极，耿耿徒自怜。"]},{"t":"答次罗斗明感怀一首时道阻留滞江上并柬曾鲁卿令尹","f":"五言古诗","c":["川原下寒日，笳鼓喧清秋。","异郡阻时危，客心终夜浮。","华簪感徂年，志士悲同仇。","羁唫本思越，哀怨仍伤周。","道路邈以远，林泉深且幽。","邃馆俯中河，两贤此淹留。","林鸟恋旧栖，池鱼思故游。","愕梦剧飘风，愁肠甚攒矛。","理乱自相乘，勉为汎虚舟。","悠然任化运，穷达安其由。"]},{"t":"与周思忠刘孟文诸君子会饮李克贞宅分韵得三字","f":"五言古诗","c":["秋日凄以烈，华轩何潭潭。","众宾适燕止，凉飙飒崇楠。","笾豆秋有光，冠佩蔚交参。","尝闻旅也语，式奏乐且湛。","献酬礼百千，言议陈再三。","授简惭末至，怀贤惕高谈。","兵戈属时危，风尘蔽东南。","罹疚秪自伤，太康宁敢贪。","反顾企明哲，悲歌恋林岩。","仰睇天际云，中情何由缄。"]},{"t":"送杨公望赴京得满字","f":"五言古诗","c":["君行服初命，列宴当候馆。","宾从塞道周，风烟激危管。","舟航既汎汎，佩璲亦鞙鞙。","沧江东流深，浮云北飞远。","林含春雨润，石抱苍山转。","朝驱历荆吴，夕秣迈齐兖。","凌云紫殿重，栖日丹阙烜。","玉塞缭都城，金河注林苑。","薇垣甚弘敞，天衢实夷坦。","凤毛出西掖，鹭翿翳云䍐。","谁论羽林直，自足郎官选。","茂名勖树立，令绪慎继缵。","兹辰怅言别，于饯宜乐衎。","日丽花气薰，莺啼草香暖。","承恩贵在早，趣驾焉得缓。","仰怀天外翮，俯愧沟中伴。","伫立睇遐征，城闉月初满。"]},{"t":"拟古四章将适钟陵赠别廖子所 其一","f":"五言古诗","c":["南征有孤雁，爰止河之洲。","一雁西北来，飞鸣以相求。","厥初异生族，及此同泳游。","唼食以终日，中情甚绸缪。","月落霜正飞，繁星激中流。","岂不念群处，安居或多尤。","肃肃待明发，逝此各有谋。","鸣声倘相及，犹足慰离忧。"]},{"t":"拟古四章将适钟陵赠别廖子所 其二","f":"五言古诗","c":["茕茕幽闺妇，袅袅当窗柳。","盛年而离居，忽忽伤老丑。","临流采荷花，水深不见藕。","愁如风中丝，错乱纷在手。","独携合欢带，谁结同心纽。","佳期谅不违，岁月浩难守。"]},{"t":"拟古四章将适钟陵赠别廖子所 其三","f":"五言古诗","c":["东邻淘眢井，拾得古时钗。","并头馀一扇，长股折两叉。","早辞腻粉污，甘就泥沙埋。","至宝识夜气，寒光出瑶阶。","鍊多色不改，世远制乃乖。","沈唫伤老大，嗤笑来姝娃。","淫巧夺众目，谅非时所谐。","藏之第勿言，毋以伤我怀。"]},{"t":"拟古四章将适钟陵赠别廖子所 其四","f":"五言古诗","c":["少小同里闬，不识里闬人。","与君南北巷，何似东西邻。","束发事远游，不得长相亲。","况复老大辈，长成先十春。","飘飘林上风，亦逐车下尘。","未必志气士，相疏遂沈沦。","乃者涉中泽，言采秋风蘋。","持赠同心者，庶以丽佩纫。","春华岂不荣，憔悴易伤神。","高谊媲金石，终为雷与陈。"]},{"t":"春日述怀五首 其一","f":"五言古诗","c":["蝼蝈当夜鸣，禽鸟亦晨喧。","岂不感芳序，乘时如有言。","鄙人昧达识，沈郁寡所宣。","触物惧乖违，噂沓焉得论。","高言谁为倡，欲吐且复吞。","庶几服玄默，于道契弥敦。"]},{"t":"春日述怀五首 其二","f":"五言古诗","c":["青青道傍柳，郁郁园中葵。","葵长有芳叶，柳生无完枝。","所托势则殊，荣悴固其宜。","寄言乘时者，皦皦难自持。","春雨沛嘉树，动与旬朔逾。","积阴滞群品，流潦溢九衢。","摵摵西北风，冥冥混晨晡。","云解复旋布，出日不须臾。"]},{"t":"春日述怀五首 其三","f":"五言古诗","c":["三农苦告雨，苗腐麦恐无。","陵衍卒骞崩，涔污拟瀛湖。","居人惧沈垫，行者愁沾濡。","明明青皇令，阳德乃不敷。","至仁本滋育，岂曰肆毒荼。","所忧后炎赫，閟啬成焦枯。"]},{"t":"春日述怀五首 其四","f":"五言古诗","c":["芳序积霪雨，凄其薄凉风。","物情感催促，世故伤樊笼。","宛宛陵中苕，㠜㠜江上枫。","新荑掩茂绿，旧蘤舒轻红。","调音愧流莺，矫翼怍冥鸿。","沈郁坐中庭，幽赏谁与同。","援琴发绿水，操翰萦文虹。","志惬本理齐，处裕在德丰。","推移有常运，深穆自玄功。","永言契达观，毋为戚终穷。"]},{"t":"春日述怀五首 其五","f":"五言古诗","c":["盈盈东窗姝，粲粲西楼姬。","东风二三月，相向拂娥眉。","娥眉各宛曲，玉佩光陆离。","鸣筝左右弹，凤管双双吹。","曲意承光宠，惜此艳阳时。","南邻有少妇，闭门敛容仪。","碧草掩行迹，白日守空帷。","过时独不售，徒为当世嗤。"]},{"t":"春日怀金精旧游","f":"五言古诗","c":["明月出东壁，众星亦煌煌。","念我平生友，邈在天一方。","春风起中泽，百草何茫茫。","岁月奄以逾，所悲半存亡。","缅怀昔合并，言笑得共将。","朝游将军幕，暮宿羽士房。","列骑奏鼓笳，飞觞鸣佩珰。","金精既揽秀，石华复褰芳。","汎渚拾翠羽，憩林撷玄霜。","情好夙所敦，啸歌乐未央。","浮云一朝散，东西永相望。","事往迹空存，时移心孔伤。","我行属绪春，怀远登崇冈。","跋彼重滩阻，云石聿苍苍。","石鲸久潜伏，木鹤安能翔。","岂无一尺书，感此道路长。","愿因托飘风，宛转吹君裳。","终然虑回远，伫立以彷徨。"]},{"t":"赠黄君宝弃吏归临川","f":"五言古诗","c":["我性昧章律，举世嗤其迂。","奈何耻深刻，终恋诗与书。","往年旅江县，县小烦追胥。","道逢前呵人，意气倾乘车。","有美黄司曹，相视意有馀。","高堂罢鸣琴，退食当前除。","零露沾衣裳，凄风薄髯须。","怅然置公牍，为我立须臾。","苦云罢蹇姿，不任策与驱。","清谈与佳句，宁塞上官需。","俯视疲垫氓，何能援泥涂。","永念鹤发亲，经年倚门闾。","胡为事微禄，竟与定省疏。","矧兹春事殷，锄犁当荷扶。","汝水东北流，凤山须结庐。","翩然事长揖，脱身复为儒。","此道诚厉俗，此志当不渝。","安得驾黄鹄，乘风与之俱。"]},{"t":"咏怀一首","f":"古风","c":["惊风吹阴霾，惨澹从南来。","群山不可见，赣水流喧豗。","浮梁限舟楫，苍茫使人哀。","窃闻闽寇发，跳梁驱驽骀。","啸呼千百辈，日甚蚁垤培。","倒廪夺官粟，揭竿事行枚。","汀州前月破，属县如缀鋂。","寨营少构结，仓卒罹罿䍙。","脱身锋刃徒，潜行哭焚灰。","长缨陨巨弩，紫绶窜草莱。","邻邑号虎狼，具状檄所该。","月中羽书下，邮吏疲鞍{革雋}。","百步不回头，夜呼城门开。","人心实危慄，天意固久胚。","夜来大星坠，血色烛九垓。","见者不及瞬，曳尾东南隈。","父老行叹息，儿童且嗤咍。","承平亦既久，敢谓无遗才。","干戈在穷谷，战马或虺隤。","奔腾捷猿狖，何以收渠魁。","石城界其左，剽掠易历陔。","繁云接巉壤，杀气侵崇峐。","奈何墟烬者，直以封利媒。","我兄蓝田寓，阻修困炎埃。","似闻饥窜日，饮水不满杯。","独辞主翁宅，寄迹莲花台。","消息苦不真，出滩何悠哉。","令我引睇之，泪眼如凝衃。","武山当我前，落日红焞焞。","大军动地至，笳鼓生风雷。","旌旂蔽积水，参差溯云桅。","所幸气候时，清霜折群荄。","长风肃金气，槁振枯亦摧。","鼎汤宁跃鳞，沙日会曝腮。","终然不遑寐，念此怀忧悝。","起瞻华盖尊，紫气明三台。","再拜览馀辉，天庭正高傀。","中原蓄精锐，金城屹龙堆。","计日荆棘除，道路终恢恢。","便当引轻缆，往迎泛沿洄。","归来慰亲娅，为兄具樽罍。","复此当几时，愁肠日周回。","仰彼林表翮，双飞故毰毸。","谁怜失群鸟，悲鸣正徘徊。"]},{"t":"沿邓溪登石盘岭","f":"五言古诗","c":["沿溪弄潺沄，举首见绝壁。","石脚插白沙，崩崖旧时劈。","始登足轻剽，稍瞰心怵惕。","圆峰覆锜釜，悬涧泻瓴甋。","当时风雨交，云气走霹雳。","兀立苍茫中，隤然欲无敌。","夤缘背前路，陟巘欣后觌。","委蛇冠彤霞，巀嶪挂赤霓。","梯危出深窈，指道转岑寂。","寒葩泫零露，幽翳明的皪。","迂回落陂陀，清晨方踧踖。","乔林杂松槚，玄宇散檐樀。","逝将觐天人，披发调笙笛。","神仙岂在远，尘虑恐未涤。","行歌答清啸，次第记所历。","回风散残雨，列宿光可摘。","群动亦暂休，啼螀在葭荻。","意行得无为，念此增感激。"]},{"t":"美彭泽王令尹建清忠书院","f":"五言古诗","c":["陶令本遗世，三径亦已多。","感慨起田园，从容理弦歌。","一朝谢时人，去官如脱疴。","至今门前柳，清照湖上波。","狄公后来者，屏斥留山阿。","维时改唐纪，翕翕张网罗。","公也立高庙，拜之涕滂沱。","至今林木幽，夜月闻佩珂。","二贤去已久，兹事凛不磨。","令尹建新亭，合祀理不颇。","上以厉风节，下以育菁莪。","悠悠百世下，兴感当如何。"]},{"t":"赠别王令尹","f":"五言古诗","c":["闻君解印绶，将有山东归。","山东亦何好，毋使我愿违。","阴阴垄上桑，下有雏雉飞。","沄沄九江水，虎渡不敢威。","一邑几百家，夕寐恒敞扉。","矧复饥疠馀，瘠者今始肥。","奈何去斯邑，山水无光辉。","老翁卧行辙，妇女扣马鞿。","马鸣秋风高，载驱正騑騑。","歌谣有遗思，因之拊弦徽。","不恨去者遥，但伤来者稀。"]},{"t":"戊子六月喜雨","f":"古风","c":["溪原雨既作，暝色复惨䨴。","乱云无时兴，淫浸恐奔溃。","居人坐当户，烦暑欣涤溉。","冥冥飞鸟绝，窈窈横冈背。","黄罗六七里，举首一山对。","念子暂阻修，而多发幽慨。","神驰碧林表，思豁澄宇外。","舆盖强仆夫，逝将汨泥秽。","亲情见款曲，屡起捉衿佩。","侧足石径微，颇亦虑迷殆。","野航终不渡，潦势方益大。","且复连夜床，高谈慰忧痗。","时维秋夏交，变惕蜂蚁队。","湘湖荡流波，其色黯玄黛。","将军久驻马，农亩应释耒。","簪裾恬食息，豺虎越阛阓。","明王布德泽，此理竟谁昧。","秋风落刁斗，夕露沾甲铠。","岂知藜藿味，优暇乃我辈。","勉君迟遁思，过雨方可爱。","持杯接华烛，登俎烝肴载。","庭芜欣濯濯，凉叶交??。","吁嗟治乱机，倚伏纷万态。","众流终赴海，群巘必宗岱。","欢期且莫违，天道终有在。","矧兹服平素，陈谊炯肝肺。","谁能伤局促，而不思奋淬。","会合如可常，能来勿辞再。"]},{"t":"赠张横舟","f":"五言古诗","c":["至人玩斯世，汎汎如虚舟。","横之或安止，运之亦周流。","昔者张子房，此道恒优优。","眷言百世下，之子仍好修。","手携绿玉杖，身著紫绮裘。","折花驾白鹿，采药骑青牛。","栖迟木石居，笑傲王侯州。","敲火烧灵砂，可以戏神丘。","为人葬白骨，可以生公侯。","人言死生理，杳渺甚难求。","君乃不自矜，视之良悠悠。","翩然思黄石，去作万里游。","高视浊世间，下士如蜉蝣。","玄元无穷门，出入谁与俦。","绵绵日月运，茫茫天地秋。"]},{"t":"八月枉希颜王孝廉自大唐别业相见靖安县中辱赠长句甚慰旅怀临别赋此","f":"五言古诗","c":["往与君别者，乃在南平州。","此日复可惜，送君溪上头。","子留未五日，我客已一秋。","感子远来意，中情甚绸缪。","此邦邻新吴，山水亦颇幽。","县中数百家，青峰映朱楼。","其木杂杞漆，其果多枣榴。","土沃饶桑麻，阴阴夹良畴。","近县十馀里，负贩亦易求。","公庭草如戟，其俗自不媮。","人言淳雅风，可以齐鲁邹。","矧我之所主，读书皆好修。","开轩爱敬客，秩秩叙献酬。","亦有二三友，志合而道侔。","共言吾子来，得以奉嬉游。","况当八月交，大火西南流。","山蝉夜中起，黄鸟啼青楸。","便当蹑短屐，从尔陟林丘。","西寻桃源溪，卧云石龙湫。","低头饮美酒，万事吾何忧。","此意谅所悉，宣摅在朋俦。","翩其食场驹，歘去乃不留。","回风捲行迹，我思实悠悠。","脱叶鸣岛沙，行云递中州。","磬折长林下，踯躅广道陬。","常时恣言论，及此郁不抽。","盈盈目中泪，望子河之舟。","子归大塘里，偃息得所休。","濯足坐垂钓，短衣行跨牛。","田翁与稚子，相见何油油。","视我远亲故，兀如鹰在鞲。","沧江渔樵具，何以为远谋。","平生四海志，不直千金裘。","圣贤诫谅直，庶用寡悔尤。","感君昔赠章，慷慨契所投。"]},{"t":"树萱堂诗为章仲勉赋","f":"五言古诗","c":["莫种南山葛，葛生满堂前。","其蔓滋以长，愁心苦缠绵。","不如种萱草，花开自年年。","朱英间绿叶，可以忘忧悁。","双飞玉蝴蝶，一往不可复。","八月莎鸡鸣，露花白如玉。","白露秋复春，佳人在空谷。","日暮翠襜寒，采之不盈掬。"]},{"t":"桃源","f":"五言古诗","c":["青林被重冈，苍石立绝涧。","冥冥松风回，高蔓弱可绾。","驱车鹤岭下，沮洳湿危栈。","微茫烟霞集，披靡杉筠间。","高秋灏气豁，秀色纷属盼。","芸芸澼纩子，涉水恒及骭。","山女行负薪，结发垂两丱。","年丰粳稻足，食狃刍与豢。","呼吏不及门，征租少稽慢。","银坑重茶赋，往往先月办。","缘山八九家，火耕习薅铲。","土屋桑树高，鸡鸣日方晏。","清霜落原菽，夕露沾畦苋。","吁嗟避秦人，历世乃多患。","岂知太平俗，铠甲未尝擐。","永宜旷士怀，乐此谢游宦。","种桃实吾事，荷耒乃不惯。","穷源愁日暮，流水方汕汕。","叹息行险艰，南云送凉雁。"]},{"t":"蚕尖","f":"五言古诗","c":["日出西岭赤，鸣禽度高楠。","稍陟衣带岭，东尖屹危参。","侧身忽旁断，拟步若幽探。","勃勃草木霏，高下皆浮岚。","巨石当横途，始复一解骖。","崖古树根瘦，谷深人语含。","石角利攒剑，远山突支簪。","何姑骑白鹿，绿发长鬖鬖。","坐令妇女辈，奔走祈春蚕。","千崖动合沓，秋色晚正酣。","鴐鹅飞益高，刚风回东南。","我行蒙翳中，罥刺宁所堪。","山水能媚人，夙性所乐耽。","奚能恋文字，局促如饥蟫。","旷兹登览际，踯躅忘忧惔。","振衣复少憩，历险不敢贪。","片云触石起，流泽思远覃。","惜无晨风翼，照影双溪潭。"]},{"t":"靖安刘节妇诗","f":"古风","c":["春花逐飘风，不复返故枝。","妇人守中闺，死别生不离。","借问闺中妇，守此将为谁。","岂但伤所天，恒恐宗事隳。","念昔初嫁日，委币充房帷。","母也为我笄，姊妹为我缡。","祝我出门去，事夫永相宜。","夫家庭前树，两见春葳蕤。","下有紫鸳鸯，双双戏清池。","思同郑鸡鸣，忍歌秦扊扅。","君子不百年，弃捐忽如违。","高堂无老姑，所有乳下儿。","不知后生死，身在义则随。","势弱将易摇，众言生间危。","譬彼鸟方鷇，阚窥笑群鸱。","又如孤栖燕，徒劳飞雀思。","亲戚来相看，怜我青娥眉。","叹息劝且言，悯我寒与饥。","含悽谢所亲，抆泪洗铅脂。","指天唾出血，誓死终不移。","结髦覆儿额，裹衣承涕洟。","妾身未即死，会见成人时。","夜绩坐达晨，晨理机中丝。","卖丝教买书，读书以为资。","上承祖先祀，下衍嗣续期。","忽忽八十馀，子孙足娱嬉。","甘旨虽在口，终然有馀悲。","举案奉岁时，升堂陈棬?。","被服岂无华，终乐缟与綦。","明明王令尹，具录上府辞。","母死不待旌，乡里嗟惜之。","我识贤母孙，温克而令仪。","能言小学训，实自祖母师。","外有女鉴书，谆谆诲贞慈。","遭燬乃弗传，念之涕交颐。","嘅彼穹壤间，孰不躬秉彝。","安静或反悖，仓皇竟摧萎。","岂知妇女辈，颠沛终自持。","岩岩绣谷山，望之俨馀姿。","太史倘有徵，视我贞节诗。"]},{"t":"太湖滩","f":"五言古诗","c":["溯舟易安流，入石频顾虑。","盘回四山合，所向欲无路。","层湍障流雪，飞沫洒玄雾。","嵷嵷山木交，肃肃风色暮。","前登大湖滩，篙缆集群助。","跻危苦趑缩，一若乃脱兔。","参差石角出，蚴虬松根露。","两崖走鸣瀑，抵碛开复聚。","其流不可触，龃龉复哀怒。","声腾百雷起，势挟万里去。","舟行截其冲，捩柁疾指顾。","观其曲折间，肯綮豁玄悟。","我行戒前途，起坐惊失措。","心迷已乘险，事过翻积惧。","悲悽远游子，萧飒青枫树。","维纚暂栖息，霰雪惊寒注。","俛仰宇宙间，谁能获恒豫。"]},{"t":"雪霁舟出钓洲斜望云石诸山喜赋","f":"五言古诗","c":["晨出钓洲南，陂陀见云石。","紫烟晴欲蒸，白雪寒更积。","乔林拥玄黛，流土杂坟赤。","溶溶色流动，江水光荡射。","定有高世人，栖神荫寒碧。"]},{"t":"永丰刘尊德自南雄归过宁都别予将之豫章因怀旷伯逵赋别念二韵仍以呈旷也","f":"五言古诗","c":["刘郎南雄来，高豁动晴昊。","我行山水深，逢子恨不早。","林亭春色净，闭户思却扫。","骑马晨冲泥，沾濡愧群草。","长滩石齿齿，舟楫得慎保。","呼酒破旅颜，操觚见文藻。","只今岭南幕，颂尔伯父好。","佐邦重赞诺，华发未即老。","久知阶庭除，重尔甚琲璪。","家声激前闻，谁不思涤澡。","矧子方青年，如日斯杲杲。","求师复远涉，下浦伤霖潦。","落花随飘风，何以慰中抱。","南州有旷子，友谊获深造。","高歌忘羁穷，愁绝亦颠倒。","我昔从之游，艰危极论讨。","今年始适吏，颜色脱枯槁。","独不常见之，念我心懆懆。","永怀川无梁，式赋山有栲。","从迈谅匪难，踯躅悲远道。","浮云递崇冈，斜日下深岛。","会合谅有期，持身以为宝。"]},{"t":"送孙民瞻之广西帅阃照磨","f":"五言古诗","c":["蔚蔚城闉柳，长条当路岐。","行人服王命，策马厉所之。","登高望群山，马鸣风正悲。","天连江广交，云隐湖湘湄。","向西有大府，冠盖何逶迤。","分阃控百蛮，元戎总前麾。","简书岂不畏，舒卷在所持。","忾彼猺獠徒，椎跣恒蚩蚩。","丝毫苟失御，雠杀相纷披。","闻君去参幕，道路今衍夷。","两江动晴色，八桂含春姿。","王爵有优劣，官资无崇卑。","烈烈塞上笳，泠泠月中吹。","感激丈夫气，岂不在边陲。","圣人重文德，斯道贵抚绥。","慎尔录边勋，勉为古人思。"]},{"t":"闰七月十夜独酌","f":"五言古诗","c":["华月出渐高，飞光入危榭。","幽人对尊酒，独酌意颇暇。","风林起森寂，方帙散狼藉。","虑顾不成歌，微唫答清夜。","庭前有隙地，植木引藤架。","蓬蒿日萧条，鸡鹜集其下。","旁罗三石峰，培塿互骈亚。","蟋蟀鸣中宵，悠然感时化。","二年厌羁旅，奔走涉冬夏。","思营堂中养，遂别江边舍。","不复理茅茨，焉能事耕稼。","童孩缠瘉疾，老大伤徂谢。","天寒道路远，滩水哀激射。","止酒且莫斟，有泪迸欲泻。","鸣马顿长缨，谁能纵其靶。"]},{"t":"古诗九章赠别郑同夫 其一","f":"五言古诗","c":["君子如鸾凤，肃肃仪羽齐。","梧桐苟摧谢，凡木竟不栖。","又如神马驹，来自荥水西。","有足追奔风，不踏沙与泥。","明明希世瑞，自异犬与鸡。","所以贤达人，出处终不迷。"]},{"t":"古诗九章赠别郑同夫 其二","f":"五言古诗","c":["明珠閟深渊，沈绠或求之。","高人在岩谷，岂以远见遗。","下勤州府荐，上感圣明知。","濯足东溪流，弹冠南山陲。","朝从烟霞别，夕与剑佩仪。","小大思奋功，树立当及时。","芸苕岂无华，芄兰亦有支。","宜尔令德士，允为善人师。"]},{"t":"古诗九章赠别郑同夫 其三","f":"五言古诗","c":["翩翩郑博士，起身自文章。","冠带讲洙泗，忠诚百夫行。","昔为新昌校，今作宁都庠。","六年系儒官，两州服其良。","禄米月不充，蔬食饮水浆。","弟子求执经，大夫为承筐。","革顽见揖让，草偃风益张。","人言兹道盛，岂独齐鲁乡。","怀尔金玉音，弹琴咏清商。"]},{"t":"古诗九章赠别郑同夫 其四","f":"五言古诗","c":["积雨秋始凉，绿苔閟庭馆。","闻君起常晏，巷深人事罕。","去年所种树，两两当户短。","初欣花盈盈，今见实纂纂。","感此时物迁，愁思无时断。","美人当歌罢，向夕喧急管。","独复步前楹，城高月初满。"]},{"t":"古诗九章赠别郑同夫 其五","f":"五言古诗","c":["明月何皎皎，流辉青天中。","美人褰碧幌，汎若晴烟空。","露下白玉团，乌啼金井桐。","永怀君子心，寤寐向秋风。","道远而别多，烦忧郁忡忡。","焉知南园下，昔日桃花红。","君看旧行迹，一一生蒿蓬。"]},{"t":"古诗九章赠别郑同夫 其六","f":"五言古诗","c":["青林悲夕风，惨惨当北户。","起视河汉高，明星粲垂素。","旅游抚行辙，复独伤迟暮。","白露零中宵，柔条浩盈注。","百草寒不芳，莎鸡振其羽。","悠悠思华年，悄悄积中愫。","佳人碧云表，渺漠乖良晤。","晏岁来无期，徘徊企中路。"]},{"t":"古诗九章赠别郑同夫 其七","f":"五言古诗","c":["秋水忽时至，百川浩漫漫。","蒹葭薄晨露，芰荷激轻湍。","闻子驾方舟，咏歌以盘桓。","思结君子佩，所忧无芳兰。","天高碧海远，坐恐秋霜寒。","临流顾其徒，酌酒不成欢。","君行我当留，此别良独难。","踟蹰岐路侧，耿耿忧恨端。","独无凌风术，从尔乘飞鸾。"]},{"t":"古诗九章赠别郑同夫 其八","f":"五言古诗","c":["冥冥阳灵洞，中有绿发仙。","世人不可见，出入乘紫烟。","时来拾瑶草，独立青山前。","粲然发皓齿，玉井开红莲。","我欲往从之，兹事今千年。","似闻九州外，碧海回青天。","愿携两玉笛，吹上昆崙巅。"]},{"t":"古诗九章赠别郑同夫 其九","f":"五言古诗","c":["昆崙九千仞，浩荡不可期。","九州行无穷，会有相逢时。","执手不忍别，赠子双琼枝。","交道愧苟合，素心谅难知。","油油山上云，冉冉无定姿。","松柏生涧壑，贞性终不移。","天寒白日暮，秋风动江蓠。","怅然道路远，何以慰所思。","马鸣城北门，长揖从此辞。","但知行者乐，讵知留者悲。"]},{"t":"秋日同郑同夫罗孟文田仲颍游苍山访宋曾子实故居遗址今为陈氏居矣感赋一首","f":"五言古诗","c":["群峰何苍然，回抱得幽旷。","偶寻昔人居，遂历青霞嶂。","低连水竹交，高出雨云上。","瑰奇本天设，终亦由规创。","梯危与凿险，嵷嵷各异状。","子孙久漂散，兵火成彫丧。","回风吹禾黍，烟草亦漾漾。","我行问其故，指点迷所向。","呜呼前代秀，诗名宗哲匠。","仓皇嘉熙末，戎马日方张。","拂石事冥栖，空馀白云唱。","百年总飘忽，过者一惆怅。","长啸豁清秋，吾将骋遐望。"]},{"t":"醉后偶书","f":"五言古诗","c":["高人事饮酒，饮酒亦有期。","一日十二时，三时斟酌之。","曲糵糜我肠，夫岂乐在兹。","沈沈百忧中，聊以一解颐。","兹晨复旷饮，困败乃不支。","床前有小女，长跪陈戒词。","甚矣昨日醉，反为醒者嗤。","今日可以已，明日当再持。","百年亦良远，岂独今日宜。","不见刘阮徒，沈冥竟奚为。"]},{"t":"园居述怀和王迂叟","f":"五言古诗","c":["园居背城闉，皋衍沐时雨。","颇怀人事幽，岂计力作苦。","秋麻青已黄，风露薄墙堵。","荷锄还独往，脱帻时自舞。","地偏閒已极，暑退凉亦甫。","时来藉草坐，静与竹石伍。","夕憩思尝瓜，晨兴问炊黍。","高秋澄沤潭，返照淡林莽。","亦欲具轻舠，从君钓中浦。"]},{"t":"拟古赠友人别","f":"五言古诗","c":["上山采兰苕，下山采杜蘅。","采之何所为，将以遗远行。","君行日以远，欢会日以浅。","乡心一千里，日逐车轮转。","石林夏气清，憩马到江干。","杂佩粲琼玖，长祛峨弁冠。","驱驰道旁子，赪颜触烦热。","永怀高世心，炳炳照冰雪。","秋风起天末，百草终摧残。","君子谅不违，揽芳发长叹。"]},{"t":"苦热","f":"五言古诗","c":["高馆閟烦歊，蹙蹙思一骋。","叶定风乍稀，蝉鸣昼方永。","西偏梧桐树，疏薄不布影。","移床坐叹息，仰见绣谷岭。","汗滋苦流踝，发短压垂领。","黄葛秋未成，乌帽时一整。","遐思翠竹林，下荫青苔井。","修绠络铜瓶，时来漱清冷。"]},{"t":"衣带岭","f":"五言古诗","c":["朝辞桃源溪，暮宿衣带岭。","心同秋水净，思与群山永。","白云松际来，日入鸡犬静。","苔藓依古垣，薜萝罥深井。","天清露气肃，衣袂忽已冷。","明晨当远发，我驾思夙整。","西上挹高霞，蚕尖纵幽骋。"]},{"t":"九日胡孟浩携酒与客登官峰赋此","f":"五言古诗","c":["今日天气肃，我心舒且閒。","美人携碧酒，与客登青山。","矫首思八荒，意适忘险艰。","双流白日下，千室浮云间。","木叶露已黄，泉声亦潺潺。","时序忽若流，但伤游子颜。","鴥彼南飞翼，可望不可攀。","绵绵山下路，逝此何当还。"]},{"t":"入苍山下岩寻曾子实先辈故居遗迹往往有题刻存焉","f":"五言古诗","c":["层岩上苍翠，下结赤石沙。","题刻不复辨，莓苔见欹斜。","始经茶岩幽，流泉注其窊。","复登石楼重，谷吻奋以呀。","跻攀出众险，一目纵迩遐。","窅窅平原中，群山如削瓜。","筼筜旧种竹，隐隐明秋霞。","亦欲问青天，举觞酬黄华。","梯危且憩息，仰首闻叹嗟。","蹊路梗不通，荆棘为我遮。","昔人苦好事，侈以名自誇。","焉知百岁后，寂寞犹枯苴。","途穷日将夕，鸣鸟纷已哗。","暮出藤萝中，还寻野人家。"]},{"t":"题姜炼师山房有怀赵伯友郑同夫二首 其一","f":"五言律诗","c":["金精五千仞，之子住石屋。","阴风昼夜寒，猿鸟下檐曲。","暮归斸松苓，朝出采簧竹。","头发乱不梳，容颜美如沐。"]},{"t":"题姜炼师山房有怀赵伯友郑同夫二首 其二","f":"五言律诗","c":["往者赵郑辈，联句高岩中。","吹灯坐深夜，露冷栟榈风。","一别山月白，再见仙桃红。","奈何行役者，容易各西东。"]},{"t":"题旸谷出日图","f":"五言古诗","c":["东眺嵎夷谷，夜陟泰山顶。","天角烂五色，六龙驾方整。","手攀扶桑枝，下瞰黄河流。","阴风忽南来，烟雾半九州。","安得古仙人，凌景事吞吸。","我欲从之游，凭虚怅孤立。"]},{"t":"送郭韬之豫章","f":"五言律诗","c":["鼓瑟送行客，调高难为情。","感君万里心，为作秦中声。","纷纷江南弄，中有鸣凤曲。","静听谐古心，毋为眩烦促。"]},{"t":"题萧氏孝思亭","f":"五言古诗","c":["百草在中野，霜露零悴之。","君子怀古先，怆悽以遐思。","筑亭墓田下，负土起崇基。","疏敞而不华，修楹带高茨。","岁时来祀墓，聚息恒于斯。","目泫荆棘丛，手攀松柏枝。","行人为驻马，问此今为谁。","人言萧氏墓，孝孙能尔为。","教授得俸钱，不营寒与饥。","结庐会宗族，买田供祭祠。","父老共嗟讶，观者垂涕洟。","此意良已厚，此事俗已亏。","永言锡尔类，视此萧阡碑。"]},{"t":"登三顾山次王子启","f":"五言古诗","c":["闻子避地日，南登三顾峰。","长吟白云里，笑拂青芙蓉。","芙蓉何亭亭，秀色相倚叠。","仙人坐中顶，气与元始接。","俯视白下城，累然若蓬丘。","淦水不可涉，西山焉得游。","谁能拥长彗，蜂蚁罄一扫。","莫遣秋风尘，惊飞污瑶草。","瑶草萋以绿，繁华谁敢争。","永怀东海客，身隐扬令名。","拂衣本馀事，终亦恋冀阙。","献纳倘未酬，从君卧萝月。"]},{"t":"南园灌隐诗","f":"五言古诗","c":["苦无千丈流，沃此万里焦。","独寻南园隐，灌畦以逍遥。","亢夏天势高，凿地不见水。","凿深地骨出，常恐见骨髓。","朝抱一瓮出，暮抱一瓮归。","草间行道微，茨蔓沾人衣。","良苗灌难苏，恶草苦不死。","一日灌十畦，采之不盈篚。","欢然对藜藿，似欲忘朝饥。","雨露自天泽，劳生须有期。"]},{"t":"题渊明像寄刘仲脩","f":"五言古诗","c":["斯人管乐俦，而分山泽槁。","岂无园中菊，念此霜露早。","衡门卧日晏，幽径时自扫。","芳晨有旨酒，客至即倾倒。","兹言乐游衍，春服丽轻缟。","古道少人行，杖藜入秋草。","神閒韵自适，意远色逾好。","鼎鼎百世师，遗荣以为宝。"]},{"t":"朝采南园栗","f":"五言古诗","c":["朝采南园栗，暮捧贤能书。","贤书岂不荣，食力意有馀。","念昔事先训，读书本菑畬。","时危乃弗殖，竟与耕凿疏。","昨者出充赋，黾勉应里胥。","擢秀或偶然，揣分良惕如。","置筐忽叹息，我奚以自抒。","风尘蔽江海，戈甲满州闾。","再拜谢乡老，返我林下居。","行已贵实践，徇人俱虚誉。","恻恻念时序，悠悠随卷舒。"]},{"t":"题练江渔钓图为郑伯威赋","f":"五言古诗","c":["练江白如练，千丈峡中流。","客有槎上仙，啸歌在扁舟。","风吹石楠树，沙浪蹙微雪。","潭影见垂萝，悬猿弄明月。","东望七里滩，苍苍云雾间。","寻源不知远，时听棹歌还。"]},{"t":"采菱篇为林森赋","f":"五言古诗","c":["朝采湖上菱，菱实何离离。","浮叶当雨乱，低华映日欹。","清流苦难肥，浊水乃易滋。","水面方羃䍥，泥间已委垂。","中含白雪质，外袭赪玉皮。","游鱼畏芒刺，不敢扬其鬐。","采采盈倾篚，皎皎吴中儿。","密愁垂钓涩，深怯荡舟迟。","忽闻歌采菱，借问歌者谁。","褰裳往从之，烟水浩两涯。","怀德贵自充，中心谅无疵。","永言托嘉好，及此秋风时。"]},{"t":"远游篇为黄子邕赋","f":"五言古诗","c":["闻君有远游，请赋远游篇。","上陈道里遥，下感时序迁。","茫茫九州外，历历秦汉前。","山行岂无车，水汎亦有船。","豺虎忽纵横，蛟龙方纠缠。","井邑化为灰，墟里但荒烟。","人生非鸿鹄，何以周八埏。","君行忽踟蹰，惜此全盛年。","宝剑珠玉匣，结驷青连钱。","谈辨三军帐，笑歌五侯筵。","会合鄙毛遂，功成羞鲁连。","落日临广陌，回风激繁弦。","此别诚艰虞，忍为离绪牵。","不见里巷儿，封侯起关边。","毋为北郭叟，白首事太眩。"]},{"t":"八月十日同王睿刘霖旷逵萧谌欧阳铭钟哲焦瑜王佑燕集王氏南园赋诗有图有序","f":"五言律诗","c":["南园淡将夕，北渚复已秋。","欣言属游咏，千里会良俦。","乘月歌窈窕，临觞结绸缪。","高情谅无极，庶用慰离忧。"]},{"t":"同萧谌旷逵诸君子夜集蟠溪王新书舍得竹字","f":"五言古诗","c":["涉溪蛩始鸣，带暝度原陆。","及门会凉风，月下照林屋。","夜深露华集，众叶净如沐。","曲径罥垂萝，虚檐响疏竹。","周回丈席间，坐者四与六。","张灯接谐宴，分韵酬翰牍。","居当惜盍簪，行勿念脂轴。","亲情正款洽，夕气稍澄穆。","明星乍稀微，群鸟各已宿。","明发咏白驹，怅然邈空谷。"]},{"t":"题罗浚诗藁","f":"五言古诗","c":["远有万古调，写之声诗间。","长吟不自已，哀响连秋山。","问君何尔为，萧瑟多苦颜。","抱志悲徂年，颓波不东还。","古有大圣人，制作垂定删。","清庙继者谁，王风竟间关。","怅言百世下，蹇独伤时艰。","祥凤伏䲭鹗，猗兰化草菅。","感此坐叹息，穷栖在宽閒。","矫矫孤飞鸿，冥冥安可攀。"]},{"t":"题高人汎舟图为铁柱左炼师赋","f":"五言古诗","c":["刺篙度回渚，解带会微风。","仰视青天高，浩歌秋水中。","沧江渺空碧，嘉树发霜红。","玄境有至乐，伊人若凫翁。","遐思青玉佩，应过紫霞宫。"]},{"t":"悼严焕","f":"古风","c":["旧宅已芜没，城乌终夕啼。","新坟亦宿土，秋草还萋萋。","谁为荓螫蜂，永痛触网?。","老母抱弱孙，投迹向山溪。","新愁不可道，往事焉得追。","故交半零落，梦寐增惨悽。","对酒忆同醉，检书看故题。","茫茫风中尘，汨汨山下泥。","维南三顾在，谁与重登跻。"]},{"t":"过南圳访友同王子与罗子理分韵得满字","f":"五言古诗","c":["连阜衍平皋，深林閟虚馆。","扬襟畅遐思，散帙延清款。","溪莼花羃羃，田黍实纂纂。","径回阡弥永，水落涧初满。","载欣秋稼登，矧惬人事罕。","欲往悲旷途，言归理脩疃。"]},{"t":"题刘韶书屋","f":"五言律诗","c":["萧萧水杨树，叶脱秋涧小。","知是幽人居，声歌出林表。","启窗挹风袂，散帙惊山鸟。","即兴已复迟，空伤晤时少。"]},{"t":"陪萧谌欧阳铭陈宜邹吉泰诸君子晚宴兴福寺汎舟夜归三德院明日分韵得口字","f":"五言古诗","c":["时危昧经济，适兴在林薮。","屏居甘事农，远顾欣得友。","初翱珠树林，暮景飒高柳。","复憩金塔园，清宵坐行酒。","萧萧风露集，莽莽波澜走。","轻舟乱寒星，夜下秋江口。","抚时增叹息，延论恣击剖。","披烟入林扉，列烛光照牖。","感激欢会难，闻钟坐逾久。"]},{"t":"送欧阳孔述归安城","f":"五言古诗","c":["晨出西昌门，北望盐水冈。","冈峦互回伏，寒日惨其光。","君行将所亲，逝此返故乡。","故乡岂在远，昔为豺虎场。","田庐既芜没，岁月复茫茫。","邻里存者谁，童稚各已长。","念此不遑寐，夜拂衣上霜。","驱车入寒雪，永望梓与桑。","黾勉事生理，艰危安可忘。"]},{"t":"贫居二首 其一","f":"五言古诗","c":["种瓜苦不实，閒草各已花。","抱锄忍朝饥，对之以长嗟。","蓬门昼长掩，游釜亦有蜗。","破屋乃无茆，雨来安可遮。","聊持手中卷，展玩至日斜。","荣枯与得丧，来往宁有涯。","悠然达其会，忧戚焉能加。"]},{"t":"贫居二首 其二","f":"五言古诗","c":["种麦在高丘，丘长草生满。","秋馀乃无雨，秀色遂枯短。","朝行垄间蹊，暮息林下疃。","荷锄待春风，时至谅不远。","东邻桃李花，终岁实纂纂。","生理宁独艰，如何乐疏散。"]},{"t":"园居杂兴八首 其一","f":"五言古诗","c":["启窗面脩竹，下荫方池幽。","兹晨微雨至，其气飒以秋。","芳时如佳人，徂矣安可留。","草木性已定，禽鱼狎其俦。","披襟纳良风，掩卷睇崇丘。","所欣城郭遥，归哉此优游。"]},{"t":"园居杂兴八首 其二","f":"五言古诗","c":["幽居寡人事，日晏门未开。","谁欤剥啄声，谓有好客来。","呼儿出洒扫，谢客无嫌猜。","蓬室陋且卑，风雨生莓苔。","起摘园中菜，自涤窗下杯。","清风忽南至，好鸟鸣高槐。","幽怀谅无遽，日夕方徘徊。"]},{"t":"园居杂兴八首 其三","f":"五言古诗","c":["北园莳嘉蔬，生长各以时。","入夏风雨多，众草丛没之。","夕花岂不荣，晨蔓亦自滋。","终然因采掇，濯濯馀空枝。","我贫本食力，澹淡固其宜。","拔本惧有违，植善非自私。"]},{"t":"园居杂兴八首 其四","f":"五言古诗","c":["种桃在墙阴，枝干数尺长。","今年始作花，秋实已可尝。","北园岂无李，西坞亦有桑。","勉为衣食赀，耕种安可忘。","里胥昨相过，录我桑果场。","新令有严课，民生固其常。","相送里胥去，悲歌念时康。"]},{"t":"园居杂兴八首 其五","f":"五言古诗","c":["种菊春树下，树荫菊不荣。","岂无雨露滋，蔽隔伤其生。","嘉树自芬敷，蔚然谁与争。","上延好鸟栖，下杂秋蛩鸣。","风霜坐飘忽，摇落何纵横。","终然保令姿，独立扬秋英。"]},{"t":"园居杂兴八首 其六","f":"古风","c":["荷锄出东皋，我黍忽已苗。","苗短不自持，百草势转骄。","良苗异本根，芜秽乃独超。","敢辞?耘勤，永愧雨露饶。","周雅永思古，王风竟颓凋。","人生重所务，岂独在夕朝。"]},{"t":"园居杂兴八首 其七","f":"五言古诗","c":["艺麻本欲疏，本疏乃繁殖。","小人务多种，偪侧伤天瘠。","离离叶间花，畟畟雨中实。","秋阳势方烈，日夜蕃所息。","寡欲而务滋，吾将食其力。"]},{"t":"园居杂兴八首 其八","f":"五言古诗","c":["南邻有老翁，所居止茆屋。","屋中两夫妇，作息遂所欲。","朝耘夫在前，夕稼妇相逐。","同心向白首，终岁无不足。","如何西邻子，早岁伤局促。","抱瑟守中房，空悲艳阳曲。"]},{"t":"晨兴","f":"五言古诗","c":["晨兴理短发，日晏闻儿咿。","老妻向我言，何以具晨炊。","畦蔬委霜雪，采摭无馀遗。","年丰乏储粟，矧此丧乱时。","忽闻剥啄声，谓有好客来。","弃置出迎客，兀坐方哦诗。","中有至乐者，相视亦解颐。","乌能累妻子，戚戚忧寒饥。"]},{"t":"寻云陟累榭送严子善之上犹","f":"五言古诗","c":["寻云陟累榭，遐览以舒忧。","皛皛天宇清，矗矗栏楹幽。","静赏抚危构，浩歌睇崇丘。","君子有远行，佳期谁与俦。","饯言以遵路，延伫更临流。"]},{"t":"养牛","f":"五言古诗","c":["养牛事春耕，春去耕苦迟。","扶犁向牛叹，我饥力已疲。","宿草交旧阡，嘉苗蔚新菑。","锄荒岂不勤，稼事良在兹。","无食乃劳生，有营常后时。","所以驱牛行，不忍鞭朴之。","穷达谅有定，放牛安所为。"]},{"t":"春耕","f":"五言古诗","c":["春耕恒苦迟，夏旱乃独早。","青青田中稼，忽忽同秋草。","雨露久消歇，泉源亦枯槁。","天高多惊风，赤日行杲杲。","微生恒寡欲，衣食宜有道。","劳力冀所资，遘凶岂云好。","古人九年备，捐瘠得善保。","孰能澹无营，饮水以终老。"]},{"t":"悯旱","f":"五言古诗","c":["我贫无储粟，我稼早已萎。","朝夕惧不充，矧此岁月滋。","朝饮南涧泉，暮采北山藜。","苟焉免饥渴，庶无罹崄巇。","西里有高门，连囷积如茨。","露溢到鸡犬，烹炰穷岁时。","乃知凶旱年，徒为志士饥。"]},{"t":"出门","f":"五言律诗","c":["出门见遥山，翠色纷在眼。","不知所到处，更隔几丘坂。","烟云何苍苍，道途方坦坦。","策驾属所之，怅然念时晚。"]},{"t":"述怀","f":"五言古诗","c":["我有二亩田，力薄耕不胜。","分田籍农父，所冀得斗升。","丰年本狼藉，薄俗乃侵陵。","一日凶旱来，颗粒遂不登。","我廪既莫实，公租方急徵。","叹息谢农父，此岂人所能。","天时一何常，盈歉古相乘。","宁为敛者嗔，毋为贫者憎。"]},{"t":"过刘氏废圃阮生携酒共酌","f":"五言古诗","c":["晨兴念良友，驾言向南坰。","良友喜我来，相邀坐高亭。","兹亭岂无华，疏井交碧青。","云是豪盛时，昔人所营经。","绮罗日高回，花卉扬芳馨。","十载事乃非，蔓草萦前棂。","独携一尊酒，言笑得暂停。","缅思昔人意，光采如流星。","曷不适真趣，超然外骸形。","如何累土木，徒使叹凋零。"]},{"t":"造田父","f":"五言古诗","c":["清晨造田父，设馔当前庐。","呼儿出揖客，汛地先扫除。","欢客啜糁羹，年荒无旨蔬。","物薄礼乃丰，情亲心已舒。","感此坐复起，一饱不顾馀。","谁云贱可鄙，秖觉贵自疏。","不见闾里间，坐食常晏如。","如何肉食者，阔绝严追胥。"]},{"t":"岁暮南归留别萧翀诸友","f":"五言古诗","c":["旅寐不能旦，披衣坐床帷。","屋角晓色动，鸟鸣已多时。","起坐出庭际，云物正华滋。","残雪未尽消，群山郁参差。","即此念故园，焉得不怀思。","岂曰无尊酒，足以欢相持。","矧属岁运周，返驾固其宜。","理策望前路，揖君从此辞。","穷檐有稚子，但讶归来迟。"]},{"t":"和答萧翀春雨过林居之作","f":"五言古诗","c":["林居滞昏雨，不知白日西。","窈窈穷巷阴，客至鸡乱啼。","旧梅既粲野，新柳复盈堤。","感此岁序迁，中情忽如迷。","簪盍慰远勤，尊酒欢相携。","古交今则稀，世道方涂泥。","立善固所欣，企贤贵思齐。","笑咏且永夕，勿辞此幽栖。"]},{"t":"辛丑正月廿二日述志","f":"五言古诗","c":["经年掩扉卧，迹与城市遥。","谁为拔茹意，乃以仕见招。","本昧平生素，敢劳中道要。","公檄临我门，戒命在夕朝。","九江今雄州，迈往方迢迢。","有母谁与居，念之中心焦。","起揖谢来客，我何希市朝。","澹然一室内，燕坐风寥寥。"]},{"t":"廿七日书怀","f":"五言古诗","c":["夙禀栖遁性，雅怀在丘樊。","三十谢城市，高歌返田园。","田园非有馀，衣食固其源。","投笔且依仁，掩扉聊避喧。","具餐适丰俭，酌酒任清浑。","力微愿不奢，志惬情自敦。","所嗟茆茨下，老母抱弱孙。","暮年餍藜藿，俛仰终寒温。","贱贫非有馀，至乐谅斯存。","谁能腼面颜，日枉豪盛门。"]},{"t":"春日游武山柬同游者","f":"五言古诗","c":["携酒陟层巘，披榛趁幽途。","眷言宾友集，乐此山水娱。","烟峦既合沓，风磴复盘纡。","济济丽服偕，洋洋清奏俱。","维时春气暄，谷鸟鸣相呼。","丛柯自交叶，花萼方承跗。","始登天宝坛，稍瞰北岩隅。","丹井注紫霞，云峰耀玄珠。","龙洞辟南巅，层宫俨清都。","纵目领众奇，游心周八区。","相劝各欢饮，击鼓吹笙竽。","立监视行觞，更仆佐倾壶。","舒怀或同笑，愤志亦独吁。","所欣契谊齐，幸免礼法拘。","言归已向夕，落日相携扶。","奕奕花间灯，馀辉烂星湖。","岂曰恣沈湎，庶用弥忧虞。","寄言城市子，此乐今恐无。"]},{"t":"猎犬篇","f":"五言古诗","c":["晨起同出猎，跳梁相叫嘷。","岁久识主情，指顾能周遭。","山石穿我蹄，荆棘罥我毛。","为主逐肥鲜，不辞奔走劳。","穷深抉幽险，狂狡焉得逃。","咂血不顾馀，一饱随所遭。","主人获隽归，意气方盛豪。","累然妥其尾，偃卧墙东蒿。"]},{"t":"二月八日对酒","f":"五言古诗","c":["对此春日酒，高堂乐未央。","客从州城来，怀牒促我装。","问客今何为，求贤寘周行。","麾觞忽叹息，我岂时所良。","少小适情真，穷栖恋閒荒。","譬彼蓬下鹪，敢怀云中翔。","岐路今已多，素丝乌可常。","念之不成欢，展转中怀伤。"]},{"t":"登北岩眺望因投巨石宛转为戏","f":"五言古诗","c":["自爱北岩秀，缘云穷翠微。","回见大江流，独立一振衣。","崖表人迹绝，烧馀寒草稀。","绕涧聆暗泉，攀萝憩危矶。","投石转阴壑，霆击星火飞。","奇探恣游衍，兴惬忘崄崎。","日暝思更寻，逍遥望月归。"]},{"t":"游三华山","f":"五言古诗","c":["龙门两峰圆，一水下回绕。","苍峡忽中开，飞桥出林杪。","盘盘石磴引，羃羃松林窅。","危栏正西挂，层阁复东缭。","树暗尽含云，花明忽闻鸟。","悬崖旁架栈，凿石潜通穾。","早闻三仙人，栖化迹已杳。","常疑云月上，颜色觌清皎。","丹井旧时深，朝真乱来少。","荒坛翳霜叶，虚馆閟丛筱。","凝神观众妙，屏迹谢群扰。","怀贤嘅重憩，振翼思远矫。","佳境能娱人，何因致清醥。"]},{"t":"晚出溪上将登武山不果","f":"五言古诗","c":["理筴迈前路，将言陟高岑。","中途阻且艰，忽复至夕阴。","林木郁萧森，烟雾亦何深。","不见好鸟翔，但闻哀猿唫。","重明曷由际，怅望此嵚崟。","恒恐岁年暮，遂为霜雪侵。","恻怆不能言，泪下忽沾襟。"]},{"t":"数日无酒饮","f":"五言古诗","c":["数日无酒饮，閒居谁与娱。","岂惟情怀恶，颇觉文字枯。","乃知古贤达，饮酒恒有道。","陶然乘运化，混混忘机巧。","举世桃李花，松柏摧为薪。","泰华忽破碎，枭獍称鸾麟。","如何今之人，有酒不肯饮。","颦蹙终其身，岂不愚亦甚。"]},{"t":"陪陈尹饮江上雨过夜归明日赋此","f":"五言古诗","c":["渡江云断桥，把酒风振袂。","芳园遂幽寻，良友适远至。","谐谈且云欢，酬劝忽已醉。","一雨洗尘襟，千山拂凉翠。","柘林既回薄，兰渚复延企。","月转城东门，萧萧送归骑。"]},{"t":"别罗伦","f":"五言律诗","c":["日暮出九洲，相送莲塘下。","林深归路黑，虎出须可怕。","双塘青松山，山近有茆舍。","今夜鹧鸪啼，思君山月低。"]},{"t":"题竹石图","f":"五言律诗","c":["何以秉贞节，而多抱苦心。","幽情旷前古，高谊式如金。","飘摇青霓涧，凌厉白云岑。","愿裁伶伦管，远谐凤仪音。"]},{"t":"会饮泮亭柬郭存敬","f":"五言古诗","c":["泮阴弭轩盖，游咏集高台。","感我平生友，中怀豁以开。","穆穆凉飙振，翳翳流景颓。","崇云向空起，飞雨从东来。","即赏心不违，怀古意悠哉。","谁怜临岐者，返顾方徘徊。"]},{"t":"别焦瑜","f":"五言古诗","c":["故人异县至，晨款林下茨。","感此丧乱馀，会面非有期。","土锉寒无烟，木榻坏不支。","坐起谢再三，艰难方在兹。","远怀若为浣，宴劳礼则宜。","邻酒忽告罄，虚觞但空持。","娈娈秋菊花，蓬茆翳幽姿。","君子惕驰骛，庶以善自怡。","天长远山没，日晏寒江迟。","送子出门去，怅然从此辞。","大哉天地间，委顺复奚疑。"]},{"t":"宿沓垄柬胡敬萧翀钟祥","f":"五言古诗","c":["夜宿沓垄西，衡茆荫平麓。","起视虎鼻峰，岧峣月中绿。","悬岩引列宿，积水带横陆。","山鸟时一鸣，回风应虚谷。","庭寒翳华灯，露下响丛竹。","朋情遂欢洽，世事伤否蹙。","清游契寤寐，往事成昔宿。","北岩有奇石，东园饶佳木。","明当扣萝扃，振舄骋遐瞩。","复恐惊尘飞，幽栖未能卜。"]},{"t":"夜宿下郛","f":"五言古诗","c":["我行一山远，云逐一山近。","山山云相逐，何处得幽静。","向来草木深，行者自有径。","古称武陵津，或者亦谩兴。","止止吾且休，冥冥付天定。"]},{"t":"登大庄高山","f":"五言古诗","c":["登山望风烟，四向烈焰红。","遑遑一身穷，且如罝网中。","白日行青天，明明照下土。","下土深几重，不鉴生人苦。","生者良不易，杀之独何心。","万古一哀痛，青山应陆沈。"]},{"t":"兵后过故里","f":"五言古诗","c":["种豆向南陇，秇禾满东菑。","不辞终岁勤，食力在所期。","维时失总御，疆土有侵移。","戎马无定交，彼此更戕之。","稛载已不遗，征责方在兹。","三农舍之去，离析当告谁。","念昔劝垦辟，里胥费言辞。","如何场圃间，满目但蒿藜。"]},{"t":"晨兴","f":"五言古诗","c":["露气旦弥肃，况在山谷里。","秋高草木滋，羃䍥浩如洗。","微茫破云雾，日色上苍翠。","乍寒感时序，向晓念行李。","禽栖尚敛翼，客起方振袂。","风动池上枝，时时听清坠。"]},{"t":"送汤子敏王伯衢由水口暂出流江","f":"五言古诗","c":["二友忽言别，孤怀易成惋。","秋高北风急，日薄众山晚。","迟回各抗手，越历犹在眼。","前旌转崇林，后骑拥脩坂。","庭间怯初散，路缅惊渐远。","离离云树合，泯泯溪流漫。","斯违谅匪遐，同车冀遄返。"]},{"t":"田家","f":"五言古诗","c":["田家住山曲，两两结茅茨。","鸡豚互来往，桑麻当蔽亏。","言笑情则均，动息理无遗。","浑然天之真，岂以物自私。","日入负薪还，斗酒欢相持。","醉卧衡门下，营营非所知。"]},{"t":"水口山居杂兴六首 其一","f":"五言古诗","c":["夙好慕山水，幽寻每忘疲。","兹晨遂栖止，乃在山之陲。","维时属秋杪，万壑敛寒姿。","烟峦既合沓，风磴亦纷披。","窈窕幽谷阴，秀木自成帷。","俯听流泉响，仰看浮云驰。","夐与人世远，允契遁者期。","永言适所性，庶以静自怡。","便当谢城市，去去从此辞。"]},{"t":"水口山居杂兴六首 其二","f":"五言古诗","c":["登楼望危岑，爱此珍木林。","上有好鸟巢，下有垂萝阴。","清风日披拂，可以涤烦襟。","人言此回远，溪水汩以深。","阴壑多龙蛇，山石自嵚崟。","终然未能往，抚槛独沈唫。"]},{"t":"水口山居杂兴六首 其三","f":"五言古诗","c":["山上一茆屋，知是何人居。","时时白云中，閒读古人书。","古人去已远，言论乃有馀。","清风飒然至，佳木周四除。","蒿卧以终日，不知庭户虚。","斯人可相见，此乐当何如。"]},{"t":"水口山居杂兴六首 其四","f":"五言古诗","c":["秋气日以厉，霜露日以繁。","草木各变色，松桂何轩轩。","物生有本性，天运恒不言。","自非闭塞候，焉识春夏温。","乃知天地间，盛衰同一源。","乘时夸毗子，皦皦安足论。"]},{"t":"水口山居杂兴六首 其五","f":"五言律诗","c":["霜降休百工，将以戒寒服。","翩翩蜉蝣羽，时至亦矜束。","我无一株桑，又乏轻骑足。","衣褐何由充，萧条岁年促。"]},{"t":"水口山居杂兴六首 其六","f":"五言古诗","c":["野人省秋稼，引锸决渠水。","秋高粳稻熟，芒穗各垂委。","翩翩山鸟群，啄食秋田里。","驱去还复来，嗷嗷讵能止。","彼饥岂无涯，我稼自兹始。","一饱谅所同，如何较人已。"]},{"t":"病疟述怀六百字","f":"古风","c":["我行兵乱途，远以唁所旧。","遭罹窃自伤，漂落惧莫偶。","今夏入阆川，七月出南富。","秋中上流江，深入穷水口。","是中何岧峣，山密林亦茂。","阴风常夜寒，毒雾或昼瞀。","砭人甚刀镞，袭体惊激透。","当途草木交，压眼崖石凑。","怪禽啼呕?，蝮蛇结缪纠。","其风杂顽戾，土物恣所取。","力作忘春冬，忻忻自鸡狗。","惟我贤所主，好客情则厚。","授衣候寒温，设席墐蓬蔀。","岂知体素弱，易与气为构。","起居陟秋冬，焉得免疏漏。","昨来遘寒疾，猝至纷莫救。","始由欠伸得，更历惊颤久。","夤缘膂脊升，洒淅肌理奏。","汹汹波涛翻，岌岌山岳辏。","初萌冱严凝，挟纩欲蒙首。","中更翕炎赫，撤被更露肘。","噤寒颤齿龈，炽燎薰耳窦。","厌烦将怀冰，恨薄思曝昼。","拳联久僵伏，呼叫忽狂走。","亭亭发上指，屹屹骨交斗。","口咽失常嗜，情性昧初守。","饱疑伤粟粒，渴欲咽河溜。","缩如蚕赴茧，噞若鱼聚笱。","困如虎丧乙，戚若鸟缄咮。","气蒸床屡撼，汗漉衣每透。","暂苏惊脱鞲，久絷疑被扭。","时来如有期，忽去若恐后。","窘迫犹仇雠，缠绵共婚媾。","朋来勉加饭，客至止陈酒。","医师剧攻剿，巫祝妄称咒。","或教潜隙地，或诱祭三牡。","腊蛇谩时佩，画狮空日觏。","逢人畏询问，进食忘腥臭。","何由究情状，且复述粗苟。","人生天地间，六气等蟊寇。","堤防一失所，颠倒竟谁咎。","譬之朝廷治，纲纪在明懋。","昏邪倘蒙锢，赏罚遂纠缪。","周衰始幽厉，商覆由受纣。","夭淫既内讧，狂恶复外揉。","药言苦乖违，国脉焉得寿。","余生三遘厉，此日伤衰丑。","炎荒苦奔窜，木石并黧瘦。","矧兹中年际，盛气难猝复。","客居苟苏息，故里孰侦候。","老妻感霜雪，单薄恒在疚。","幼子额如玉，差差发初覆。","饥寒本吾事，缓急欲谁扣。","指期伤远涉，抚事怨寒陋。","岂知道途者，方此困驰骤。","看云愤重掩，望月愁初彀。","萧萧风鸣叶，揭揭天挂斗。","羸躯既艰植，愁绪焉得剖。","荒村悄寒日，断岸空残柳。","戎马又塞途，归期向何首。"]},{"t":"乙巳正月九日大雪避抄兵由王山将入富田至洞口与家兄相失","f":"五言古诗","c":["惊尘飒南至，妻子哭道周。","出门四山云，欲止安得留。","严风裂我肌，行潦冻不流。","入洞怪崄巇，度岭伤阻修。","风波一相失，咫尺生愁尤。","大哉乾坤内，性命若云浮。","譬彼孤飞鸿，冥冥安所投。","嗒然向西望，泪下不可收。"]},{"t":"兵退由佛原出南富","f":"五言古诗","c":["晓发龙头江，江险绝危径。","跻攀出深窈，曙色破孤迥。","人归闻野哭，雪霁见崖胫。","泯泯泥潦交，稍稍林壑静。","出伤投遽远，返觉行逾近。","稚子识柴扉，相呼入烟暝。"]},{"t":"视西园作","f":"五言古诗","c":["丛篁久刊落，秾李遂摧仆。","芳椒既垂萎，嘉橘亦含蠹。","凄凄杂寒烟，泫泫浩零露。","荒哉中林迹，寞矣西园路。","芜秽独伤新，荣滋重怀故。","抽茨感时旷，植杖勤所务。","岂不戒栽培，眷焉念迟暮。"]},{"t":"忆弟作","f":"五言古诗","c":["永夜不能寐，披衣起彷徨。","念我骨肉亲，三年辞故乡。","故乡不得归，越绝虎与狼。","婉娈抱弱子，远滞湘水傍。","湘水自东来，不见征鸿翔。","念昔遘难初，进退何仓皇。","既兴悼亡叹，旋赋远游章。","田园舍之去，秋草俱已荒。","念子抱耿介，敝褐凋风霜。","心危虑鲜舍，鬓落恐易苍。","徒闻篇翰积，矧婴贫病伤。","维时春泽敷，群卉各扬芳。","翳我手足情，沦落天一方。","载歌常棣篇，具迩固其常。","逝言事堂构，庶以永乐康。","毋徒事游衍，阔绝劳相望。"]},{"t":"伤兄子解辞","f":"五言古诗","c":["植木惧伤枝，枝伤木易衰。","念我犹子逝，主器当为谁。","鞠育二十年，学植方在兹。","一朝陨奇疾，负绝恩与私。","汝母骨已朽，汝妹久流离。","而父理埋葬，念尔衔深悲。","汝有两从弟，季也方孩嬉。","仲也别三载，客游应未知。","先庐故荡析，旧书谁与持。","伤哉珠树林，失此乔特姿。","春风倘重至，见汝当何时。"]},{"t":"赠别严吾敬","f":"五言古诗","c":["客有款我庐，谓言平生亲。","倒屣起揖之，累然翳其巾。","问客此何来，恻怆不能陈。","田园久荒落，道路多风尘。","旧家南山下，存者今何人。","春风入我里，绕屋但荆榛。","念子十年别，丧乱长苦辛。","岂无一尊酒，相与叙斯晨。","良田有丰岁，盛时无弃民。","贱贫不可厌，愿子勤书绅。"]},{"t":"寄题金精山凌云亭为王太守赋","f":"五言古诗","c":["仙女谢尘匹，啸歌云雾间。","一朝乘云去，笙鹤渺空山。","山山翠石盘，涧涧飞泉响。","谁凿洞门开，峰前见仙掌。","虚圆若剖瓜，中抱玉清家。","秋风石岩顶，吹下碧桃花。","桃花不到地，化作云飞去。","紫殿十二重，重重映琪树。","太守骑马来，解鞍憩青屏。","冯虚斲山翠，特起凌云亭。","亭中秋气高，濯雪嗽丹井。","遥空明月上，歘见孤鸾影。","露下白石床，满林金橘香。","绿发垂千丈，秪今馀几长。","忆同姜炼师，载酒跻灵域。","手把女萝衣，题名向东壁。","仙人久相待，重往当何时。","为君扫苔石，更写凌云诗。"]},{"t":"奉酬夏仲寅秋日枉顾见贻之作","f":"五言古诗","c":["早岁去城市，思为山泽游。","茫茫宇宙间，俯视若云浮。","飘摇风尘际，敛迹此林丘。","古道日榛芜，怅然念东周。","鸣鸟乃不闻，禾黍飒以秋。","登高渺四望，谁为千载忧。","客有从东来，盛年著芳猷。","入林践枉顾，维舟成羁留。","贻我丽藻篇，释我心烦愁。","名谊良可尚，荣华安足求。","江湖有箕颍，企子承光休。"]},{"t":"六月自流江返林居","f":"五言古诗","c":["始我去家日，温风临绪春。","兹还大火中，草木浩发新。","念昔罹兵来，庐井屡摧湮。","琴书委泥潦，桑果荡为薪。","悄无鸡犬喧，焉得晤旧邻。","人生岂无营，返故各有因。","譬彼南飞鸟，恋巢心所亲。","永怀事栖止，此里俗固淳。","言笑抚弱子，息偃谢朝绅。","谁为物外婴，而使忧患臻。","天道谅不远，吾行当力遵。","所欣檐间雀，不厌今年贫。"]},{"t":"续悼亡篇","f":"五言古诗","c":["寒暑迭更代，昼夜苦环循。","斯人赴冥漠，一往不可晨。","依依抱恻怆，耿耿衔悲辛。","褰帷怯孤影，入室惊凝尘。","稚子啼不闻，亲戚至莫因。","中庭掩徒旧，虚位设已新。","念昔婚媾初，干戈日踆踆。","荏苒弥一纪，伤哉仍食贫。","昔归恒恨迟，兹感忧患臻。","残月照我膝，凄风复伤神。","彷徨见鸡犬，感叹动比邻。","婉娈闺中秀，今为泉下人。","鼎鼎百年内，谁为平生亲。","如何西阡下，一夕生丛榛。"]},{"t":"续止酒篇","f":"五言古诗","c":["吾恒赋止酒，所止寓言耳。","今日止自公，焉得不遂止。","古人止伊何，所止非一指。","止戈戒残暴，止水戒淫圯。","止言恐伤佞，止得恐伤侈。","所止止非僻，未闻止醪醴。","此止盖有由，止之以资理。","止酤可蠲费，止酿可馀米。","止饮可缮性，止酗可循理。","斗暴与沈溺，便佞而侈靡。","苟不遂止之，祸将甚于此。","抑闻古崇祀，燕飨备嘉旨。","明禋本精意，德将在诚已。","尊卑式隆杀，撙节有定纪。","此时百礼成，止不待刑弭。","止此时则然，尊罍未遑耻。","肺肠谢薰灼，清醒从此始。","苟无忧患婴，饮水亦足喜。","寄谢沈湎徒，吾今真止矣。"]},{"t":"丙午二月一日同仲弟子彦道士陈允宁游金华诸峰","f":"五言古诗","c":["早抱林壑想，而多婴垢氛。","閒来武山下，高挹金华云。","层冈既龙蟠，断垄复瓜分。","一岭忽岧峣，千岩尽缤纷。","维时二月初，淑气澄氤氲。","江上日华动，空中仙语闻。","楼台映海色，泉石超人群。","风含青松响，雨蒸赤霞文。","抚我芳桂枝，兼把芙蓉裙。","愿从广成子，再拜浮丘君。","俯视尘浊区，扰扰蚋与蛟。","高风激六合，逝此杨清芬。"]},{"t":"言怀","f":"五言古诗","c":["处贵恒多惧，居富恒苦忧。","富贵本在天，忧惧日相仇。","煌煌将万金，赫赫封五侯。","一朝将倾戮，徒为鸡犬羞。","逝者何滔滔，鉴之良悠悠。","所以高鶱士，超然谢机谋。","日食止藜糗，所依止林丘。","閒来阅书史，时至事园畴。","允矣聊自嬉，庶无愆与尤。","纵心南山云，濯足清江流。","岂曰昧闻道，四十忽已遒。","庶几后来日，复此成优游。"]},{"t":"移竹舍南","f":"五言古诗","c":["閒居罕人事，植干在丘樊。","谁为斧斤祸，伤哉林木繁。","旧宅已凋落，蓬茅暂依存。","苦无蒙翳资，何以周篱藩。","兹晨春气达，荷锸出前村。","不惜微雨滋，远移脩竹根。","新萌且卷曲，故叶自欹翻。","始分一枝奇，终异千干蕃。","植木既有托，发生良不言。","我惭遗世好，于尔情孔敦。","明当振苍翠，荫我西南轩。"]},{"t":"感旧","f":"五言古诗","c":["我里经丧乱，亲故存者稀。","昨来寻旧溪，径路各已非。","石底塌枯井，草间遗败扉。","因仍十载馀，荡覆兵与饥。","但闻相携去，不见一人归。","寒日下荒原，山水澹不辉。","往事焉得诘，泪下忽沾衣。","独寻古道还，时逢山鸟飞。"]},{"t":"寄汤子敏","f":"五言古诗","c":["芳序倏已判，卉木荣且偕。","念我同年友，怆然动中怀。","昔别冬始厉，波流咽喈喈。","兹游春日妍，顾瞻藐云崖。","操弦叹离索，抱璞悲沈埋。","恻怆不成欢，偃息在东斋。","理契聊自遣，忧来安可排。","人生重合并，时亦暂违乖。","勿以参商故，终当金石谐。"]},{"t":"赠子元龙贡士别并柬刘云章","f":"五言古诗","c":["畸人昧达识，閒居缅良时。","感我平生友，贲然发幽思。","昔别怆徂冬，兹来遂前期。","交交中林鸟，濯濯垂柳枝。","光仪蔚以都，流响一何悲。","运移惕年迈，契合欣道夷。","岂曰郁冲抱，写之在相知。","谁为缁磷尤，式秉金玉资。","苦志谅所存，高风宁独隳。","执手不忍别，扬尘正交岐。","岩构足自栖，食场焉可维。","大江抱群山，流波浩东驰。","旷野日载阳，微阴复凝滋。","人生有显晦，宁受外物移。","寄言谢同志，永以慎于斯。"]},{"t":"题筠雪斋","f":"五言古诗","c":["我昔游云中，爱此万筠绿。","萧萧锦江浒，亭亭凤山澳。","友有宋子者，卜居俯平陆。","虚庭带深窈，苍簳拥森肃。","时维玄冬厉，大雪遍原谷。","脩条与佳卉，狼藉向摧蹙。","维筠于此时，挺拔各在目。","气清神益旺，心远意愈足。","澹然一室间，对此乐真独。","寒光射檐隙，缟素被林麓。","凄凄岁云暮，炳炳情内属。","闭门有高卧，敝履无往躅。","高洁良可希，贫困聊自淑。"]},{"t":"题赠巢云子","f":"五言古诗","c":["古有巢云子，构栖山木中。","淳贞既凋丧，土木穷人工。","一为侈心移，簪绂思华躬。","积宠乃倾危，瑶台成蒿蓬。","所以避世士，永希巢云翁。","浮云本无方，我居宁有终。","凌厉六合间，飘飘若冥鸿。","回视下土方，埃尘方濛濛。","青山几千仞，揽结甘所同。","安得往从之，邈焉仰高风。"]},{"t":"风从窗隙来","f":"五言古诗","c":["风从窗隙来，竽籁声甚扬。","忽起坐听之，宛转谐宫商。","至器本自然，谁能执其方。","天机一振触，止作自成章。","寄谢纤纤手，毋劳更鼓簧。"]},{"t":"秋兴四首 其一","f":"五言律诗","c":["中夜畏烦促，起坐爱凉风。","明月在东壁，流辉当井桐。","翩翩林鸟翔，喔喔邻鸡起。","感时不复寐，短发聊自理。"]},{"t":"秋兴四首 其二","f":"五言律诗","c":["韶华不再返，春去夏亦徂。","玄鸟逝安之，草木浩欲枯。","风高豺狼横，日入禽鸟呼。","独有一尊酒，空山谁与娱。"]},{"t":"秋兴四首 其三","f":"五言律诗","c":["秋至倏十日，客归定何时。","伤哉摇落风，已复鸣高枝。","海水不识寒，穴居乃知雨。","触事苦迟徊，忧端共谁语。"]},{"t":"秋兴四首 其四","f":"五言律诗","c":["少小事文翰，结交尽时髦。","浮云一飘散，寂寂沦江皋。","存没今则殊，宠辱巧所遭。","谁能返初服，永以善自韬。"]},{"t":"见树上浮查","f":"五言律诗","c":["浮查罥高枝，仰视欲数丈。","乃知春时水，更出乔木上。","奔流一赴海，寂寞遥相望。","落日馀悲风，萧萧语寒浪。"]},{"t":"观岸上人放船下水","f":"五言律诗","c":["造舟向平陆，欲动难为功。","一朝集千夫，挽寘大水中。","漂流既无滞，运转宁有终。","始知水力大，可以载虚空。"]},{"t":"酬萧翀怀别见贻之作","f":"五言古诗","c":["久阔易成晚，独居难为欢。","如何天壤间，有此忧患端。","永念昔别日，春花始资繁。","一往落秋风，空闺馀蕙兰。","芳年坐超忽，故物俱摧残。","海水亦已冰，飞霜中夜寒。","沈吟顾俦侣，伤哉涕汍澜。","素丝宁独持，抱璞耻相干。","感子问远动，志愿得少殚。","驰音发孤咏，击节欣众叹。","白日照空谷，玄云起崇峦。","苟怀合并诚，道路谅匪难。","眷言慎初服，黾勉同加餐。"]},{"t":"挽杨子将因乱客袁州后暂还乡复往寓所而卒","f":"五言古诗","c":["昔归已伤迟，再往乃不返。","云萍忽散迹，玉树犹在眼。","高堂念夙昔，群季轧歌筦。","嘉谷森特菀，华星粲孤皖。","凄凄去干戈，窅窅隔丘坂。","至今念行李，何日候还輚。","寡妻负孩稚，弱弟拾遗简。","独不见斯人，谁能不悲潸。"]},{"t":"题春山楼观图","f":"五言古诗","c":["川光媚春阳，岩溜含夕响。","林花间欲飞，江草晴方长。","迢递楼观阴，峰回见仙掌。"]},{"t":"胡侯五子诗","f":"五言古诗","c":["胡侯有五子，祜禧礼裕祺。","五子名各殊，称宗以同辞。","暨乎所命字，实自授经师。","谦诚让谊详，申以伯冠之。","宗以正其系，伯以重其仪。","长字而幼名，立德端在兹。","吾恒登侯堂，见侯鬓如丝。","呼儿出拜客，磊落群熙熙。","祺也年最幼，束发方参差。","见人远相揖，学语声嚅唲。","裕也长于幼，不好弄与嬉。","踉蹡讲论语，光彩浮脩眉。","宗祜最居长，冠裾鸣佩觿。","应门肃宾客，进退何逶迤。","中子禧与礼，充体而丰颐。","粲然玉雪质，并是麒麟儿。","方今重贤良，少壮咸登咨。","有子如五男，奚以多惧为。","子也思顺亲，和乐恒孔宜。","因名以求实，循字以反思。","多福贵自求，所脩慎操持。","天材实国用，授尔百职司。","胡侯有淳政，子孙利其慈。","允为淳政告，视此五子诗。"]},{"t":"赠田观","f":"五言古诗","c":["田观颇淳朴，精神秋水清。","往居西山下，师事凌先生。","先生授之学，心眼豁开明。","苦攻文字间，誓先诸子鸣。","林居涉寒暑，闭户闻书声。","起卧斗室内，超然澹无营。","一朝辞亲去，出门人尽惊。","远从郑文学，司计宁都黉。","跋涉七百里，所冀禄养荣。","升堂揖多士，冠带何峥嵘。","太守见之喜，重是瑶林英。","征租信出入，考稽缓其程。","观也益周慎，戒私甚防兵。","被服大布衣，啜食不糁羹。","阅历三星霜，拮据殆无宁。","山田本硗确，廪积乃见赢。","所以春秋祀，明明奉粢盛。","宪司覈其纲，大府会其成。","议闻升县吏，檄下思返征。","再拜谢官长，远役非所营。","愿求靖安近，得伸孝子情。","苍茫十八滩，滩涩水不平。","浑流杂哀怨，何以濯子缨。","夜来秋雨过，群星正纵横。","念子独不乐，起坐摇心旌。","兹晨别我去，奋袂身欲轻。","岂知失群者，忧思方日盈。","祝子服明训，望子矜疲氓。","万勿为酷辛，庶以善自鸣。"]},{"t":"宴客池亭","f":"五言古诗","c":["饮酒有至乐，乐极不可湛。","愿奉尊禁图，为君警其贪。","斯盘本规制，文理粲梓楠。","阖辟恒虚中，隆址而穹弇。","中画五十行，令条杂周参。","行尾各承窍，运珠随所函。","司令迭进之，盘动珠走龛。","怡然信所值，启视纷雄眈。","旅酬斯款款，大爵何潭潭。","杜觯且浮二，汉酺乃行三。","问奇惧乖应，别类愁误探。","秉烛卜昼夜，飞觞遍东南。","交酢宾主欢，对酒驺从惭。","揖让忽致敬，吟哦遂忘餤。","交传意孔均，自卜情乃甘。","饮或与其免，量仍随所堪。","岂不重酬劝，终焉戒沈酣。","山城淡月夕，尊俎浮飞岚。","刘侯爱敬客，持以慰盍簪。","常思宾筵悔，童羖恐酗谈。","孰知尊禁严，防卫甚铠䤴。","祭遵昔投壶，坐不拥戈锬。","歌咏肃边境，岂在多杀戡。","顾我羁旅中，局促伤忧惔。","欢然及数子，契合如神镡。","下怀将军仁，上感圣泽覃。","乃知太平世，礼乐归濡涵。"]},{"t":"出赣滩读伯友赵君知非藁命同李以庄进士韵题其后","f":"五言古诗","c":["正冠坐方舟，晨诵赵子诗。","风湍忽荡激，感此危苦辞。","古人去已远，来者知为谁。","正音堕空阔，遗响何差差。","桂枝岂不华，天霜肃严威。","春风在中泽，日长蒿与藜。","乘休不得奋，吐气千丈霓。","徒令文字间，勃郁含愤悲。","兹晨岁云暮，矧当违远时。","且复对尊酒，高歌送寒曦。","歌竟不重陈，潜心以为期。"]},{"t":"送孙伯起之镇江司理","f":"五言古诗","c":["昔在朐山尹，为政声甚扬。","朝廷重青籍，铨擢有耿光。","永念赤子愚，罪罟罹披猖。","谳覆苟非人，终焉阽危亡。","东南有大郡，地广滨海洋。","岂不繁狱讼，擢尹推丹阳。","维时大火中，暑炽日正长。","上吉祖东门，沥觞理行装。","候吏千里至，得诹民俗康。","矧兹服先声，恶伏善且彰。","政方实多岐，所先在慈祥。","庶见囹圄空，秋芜卧桁杨。","惟君伯仲间，济济充周行。","卓彼仪真守，飘飘云锦裳。","摇摇江上波，两两发征航。","邦人共嗟讶，符绶相辉煌。","汀云槐柳深，夕雨菰蒲凉。","仕邦乃相望，何异家与乡。","永念幽谷士，抱书迈年芳。","送行重言赠，敢以诚自将。","舞文戒吏胥，操纵成条章。","无刑乃至理，庶用登虞唐。"]},{"t":"自兴国过宁都度黄竿竹岭险甚","f":"五言古诗","c":["客行青塘岩，却望黄竿岭。","陂陁缘大麓，嵽嵲陟孤顶。","蹲身事潜行，俯仰立梯井。","灌丛方截辕，巨石忽树屏。","冥冥日脚昏，瑟瑟风力紧。","但闻阴壑呼，不见行云影。","仆夫筋力尽，悽怆助悲哽。","荆棘罥手足，跬步不得骋。","虎狼恐奔突，魑魅或骄逞。","怪禽当我啼，毛发竖寒㾕。","常时山下民，攘劫玩官警。","杀人委溪洞，椎宰肆庖鼎。","时平向置砦，恃险益顽狠。","反思二水上，道路何炳炳。","坐贫昧艰危，欲速烦虑省。","但伤游子魂，日夕更忧怲。","安得刬高崖，连山豁畦町。"]},{"t":"答赠王子启","f":"古风","c":["晨得故人书，握发再三读。","缠绵数百言，肝胆豁倾覆。","上承起居问，下感进脩勖。","虽劳鸿燕思，且慰泥涂辱。","去年所寄诗，徵我当和复。","谫材本迟钝，往报愧不速。","置书怀袖间，汗出颜腼恧。","永怀通家好，先世辑姻睦。","呜呼我大父，文雅动季叔。","追惟所自出，实本王氏族。","风流齐阀阅，情谊均骨肉。","兔丝附长松，柔弱易摧蹙。","矧我后生辈，疏略坐拘束。","饥寒役道路，时序少攀属。","缅思老成会，光景同转烛。","每过城西隅，低回怆心目。","时寻贤者居，邈在?湾曲。","方畦带寒蔬，斜径出脩竹。","升堂奉甘旨，宴客湑醽醁。","委蛇伯仲间，颜色何婉郁。","往时客南浦，公馆蕃乐育。","学子来趋风，簦笈奋远躅。","襜襜讲帷侧，济济森立玉。","敷扬六义旨，骈叠雅颂录。","咏歌逾金石，剖析见丝粟。","似闻厌尘鞅，欲访匡庐麓。","重湖涉深渺，把卷面飞瀑。","云林固深窈，问学伤寡独。","岂必远人群，终然起岩谷。","贱子罕所谐，微陋等朴?。","偶从将军幕，未决詹尹卜。","老亲困痹疾，稚子抱寒瘃。","内顾环堵空，何以甘藿菽。","筠阳近留滞，风土渐谙熟。","锦水流郡西，闾阎散平陆。","长云亘浮梁，车马竞驰逐。","风激仙洞凉，江浮凤山绿。","苏扬遗赋咏，草木含清淑。","至今民俗淳，守业不出屋。","反思好游子，奔走何碌碌。","故园久芜秽，荷耒思穜稑。","轩裳苦乖违，农圃岂污渎。","勉意慰所亲，志愿在昔夙。","感君同心言，义重秋兰馥。","抽辞酬远意，焉得不醇笃。","扬矣合并期，悲歌睇鸿鹄。"]},{"t":"题西山五仙图","f":"五言古诗","c":["西山多仙灵，往往宅幽阻。","飘然不可招，作者焉得数。","昔在汉晋间，凌厉出梅许。","伟哉忘机士，泯迹事纳吐。","千载仰高风，谁能究其绪。","披图觌古像，先后得四五。","苍茫越王山，飒杳文绣虎。","陈陶终市药，伊业解歌舞。","把卷识肩吾，曳杖知蕴古。","神情各冲逸，簪褐杂襦裋。","观其英迈姿，宇宙一仰俯。","超遥云中物，安得系缨组。","佯狂或玩世，精鍊得无补。","终然委大化，岂必事矫举。","吾恒登鹤岭，览胜睇玄圃。","长松夹皓月，阴壑振清羽。","药庐与丹井，一一恒历睹。","独不逢若人，高怀竟谁语。"]},{"t":"奉答丁克诚拟古四首并各因其首句云 其一","f":"五言古诗","c":["昨者去如箭，去者焉得追。","今晨复不念，无乃甘弃遗。","孳孳孔尼父，老至忽不知。","赞易著自强，昭若星日垂。","泉流当达海，落叶宁返枝。","圣狂本一念，所异公与私。","永言惜去日，鉴此川上辞。"]},{"t":"奉答丁克诚拟古四首并各因其首句云 其二","f":"五言古诗","c":["谁将宝瑟弹，逸响故超绝。","得心应之手，有口焉得说。","宫商谐律吕，高下本定列。","至音不自发，假器以舒泄。","徇名而求声，惉懘乃乖劣。","怀哉葛天民，为我陈一阕。"]},{"t":"奉答丁克诚拟古四首并各因其首句云 其三","f":"五言古诗","c":["秋月白且凉，金风豁森爽。","铮然高林叶，坠地不复响。","感君平生言，慰我清夜想。","揽衣起彷徨，秉烛增叹赏。","允怀江海观，敢怠泰华仰。","古人在当日，政亦企前往。","末予疲钝资，焉得中脱鞅。"]},{"t":"奉答丁克诚拟古四首并各因其首句云 其四","f":"五言古诗","c":["幽兰湛秋露，远系君子思。","繁华逐飘风，乃以色见知。","春阳无悴容，冰雪有令姿。","感物固贫贱，反躬服芳菲。","鹿鸣咏好我，永谢贻令辞。","愿言慰离别，勖德此其时。"]},{"t":"题筠轩","f":"五言古诗","c":["修竹夏向深，层轩昼逾静。","沈沈幽荫交，洒洒众绿净。","微风枕簟入，落日琴尊并。","揽枝发清啸，抚节延孤咏。","怅望生夕霏，幽期在萝径。"]},{"t":"题枯林墨兰","f":"五言律诗","c":["山中石累累，百草寒不芳。","猗兰如高人，迹隐名愈扬。","我欲采其英，系之芙蓉裳。","林深路回窈，伫立以彷徨。"]},{"t":"题兰雪斋","f":"五言律诗","c":["阴岩冻欲敛，芳颖寒初破。","回风汎纤绿，时见白粉堕。","援琴不复鼓，委佩空沈吟。","掇此花上雪，比君尘外心。"]},{"t":"壬辰感事六首 其一","f":"五言古诗","c":["生长承平日，乱离非所知。","垂髫读史书，痛彼艰危辞。","儒绅谢徭役，生理固云夷。","虽无二顷田，亦不蒙寒饥。","岁时洽亲故，聊厚相娱嬉。","出门不赍粮，四达随所之。","万里若户庭，道路方伾伾。","牛羊被原野，桑麻翳边陲。","四方绝争斗，兵寝城亦隳。","积薪而厝火，治道乃日亏。","理乱自相乘，谁欤启猖披。"]},{"t":"壬辰感事六首 其二","f":"五言古诗","c":["猖披者谁子，昉自邪说兴。","香火崇幻教，肇彼有发僧。","其源始涓沥，弗遏终沸腾。","宜阳一倡乱，和者纷驾乘。","赭巾忽充道，杀戮相凭陵。","蔑法恃妖谶，江淮竟先登。","古来心腹地，广衍昔所称。","乃知为厉阶，不在凭丘陵。"]},{"t":"壬辰感事六首 其三","f":"五言古诗","c":["汝颖始媒蘖，徐沛乃蜂起。","浸淫及荆湘，浩荡入彭蠡。","风摇草木动，杀气薄炎纪。","仓皇九江守，血战扼孤垒。","海门白日暝，烈士先斗死。","雄波失天堑，北舸竟南舣。","我师岂不锐，势奋易披靡。","叹息江之流，艰危欲谁倚。"]},{"t":"壬辰感事六首 其四","f":"五言古诗","c":["豫章屹孤城，出战当水背。","退移石头渡，桥绝偶奔溃。","红尘蔽江水，白昼惊惨昧。","呼号振渊鱼，山石忽破碎。","桓桓章将军，勇锐百夫倍。","登城一指麾，奋击出前队。","戈船久遮列，坚壁方拥对。","堤防蓼洲急，控扼龙沙会。","自断忽纵燎，危哉岋蓬块。","斯人盛经济，兵略众所戴。","肘腋将弗支，谁从振其匮。"]},{"t":"壬辰感事六首 其五","f":"五言古诗","c":["寇移石头渡，南掠乌山驿。","新吴与修水，变起何络绎。","长驱逼筠阳，守者亦坚壁。","连云忽倾陷，烈焰半天赤。","猖狂府中坐，惨酷肆脔磔。","艳媚妇女群，烂熳金帛积。","倒仓散游惰，夺印援凶逆。","坐令荷耒民，反戈半红帻。","人情苦惶惑，王事方否隔。","摧廓谅匪难，煌煌济危策。"]},{"t":"壬辰感事六首 其六","f":"五言古诗","c":["庐陵古名郡，繁盛何雄哉。","井邑十万家，一炬同飞灰。","寇来背南岑，豕突势莫摧。","白昼呼市中，城门四边开。","居民望南走，千步不一回。","官马如流星，绝桥窜山隈。","府中方缮兵，填委粟与财。","我粮寇之资，我兵寇之媒。","一罅弗自谨，致此千丈颓。","向来阛阓区，赤地生莓苔。","慎勿东望之，茫然使心哀。"]},{"t":"出南门","f":"五言古诗","c":["送客出南门，客行苦踌躇。","前有血流地，暴尸临路衢。","借问守关兵，云是妖贼徒。","往者东西乡，啸聚如群狙。","跳梁恃山谷，根结未易锄。","潜行巧阚伺，动与鬼蜮俱。","官中急召募，捣穴将扫除。","往往禽捕之，束缚来献俘。","械系置庭下，诘问非枉诬。","每戮三审之，仁哉贤大夫。","岂不愤彼逆，终然恻其愚。","先时获游谍，揭竿枭首颅。","州人食其肉，刌剔无完肤。","嘉禾化稂莠，红紫竟乱朱。","下为人所忍，上干天所诛。","吾闻圣人教，伐恶仁之符。","一奸伏刀踬，万姓安其居。","官军北来近，此辈沟壑馀。","行者勿怆恻，黾勉慎所趋。"]},{"t":"赋白马祠送曾照磨领兵防龙泉寇","f":"五言古诗","c":["将军骑白马，朝出西门道。","初日射旂竿，秋风动原草。","问君此何之，鞍马甚光仪。","新承大夫命，去逐红巾儿。","笳鸣武溪曲，鞭指石州路。","手持白羽箭，却射林间虎。","深行五十里，提卒三千人。","定摧中军帐，独清西北尘。","丈夫誓杀贼，老剑耀如雪。","箫鼓城南楼，归来宴明月。","送君白马祠，因吟白马篇。","殷勤折杨柳，赠比珊瑚鞭。"]},{"t":"和全参政别王照磨至刚","f":"五言古诗","c":["惨恻壮士别，哽咽止复说。","妖尘污后土，臣子愤所切。","扬威激骁勇，振义戢顽劣。","差差战飞霜，屹屹壁立铁。","崆峒兀危倚，章水不可越。","舳舻亘缥疾，旌旆森侧叠。","熊罴方蓄锐，蛇虺政蟠结。","由来国中士，当作天下杰。","轩轩扫霾雾，炳炳揭日月。","侧闻王师至，冠盖相填接。","双江波涛急，浩荡壮心折。","往者靖四隅，屡战非小捷。","何由濯炎酷，万里洒飞雪。","永慰涂炭民，呻吟化欣悦。"]},{"t":"陪王珊克温薛益伯谦王睿王佑严焕夜宴焦瑜宅看薛舞剑分韵得深字","f":"五言律诗","c":["高树凉风下，丛兰夕露深。","宾客集高馆，遥怜当别心。","起舞出古剑，回歌罢瑶琴。","焉知夜寥阒，清赏豁烦襟。"]},{"t":"赠州掾李复亨","f":"五言古诗","c":["李君青原英，早辟此州掾。","遭时极艰虞，酬酢周万变。","轩昂七尺躯，磊砢出群彦。","摅词犹转丸，制胜若激电。","以兹悟贤侯，允矣获深眷。","请从去年说，从事实展转。","寇兴自淮河，焚劫遍㝢县。","仓惶蹙大府，闻者惊战眩。","我侯力区画，建义急防援。","戈矛首奋勇，城壁次修缮。","视民勿惊畏，出入兼守战。","当时筹帷幄，裨益总优衍。","慅慅西土氓，啸聚郁相煽。","侯曰往靖之，君时实在遣。","高冠晨簪笔，轻骑夕鞬箭。","落日猿狖号，石门路如线。","摧凶意已决，拥槊身独先。","我兵偶失利，蛇虺纷纠缠。","愤呼突重围，脱兔不可罥。","生还趋进讨，汛扫何捷便。","矧怀疾恶心，直道昭烂炫。","奸攘速夷戮，仇狱谢贿眩。","温温自盈拱，凿凿真百鍊。","从容就三考，著绩伟自见。","或同文子升，偶遇于公荐。","青云一攀附，腾趠超紫燕。","汉史徵循良，终言托佳传。"]},{"t":"承邓子益黄树之作依韵奉答","f":"五言古诗","c":["客愁如浮云，沓至不可扫。","日闻寇盗急，战士何草草。","岂无鹰扬勇，未奋鼠穴捣。","经年数避地，贵贱沦丑好。","嗟嗟邓孝廉，尽室窜鸟道。","天寒拾橡栗，日晏揽蘋藻。","头额谢焦烂，裳衣剧颠倒。","百年侍郎宅，故物粲可宝。","烈焰白昼飞，伊谁得探讨。","庭前花竹区，漫与瓦砾槁。","昨投柘黄村，母子慎完保。","低头狎樵牧，徒跣接猺獠。","昼行岩下蹊，夕宿溪上岛。","荒山少邻并，木石藉围堡。","春阴蛇虺出，簸荡汨行潦。","鹰鹯苦未击，云霓蔽晴昊。","平生忠义槩，知子是素抱。","惊承黄树作，再诵豁忧恼。","东归定何日，漂泊伤潦倒。","正士惧摧残，如何问穹昊。"]},{"t":"答曾同升见语","f":"五言古诗","c":["沿崖入深谷，群木罗秋阴。","泉响一何幽，岩栖有鸣琴。","已欣人迹遥，恒恐尘虑侵。","愿持白云操，一写高世心。","骅骝厄盐车，局促上峻坂。","长鸣悲风生，惜此白日晚。","时哉一纵辔，造父未能挽。","荡荡轶浮埃，天门望中远。"]},{"t":"凶年民有弃子于江者诗以寄哀","f":"五言古诗","c":["骨肉岂不亲，无食难为恩。","抱子弃水中，哭声吐复吞。","母饥骨髓枯，儿饥眼眶出。","终然两存难，何以共忧恤。","岁月不相贷，恩爱从此分。","我死尚可忍，儿啼那复闻。","儿啼那复闻，江水流浩浩。","不忍回视之，衔悲入秋草。"]},{"t":"送孙景贤归江东","f":"五言古诗","c":["客有敬亭思，春愁何渺然。","谢公楼前月，已照江西船。","船头花乱飞，酾酒发鸣鼓。","四顾不成欢，悲歌泪如雨。","壮游南海上，曾著从事衫。","骢马青连钱，驰突开巉岩。","南归阻寇乱，寄食赣江侧。","多谢尚书公，看客好颜色。","高筵列绮馔，宾客如流云。","舞剑万人却，谈兵四座闻。","年华逐流水，五见杨柳绿。","夜夜梦故山，浮云满岩曲。","兹行未可住，却望江东还。","人散井邑空，鸟啼烟树间。","殷勤候高堂，次第访邻里。","山栗与木瓜，离离照烟紫。","放舟弄明月，蹑屐凌紫微。","春风久相待，吹老薜萝衣。","南平三月暮，惆怅忽成别。","把臂重论心，知君有奇节。","东游我所愿，远作秋风期。","却携采石酒，高咏敬亭诗。"]},{"t":"送萧一诚赴万安教谕","f":"五言古诗","c":["闻君戒行装，去领万安学。","征舸已载书，离筵更行酌。","春还野色迥，日入川光薄。","悠悠水上凫，矫矫天际鹤。","寇垒尚连戈，边防正鸣柝。","千村少烟火，百里到县郭。","古来重庠序，乱后馀殿阁。","绿野一榛芜，青衿半荒落。","师承岂无待，教立将有托。","山水舜祠深，端期听韶作。"]},{"t":"赠医师任光显","f":"五言古诗","c":["我非金石资，敢与寒暑俱。","岂不慎所爱，苦以贫见驱。","昼行冒炎赫，暮宿蒙沾濡。","短褐不自温，藜藿兼秕稃。","外邪或乘间，内扃焉得虞。","乃者春夏交，伏暍卧衡庐。","俯仰一日间，气候乃顿殊。","厝火愤惔烈，抱冰增郁纡。","对案不能餐，呕哕闻喑呜。","亲友来问疾，药物审所须。","交辞赞其贤，里有任大夫。","祖孙已再世，诊候明机枢。","入门即闻望，审疗穷锱铢。","药液制鍊精，再啜气已苏。","诘朝谢枕席，体胖心孔愉。","怡忧古所戒，惩创以嗟吁。","永怀药有神，如以水沃枯。","至人岂衔报，感德在我徒。","毒疠济不仁，疮痏困夷诛。","安得四海间，皆君起羸痡。"]},{"t":"赠画师刘宗海","f":"五言古诗","c":["寇盗馀五年，山林一憔悴。","刘君最英发，笔墨有生气。","苍然祁郑间，见此丧乱际。","拔足自踰尘，师门本罗氏。","聪明破溟涬，飞动入玄契。","总角解挥涂，老成兀超异。","高堂敞轩豁，图画入苍翠。","纷披烟雾舒，晃朗城邑丽。","霜禽晚更净，水木寒不坠。","翩翻毛翮分，的皪花果碎。","江沙隐舟楫，山雪带远骑。","潇湘乍微茫，衡霍忽丛萃。","冥冥开古色，漠漠浮远势。","东南半天下，屏障光溢视。","遂令购求者，尺璧不敢贵。","相逢苦漂泊，泽国春正媚。","口诵名诗文，磊落倾腹笥。","穷途偶羁客，绝艺终名世。","岂必怀古人，艰难发深喟。"]},{"t":"杀蛇篇","f":"五言古诗","c":["蛇虺各有穴，合在岩谷陬。","明明庭宇间，岂尔之所游。","灵蟾无爪牙，草宿甚优游。","尔乃攫食之，吞噬不少休。","嗟尔毒螫性，吐燄若火抽。","潜乘夜色暝，巧伺人迹幽。","触草或尽死，杀人甚戈矛。","恻恻仁者心，嫉之若仇雠。","奋挺往击之，妖言焉得留。","首毙文锦裂，钩尾委不收。","观者愤稍抒，蟾脱金背浮。","呼童出弃此，转置湖水头。","犹恐毒流波，瘗之向崇丘。","念昔大禹治，驱蛇菹泽投。","叔敖患两首，阴德跻公侯。","圣哲忽已远，草木塞道周。","纷纷蛇蜮交，毒疠遍九州。","养虎方刲豚，食狼乃刳牛。","彼哉独何心，良善生怨尤。","我歌杀蛇篇，歌竟泪自流。","为此乃旷逵，古人谁与俦。"]},{"t":"赋青简所送邓宪史南台","f":"五言古诗","c":["肃肃青简所，粉署若秋霜。","闻君将去此，远赴柏台郎。","驱车临广陌，沈忧结离觞。","青云正岧峣，黄鹄方高翔。","还念同居者，湖阴看月光。"]},{"t":"奉和右丞廉惠山凯牙喜雨诗","f":"五言古诗","c":["亢阳閟时泽，赫欲槁众绿。","台衡忧民心，惴惴甚集木。","一朝注甘澍，允矣生百谷。","堂邑歌既零，南山咏沾足。","向来击鸣鼓，望祀走巫祝。","孰云丰年迟，永念诚感速。","广陂润方流，酷炎势已蹙。","省署扬清风，薇花濯红玉。","民情洽和畅，天意划清肃。","庶草徵则同，时哉念蕃育。"]},{"t":"题太古斋为刘政卿赋","f":"五言古诗","c":["士有希古者，端居在衡茅。","鸣琴既无谱，酌酒亦用匏。","气淳语言朴，其俗自不浇。","誓将木石俱，永谢时世交。","垂裳可为理，游麟方在郊。","独往思见之，怅然歌有巢。"]},{"t":"旷伯逵移花竹石盆","f":"五言古诗","c":["慈竹绿而贞，慎草青以润。","披纷瑞香蟠，纠屈栀子韧。","蓬然出众美，生意各欣振。","虚庭荫深广，烈日光不瞬。","泉石涵清妍，盎盆陟崇峻。","移床坐其侧，凉吹飒两鬓。","重门掩苔藓，尘迹戒蹂躏。","赏幽君子心，席地频洒汛。","茗瓯既己陈，酒盏焉得摈。","高情寄林壑，乐此乐无竟。","我惭去田园，畏暑剧焚烬。","抱瓮息林阴，还思问田畯。"]},{"t":"赠曾沂画山水诗","f":"五言古诗","c":["山水有雅趣，绝艺固难名。","翩翩沂水生，皦皦高世情。","观其笔墨间，颖悟契天成。","况复师名哲，挥洒欲纵横。","我有林壑兴，回车谢遐征。","怅言事求志，结好在柴荆。","恋恋返桑梓，依依寻耦耕。","驱牛涉晚涧，坐石闻春莺。","茅檐有浊酒，思就野老倾。","风尘正萧瑟，念此心频惊。","感君作图意，慰我南征程。","卷之怀袖间，离思浩方盈。","赠言匪谀溢，愿子垂休声。"]},{"t":"过顺流口寻归舟不见留寄旷伯逵","f":"五言古诗","c":["居人惜离别，行子念归路。","牵衣苦徘徊，酬酢乃烦屡。","岂知风力便，徒侣惜迟暮。","孤帆竟先发，江永不可渡。","登高望前湾，欲往复回顾。","令我行踯躅，感君郁情愫。","去翼安可招，苍苍但昏雾。"]},{"t":"题带经亭为旷伯逵赋","f":"五言古诗","c":["时雨度原陆，我俶事耦耕。","晨兴荷锄出，于道非所营。","古人邈以远，遗言粲昭明。","岂不念周览，力穑自有程。","携书徂畛间，卷舒契深情。","息偃林樾下，放歌激商声。","皤皤东邻叟，来问所读名。","作者安在哉，所为竟何成。","谁能舍耒耜，坐致仓廪盈。","掩卷谢邻叟，此道久榛荆。","圣哲本不死，我宁昧所生。","且复具尊酒，相对得共倾。","陶然亦径醉，春鸟方和鸣。"]},{"t":"赠萧自愚炼师","f":"五言古诗","c":["填海衔木石，移山开路衢。","既怜精卫苦，复笑愚公愚。","扰扰六合间，机械纷奔趋。","岂知大智者，敛之寂若无。","缅彼白鹤仙，昂藏一丈夫。","冲抱龙虎气，清含山泽癯。","炼药入紫霞，吹笙上玄都。","逍遥青天中，湛寂以自娱。","我欲蹑其躅，飘然安可呼。","永怀伯阳翁，握此玄化枢。","毋为事辩巧，取愧斯人徒。"]},{"t":"所闻","f":"五言古诗","c":["客谈所闻者，我亦闻所闻。","翕忽片言间，源委焉得分。","当时初闻时，心绪相纷纭。","汹如春江涛，汎若秋空云。","肝胆不自持，反复贻戚欣。","岂知无闻者，兀兀穷朝曛。","起揖谢上客，慎勿云所云。","我心久冥漠，无以置斧斤。"]},{"t":"避寇宿岭下田家","f":"五言古诗","c":["攘攘忽超岭，冥冥遂投村。","不知来远近，但见行者奔。","风起草木动，牛鸣人语喧。","妻子局道隅，泪下声吐吞。","老翁墙头看，为我启重门。","掬泉沃烦热，坐我林竹根。","稍觉颜色定，岂知心魂翻。","兹行寔仓卒，感君言貌温。","平生亲与友，此日焉足论。"]},{"t":"过周宜冲林居","f":"五言律诗","c":["幽人系遐思，散策欣往即。","圳南秋水落，行踏涧中石。","离离数青松，远荫林下宅。","落日在柴门，清风满蒲席。"]},{"t":"送谢君寿归豫章","f":"五言古诗","c":["谢君芝兰秀，玉立含春温。","昨从钟陵来，过我江上轩。","临流一解佩，坐石倒芳樽。","时序浩若流，霜露忽已繁。","怅然念归路，孤雁同翩翻。","城西昔栖隐，旧宅今不存。","采药度沙屿，悬壶当市门。","隔水望西山，翠屏矗云根。","逝此安可觌，清风怀笑言。"]},{"t":"述怀一首别表兄严允升之兴国","f":"五言古诗","c":["我始束发时，出居城东郛。","兄从濠上来，青裾如短凫。","父母共爱惜，两两相携扶。","读书本不多，颇好弄墨朱。","暮拾草上萤，晨探花间雏。","缀文暗矜衒，学字缪拟摹。","登床夺砚笔，入室窥庖厨。","诟怒或暂违，欢欣复同娱。","时来饮美酒，终不事樗蒲。","俱为乡党怜，自许如联珠。","稍长各辞家，东西趋道涂。","饥寒两契阔，千里长睢盱。","论心怆无梦，揽镜觉有须。","岁时骨肉聚，俯仰亲情俱。","我父寔尔舅，尔母为我姑。","十年递倾逝，顾影怜羁孤。","嗟尔前年春，妻子复殒徂。","空庭閟白日，苔藓生檐枢。","尔兄亦早丧，有子居僧庐。","削发岂高士，承宗寔良图。","去年避兵难，闻窜五岭隅。","归来见颜色，窃喜雉脱罦。","昨聆遘寒疾，服食幸少苏。","所依弱妹存，亦苦贫病拘。","如何便诀绝，孑孑复远趋。","山雨晴少泥，林华正纷敷。","紫燕亦高飞，春城沸笙竽。","我惭识字来，奇蹇多忧虞。","所以遁幽谷，远从耕钓徒。","兹晨怅言别，有酒得更沽。","感激少小怀，临分重蹰踟。","五月蒲艾香，九月有菊萸。","故园恐芜没，归候焉得逾。","武姥泉石嘉，远驾尚可纡。","庶慰同心契，慎保千金躯。"]},{"t":"题山水画","f":"五言古诗","c":["群峰矗青屏，邈在云雾中。","逶迤临广川，杳矫凌高空。","太阳旭朝升，霞彩烂青红。","草木石上生，流淙挂寒虹。","突若汎水鳌，背负蓬莱宫。","我欲登览之，云深路难通。","恍然对图画，思访商山翁。","蹑屐行紫苔，舣船并青枫。","凭高思无极，引咏送飞鸿。"]},{"t":"见家鸭浴于堂㘭感赋","f":"五言律诗","c":["凫鹥浮江湖，万里可适意。","㘭涔濡家鸭，振洒空作势。","人生天地间，穷达同一世。","悠哉赋命初，岂不系所值。"]},{"t":"夏日同欧阳仲元罗子理邓崇志会饮林屋得紫字","f":"五言律诗","c":["幽居带林皋，烟草共墟里。","两日不相承，鸟啼春竹紫。","川平雨初集，日落风更起。","怅望城市遥，青山隔流水。"]},{"t":"怀万德躬","f":"五言古诗","c":["万生江海士，蚤志在经术。","贤网失雄奇，低垂向蓬荜。","豪吟高李间，盛世宜作述。","光华丰城剑，洋溢清庙瑟。","霄汉未有期，风波乃相失。","今年赴大庾，华发映初秩。","名高乃为累，退伏惧谗嫉。","维时三月初，上道戒吉日。","江发南云长，帆开北风疾。","停舟一相过，取别伤草率。","岂不念平生，衷怀讵能诘。","维南苦凋瘵，民情甚回遹。","治棼古有戒，何以布章律。","秋风渺鸣雁，赞佐在轸恤。","妻孥隔异县，岁晏悲蟋蟀。","微生且漂泊，吾道在否塞。","怀哉南川隐，千载竟谁匹。"]},{"t":"六月晦日山下观稼归","f":"五言古诗","c":["东日出未熹，我兴事晨稼。","莽莽逾广阡，悠悠至山下。","良苗各已实，载穫纷䆉稏。","流泉荫馀亩，束穧归南舍。","柴门日向夕，鸟雀喧已罢。","老翁携壶至，言笑相慰藉。","春作幸有成，明当戒秋社。"]},{"t":"题钱氏贞节堂","f":"五言古诗","c":["织素伤断丝，汲井伤短绠。","百年不偕待，逝者悲耿耿。","空闺凝芳尘，白日惊寒景。","独携嫁时镜，坐照孤鸾影。","孤鸾镜中老，雏凤方和吟。","何以慰母勤，山海匪高深。","苍苍千古石，烂烂百鍊金。","惟应诸源水，鉴此贞节心。"]},{"t":"早行雾中过田家失道","f":"五言律诗","c":["我行烟雾中，不复辨原陆。","幽幽闻鸡犬，隐隐见松竹。","田家迷远近，阪路有崎曲。","已觉瞻望劳，谁云往来熟。"]},{"t":"感时和王以方","f":"五言古诗","c":["雾雨晦平陆，穷林翳清秋。","众鸟各喧嚣，孤鸿独怀忧。","矰缴方可虞，稻粱焉得谋。","塌翼堕中流，泛然若遗舟。","屯云蔽白日，泽国生暮愁。","飘飘竟何适，莽莽奚所求。","且复敛踪迹，栖遁此林丘。","时哉周周遇，可以衔羽不。"]},{"t":"题严氏东园","f":"五言古诗","c":["里有严氏族，昔维孝友门。","大厦连高云，江波下流奔。","我识秘书孙，令质何温温。","行年踰六帙，苍鬓雪不翻。","冠裾肃其仪，恒以诚自存。","族处三百年，清风望弥尊。","燕游有别墅，近在城东园。","永念昔贤居，乐此竹与萱。","兹晨天气佳，风日丽崇轩。","秩秩叙宾友，怡怡从弟昆。","图画既罗列，醪醴亦满樽。","至乐恒未央，世事焉足论。","眷惟此流庆，宜尔但高言。","群翁有述作，来者宜勿谖。"]},{"t":"忆邓子益","f":"五言古诗","c":["翔风振层冈，日出林鸦散。","故人不可见，对酒发长叹。","昔别惊苍茫，新愁复零乱。","栖迟岂沦逸，才美宜卓冠。","伤哉岁年暮，之子实国干。","有兄承家学，足以资考赞。","泣把海上书，去年入东观。","秋霜肃群木，万里消息断。","念彼孤飞鸿，凄然度云汉。","遥知当此夕，沈吟出虚馆。","上堂候甘旨，綵服故明烂。","江亭春风远，水涩冰未泮。","中州烟雾集，群宿起鸣鹳。","我怀实悁结，徙倚至夜半。","仰视天宇高，明星复东粲。","况兹当远征，展转遂达旦。"]},{"t":"送邢秀才之南海","f":"五言古诗","c":["骅骝蹑层云，振鬣可千里。","岂有贤达人，低头恋妻子。","买臣未返越，季子终去秦。","上策干君王，抚剑清风尘。","英英邢茂才，三十沦草莽。","长笑别中原，驱车事南往。","梅关积雪白，大海瘴雾深。","穷冬在远道，念子多苦心。","维南峙藩城，五岭树旌节。","得子先群英，清风濯炎热。","我留山县久，感此霜露馀。","遥遥不可攀，羡尔南飞鱼。"]},{"t":"病起理发","f":"古风","c":["卧病七十日，我发如毡茵。","沈绵旷时理，卷郁乃不伸。","徒蒙垢腻积，虮虱来相亲。","?咂无遗肤，搔之反纷缤。","兹辰风日佳，隐几支羸身。","梳栉试剪摘，洒洒开风尘。","蓬然满其梳，易若振槁榛。","恒恐自兹始，种种空轮菌。","傍有笑且言，子何昧所因。","四序一气尔，荣悴若环循。","凋零岂不秋，萌蘖方复春。","不见柏与松，相承为旧新。","矧子属壮强，盛气方向晨。","六淫戒侵慝，所养贵得均。","肤革苟充盈，宁伤发生仁。","兹言颇有契，我志岂遂沦。","被衣衡门下，反视怡心神。","微风从南来，且复正葛巾。","晞之跂阳阿，庶以怡天真。"]},{"t":"赋龙沙赠友人别","f":"五言古诗","c":["朝出城北门，遥见城下沙。","簌簌鸣北风，萧萧入人家。","坡陁浩如雪，漫漫不可越。","水落黄金澄，天晴紫烟灭。","别君沙下亭，逝此歌扬舲。","春来倘相忆，芳草是中青。"]},{"t":"检故箧中得亡儿觭所服药裹赋以致悼","f":"五言律诗","c":["汝葬已在野，汝药尚在笥。","当时閟神功，事往一流涕。","神仙岂不死，海上多奇方。","俯仰犹昨朝，呜呼今则亡。"]},{"t":"题牧牛图","f":"五言古诗","c":["清晨跨牛出，日暮吹笛归。","草野不逢人，田乌相逐飞。","山中有风雨，蓑笠莫教迟。"]},{"t":"赋别南涧诸友人","f":"五言律诗","c":["岁杪无淹晷，归人滞山居。","兹晨复不发，明日当岁除。","宴会良已勤，愁思独不舒。","愿回投辖意，一解送行车。"]},{"t":"舍弟往三㘭岭寻觯子日夕未归坐候林下","f":"五言律诗","c":["西林已鸡栖，北涧复虫响。","沈沈四山暝，寥寥一星上。","时危剧钟情，期逝劳纡想。","怅立此溪阴，欲休未能往。"]},{"t":"分韵得一字饯别张彦昌赴豫章","f":"五言律诗","c":["君行赴豫章，燕饯在兹日。","短剑出匣双，轻舟泛江一。","峡深霜猿苦，天阔云雁集。","酒尽不成欢，南瞻恍如失。"]},{"t":"和答萧伯玙","f":"五言律诗","c":["客有鹤上侣，巢云松桂林。","秋风夜中发，相思烟水深。","青鸟从东来，惠我瑶华音。","援琴不成叹，徒劳千里心。"]},{"t":"题黄氏三馀斋","f":"五言古诗","c":["天地有明晦，阴阳互始终。","人心蕴至理，妙运焉可穷。","端居淡无营，肄业肆旁通。","陶以典籍富，积之道义充。","春作肇有严，夙兴在省躬。","日入未遑息，岁周方底功。","良辰风日妍，游咏从冠童。","矧当阴雨交，而敢怠击蒙。","混混循化机，渊渊湛天衷。","及时戒自嬉，树德务永崇。","潜心董生业，绍迹曼倩翁。","三馀宁有期，百岁将无同。","勖哉黄氏居，庶以厉颓风。"]},{"t":"题吴氏宗夏所作秋林高馆图","f":"五言古诗","c":["江皋秋气澄，林屋带幽夐。","霜馀群木敛，日落众山静。","浟浟舟泛叶，湛湛水涵镜。","归鸟愁暝啼，飞鸿淡遥映。","市朝从兹远，轮鞅焉得竞。","钓怀渭滨叟，耕忆谷口郑。","彼美孰与期，援琴发孤咏。"]},{"t":"吴太守将赴韶阳西昌浮屠周师以九鹭图为别邑人刘荆生复为诗以系之","f":"五言古诗","c":["九鹭何娟娟，翔集在中沚。","感此秋气澄，森然欲飞起。","差差白羽分，皦皦皓翼比。","临深既群簉，憩浅复危跱。","流音振林薄，顾影下清泚。","落日枫岸遥，风回筱溪驶。","谁为霜雪标，墨素得其似。","悠悠岭海迈，肃肃鹓鸾止。","怅怀将远违，持以贶君子。","迹幽同九皋，心远向千里。","舞翿登清庭，翳车列天轨。","眷言羽仪盛，振振自兹始。"]},{"t":"江干草居","f":"五言古诗","c":["江干惬幽屏，草扉亦常关。","晚途断归人，虚市见寒山。","林木变冬候，繁绿忽已殷。","鸣鸟相因依，孤云时去还。","唐虞既云远，慨此时独艰。","四体岂不勤，我发日已斑。","翱游千载上，偃仰一室间。","乐咏古人诗，庶几无腼颜。"]},{"t":"戏题访戴图","f":"五言律诗","c":["大雪满天地，高兴何悠哉。","终然不相见，独棹月中回。","人言越溪春，酒熟山花开。","此时风日好，何事不能来。"]},{"t":"田父邀尝酒感赋","f":"五言古诗","c":["客有携壶来，酌我盈觞酒。","自云秋糯熟，酝酿满盆缶。","莫嫌山野俗，盘馔本无有。","园蔬杂蒸芼，甘脆幸可口。","丧乱二十年，蓬蒿遍田亩。","谁能厌糟糠，何意问升斗。","我时适归田，枯腹馀皓首。","感此慰劳勤，比酒觉逾厚。","陶然就径醉，高卧北窗昼。","门外清风来，飒然在高柳。"]},{"t":"题刘诚本画绿阴静钓图","f":"五言古诗","c":["绿渚净秋波，苍林含夕景。","之子坐垂纶，冥冥钓深冷。","归鸟背林梢，游鳞漾文荇。","扁舟有馀閒，庶以怡日永。","断岸不逢人，虚明见清影。"]},{"t":"答陈耕閒见贻之作","f":"古风","c":["微生本田野，志岂希庙堂。","采掇乃不遗，徒为仁者伤。","煌煌大明宫，四海皆来王。","圭璋映冠冕，光宠安可忘。","而我叨其逢，能无重忧惶。","驽骀匪逸足，朴?乏远扬。","摈斥固其宜，低回返山房。","幸有二三子，弦歌以徜徉。","感君笃所贻，韵语清琅琅。","逝言托晏岁，江海侔深长。"]},{"t":"题渊然刘炼师崆峒访道图","f":"五言古诗","c":["至人若浮云，会遇何有常。","有伟渊然子，早师赵元阳。","西游崆峒山，心迹两超越。","朝餐赤城霞，夜弄瀛海月。","瀛海几清浅，鲸波隔人烟。","楼船送童女，白日迷秦天。","伊谁秘灵机，颠倒凿玄窍。","相视乃无为，不言亦不笑。","问君此何之，颜色如桃花。","谷城访黄石，勾漏求丹砂。","我从昆崙归，秋鬓忽已雪。","安得骑青龙，相从叩真诀。"]},{"t":"和鹏举赴滁阳道中述怀见寄二首 其一","f":"五言古诗","c":["闻君赴滁阳，前月过秋浦。","轻蓬去如叶，列屿若浮俎。","思亲念方永，怀友心亦苦。","清宵发孤咏，馀响应柔橹。","盈虚谅谁卜，忠槩伤自许。","君心正悬旌，我发已垂缕。","苦无太古调，何以袭宫羽。"]},{"t":"和鹏举赴滁阳道中述怀见寄二首 其二","f":"五言古诗","c":["峨峨北岩山，上轶雨与云。","下有蕙与兰，芃芃扬秋芬。","君子在远道，怀思极忧勤。","眷言感时泽，亦复伤暌分。","念兹恺惠性，化者将同薰。","由来金玉姿，不如萧艾群。","逝将媲贞美，庶以怡朝曛。"]},{"t":"晚出登前冈候王徵君不至","f":"五言古诗","c":["出门候亲知，引望欣往即。","崇林既前登，修坂亦屡陟。","浮云正东驰，馀景忽西匿。","漠漠烟散霏，稍稍昏向极。","驱车来何迟，远近谁与测。","行非多岐累，鞅岂中道息。","幽期宁独违，冲想竟难抑。","欲留感凄冥，更往念艰棘。","簪盍谅勿疑，忧纷已盈臆。","鴥彼晨风翔，何日倩飞翼。"]},{"t":"和答萧国录八月十一夜对月有怀之作","f":"五言古诗","c":["林塘澹清华，庭宇豁虚朗。","露井波澄辉，风林叶交响。","高言倡令德，孤吟振遐想。","亭亭江上月，肃肃云雁往。","美人浩前期，令节延远望。","池鱼既堪纶，旨酒亦可酿。","永怀契天游，庶以会心赏。","宇宙本达观，如何较铢两。"]},{"t":"月夜舟中","f":"五言律诗","c":["溯舟忽淹逾，日入愁将夕。","江流星斗回，月出洲渚白。","飘飘风中蓬，渺渺槎上客。","利涉吾岂贪，归哉问林宅。"]},{"t":"题胡子敷朝阳轩","f":"五言律诗","c":["晨起罢盥栉，初日光离离。","晃然幽轩上，坐见扶桑枝。","揖客正几席，咏歌理弦丝。","高梧已结荫，鸣凤当来仪。"]},{"t":"题郁杰观泉图","f":"五言古诗","c":["我昔负疏散，放为出泽游。","自蹑两蜡屐，时操一轻舟。","陟险或穷日，探奇遂忘秋。","行与云水俱，坐与木石俦。","吐词辄吟咏，得酒即献酬。","自谓长若斯，不复怀隐忧。","中年遘沦荡，世路伤阻脩。","兀兀感时迈，栖栖愧身谋。","反思膂力初，岂乏十角牛。","谁令惰四体，而不营西畴。","又如规什一，利可等封侯。","胡乃忽彼贱，忍贫事坟丘。","工而昧执艺，卒也拙操矛。","徒以落魄资，重贻亲故羞。","属兹际明盛，草野咸登诹。","慢游幸免罚，识字偶见收。","上叨命秩崇，下感禄奉优。","补报惭鲜称，劻勷惧多尤。","鸡鸣事趋谒，日晏研书筹。","譬彼策驽钝，喘汗焉得休。","谁为泉石居，偃息得优游。","冠服如古贤，琴书粲琳球。","不图忽见此，如病顿获瘳。","池鱼恋圉圉，羁鹿怀呦呦。","山林岂在远，至性不可廋。","郁郎自超逸，台阁方见求。","鬓发幸未白，功绩宜力裒。","萧萧松桂幽，尔岂能淹留。","致此倘有道，吾将诘其由。"]},{"t":"五月十九日夜同蒋起居注杨主事宋给事中宴刘起居千步廊之寓直","f":"五言律诗","c":["步廊向寥阒，卫士传呼叫。","壶觞夜初集，刀戟灯相照。","风回阊阖迥，月上觚棱峭。","起坐惊向晨，束衣待明诏。"]},{"t":"偶题","f":"五言古诗","c":["一室秘炎暑，烦歊苦难禁。","安得天际云，油然起层阴。","愿持白团扇，步入青竹林。","却坐林下石，开襟以鸣琴。","奈何限清禁，可望不可寻。","且复此静息，聊以清吾心。"]},{"t":"送娄徵士叔真归金华曾侍郎邀赋","f":"五言律诗","c":["祖帐出都门，鸦啼掖垣曙。","春从天上归，人望山中去。","离亭烟柳变，极浦风帆暮。","亦欲把萝衣，空伤别琼树。"]},{"t":"兰雪轩诗","f":"五言古诗","c":["闻君好幽兰，罗植层轩阴。","青青在人境，意不殊深林。","光风澹容与，拂披动冲襟。","佳时聿云迈，众卉忽消沈。","重阴既凌厉，凛冽乃见侵。","念尔宛自持，将将式如金。","亮不渝芳洁，芳洁良可谌。","愿掇花上雪，比君尘外心。"]},{"t":"题观泉图","f":"五言律诗","c":["野客爱清溪，翛然净心迹。","仰聆松上风，俯见潭底石。","云林兴无远，鱼鸟欢自适。","坐待山月高，鸣琴送遥夕。"]},{"t":"题米元晖山水画为郭掾吏赋","f":"古风","c":["米侯奇崛士，作画有家法。","墨色运华滋，毫端散轻霎。","摊平布汀渚，立险出岩峡。","峰转路盘纡，林欹树交夹。","阴疑神鬼会，幽与鱼鸟狎。","野屋架深冥，溪桥跨危狭。","嵚崟负灊霍，滉漾注苕霅。","花醲雨初膏，草健风可?。","藤垂怯猿把，藻漾信凫唼。","层烟千嶂合，积雪万石压。","钓鲜忆鬵溉，采菽思衽扱。","斯人世己庚，此笔品宜甲。","高情烂初放，正气浩不乏。","灿灿珠吐盘，辉辉剑排匣。","兵曹坐拘束，吏牍烦捡押。","槐云屯故幄，梅雨润新袷。","探奇卷时启，历胜怀始洽。","何以谢朝绅，归哉荷农锸。"]},{"t":"青萝山房诗为金华宋先生赋","f":"五言古诗","c":["我有尘外想，长悬山水间。","昨逢金华客，因问青萝山。","青萝几千仞，翠色净如洗。","江上见数峰，分明紫霞里。","缅慕宋夫子，高栖在丘樊。","扣舷沿桂溆，翻帙上松门。","幽寻聆涧淙，静坐看庭绿。","著书三径荒，饮水一瓢足。","昔在山中住，声名天下闻。","一朝被徵起，长笑下秋云。","官联玉堂署，诏入金銮殿。","元史公是非，雄文掞雷电。","今年谢山县，稽礼移春官。","并结芙蓉绶，仍餐苜蓿盘。","翩翩霞上鸾，皎皎雪中鹤。","振佩朝天衢，回车睇云壑。","自从出山远，芳草满岩扃。","弟子感时雨，里人瞻德星。","岂无京华乐，秪念山房好。","恒恐归来迟，青萝笑人老。","仙岩勘灵笈，禹穴探古辞。","此意在千载，世人安得知。"]},{"t":"赠欧阳济可主簿自金陵复归济宁府","f":"五言古诗","c":["兵曹限清切，退食釐所务。","趋庭有来谒，乃是长清簿。","揽衣闻乡语，出袖惊柬素。","自云欧阳氏，文物乃吾故。","家藏两诰命，上代崇公祖。","紫锦绚春云，回鸾掞玄雾。","每启必三盥，兢兢惧沾污。","维时有侍讲，派别长沙住。","兄持往访之，题赠得佳句。","群公继挥发，浩瀚倒词赋。","后来兄入海，缇袭甚完具。","持携遂不返，旅殡石龙寓。","苍皇凶燄起，燔烈剧毛羽。","至今梦寐间，恍惚见题署。","兹从山东来，王事属驰骛。","永怀家室坠，毒若心火炷。","偶赖记诵存，手笔得缮注。","惟君尚友谊，每恨缺告诉。","便当乞一言，庶以偿企慕。","言已复怆然，泪雨纷悬注。","我惭縻廪禄，学殖成废圃。","先训既莫承，壁藏乃漂蠹。","感子重彝伦，矧复执义固。","勿伤昔贤远，勿叹来者暮。","骅骝苟纵辔，千里起尺步。","古人重收族，桑梓恭爱护。","孝忠可特立，荣显非倖遇。","千年兖公传，星日焕昭布。","烟尘暂纷纭，得丧奚足惧。","似闻四派绪，凋落少联属。","振先近捐世，南派亦微斁。","颍上存者稀，庐陵盛宗聚。","维时秋气肃，圻树飒凉露。","别子秦淮湄，明当发前路。","驿马向悲鸣，河水恐凝冱。","还官觐慎保，世泽常衍裕。","乱馀丘垄荒，樵牧方交瘉。","何当望南归，一省泷冈墓。"]},{"t":"椒园诗为台州杨子赋","f":"五言古诗","c":["海陬有东麓，天台所遗馀。","其下五亩园，幽人之所居。","幽人志事亲，行不出里闾。","升堂既问候，入室还读书。","园中何所有，椒树蔚扶疏。","露芳或晨采，秋秽亦自锄。","持此酿春酒，气和心孔舒。","东邻岂无牲，北里亦有鱼。","所贵在力勤，旨甘将乐胥。","苾馨重胡考，蕃衍咏聊且。","慎旃志洁白，庶以承厥初。"]},{"t":"陪陶尚书宋太史夜宿斋宫分韵得万字","f":"五言古诗","c":["鸣鸾莅阳郊，陪祀服明宪。","旂常拥圆壝，幕帟蔽脩甸。","天高风泠泠，露白星烂烂。","尊罍秩斯举，簴业枞以建。","凝神向澄肃，秉德方恪愿。","调笙思肄三，振羽将舞万。","张筵盛布设，陈币昭奠献。","听漏促晨兴，严衣戒宵偃。","骏奔尚齐遫，慎简惭硕曼。","感孚岂殊徵，恭事式同劝。"]},{"t":"赠萧忻","f":"五言古诗","c":["萧忻辞我行，有泪迸若雨。","仓惶奉旅殡，踯躅望乡宇。","主家隔万里，生死托童竖。","恒焉感恩义，誓不避艰苦。","路人为叹息，来与陈酒脯。","古有不反蔂，忻能瘗其主。","无子未足悲，有子焉足数。","作诗赠萧忻，庶以厉忠矩。"]},{"t":"题黄筌百禽图","f":"五言古诗","c":["百禽百声音，一动一情性。","谁欤写羽族，萃此一奁镜。","况有水与石，山桃竹相并。","物类巧纷薄，姿态飒飞竞。","掩卷冥所观，吾将契虚静。"]},{"t":"送赵可立来北平省其兄可久参政却归处州","f":"五言古诗","c":["华省张离筵，骊驹陈苦词。","北风吹旷野，归雁何参差。","弟也怀故乡，兄以王事羁。","高秋一为别，霜露忽已滋。","驱车抗前旌，执手安得辞。","君看并蒂菂，不独连理枝。","眷言此持赠，以慰长相思。"]},{"t":"送赵参政赴召还京分韵得风字","f":"五言古诗","c":["凛凛岁云暮，辚辚车徂东。","简书属严召，君子怀尽忠。","外劳既旬宣，内弼方奏功。","岂曰择所事，简知在宸衷。","念昔历曹署，朝趋接珩璁。","北来虽异寀，幸以义见同。","庭柏寒始青，垣薇春向红。","欢会不终岁，忽如萍与蓬。","俯惭辕下驹，仰羡天边鸿。","滦水方凝澌，燕山屹崇墉。","暌离会有时，精感理则通。","操持宜努力，蹇直在匪躬。","敢希仁者言，永励国士风。"]},{"t":"布履篇答舍弟","f":"五言古诗","c":["季有双布履，携来自家乡。","见兄赤两足，奉以慰踉跄。","此履岂有华，素质而白章。","缝纫出新制，絇綦已莫详。","念兹苦寒地，九月露成霜。","上马揽敝裘，入室坐匡床。","谁为手足念，寒瘃惊劻勷。","一朝被温柔，步履便且康。","足受惭黄石，踵决谢卜商。","不忍践荒秽，恐为明洁伤。","俯视物有类，怆然感中肠。","冠緌既成两，凫雁亦双翔。","如何弟与兄，阔别遥相望。"]},{"t":"题陈原初掾郎所藏古涧幽人图","f":"五言古诗","c":["端居谢尘鞅，濯足行涧湄。","青山既盘纡，流水亦逶迤。","四顾何寥寥，林阴亦纷披。","乍兴舞雩咏，亦轸濠梁思。","仰观浮云翔，俯挹祥飙吹。","春意属骀荡，我心方怿夷。","永言观象妙，庶以静者期。"]},{"t":"反哺诗","f":"五言古诗","c":["尝闻林间鸟，反食哺其母。","母衰塌翼坐，供养急衔取。","今晨观所哺，匪独矜老丑。","方其骈立次，情亦均左右。","有如雌伏时，局促拳两肘。","雄亦念其饥，出营含满口。","归飞闯巢户，彼此欣接觏。","振翼而张颐，嗷嗷类初鷇。","辛勤拾虫蚁，甘忍不下咮。","岂不犹已饥，分食贵先后。","有时通劳逸，雌出雄更伏。","母子夫妇间，出入更助守。","义恩重酬报，此意竟谁嗾。","圆颅异羽族，反目多阋斗。","腼焉不顾养，荒悖事博酒。","一体较铢锱，亲亲乃殊搆。","我吟反哺诗，庶以祛俗蔀。"]},{"t":"自述","f":"五言古诗","c":["叨禄向六载，北游且三秋。","臬司谬所寄，官服当何酬。","朗朗日月行，滔滔江汉流。","孰云倖所致，良以远见收。","有腼吹竽滥，徒劳负山忧。","秉志誓金矢，持身期玉瓯。","奈何岁年迈，鬓雪忽已稠。","勉策疲钝资，悠哉企前脩。"]},{"t":"夜坐","f":"五言律诗","c":["闭门鼓初断，振铎兵已逻。","风高群乌号，月黑一犬卧。","命樽乍舒怀，抽牍更娱坐。","稍稍空叶飞，庭虚觉霜堕。"]},{"t":"暮归二首 其一","f":"五言律诗","c":["驯犬闻我归，起迎出前阶。","饥猫如娇儿，奋跃入我怀。","閒居感物理，岂以形自乖。","攘攘殊趋者，孰云真我侪。"]},{"t":"暮归二首 其二","f":"五言古诗","c":["日暮骑马归，惊踏天上雪。","北风吹寒沙，高树低欲折。","谁怜牛车行，来往同一辙。"]},{"t":"朝抱一印出","f":"五言律诗","c":["朝抱一印出，暮抱一印归。","公家有严程，出入焉敢违。","吏曹方劻勷，文牍正填委。","力弱惊任隆，劳微愧恩私。"]},{"t":"十月十三日燕相府知印张观复从江西来承大兄六月八日家问捧诵之馀悲喜交集因赋五言长歌一首奉报匪敢言诗姑述怀耳","f":"五言古诗","c":["张生江西来，手持家问至。","剥封未及读，先讯伯与季。","书题八月写，上有平安字。","孟冬始获承，道远良不易。","首云念我病，迩只复何似。","中陈困书社，驱勒乱迁次。","末述儿子顽，刍牧荒诵肄。","又云先茔木，里横肆戕毁。","官府呼不闻，樵竖剧跳戏。","次云今夏旱，坐食困憔悴。","私储乏担石，何以供卒岁。","仲兄往黄陂，迎女别子婿。","季弟石台馆，游从盛脩贽。","阿鸾缔姻早，诸侄亦勤勚。","抒词良激切，苦语杂琐僿。","如聆丁宁教，如获左右侍。","始惭终作恶，扑簌纷洒泪。","我本疏野资，遭时误登试。","事兄且未能，从政安足齿。","往者被徵迫，欲走不得避。","仓皇赴京阙，惨戚去田里。","渺如蛙望海，茫若蠓发甀。","春官书题目，冢宰叩言议。","拜命黄金门，亲题职方氏。","天颜正温穆，谕旨极谆致。","退朝感恩隆，际遇荷明世。","从兹谬通籍，出入清要地。","含香大明殿，赐食光禄寺。","庙庭严奉瓒，坛壝恭执币。","厚禄既宠叨，宫衣亦沾被。","迟回历初考，艰险尝百事。","前年调北平，滥擢宪府贰。","言议久疏儒，条章昉师吏。","山河八府辏，辽海三陲寄。","土风混戎俗，吏治尚沈鸷。","贪婪乃蚕食，剽掠更狼戾。","论当虑乖违，拟步恐颠踬。","忧多变容发，务冗废寝寐。","倦禽困长云，羸马伤促辔。","离居形吊影，鞅掌矇接瞆。","得书暂慰莞，抚已重唏喟。","违离路五千，契阔弥六祀。","事生与追远，俯仰两蒙愧。","归休期莫竟，追赠仰朝制。","华纷倘欢聚，泉壤亦荣贲。","君恩未能报，私愿焉得遂。","乾坤等籧篨，今古一奔驷。","勿忧时事艰，勿以外物累。","消閒且时教，娱老宜日醉。","中情更谁谕，此责当我致。","由来紫荆树，一气共荣悴。","岂以连理枝，同根乃殊植。","世机纷倚伏，强悍焉足恃。","要当戒盈溢，奚必较钝利。","蜉蝣常撼树，蝜蝂亦排礩。","永念珠浦源，绵延本仁义。","滋培藉先德，振拓属来嗣。","天意苟从欲，此志终可觊。","作诗报兄前，庶以见微意。"]},{"t":"纪梦","f":"五言古诗","c":["夜梦归故里，见我平生亲。","升堂具杯酌，恳款话所因。","问我归何迟，怜我白发新。","恍忽一室内，酬献相主宾。","东邻粲新疃，南舍俨旧邻。","稚子笑相即，老翁言谆谆。","似亦谢前倨，敬我今缙绅。","我心本无滓，敢劳深意陈。","喔喔鸡鸣曙，悠悠天向晨。","苍茫枕席间，委曲所历真。","怅然不可讯，恻怆徒伤神。"]},{"t":"题朱知事云樵图","f":"七言古诗","c":["使君昔隐灊川曲，惯逐山樵伐云木。","一从去作宪幕宾，长忆灊川好林谷。","灊川之东山插天，中有峭壁何崭然。","寒光夜接九华雪，秀色日射峨眉烟。","褚君妙笔世稀有，为写兹图传不朽。","山气清含五粒松，江光绿浸三春柳。","长裾曳杖为何人，从以樵斧方逡巡。","层峰正隔秋浦水，仙境似与柯山邻。","山回峰转愁欲暮，斸药携琴更深去。","林路时冲虎豹过，湍崖暗激蛟龙怒。","此图此景何清奇，疑是当年亲见之。","采芝南岭去已远，濯足东涧来何迟。","只今却上青霄立，斩伐芟夷乃其职。","卷曲宜刊恶木枝，乔修要简良材植。","人生穷达焉可期，云中樵者非君谁。","会稽太守自结驷，王屋山人方看棋。","功名时来信所遇，伐木丁丁为君赋。","他年持斧绣衣行，还忆灊川卧云处。"]},{"t":"秋夜南溪席上听邬和卿胡琴歌时和卿留袁城将归西昌","f":"七言古诗","c":["空山无云风叶静，酒行高堂烛垂烬。","邬郎起控二弦琴，一曲新声发孤咏。","泠泠滴滴弦初调，欲语乍吞声忽飘。","龙头宛曲转秋玉，马尾振荡回春娇。","萦纡往复腾袅袅，宫换商移破清悄。","綵鸾笑侣出花间，断雁呼群入云杪。","满堂宾客惨不哗，侧耳如到仙人家。","乃知胡中歌敕勒，不独马上传琵琶。","我从往年客燕蓟，羌笛戎歌乱人意。","归来华发映清尊，坐感商音一流涕。","邬郎好手早得名，岂可久滞宜阳城。","太常此去徵绝艺，会奏法曲升天行。"]},{"t":"夜宴富滩郭氏西庭和荅九洲萧徵士并柬履理履祥于渊贤伯仲","f":"七言古诗","c":["升筵月高花影长，我当起舞君行觞。","丈夫志气倾海岳，一笑已觉形俱忘。","雕盘馔香切寒玉，酒波摇红荡人目。"]},{"t":"题山中归隐图为萧与靖赋","f":"七言律诗","c":["高人霞裾青玉筇，径行自挟双青童。","飘然独往不可挽，逸气矫矫如飞鸿。","峰回涧折流淙怒，彷佛崖阴见行路。","云间桃洞如可寻，亦欲从君度桥去。"]},{"t":"镜岩歌为镜方彭及予赋","f":"古风","c":["君不见南山山前一片石，崭然壁立当流泉。","皎如千年青铜镜，挂在万仞高崖巅。","泉流日冲激，烟云相荡摩。","鱼龙过之不敢睨，如有神物严撝呵。","夜深月明从东来，但见五色灿烂寒光开。","扫空婆娑黑云影，照见海上金银台。","我从武姥来，却望嵩华去。","道逢老篯铿，盛说岩中趣。","东风拂涧桃花飞，爱此山水含清辉。","放歌谁和碧玉调，起舞更揽青萝衣。","我怜老仙极清越，颜色如童发如雪。","便从石上引芳尊，夜夜岩前醉明月。"]},{"t":"题秋江待渡图为萧学士赋","f":"七言律诗","c":["小航冲风岸将及，行人下马沙头立。","水阔云深野渡閒，天寒日暮归心急。","人生行役安可休，到江路尽还通舟。","谁能裹足山中老，不识风沙一日愁。"]},{"t":"和子与王徵君中秋短歌一首","f":"七言律诗","c":["玉绳差差月澄曙，银汉西流天尽处。","晃朗惊浮玉井莲，空明似见婆娑树。","澄曙光连宿鹭翻，关山影逐行人去。","谁似溪头王子猷，一庭竹色耽吟趣。"]},{"t":"翁源行","f":"古风","c":["大蜡岭，小蜡岭，东南相望两尖顶。","千崖无人野蕉绿，一涧缘山石泉冷。","伊谁置县当僻源，井邑人废馀荒村。","后来分隶曲江县，偏与豹狼生子孙。","荒山亘连二百里，六寨獠兵连岁起。","韶州号令不知闻，势力凭凌自倾傂。","一从洪武初设官，路启旌旂笳鼓喧。","莲塘镇里立廨宇，父老欢呼来聚看。","往时养马如养牛，腾踔山谷夸豪酋。","只今买牛还卖马，弃掷弓刀事耕稼。","今年我从英德来，攀岩历壑何艰哉。","路穷蒲岭见空豁，白昼阴霾浑不开。","阴风鬼号荒古道，嗟尔遗民真再造。","男不事诗书，女不理蚕桑。","草衣蕉布无冬夏，蓬首垢足畏客如麇獐。","食储岁饱一千户，馀四百石输官粮。","自言老死不出乡，官事不生衣食强。","三朝作社共杀牲，十室纳稼同囷仓。","开畬烧土任耕作，引水激机舂稻粱。","榛栗遍秋岭，旨蓄足冬藏。","月上叱牛日入毕，营求易足本天性，耳目不移非外物。","况闻畏法如畏虎，道路不遗门不拄。","鸡豚日出散如烟，米粟年登贱于土。","我怜浑朴若可亲，岂有毒厉兴妖神。","由来仁化感木石，宜以礼义开真淳。","君不见铜场恶溪流赤水，八月禾花瘴烟起。","秖言北客少生还，宁信土人长不死。","我歌翁源行，听者莫伤情。","丈夫正气易水土，薄俗可敦浑可清。","便骑黄犊入山去，閒与洞民歌太平。"]},{"t":"锦裹石行","f":"楚辞体","c":["锦裹石，何苍苍，我行入封川，问之江上郎。","云昔有辩士，往说南越王。","道傍见山石，指天誓不忘。","谓苟得意归，不独衣锦还故乡，要使兹山之石同辉光。","一朝缓颊下南荒，车马千驷金满装。","便令制锦百万匹，尽裹山石荣铺张。","至今岩阿草木昭煌煌，兽不得憩鸟不敢翔。","烂然云霞彩，下照江中央。","我欲登其巅，窥海略扶桑。","掇此五色文，献之紫虚皇。","有志愿莫遂，却立增慨慷。","吾闻陆贾去汉室，乃有贾生流涕论帝傍。","惜此文绣被屋墙，丈夫未遇焉可量。","衣或带索食秕糠，偶然会遇亦其常。","奈何暴殄恣所偿，胡不衣被沾四方。","不曰爰居徒劳铿锵，匪悼尔石兮惟狂之伤。"]},{"t":"题堵炳所画扇面山水为李鸿渐赋","f":"七言律诗","c":["紫崖碧嶂连云树，白石青莎并江路。","采樵客去洞门深，出郭人归烟水暮。","两崖之间高且虚，有亭翼然谁所居。","山花当户可载酒，芳草满庭宜读书。"]},{"t":"题山水画","f":"古风","c":["大山隆然如釜钟，小山崭然如剑锋。","阴崖直上见?影，幽径独寻麋鹿踪。","野人似厌门前路，移家又入云深处。","云深更隔水千重，却望桃花满山树。"]},{"t":"题松下丈人图","f":"古风","c":["丹崖白石之间，有松屹立当林关。","伊谁槃礴坐其下，矫首似看云中山。","白云自飞山自远，神气冲逸清而閒。","自非服鍊不老药，安得有此冰玉之芳颜。","石门苍苍閟烟雾，东风开遍桃花树，花底相寻定何处。","兔丝百尺空中举，松根茯苓应可煮，就君却向山中住。"]},{"t":"题魏氏见山楼陶秘书邀赋","f":"古风","c":["秘书陶君清且贤，家住越南山水边。","为言魏氏楼居好，邀我共赋山楼篇。","忆我在山时，长与山相见。","自从入城府，少见青山面。","我虽未曾游上虞，闻君诵诗心已娱。","龙山蜿蜒走西北，下赴平陆开澄湖。","湖天滟滟涵秋练，菱叶荷花两青茜。","千章霞绮动晴波，百叠云屏落秋巘。","东南诸峰何宛然，惟有夏盖亭亭高插天。","寒光交射明月见，秀色飞入春风筵。","他年载酒湖边去，却访青山起楼处。","楼前好鸟自啼春，源上繁桃定迷路。","此时共酌陶秘书，酣饮不下山楼居。","手招黄鹤凌紫虚，更问伯阳符契今何如。"]},{"t":"题昆丘山水图为李德昌赋","f":"七言古诗","c":["姑苏好山名昆丘，玉作芙蓉凌九秋。","至今宝气伏光彩，白石磊磊皆琳球。","问君何年宅其下，桂馆芳堂极潇洒。","篱月当窗烂不收，松风扫屋声如泻。","山林真乐安可忘，时援绿绮歌清商。","自来南京直大省，长对新图怀故乡。","图中云壑更窈窕，双塔参差出林杪。","花开何处望长洲，日落遥空送飞鸟。","道逢两翁如松乔，我欲从之安可招。","便当携酒上绝顶，与子共看沧江潮。"]},{"t":"题米元晖云山万里图为倪郎中赋","f":"楚辞体","c":["远山如眉，近山如茨。","洲渚盘互，林木纷披。","云浓浓以凝宇，烟淡淡而凌陂。","望佳人兮极浦，伤暮春其多离。","意怫郁以终夕，心低回而独悲。","瞻彼长江兮浩浩其驰，我无舟楫兮将安所施。"]},{"t":"椿萱图为会稽胡郎中赋","f":"古风","c":["越中山水称雄秀，越中胡家称孝友。","父母怡愉在一堂，六十齐年健相守。","人言积善深且长，早有令子登贤良。","今年徵召入朝省，白衣超拜尚书郎。","会稽岧峣白云里，江船南来向千里。","鉴湖风起藕花秋，子念亲恩亲念子。","午门晓开东日红，万国干官朝九重。","方惭孤蹇昧补报，何幸奏对相追从。","吁嗟胡君我今恨如海，禄虽有馀亲不待。","愿君爱日保祯祥，忠孝一心长不改。","人生穷达安可量，事亲之乐真无央。","矧君妙年当盛际，似此具庆非寻常。","愿萱忘忧椿介寿，绿叶朱华照鸾绶。","眼看升堂棒诰书，衣锦归来献春酒。"]},{"t":"白云书舍图为掾史褚德刚赋","f":"七言古诗","c":["褚君本是河南褚，家在卧龙山下住。","一从辟椽入中书，长忆龙山读书处。","山中白云相卷舒，褚君卧云方读书。","清池有鱼林有笋，甘旨升堂时起居。","在家不知事亲乐，游宦还应念城郭。","山头日望白云飞，鸿雁离离向空落。","丘郎自是同乡人，念子远游情最亲。","为拈彩笔写幽思，物色正与秦山邻。","问君何年辞别墅，萝月松烟淡如许。","山犹拥石护遗书，云已从龙作甘雨。","人生重是君亲恩，田园荒芜安足论。","由来荣养须食禄，孝子忠臣同一门。"]},{"t":"宫墙树","f":"古风","c":["宫墙树，乃是青青柏。","劲直由来气拂云，坚刚况复心如铁。","枝间岂少王裒泪，土中定有苌弘血。","事往空遗国士悲，年深尚记乡人说。","宫墙柏，何青青，千古万古遗精灵。","宫墙若倾柏树折，府君之名应不灭。"]},{"t":"都门柳送熊主事归丰城","f":"古风","c":["都门柳，青青一似腰间绶。","千叶皆含雨露恩，一枝偏入行人手。","行人初辞丹凤台，买船龙湾明日开。","到家好种青青柳，还念都门送别来。"]},{"t":"赠吴伯武并柬刘起居","f":"古风","c":["永丰范萧之峰，有坟隆然而新封。","问之父老坟者谁，云是刘家兄死弟葬之。","兄行万里死毒厉，家有婺妇无孤儿。","弟也来葬之，涕泪如雨垂。","捧土营成坟，挽棺声酸悲。","山头茫茫石与土，谁欤卜者吴伯武。","酬之十金挥弗取，乡人称之不容语。","弟从去年入南都，簪笔趋朝官起居。","得禄不待养，为我一语三嗟吁。","所嗟当时事急天莫呼，非吴卜之谁与图。","昨来徵文盛扬揄，吴君高谊真不诬。","起居衷诚不可孤，我诗字字如璚珠。","更后千岁当不渝，愿持荅刘兼报吴。"]},{"t":"题垂钓图","f":"楚辞体","c":["石礧磈兮溪则有浔，山嵚崟兮岸则有林。","我钓我游兮曷溉之鬵，彼滔滔者孰知予心。"]},{"t":"送潘郎中迪允谢病归山阴","f":"古风","c":["兵曹潘郎美如玉，纱帽锦袍银带束。","去年春秋才廿六，起家早食郎官禄。","才资简静推酝藉，精爽开明夸敏速。","潘为驾部我职方，联事兵曹颇雍陆。","喜君妙颜方向盛，觉我秋鬓已先秃。","人生聪慧岂外取，灵秀端在两耳目。","云胡奇疾忽攻剽，有耳如涂翻不足。","阗阗莫悟桴应鼓，辘辘都忘车转毂。","传言错误叹朋友，问字惊呼骇童仆。","时来内讧疏啖食，十日僵眠战寒燠。","文移相府怪沈滞，奏入天墀许归复。","我惭迟钝百无补，两耳虽闻竟何属。","岂如君以沈聩故，退就休閒非谴逐。","谈经作赋未足病，解绶投簪竟何促。","都门官柳青欲染，江驿小桃红正蹙。","此行先喜拜家庆，次第升堂会姻族。","卮?恳款视时馔，巾履逍遥试春服。","鉴曲时歌采采莲，柯亭更访青青竹。","古来辞荣出昏眊，此日归休见清淑。","客怀戚戚感睽合，世态茫茫嗟倚伏。","床阴牛斗安足省，夜半鸡鸣竟奚卜。","不如万事俱不闻，且与痛饮樽中醁。"]},{"t":"题嵩高云气图为工部王子邕赋","f":"古风","c":["颍川阳城之间，乃有云气郁然而干天。","中峰拔地九千丈，三面侧叠开青莲，云是嵩高之层巅。","扪柳掠井当星躔，往往白日朝群仙。","复有东西二石室，洞穴窈窕相钩连。","天风吹雨不到地，石髓如泥流紫烟。","但见瑶林琪树纷百千，朱楼绮阁丹碧悬。","美人绿发垂两肩，手持玄文驾飞軿。","欲往从之嗟渺绵，似听流水㶁㶁鸣丝弦。","仙游杳漠今几年，清梦忽堕新图前。","玉光下起崖石底，松顶上出飞鸿边。","山中古路广以平，秦车汉骑何翩翩。","徒闻金丹閟石检，尘土世人安得传。"]},{"t":"赵江宁鸣玉为余写武山云气图赋此奉酬","f":"古风","c":["赵江宁，才且清，烱如白露凝金茎。","鸣弦佐政重京邑，潇洒独怀遗世情。","人言江宁好文彩，越土王孙著前代。","乃翁旧图八骏马，电影风行破云海。","江宁好画水与山，意比八骏尤高閒。","近追高公远董氏，神气正在苍茫间。","伯兄侍郎我同事，邂逅兵曹见高致。","偶携雪楮问乡山，便写嵯峨出云势。","朝怀武山景，暮看武山图。","披林指涧忆所历，云中似有人相呼。","我昔游山时，秋风落松子。","泉泻洞门青，霞翻石屏紫。","北岩千丈高且虚，骑虎曾到仙人居。","菖蒲石上看残弈，柿叶林中闻读书。","一从南京来，奔走愧尘鞅。","钟山只在城东北，日日见之未能往。","都门杨柳青入云，黄莺乱啼终日闻。","秦淮楼高花似锦，安得烂醉江宁君。","江宁欲别当奈何，乘兴更与挥云萝。","他年载酒鉴湖上，却唱武山归隐歌。"]},{"t":"雉朝飞一曲题双雉图","f":"古风","c":["雉朝飞，雄飞雌随声喔咿，山晴草暖风日迟。","绣襦锦翼何缡䙕，或登木而号，或据石而栖。","一步一饮啄，步步不相离。","所以贾氏女，御射有获方笑嘻。","物生自有性，配匹亦有时。","嗟尔牧犊子，七十而娶将奚为。"]},{"t":"渔家乐题渔乐图为曾朝佐郎中赋","f":"古风","c":["渔家乐，船里为家无土著。","朝朝日日大江边，长汀短汊从湾泊。","醉眠饱食托烟波，却笑傍人事耕作。","月明蓬上芦花飞，雨打船头枫叶落。","芦花飞出水，鳜鱼秋正肥。","侵晨相唤提网去，薄暮放歌收钓归。","夫妻白首长相聚，有脚何曾踏山路。","教儿打网莫种田，长江有水无荒年。"]},{"t":"鸿雁来奉题张嗣宗雁图","f":"古风","c":["鸿雁来，秋风起，江北江南几千里。","渺渺初离紫塞云，潇潇忽度平湖水。","平湖水浅沙渚长，欲落未落纷低昂。","蓼花过雨红更白，荷叶著霜秋已黄。","可怜分飞毛翼冷，乱入蒹葭唼蒲荇。","群叫遥传空外声，独宿频惊月中影。","江南地暖风土殊，彭蠡潇湘从尔居。","只今塞外无菉草，沙碛苦寒愁夜呼。","由来有序本天性，饮啄飞鸣远相应。","我惭飘泊未能归，见尔忧伤泪如绠。","茫茫江河多风波，柰此缯缴危机何。","为君卷画三叹息，高飞冥冥安可极。"]},{"t":"松泉操为姜县丞作","f":"楚辞体","c":["松飕飕兮以风，泉锵锵兮鸣石。","澹云生兮北林，悄月上兮东壁。","崇构在丘，鸣琴布席。","我歌和之，式咏以绎。","升高四顾，逝将安适兮。","鸟飞冥冥，不见其迹兮。","聊息荫以焉依，诚予衷之所怿兮。","苟循物而多忧，吾宁不以易兮。"]},{"t":"题耕读轩为吏部主事顾硕赋","f":"古风","c":["我从前年改初服，冒荣坐请公家粟。","寻章摘字勘科律，压几堆床披案牍。","文深有害心愈惕，食饱无功颜自恧。","常怀战慄趋府署，岂有游歌到庠塾。","实忧慵惰饥欲死，复恐荒嬉昧所属。","今晨览君田庐咏，往日嗟余去从卜。","君才特达当庙堂，我志依微渐朴?。","何由放斥遂归休，扶耒朝耕仍夜读。"]},{"t":"陶氏三节妇诗","f":"古风","c":["往年兵入台州府，劫掠州人尽荼苦。","陶家一妇偕二女，捐命俱能保真素。","孟也夫亡十八年，姑死未葬有柩停堂前，日夜号泣相弃捐。","忽然被执发怒骂，宁死白刃骈首地下从姑还。","季也嫁夫才一月，走陷淤泥信颠蹶。","香裾未许污妖尘，腾入深池竟沦没。","妇本名淑身姓王，心知事急有子不得将。","抱儿属姆还夫婿，被发狂走茫无方。","一朝见梦嫁时婢，我在南邻井中毙，井中亦有簪与珥。","陶君求之果如识，妇人英爽乃如此。","丈夫腼颜胡不尔，我为此诗良有以。","一歌陶家女，再歌陶家妇。","一门贞节世所稀，信是名家足贤姱。","君不见金华宋太史，特笔作传藏天府，要使清风激千古。"]},{"t":"送臧主事哲新除兵马指挥后承诏赐鞍马白金归山东宁亲","f":"七言古诗","c":["朝鞬长弓入兵马，买船暮出龙江下。","问君行色何尔忙，诏许东归问亲舍。","去年辞亲谒金銮，入参礼幕陪春官。","昨朝却换兜鍪服，健卒马前刀剑簇。","奉天诏下朝班时，拜舞谢恩当赤墀。","青年如玉衣绚锦，喜气得得浮修眉。","赐金在案马在道，千里归宁拜亲好。","好念君恩似海深，岁暮还朝须及早。"]},{"t":"紫髯使君歌为本拙吕佥宪赋","f":"古风","c":["紫髯使君颜雪色，八尺长身鬓光黑。","前年奉诏出承明，万里观风来蓟北。","肃政堂前喜遇君，共持使节登青云。","君乘铁骢踏霜月，燕南渤海皆澄氛。","忆我兵曹初释屩，看君两历中书幕。","已从秋贰拜天官，复报司常奉祠礿。","殿庭奏对先六曹，春花如锦映宫袍。","象牙牌促中使急，玉笋班出璚林高。","当时追趋赤墀下，彩帉杂佩光相射。","宁知此地复相逢，三见鸿飞送秋社。","朝随升堂坐，暮逐骑马归。","林间日上乌鹊喜，井上花落黄鹂飞。","花开花落春风起，云去云来山色里。","怡然不笑亦不嗔，手把芙蓉看秋水。","向来车马都城道，甲第高门迹如扫。","题诗爱赠吕仙人，惟有黄州玉堂老。","我惭尘土得暂亲，岂有风采称朝绅。","青山对面雨愁客，白发满头花笑人。","嗟君自是真仙骨，廊庙才华正英发。","好从双阙觐红云，却上三山弄明月。","君家旧住淮河湄，投簪共载当何时。","春申台前沽美酒，烂柯山下看残棋。"]},{"t":"题赤松山房歌为张思让赋","f":"楚辞体","c":["吾闻古有赤松子，云是神农之雨师。","后来留侯从之游，汗漫恍惚安可期。","金华北山秀且奇，或云仙人游于斯。","盘云捎雾几千文，奔腾直下兰江湄。","兰江美人晰而颀，风骨不殊仙者姿。","时来山中攀桂枝，架岩凿谷临湾埼。","灵湫洞黑蟠蛟螭，流水下注为渊池。","前开层峰出渺瀰，丹霞浴海腾金支。","云中老仙方颔颐，手携锦轴绿玉词。","导以玉女载两旗，从东而来复西驰，欲近忽远不可追。","千岩万壑绝人迹，但觉浩浩天风吹。","伫立却望成逶迤，回身太息冥所思。","左引紫霞觞，右弹冰玉丝。","山空月白秋似水，老鹤夜下要人骑。","问兹山房谁所为，留侯子孙非君谁。","只今从军伤远离，万里幕府随旌麾。","燕山马上昨见之，山水秀色浮修眉，仙人之徒真不疑。","我惭渐老才力衰，何以报尔游仙诗。","南望武山胡不归，山下亦有金华祠。","闻君佳致欲往随，便来南游拂云衣。","憩青萝兮咏双溪，万一赤松寻不见，从君先访牧羊儿。"]},{"t":"楚酒苦如檗歌","f":"古风","c":["楚酒苦如檗，燕酒毒有灰。","自能螫喉吻，何以宽心怀。","不如江南有美酒，香如芙蓉色如柳。","小瓶浮蚁信宿成，大瓮沈醅十年久。","饮之不鸷亦不狞，温温如春和且平。","丹田微蒸香露溢，着面已觉赪霞生。","当时放意事杯酌，倒海回山恣行乐。","有时醉倒黄公垆，卧看山花酒中落。","一从远游楚与燕，苦曲黄米无甘泉。","刮肠呕胃甚荼蓼，使我颦蹙清樽前。","何时南归事林亩，邻曲招寻二三友。","呼儿多与种秫田，日日花前饮春酒。"]},{"t":"风蓬叹","f":"七言古诗","c":["野蓬团团大如斗，生来轻捷随风走。","四傍枝叶共轮囷，流转须臾遍原薮。","秋风平地吹来时，十科百科相逐飞。","东家小儿誇健足，十步一蹶何由追。","蓬生不是无根叶，脆软何能坚著地。","霜枯雪悴少筋骨，材质轻浮等沦弃。","无端飘入流水中，犹复衮衮旋西东。","可怜一落坑堑里，纵有春风吹不起。"]},{"t":"获熊","f":"七言律诗","c":["山北狞熊色深黑，蹂谷攀林恣趫捷。","一朝冒雾出郊坰，不待虞网远搜猎。","嗟哉尔兽真途穷，白日授首辕门中。","谁知狂狡无馀技，只在将军一箭功。"]},{"t":"题张京尹所献嘉瓜图歌","f":"七言古诗","c":["南京五年夏六月，京尹献瓜状殊绝。","骈瓞双承雕玉槃，连包并进黄金阙。","尹言产自句容县，野老田夫骇初见。","一叶连蜷引浑沦，两壶磊砢连葱茜。","是日君王御武楼，徵问吏牒趋公侯。","星联翠影落丹扆，日射神光浮冕旒。","敕令捧至乾清殿，永拟先尝须庙荐。","词臣上颂美真奇，画史图形著蕃衍。","盛哉圣恩浩如天，民勤物阜宜丰年。","小臣作诗纪嘉应，愿继大雅歌绵绵。"]},{"t":"题溪居图为余经历赋","f":"七言古诗","c":["高人爱傍清江住，草屋松林带烟雾。","书帙閒栖案上云，钓竿静倚门前树。","树枝蜷曲交棠梨，上有古藤萦结之。","屋头黄叶落如雨，此老宴坐方吟诗。","人生幽居有如此，何必驱车踏城市。","谁知出处自有时，诸葛终然拂衣起。","青云腾踔方远期，江海茫茫劳梦思。","他年献纳成功去，却借沙头一鹤骑。"]},{"t":"题碧潭图送王闻喜主簿之官阳谷","f":"古风","c":["王郎作县之阳谷，北望黄河冰冻蹙。","金陵呼酒别行装，示我碧潭图一幅。","碧潭之水绿且深，风不能扬尘不得侵。","嗟哉王郎子，勖我湛湛之清心。"]},{"t":"三峰樵者歌为宗原张员外赋","f":"七言律诗","c":["若有樵者清且閒，游栖乃在三峰山。","雨馀濯足深涧底，日高伐木乔林间。","人生出处若云变，买臣会稽君不见。","秖今怀绶作员郎，却望三峰思故乡。"]},{"t":"题刘一清清溪图歌","f":"古风","c":["我家昔住清溪曲，五月柴门漾寒绿。","望仙门外石桥湾，百折苍波转林麓。","老藤修竹翳两涯，茅屋高下连桑麻。","江鱼出跃青荇叶，水禽啼上碧桃花。","悠悠三十年来往，却别清溪事游荡。","东园有客种狸瓜，北渚何人系渔榜。","兹晨览君图画工，作者乃是清溪翁。","清溪自住渝水上，名称偶尔能相同。","长汀短棹溯云水，绝壁乔林澹霞绮。","乌鹊散漫夕阳边，楼阁依微空翠里。","伊谁手携九节筇，从以童子囊孤桐。","至音雅调不易识，深山古木号天风。","我今欲归归未得，时时梦绕溪南北。","钓槎欹石雨边青，菱角沈泥雨中黑。","问君何从得此本，强拟乡园寄幽遁。","避名惟恐世人闻，抚景应悲岁华晚。","三山矶，白鹭洲，京国相逢俱胜游。","请君更棹酒百斛，相与烂醉秦淮楼。"]},{"t":"送别石泉县丞钟尚贤以公役赴京却还成都府","f":"七言律诗","c":["送君西还酌君酒，更出都门折杨柳。","怜君自是同乡人，上马欲别愁回首。","风帆五月上瞿塘，却望石泉如故乡。","啼猿峡里见明月，万里相思应断肠。"]},{"t":"题山水画","f":"七言古诗","c":["小山削玉搏空青，大山错绣开帷屏。","划然千文崖壁立，下有流水当高亭。","亭中幽人颜色好，城市何年迹如扫。","长江日落澹浮云，极浦春回满芳草。","深林窈窕仙路遥，谷口雪明双板桥。","便携绿玉上绝顶，閒听松风吹洞箫。"]},{"t":"题堵郎中画湘汉秋色图","f":"七言古诗","c":["兵曹簿领困填委，忽见云山落尘几。","问君何意貌此图，湘汉萧萧秋色里。","长峰巨壑相参差，彷佛江行曾见之。","云中树色三百里，峡里猿声十二时。","古人今人不相见，江水依然净如练。","鱼凫窈窕接山川，云雨荒荒出台殿。","岸回路转枫林青，丹崖绀壁秋冥冥。","山童出扫涧上叶，客意已到松间亭。","登高望远心独苦，江阔霜清雁如雨。","九天飞瀑下香炉，万里归帆到鹦鹉。","我从前年来帝京，偶离蔬屩峨冠缨。","故园耕钓归未得，对此佳致空含情。","茅堂远在珠林下，安得从君问图写。","九衢尘动五更风，又趁鸡鸣逐朝马。"]},{"t":"题都府俞溥经历所持山水画扇","f":"七言律诗","c":["俞君手持一尺练，水色山光坐来见。","烟林嘉树蔚森爽，云磴寒泉飒飞溅。","茅亭萝径青石床，松风洒衣如雪霜。","便从花底抱琴去，閒听渔父歌沧浪。"]},{"t":"题许霍州如圭所画誉溪图送张秉文徵士还山中","f":"七言古诗","c":["许侯作画如作字，点缀清妍极风致。","此图偶为张君写，雪茧参差出空翠。","张君于我同乡人，每对画山情更亲。","就中大似爵誉景，遥见武姥青嶙峋。","我欲披云扪绝顶，手招陶皮漱丹井。","千年石室望来深，六月松风坐中冷。","山原草荒行者稀，伊谁读书方掩扉。","如此林阴两茅屋，安得与子长相依。","禾溪向东石桥路，犹忆往年携酒处。","春风几落杜鹃花，归梦微茫隔烟雾。","许侯今在太行西，君亦南还寻故栖。","卷图相送一肠断，烟柳满河莺乱啼。"]},{"t":"题雪山行旅图","f":"七言律诗","c":["野桥路迷雪初集，行旅萧萧骑行急。","北风吹面须髯寒，茸帽驼裘半沾湿。","木皮石角冰粼粼，十步九却何苦辛。","安知道傍茅屋底，不有闭门高卧人。"]},{"t":"樵隐诗为北平检校书吏朱廷玉赋","f":"七言古诗","c":["上虞朱郎美如玉，昔隐负樵今食禄。","抽毫晨趋北省署，归梦夜绕东山麓。","朝廷徵贤图治康，岩穴搜剔无遗良。","云山纵有千万叠，似子风格何由藏。","垂纶鼓刀自前古，功业终须致圭组。","愿君长忆负薪时，莫羡轻肥忘勤苦。"]},{"t":"题柳坡图歌","f":"七言古诗","c":["杨君躯干长九尺，力挽长弓过三石。","樱桃园里旧名家，杨柳坡前新列戟。","往从开府大将军，北定燕蓟收奇勋。","铁衣夜度居庸雪，虎旗昼掩卢沟云。","归来殿前拜天子，宝带金符耀秋水。","宠承恩命五色诰，分控边庭九千里。","今年我从南京来，幕府忽逢心眼开。","清筵雅咏狎文士，号令仓卒生风雷。","昨朝视我图一握，云是杨绳之所作。","江堤窈窕出翠室，亭榭参差带丘壑。","中有骑者从一童，锦衣挟弹行春风。","向非自寓行乐意，安得景趣超然同。","君今拓边方报国，却望江乡归未得。","黄鹂啼处绿阴多，时展画图看春色。","我歌此曲声呜呜，愿君逐虏成长驱。","欲知此去功多少，栽遍沙场柳万株。"]},{"t":"蓟丘墨竹歌为克隽李兵曹赋","f":"七言古诗","c":["蓟丘墨竹妙天下，海国中州重声价。","事往云流五十年，孙子兵曹更潇洒。","昨来相见浑河东，身骑官马行匆匆。","从君早怀壮士志，将命绰有前贤风。","当家谱竹精形类，倾轶湖州出清致。","缣绢磊落动千古，翰墨晶荧照三世。","自云真迹世已讹，后来作者俱不多。","空庭月落见修影，绝壁秋风闻振珂。","我家江南竹林里，与竹同游同卧起。","一从北向感飞蓬，却爱横梢写生纸。","划纸落笔生萧骚，秀色娟娟真凤毛。","蓟丘风节慎操励，看尔腾踔青云高。"]},{"t":"竹石图","f":"七言古诗","c":["东吴妙手不可得，省郎山石兵曹竹。","唐侯座上偶相逢，并写秋光归一幅。","丛篁擢玉分弯环，怪石立铁支孱颜。","笔锋挥霍斩绝外，意匠回斡苍茫间。","物情境态精描貌，紫蔓青苔见班驳。","凤雏濯濯散毛羽，稚子差差露头角。","人生会遇安可常，一时合景如干将。","千年崖谷注明月，九夏庭馆寒飞霜。","唐侯特达参朝政，两君高致谁能并。","嗟哉奇绝真二难，此石此竹谁当看。"]},{"t":"慈乌叹","f":"古风","c":["台前柏树八九株，树上百千啼老乌。","乌能返哺本孝鸟，奈何朝夕争喧呼。","夕眠昼坐不得息，有时奋疾试一驱。","东枝乍起西枝落，去不能远仍旋趋。","岂无弓与缴，尔独不我虞。","嗟哉慈乌尾毕逋，借尔柏树生汝雏。","雏成报汝劳与劬，便当归飞东海隅。","海隅有山从尔居，悯尔至孝惜尔愚，慎尔利口毋趑趄。"]},{"t":"次周所安寄短歌","f":"古风","c":["周郎春兴醲如酒，绕屋陂塘种杨柳。","忆曾相过赏东风，手引流霞?北斗。","当时不省生远愁，花下起舞回高秋。","长松挂月出石岭，清夜醉倒东溪头。","别来几度秋风发，却怪音书望中绝。","行人马上念乡关，九月居庸洒飞雪。","羡君一门如棣花，石室旧藏书五车。","昨来寄我三百字，字墨矫矫犹翻鸦。","我惭衰迈成漂泊，钓水耕山负前约。","山林啸傲方日长，慎勿白首悲冯唐。"]},{"t":"题春船出峡图为刘彦祥作","f":"七言律诗","c":["春船出峡声嗷嘈，众工力险齐所操。","两崖牙角不可触，直指洄洑乘虚涛。","瞥然势脱千丈落，万叠青山去如掠。","海门东望正滔滔，便驾云帆纵寥廓。"]},{"t":"题晴峰双涧图寄故里刘存大秀才","f":"七言古诗","c":["一峰巉岩白云中，双涧下出蟠西东。","湍撞石斗雷电激，白日虚谷回松风。","风声浩汹泉声合，飞蔓樛枝青匝沓。","岩深路暗不逢人，似有呼猿在相答。","此图此景真绝奇，彷佛梦中曾见之。","手招仙人赤松子，照影太乙莲花池。","只今怀禄未能往，日日凭高增怅怏。","故山更在彭蠡外，武姥仙坛俨相向。","仙坛楼阁开岧峣，流水百折通溪桥。","我家草堂小河口，白沙翠竹寒萧萧。","瓜畦桑坞带原陆，五月柴门映江绿。","田翁稚子笑相迎，醉折山花唱村曲。","缅思此乐安得同，万里愁绝孤飞鸿。","卷图却寄山中客，他日来寻黄绮公。"]},{"t":"寄题凌云亭","f":"七言古诗","c":["吾乡山水何处好，石台溪上桃源堡。","兰陵公子气凌云，故结新亭傍林岛。","亭前地势深回环，落花细草晴班班。","垂杨尽拂烟际水，好鸟啼破云中山。","我昔东寻雪山顶，忆过溪南踏松影。","开轩酌我紫霞杯，三日东风吹不醒。","就中二老难弟兄，阶庭秀发皆璚瑛。","向非前朝进士宅，安得乔木排高闳。","仙坛峨峨峙亭左，云气飞来交四座。","月明吹笛泛灵槎，定有仙人夜相过。","人间车马尘纷纷，羡君清逸能超群。","题诗先寄亭中友，他日相携玩白云。"]},{"t":"题钱舜举凌波仙子图","f":"楚辞体","c":["若有人兮美而鬈，冠切云兮衣翩翾。","粲然独立青山前，褰裳流盼凝娟娟。","乘云而行兮从风而旋，态庄色正合自然。","矫如翔鸾凌紫烟，朗如明月行青天。","山之石兮骈阗，山之松兮连蜷。","下有瑶草纷交连，素华绿叶何芊芊。","不言不笑意已宣，风骨乃是凌波仙。","金华老人惜㛹嬛，友于联属成三妍。","其来无方往无边，世人不见将千年。","谁其画者钱塘钱，我歌欲继湘江篇。","张君好古宜宝旃，此画此歌毋浪传。"]},{"t":"题华川樵逸图","f":"七言古诗","c":["三衢御史风霜笔，高谊飘飘张云日。","手把新图出华川，邀我题诗寄樵逸。","自言樵者非真樵，托隐早赴山人招。","烂柯不顾岩下斧，采药曾度云中桥。","屋头青峰千万叠，流水当门清可涉。","柳矶风起漾鱼竿，松坞天寒扫霜叶。","当家群从孰最奇，华也英俊真佳儿。","两年北平旷定省，指点山水怀归期。","浙山盘回烟雾锁，静养性灵奚不可。","驯虎来寻卖杏林，野鹤为守烧丹火。","川南春来花满坻，黄精酒熟杯行迟。","醉吹铁笛花下坐，是仙是逸谁能知。","我惭窃禄驱驰早，贪看图中似蓬岛。","何日相携持斧翁，共入华山拾瑶草。"]},{"t":"题摩痒散马图","f":"古风","c":["骏马玉削蹄八尺，昂藏汗血姿。","星流电掣见精采，鞭勒不施谁许骑。","一朝贡入金门去，五花屹立当前墀。","佩以白玉珂，被之黄金羁。","欲鸣不敢嘶，欲进不敢驰。","和鸾清道肃羽仪，中官执鞚调御之。","君不见南山楸枥大十围，节目皴作蛟鼍皮。","六月其下阴凄凄，风鬃雾鬣相纷披，还忆閒来摩痒时。"]},{"t":"日西落行","f":"古风","c":["日西落，月东生，乌鸦绕天飞且鸣。","鸦飞来宿府中树，府官坐衙不归去。","暮归独宿公房西，柰尔哑哑中夜啼。","五更鸦鸣月未堕，披衣又向衙中坐。"]},{"t":"赠北平都指挥胡昭勇歌","f":"七言古诗","c":["忆昔出使南海头，将军开府当雄州。","楼船戈甲三千万，海波不动鱼龙愁。","越王台前东风起，我复乘潮上浈水。","木绵花发照天红，正月莺啼榕树里。","将军宴客华筵开，碧幢画鼓声如雷。","起倾荔浆酌椰斗，问我此别何时来。","明朝驱马还东去，长忆虎头相别处。","清梦时随海月回，狂心远逐秋鸿度。","君从东归省墓田，阙下重逢心惘然。","岂知移镇出海峤，握手乃在浑河边。","浑河十月冰如堵，白日飞沙暗椿莽。","雪中千骑出居庸，手挽雕弓射彪虎。","君陪上将临边防，我握宪节凌清霜。","看君骁勇有如此，安得揽辔同飞扬。","山后诸州数千里，拓地横行正未已。","为君拟颂勒燕山，尽扫狼居报天子。"]},{"t":"闻山西杨使君孟载作霁雪轩于公署之东慨想高致兼怀旧别因风叙情有作奉寄","f":"七言古诗","c":["使君清严重风纪，名是东吴旧才子。","前年持节太行西，霆激霜飞二千里。","忆昔京阙初相逢，承诏作乐调笙镛。","彤闱椿树集鸾凤，画省秋水开芙蓉。","江西徵还入司马，天上兵曹动声价。","明光晓入奏封章，日射金茎露如泻。","是时我从燕蓟来，下马重逢心眼开。","龙江风雨催去棹，不得倾倒黄金罍。","驱车复渡黄河北，故旧飘零悲恻恻。","知君十月向并州，长日看云望山色。","陈昂作者来汾河，锦轴远传佳制多。","横江醉骑白鹤下，爱尔黄鹤楼前歌。","古来富贵同湮没，老去才华眼中尽。","当家词翰真不群，风雅孤鶱见秋隼。","北平九月霜草黄，大风吹沙人马僵。","台前古柏八九树，乌鸟日夕争喧翔。","闻君官居最清绝，扫地开轩题霁雪。","一帘芳草凝清香，四座光辉揽明月。","六出花开应复春，何因对酒咏清新。","山阴夜半遥相忆，愁绝扁舟乘兴人。"]},{"t":"题燕侍图为山东马希孟御史赋","f":"七言古诗","c":["竹萌车迸鱼冰跃，高堂鼎裀盛帷幕。","弄雏索果笑牵衣，人生无如奉亲乐。","长成倏复成蹉跎，禄养不干将奈何。","去家仗剑事明主，始觉此志相违多。","泰山西北长清县，马氏家风故多善。","一门寿考天所锡，二子兴隆人共羡。","孟也问学真贤良，往昔徵入文华堂。","承恩屡使江海上，反顾只忆庭闱傍。","去秋冠豸来燕蓟，自说违离过三岁。","愁心袅袅逐飞云，惊梦时时问供馈。","槁城李君名画师，感此纯孝劳伤悲。","忻然拂素运丹墨，为写燕侍欢娱时。","青峰绕屋花连院，千里亲庭坐中见。","酡颜白发映青春，一日相思一舒卷。","劝君勤事勿忧虞，由来忠孝同一途。","他日捧诏归荣日，更写衣冠家庆图。"]},{"t":"题秋色平远图赠汪孟谦归四明","f":"七言古诗","c":["我家住在澄江畔，村北村南去山远。","春风桑柘连麦畦，秋雨菰蒲隔松坂。","几回欲起看山楼，未成忽作神京游。","至今梦落珠浦曲，如见秀色天中浮。","昨来驱马趋燕北，霜草风沙总悽恻。","汪郎为写平远图，恍似江南带秋色。","横坡断岸向湾涯，危石临水如蹲犀。","松阴二客茅屋底，无乃相对方吟诗。","我欲呼之从此起，便踏渔舟弄烟水。","月明吹篴下平川，卧看青天千万里。","情不得遂将奈何，忽复秋霜双鬓皤。","归田已知生计晚，滥禄颇觉忧虞多。","君归四明沧海上，惜别临图倍惆怅。","他年载酒看荷花，贺监湖边定相访。"]},{"t":"吕性之汲井得鱼","f":"七言古诗","c":["前人凿井后人汲，一壶下井三鱼入。","泣竹常疑地有灵，奉亲已恨时无及。","吕翁诚孝天所省，异事流传遍淮颍。","至今父老寿阳城，指点高门说遗井。","翁今跨鹤游仙去，子亦攀龙翔九衢。","祥开兆应良有以，看取玉带悬金鱼。"]},{"t":"椎冰行","f":"七言律诗","c":["里河冰坚厚如掌，扬州北去船难上。","船头持火照椎冰，万杵千篙动清响。","冰开一步进一程，三日不到高邮城。","夜寒月黑北风急，舟人独拥冰椎泣。"]},{"t":"乌庄曲","f":"古风","c":["乌庄之乌黑扑扑，乌庄老人住茅屋。","屋前胶河后林木，一树十巢十栖宿。","长枝踏低短枝曲，乌来哺雏尾交簇。","童子下窥不忍触，矧敢向之加劲镞。","老人行坐乌与随，三世淳朴乌不疑。","啼哑哑，飞提提，愿翁孙子如乌慈。","不嗔不恶乐孔宜，四海咸诵乌庄诗。"]},{"t":"大清河","f":"古风","c":["大清河，浑漉漉，南黄河，清淯淯。","今河不与古名同，自是河流有反覆。","君不见安山直下栗阿时，一斛之水数斗泥。","徐州吕梁走下邳，可以照见人须眉。","清河北河入北海，黄河入淮东入海。","彼此争流不相待，两水清浊各自流。","终然到海同一沤，东流北流君莫愁。"]},{"t":"田横砦","f":"古风","c":["田横砦，乃在北海之湄蓬莱之阴。","波涛下漱石齿齿，云雨正轶天沈沈。","田横古强族，北海亦齐地，王侯富贵本自致，豢养于人岂良计。","田横不返北海头，假王亦亡云梦游。","剩基沙门高屹屹，五百义魂海中泣。","丈夫一死百世雄，至今海市神愤切，褰旗跃马行空中。"]},{"t":"登成山","f":"古风","c":["登成山，望出日，不知其下海水深几尺。","夜半鸡声喔喔鸣，但见五色金莲花，滉漾捧之向空出。","当年祖龙望拜时，上山特立日主祠。","六神升天驾奕奕，馀辉却射山头石。","神人鞭石功不成，至今海水流血腥。","岂知阳精著悬象，乃欲度海观其形。","昔时日主祠，今日祖龙庙。","祖龙亲构鮀鱼知，海若望之向西笑。","颂碣摧落蔓草中，李斯何述秦何功。","一时霾雾妖怪合，千载尧日方曈曈。"]},{"t":"双堠曲","f":"古风","c":["双堠迎人来，单堠送人去。","五里十里有定程，万水千山无尽处。","我欲登高堠，东南望故乡。","故乡不可见，日落野茫茫。","野茫茫，风浩浩，马头一见一伤心，多少征人是中老。"]},{"t":"题万里望云图为台州经历谢伯敬赋","f":"楚辞体","c":["登天台，望桂林，桂林邈在千里外，有母不见，使我三岁袅袅悬归心。","山海兮冥冥，桂林兮青青，安得身为云，从风上下兮日往来乎亲庭。"]},{"t":"吴江水美王贞妇为娄主事赋","f":"楚辞体","c":["吴江水，清泚泚。","吴门山，高孱颜。","彼高兮或骞而崩，彼清兮或浑而腾。","不如娄家嫠妇心，坚不得移洁不得涅，嗟哉嫠妇兮女中之烈。"]},{"t":"磨剑歌","f":"古风","c":["我行四方如飘风，袖有古剑苍精龙。","何年尘土凝不灭，苔花绣涩青芙蓉。","往者提携访嵩岳，手抉飞泉向空落。","划然掣断青丝悬，直恐乘流遂腾跃。","青天白日交风霆，我方赤手试发硎。","阴纹差差吐寒月，碧缦隐隐排疏星。","摇拽千仞崖，动荡九泽水。","腥浪回天倒海流，阳侯夜哭鱼龙死。","归来䍡?青玉函，紫云为束黄金缄。","不愿轻污佞臣血，千年万年保冰雪。"]},{"t":"韶石歌赠钟文学赴诏州","f":"楚辞体","c":["古有虞帝奏韶之遗石，乃在庾岭之南曲江之侧。","盘盘兀兀三十六，秋霞流红雪凝白。","重华一去不复来，落花流水空苍苔。","晴云照天紫凤没，明月绕树猿声哀。","送君韶阳去，因作韶石歌。","君今南上登嵯峨，诸生环佩鸣相摩。","振皇风兮返淳和，我思虞帝感慨多。","安得御气游其阿，南望苍梧吊湘波，为君日夕攀云萝。","山遥水远不可极，韶石韶石奈尔何。"]},{"t":"题李子翀所藏罗小舟青松障子歌","f":"七言古诗","c":["罗君画松奇且雄，两株屹立青天中。","已愁白昼结寒雨，更觉素壁吹长风。","横梢屈铁苍皮健，恍惚垂云青一片。","若非巫峡道中逢，定向华山峰顶见。","深林无人日色昏，萧瑟似有孤啼猿。","苍根下走岩石裂，清响暝与溪流喧。","古来志士沦野草，每见良材叹枯槁。","何如此树保天真，千岁高堂奉君老。"]},{"t":"所思曲寄旷伯逵","f":"楚辞体","c":["我所思兮西山之美人，爱而不见劳我心。","美人娟娟隔云林，昔别遗我双南金。","东风吹行云，飘忽在远道。","绿发青蛾眉，念此颜色好。","秋风八月芙蓉开，忆君寄书南浦来。","芙蓉寒死十月露，忽复寄书重相催。","我行十八滩，滩水流浩浩。","青天急雪乱回风，白日惊雷撼崇岛。","上有袅袅之绿萝，下有汎汎之回波。","玄猿暝啼江月出，独不见之愁奈何。","愁奈何，风潇潇，山中岁晏不可以远招。","雁鸿茫茫隔烟水，杨柳飒飒悲河桥。","愿携双绮罗，赠此远别者。","新愁渺如雾，千里不得写。","早晚下南津，预将书报君。","江空日暮不可见，望望西山多白云。"]},{"t":"游白沙庙歌","f":"古风","c":["青青芙蓉峰，可望不可招。","我本山中人，因之忆归樵。","朝朝看山五云上，划见长江落危嶂。","黄公滩险昔所闻，白沙祠古今谁访。","乃有好奇卓越之孙郎，吊古往往探穷荒。","重怜沙下白云冢，为买江上秋风航。","洑滩奔迅万马疾，凉雾吹霜石屏出。","跻攀瓮口未分寸，倒截鱼梁已寻尺。","长篙戛石铿有声，神潭在望难为情。","青天高悬鸿鹄远，落日下照鱼龙惊。","童童青松枝，矫矫出云峤。","彩凤腾辉琐闼重，寒螭竦鬣觚棱峭。","舣舟祠下风摇摇，缆以垂蔓防惊漂。","撞钟挝鼓告祭酒，纸灰飞雪寒飘萧。","玉冠双峨形貌古，蛛网虫丝閟灵户。","精灵尚想入梦寐，漂溺终能托墟墓。","极知孝友天所藏，墨家孙子今何乡。","山川有时出云雨，朝家自昔隆封王。","群鸦飞鸣日欲暮，天际微茫起烟雾。","枫林竹树何萧飕，风佩霓旌自来去。","乱山四合如游龙，赣水百折争朝东。","渔郎敲火青苇外，贾客驾舶苍烟中。","长风送人下山址，猿狖悲号灵籁起。","半痕明月上遥汀，一片青天入流水。","流水不可极，夜色寒更深。","船头酌酒船尾吟，鲤鱼馔列双黄金。","就中宾客皆豪俊，邹子神情更清夐。","掷帽狂歌不顾人，夺杯放饮先成醉。","人生会合自有时，此日不乐将奚为。","飞仙早传赤壁赋，锦袍更赋郎官诗。","津亭边，石盘路，归骑翩翩失来处。","灯火低迷下远楼，星河璀璨飞寒露。","我有磊磈不尽之心怀，棹船载酒须重来。","酒醒书閤梅花冷，月落江城画角哀。"]},{"t":"万安旅次承子彦弟自上犹归迂途问劳临别感赋","f":"七言古诗","c":["有弟有弟瘦且长，短衣百里来相觅。","山城深夜绝来往，怪尔行迟扣门急。","主人惊报汝弟来，移灯出户喜复猜。","近闻虎豹出县郭，况乃霜露沾草莱。","夜阑凄切更秉烛，怜汝南游困穷谷。","瘴馀面目少光泽，岁暮阴阳苦凋促。","忆汝昔在垂髫时，倚床哭母衔深悲。","提携实赖大母健，植立早慰诸兄期。","祇今何能较雄长，江海频年空怏怏。","一身有望在事育，二十无成惭俯仰。","今年母党重可吁，十日两闻哀讣书。","岁时飘零礼数失，骨肉凋谢亲情疏。","天寒草短日色暮，长揖辞兄从此去。","汝归先我勿惮远，东入荒山慎前路。","朔风吹衣寒冥冥，过雁哀鸣那忍听。","紫袍铺下一回首，踯躅已觉涕泪零。","大兄到家凭致辞，县税莫教输纳迟。","归来重闱奉杯酌，父醉儿扶亦真乐。"]},{"t":"织女吟赠黄进贤","f":"古风","c":["忆昔束发初，娇倚云锦机。","折花事戏剧，笑诧身上衣。","一从十五时，学向机中织。","丝短愁苦长，梭缓心转急。","永夜兰灯悬洞房，门前梧叶零秋霜。","霜寒手冻丝绪乱，络纬悲啼金井床。","春花更叠黄金缕，花底青鸾蹴烟雾。","东风何日天上来，拟奉瑶池宴歌舞。","十日满匹恒苦迟，一夕停梭生网丝。","持刀沈吟剪秋水，粉泪欲落愁风吹。","远怀素心人，邈在千里道。","何因托交欢，持此永相保。","东邻小姬昔同年，至今盛饰为母怜。","几回月高鸣杼轴，正是他家夜弹曲。"]},{"t":"双桂歌为杨彦初作","f":"楚辞体","c":["杨郎庭前双桂树，我一见之消百忧。","亭亭车盖立清昼，瑟瑟雾雨含清秋。","东偏一株极偃蹇，苔藓半面青相樛。","西偏一株亦惨淡，云中倒挂珊瑚钩。","青蛟晓蜕腥雨湿，黑蜧夜斗苍烟愁。","开轩宴我坐其下，上有鸣鸟声和柔。","沈阴满地不见日，石池之冰光浏浏。","清霄叶落玄鹤舞，八月花发山翁留。","我惭学仙苦不早，安得御子昆崙丘。","便当吹笛明月底，坐看玉宇寒飕飕。","人间双桂有如此，气节岂肯卑微休。","呜呼气节岂肯卑微休，小山之隐兮毋相求。"]},{"t":"叹息行赠别胡思斋","f":"古风","c":["叹息复叹息，志士恒苦辛。","少日不得意，暮年愧其身。","前有尊酒清且旨，酌酒奉君君莫止。","人生最乐在相知，莫徇虚名轻跅弛。","市中屠贩还封侯，扬雄草玄空白头。","浮云不尽万里意，白日长悬千古愁。","南山之阴多洞府，十年不归叹修阻。","绿萝芳草淡风烟，君独胡为在尘土。","五云馆前花满津，紫骝蹀?骄青春。","春时禽鸟各自适，燕子低徊还附人。","江风萧萧吹水急，江寺钟残野鸟集。","口中吟咏眼看山，细雨苍茫愁独立。","邓溪漉漉秋水泥，见尔令我欢相携。","酒酣燕坐石盘岭，明月正在松林西。","近闻烟尘起闽广，官军驱驰日南上。","郡邑无人豺虎行，道路萧条竟安往。","我思旧游湖水东，昔者登临今不同。","常年九月章浦净，吴霜夜落青芙蓉。","芙蓉花开日欲暮，美人娟娟隔烟雾。","一段愁心化綵云，至今飞绕河桥树。","今夕果何夕，别君还忆君。","古来贤达常坎坷，慎尔出处超其群。"]},{"t":"读范太史诗赋长歌一首以识感慕之私","f":"古风","c":["麒麟凤凰不世出，我思美人宁有终。","飘然一去不可挽，徒令四海歌清风。","慷慨范夫子，行高身益穷。","读书白云下，养母青山中。","大布之衣乌角巾，于世不牾亦不同。","时来清江弄明月，潇洒绝似商山翁。","中年徒步谒京国，一鹗矫矫飞南东。","群龙方满朝，怪尔独来晚。","岂无五色线，可补舜华衮。","当时作者杨与虞，倡和往往谐笙竽。","蓝田共拟雪色玉，沧海独携明月珠。","一朝低徊去台阁，骑马南入闽中幕。","幕中三士总知名，江海高风动寥廓。","蹇予束发弄笔时，已解窃写早朝诗。","独怜生晚堕荒僻，每诵制作增涟洏。","峨峨百丈遗灵阜，安得披榛荐卮豆。","兹晨再读海康槁，玉立疏髯恍神觏。","嗟哉老成今不存，筝笛满耳愁喧喧。","百年气运有屯复，月落江南空断魂。"]},{"t":"观邓侍郎石磬歌","f":"七言古诗","c":["水中古磬世莫识，扣之能鸣人始惊。","前朝文物最博雅，庐陵侍郎先得名。","淮河东游色惆怅，忍使至宝成凋丧。","苍茫何代出泥沙，憔悴当时杂盆盎。","归来设虡当特悬，扣击往往遗音传。","奇文漫灭科斗迹，雨气缠结蛟龙涎。","是时周庙朝殷冔，师襄南踰叹修阻。","海门风起商声哀，万里孤臣泪如雨。","凤鸟一去不可闻，宜尔孙子多才文。","高堂出此坐叹息，暝色犹带崖山云。","便令敬之慎勿亵，此物宜与天球列。","百年隐显自有时，蕴德含和竟谁泄。","呜呼贤哲今不存，对之使我伤心魂。","虞庭可登兽可舞，此石不毁应能言。"]},{"t":"武溪获大木歌","f":"古风","c":["大材用世不可测，每自沦落升高隆。","君看武溪蛰古木，一朝远致黄堂中。","黄堂旧梁危嶷嶷，久待瑰奇更蠹蚀。","武溪父老不自私，为言水中有钜植，根节槎枒良可识。","太守遣吏往视之，陈牲酾酒先告祠。","踏泥直恐龙奋跃，抉石犹疑天倒垂。","伐之铮铮金铁鸣，黑洳渍入霜皮赪。","千夫挽绠土窍裂，迅雷走雨溪灵惊。","归来绳削腾高架，藻绘风生动清夏。","何年汨没泥滓馀，一日州民拜其下。","人生出处安可常，苦心未朽终腾骧。","君不闻丰城地底剑，苌弘土中血。","千年化碧安可縻，亦有龙光斗牛掣。"]},{"t":"题马图","f":"七言律诗","c":["天马西来掠西极，君门万里踏云入。","紫塞秋回玉颊明，黄河夜渡拳毛湿。","高冠圉人不敢骑，拄策却立当前墀。","半垂丝缰龁青草，明日银鞍趁班早。"]},{"t":"南山谣","f":"七言古诗","c":["淮西流民望南徙，掠财昼入南山里。","裹枪负挺八十人，拒敌乡民四人死。","流民只说江西熟，得食仍嗔食无肉。","扶伤救死官不闻，乡民还对流民哭。","东家击豕西家牛，撤屋烧火当街头。","自言性命如粪土，一死不异淮西州。","乡民不怕逢豺虎，共承只怕流民怒。","老翁夜出烧纸钱，祈神夜送流民去。","从今莫愿多丰年，第一莫旱淮西田。","流民不来贫亦好，鸡犬全家永相保。"]},{"t":"寄西山郑子纲自邵武校官归","f":"古风","c":["五月双溪上，垂杨千万枝。","春风碧水远，旦旦鸣黄鹂。","黄鹂惊飞日欲暮，念家却在南平住。","林塘高馆一逢君，千里羁愁散烟雾。","闻子昔者居西山，把书曰在青松间。","新移苓术且未斸，旧种薜萝应可攀。","武阳校官归未久，瘴疠还闻古来有。","红窗鹦鹉唤客名，青叶槟榔劝人酒。","寻幽忆过东平来，丹山碧霞仙掌开。","武夷山人住九曲，柴门不出生青苔。","中轩松竹题诗遍，宁许时流漫相见。","名姓先承紫凤书，褐冠不上金銮殿。","时来空谷行采薇，石田草生秋林稀。","往来物色不可得，使者空向江南归。","我惭羁穷少颜色，闻此伤情岂终极。","芳筵置酒清夜半，月出登楼动悽恻。","萧萧水气浮南湖，繁星丽汉光有无。","梧桐叶高白露下，起舞为子听啼乌。","君家兄弟才名早，幢憧冠盖闽湘道。","芳年苦志思奋励，莫遣秋风动原草。","由来聚散日纷纷，此别音书何处闻。","百丈岭前应念我，象牙潭上却寻君。"]},{"t":"谒靖安昭灵庙赋柬袁茂才","f":"七言古诗","c":["昭灵古祠蔚森爽，祠下流波日奔荡。","啼鸦枯柳当两楹，落日青峰照银榜。","秭归西阻蜀江口，云盖风舆自来往。","常时酾酒击鸣鼓，辄有灵风动虚幌。","楚王宫殿久寂寞，万里晴云色苍恍。","神龙自合晦渊潜，凤鸟胡为在罗网。","此邦祠宇出何代，恍惚湘楚同风壤。","石竹丛深山鬼愁，江篱花落文鱼上。","清秋旅怀百忧集，感子追游慰遐赏。","明时礼乐遍寰宇，肯使幽忠滞榛莽。","享仪每诏县官给，祀典犹闻宗伯掌。","捍菑禦患光故国，愤义终能肃群仰。","湘南屯戍苦未休，长笑因之起悲怆。"]},{"t":"七月十四日夜纪梦","f":"七言律诗","c":["美人遗我云锦书，问自何所吾故居。","章江千里波浪阔，七月舟楫来何如。","书中字字光凌乱，一读中肠一回转。","青鸟西飞不可招，凉月斜风动河汉。"]},{"t":"奉题钟隐君东皋幽居图","f":"古风","c":["微雨枫林青，高堂见图画。","幽人读书处，宛在东皋下。","东皋窈窕绿涧阴，藤萝缚门门转深。","是中松桧各千尺，飞鸟不度寒萧森。","山原之居可终日，莘野斯人皆俦匹。","清宵瓮牖出灯火，白石匡床散方帙。","寻仙学道思不穷，水边林下皆清风。","画师天趣亦偶尔，形迹安可求其同。","白下城东门，清溪颇回抱。","君家庭前景，岂逊图中好。","年年二月梅始芳，亦有杨柳当高墙。","重檐修竹啼鸟静，落花如雪青苔香。","东邻踏歌鸣急管，南舍列筵愁夜短。","空将白发笑寒迂，岂识高情在疏散。","先生布袍乌角巾，泠然自是神仙人。","二郎早已擅场屋，孙子亦能歌雅豳。","硗硗头角秀而雅，总是高门忠孝者。","他年朱紫出清朝，翁但筑堂看绿野。","我曹失学百可怜，闻公高谊心凛然。","秋风江浦破茅屋，悔不归垦山中田。","秖今东游兴未已，亦欲携书寻故里。","便从竹底拾流萤，来听先生诵秋水。"]},{"t":"寄赠万德躬时在清江","f":"古风","c":["文章名世自有神，诗家之秀今何人。","豫章特达迈先辈，一出已绝江西尘。","乾坤悠悠入清旷，叹息斯人欲谁向。","清秋鹰隼破陡绝，白日骅骝动悲壮。","时携宝玦青珊瑚，看花调笑当垆姝。","结交老苍五六辈，议论已逼东西都。","功名不来心独苦，却望美人思遥浦。","月中吹笛上丹丘，烟际飞帆拂天姥。","浩然吊古登高台，谁能酌子黄金罍。","石桥听雨青枫合，海门望日丹霞开。","县中许令高閒者，闻子悲歌在林野。","自蹑双履行相迎，手攀碧萝却鞍马。","秋风九月吹吴关，复忽鼓棹从东还。","匡庐云锦九千仞，片片飞落新诗间。","独携稚子怜远别，草堂临流故幽绝。","少年吐气成紫霓，揽发何堪半如雪。","却从帅幕坐谈兵，直以精采空鲵鲸。","楼船东下海波净，剑光夜出清江城。","由来壮志在裋褐，空谷亭亭老楠栝。","亦知扬子奈长贫，岂识相如故多达。","长安冠盖日纷纷，有诏徵贤安得闻。","白沙翠竹自江岛，隔水卧看西山云。","我自来西山，城中迹如扫。","谁家杨柳鸣黄鹂，忽见秋霜落园枣。","双溪之水东北流，上有绣谷青绸缪。","长松遥挂海底月，眼明照见樽中愁。","愁心复几何，舒卷风中雾。","落日断云飞，令人思玄度。","人生富贵须何时，莫谩穷愁伤汨之。","君行可逐白鸥侣，一棹酒船游会稽。"]},{"t":"赠写真孙君德","f":"七言古诗","c":["庐陵写真谁最良，昔有昌叔今孙郎。","风流未觉前辈远，远有意气能专扬。","家临官道青山下，白日垂帘绝潇洒。","滩口频回使客舟，绿杨惯系行人马。","人言精艺自有神，下笔可夺形容真。","吾常按图究所貌，神爽岂是寻常人。","清如春兰茁芳谷，润如秋波出寒玉。","壮如泰华倚石桧，劲如筼筜濯霜竹。","少年红颊桃花枝，老人白发春蚕丝。","心同衡鉴见机颖，功与造化穷铢锱。","吾家祖母年八帙，老父前年逾五十。","当时写置慈寿堂，老稚来看动趋揖。","喜君绝艺感君情，作歌赠君当远行。","清朝奋志写褒鄂，会且见子趋承明。"]},{"t":"岁暮自靖安县将归南平留别袁明诚茂才","f":"七言古诗","c":["昔我始客豫章城，众中识君颜色清。","十年异县风雨隔，芳草满园啼早莺。","宁知此别堕千里，与子溪南同濯缨。","春华过眼叶秋脱，思之可使神魂惊。","读书济胜恒有道，辞家作客宁无营。","亦知云中鸿雁急，岂有地上麒麟行。","清秋门巷三日雨，已觉满眼牵愁生。","高林凉日白惨淡，幽谷细雾寒峥嵘。","寻常抚事念乡邑，见尔不殊亲弟兄。","岂但过从慰寂寞，喜可纵谈开老成。","芙蓉作花露始白，拟以斗酒邀同倾。","此时高堂念游子，举杯欲饮难为情。","肥牲不如东邻菽，且可力养毋干荣。","逝兹晏岁返故里，恐有寒草荒柴荆。","稚子啼饥亦可念，几日江上先相迎。","便从早晚出溪口，与子共赏西山晴。","石头买船待明发，风吹北斗天中横。","峡江见月定相忆，此意不尽东流声。"]},{"t":"临碧亭歌","f":"古风","c":["谁能筑亭向青山，我欲憩之开苦颜。","谁能筑亭面流水，我欲因之洗尘耳。","江南万里秋冥冥，往有胜处无佳亭。","画船神消越湖白，快马目断淮云青。","筠州之山蔚霞绮，碧落仙人洞天里。","罗君家住碧落西，百尺修亭水边起。","我行叹息思见之，人言此亭多胜奇。","凫鹥不隔紫荷叶，翡翠只在青杨枝。","秋来七八月，月出凤山时。","坐石弄清景，调笙咏新诗。","时来凭高一起舞，剑影下射青玻瓈。","又如三月春，有风从东来。","红花照绿水，白雪飞苍苔。","酒酣四顾仰空笑，但见紫翠纷崔嵬。","城中匝地誇豪富，复閤重甍閟烟雾。","谁能载酒日论诗，学似君家筑亭住。","我家寄在快阁傍，门前江水春云长。","绿萝间维艓子静，蓬蒿不剪柴门荒。","闻君临碧亭，喜赋碧落歌。","故园寂寞不归去，奈尔临碧秋风何。"]},{"t":"寄赠元善张茂才","f":"七言古诗","c":["昔有姑苏张将军，百战起家身立勋。","太平老死筠州戍，孙子往往清而文。","继也芳年色白晢，未试征行已无敌。","论兵慷慨动风雨，挥笔从容谢锋镝。","将军战袍今尚存，犹污当时腥血痕。","猛思祖烈意未已，临风三叹消精魂。","高堂峨峨树长戟，堂下双槐高百尺。","清阴如水动秋云，密叶长枝总堪惜。","传家旧藏金虎符，佩之可以专千夫。","独推馀泽让诸弟，自喜閒适非其迂。","低头却骑款段马，长日行歌在林野。","已惊孝友动戎行，况复词华振风雅。","云有飞羽水有鳞，思欲一见嗟无因。","故人罗肇风格好，向我语子频殷勤。","海隅昨者南征急，诏下还闻烽警息。","将门缵武必英雄，似尔奇才岂终极。","我生长大不识兵，忧时漫使心潜惊。","但愿相逢日无事，与子把酒歌升平。"]},{"t":"送焦廷璋之洪","f":"七言古诗","c":["玄冬山谷寒崔嵬，北风吹雪从天来。","居人屏缩不出户，子有远行良苦哉。","道路苍茫岁云暮，甚欲留君不能住。","仙槎江口石潭深，南望不见青枫树。","送行却过东城头，更上桥西沽酒楼。","楼前无数白云阙，磊落如对三神洲。","当歌置酒忽不乐，少小无成总萧索。","长辕短棹日纷纭，山雨江云谩如昨。","闻昔尔祖出牧时，我家大父而翁师。","清尊画戟照白发，二老风流如见之。","旧家文物今何在，霜露荒荒岁年改。","珠林孙子真可怜，羡尔承宗振光采。","君家巷北我巷南，古藤秋树寒交参。","贱贫奔走少相聚，总有至乐何由堪。","昨者诵君新句好，于我还能慰枯槁。","雪消南浦柂楼高，忆尔离愁满秋草。"]},{"t":"赠李庚自万安迎侍祖母之庐陵就养","f":"七言古诗","c":["忆我始来万安日，远道依人附鸣鳦。","我方兄礼事尔父，见尔深怜好姿质。","束发双垂仅及肩，摄衣趋拜才过膝。","芝兰玉树未足贵，麒麟凤雏差可匹。","慷慨常闻尔父言，二十生儿寡童妷。","往客庐陵困县曹，携持又以司仓出。","未能郭外荷短镵，已解床头散方帙。","衣食艰难谩足忧，门户荒凉复何恤。","后来遣尔至馆下，庭训私闲颇周悉。","聪明日造开壅蔽，疑惑时能就咨诘。","读书先后群弟子，委靡之中见飘逸。","今年我留邓溪上，念尔远来业当卒。","担簦辑屦走百里，风雨泥涂忘沐栉。","尝从愤悱得旨趣，每以雍容谢呵叱。","盛年粲粲衣綵裾，玉雪娟娟佩刀珌。","早怜头角向崭绝，行看英华就充实。","近来尔父复司掾，见尔令我心内怵。","当家词翰追作者，东南才名今第一。","极知暂屈在孝养，岂直辛勤为家室。","此行此意尔未知，汝往应门勿私昵。","滩头水落石齿齿，上日放船北风疾。","汀云冉冉送归雁，江树离离杂柑橘。","白头大母柂楼底，羞膳三时候安佚。","青原雪消日在望，后夜抵城应可必。","天寒送子不尽意，蹇独荒山愧投笔。","穷年古书隐蟫蠹，坐榻寒毡沾虮虱。","好为人师古所戒，于汝深情岂容失。","远怀河南王廉者，勤学潜心稍精密。","又如丰城毛德广，规矩承家亦循率。","汝才警敏或过之，早已愧汝年十七。","白圭三复惧玷缺，欹器中藏戒倾溢。","由来进篑达贤哲，慎勿他岐累儒术。","矧闻特达可预卜，汝祖活人有阴骘。","终当雕鹗上云霄，岂有圭璋在蓬荜。","升堂再拜首问候，为说故人总萧瑟。","赍粮晏岁当远寻，剩有俸钱催酿秫。","世情泊如冰在水，友道庶以胶投漆。","城楼宫背草堂幽，先尔持书具称述。"]},{"t":"孙太守伯刚许送赵吴兴墨竹图赋短歌以促之","f":"七言古诗","c":["孙侯高堂竹石图，笔意迥与寻常殊。","山城五月困炎暑，坐我如对寒冰壶。","侯言此图不易得，吴兴赵公好风格。","昔者亲逢落笔时，茧纸寒翻雪花色。","竹丛隐石石作堆，海气乱拂秋云开。","夫人当坐共叹息，松雪斋前风雨来。","承平馆阁日多暇，承制文章此其亚。","往事苍茫四十年，万里江南见遗画。","当时亦有陇西公，直以健笔争相雄。","岂知书法自无敌，况尔勋阀谁能同。","楚也怀贤心未已，束发临池费千纸。","可怜生晚堕穷荒，不见中朝盛才美。","昨朝会宴池南亭，临图慷慨思吴兴。","停杯怜我重真迹，许以捲赠无难形。","吁嗟吴兴不可作，孙侯高谊犹堪托。","便令清晓送琼枝，即扫茅屋看金错。"]},{"t":"醉歌行赠周仲常归九江兼柬许天启汤又新二山长","f":"楚辞体","c":["奉君千斛酒，不尽万古情。","但令日日事狂醉，何用身后留空名。","汉家当时重公卿，天子亦复称圣明。","相如徒为茂陵槁，贾谊终作长沙行。","听我歌，奉君酒，颠倒英雄古来有。","朝客新丰暮帝庭，昨日负薪今结绶。","我怀磊块固不平，为尔作歌翻苦声。","世无千金赏词赋，安得三顾求躬耕。","君才特达吾所惜，暂客风尘未为失。","海雁南飞羽翮高，宛马西来汗毛赤。","君家自是山东人，将相所萃皆奇珍。","著书未献明光殿，移家早住浔阳滨。","山东迢迢隔千里，不如浔阳好山水。","九江翠色天边来，百叠云屏雾中起。","山有谷兮水有湫，昔人旧游今人愁。","风湍云木石壁下，?猱抱月鸣啾啾。","登高眺古频惆怅，壮心飞扬而浩荡。","青山不及苍梧东，碧海遥连洞庭上。","秋风落叶何茫然，鼓棹直汎章江船。","黄公滩头醉明月，吹笛绝似洪厓仙。","我留异县岁华晚，客路遭逢谢青眼。","浮云相别好相忆，白日西飞未能挽。","吴钩错落紫绮裘，放歌醉舞云中楼。","向来不尽万古意，寄君远挂匡山头。","君不见钟陵汤茂才，又不见宜春许文学，十年留滞困江城，一日飞腾动寥廓。","昔者之别今何如，景星夜粲东南隅。","君行何以慰寂寞，南帆一致湓江鱼赠。"]},{"t":"睡仙观魏炼师归豫章并柬黎铁峰仙者","f":"古风","c":["我忽不乐思西山，浮云孤飞道里艰。","睡仙之宫隔秋水，缥缈半落青霞间。","何年流火如陨石，郁攸煽天斗牛赤。","朱鬣苍龙天上飞，金甲神人露中泣。","当时炼师事远游，噀酒不到西江头。","归来三日哭灰烬，玄?吊月寒啾啾。","复独乘云翳鸾凤，赣水南边谒林洞。","千章乔木閟烟雾，逝此伐之作梁栋。","空山留滞今几年，断础荒甓凄寒烟。","堂中老仙发如雪，吹笛日望南归船。","南平监州最惜别，手挽琼珂弄明月。","誓将绿简授玄秘，恨不携之觐瑶阙。","铁柱仙人铁峰老，须眉飘萧颜色好。","一径清风扫落花，千岩碧雾耕瑶草。","昔曾暂宿清隐宫，石炉夜看烧丹红。","烦君乞与换骨药，明当跨鹤长相从。"]},{"t":"冬日闻百舌","f":"七言古诗","c":["臈月二日冻雨晴，百舌飞来庭树鸣。","鸣声不已自唱和，一出飞时人尽惊。","我怜此鸟在林谷，羽族之中能晦明。","常年畏寒音语滞，思之不见疑化生。","青门云屯春正远，何得先至江南城。","由来气类兆微物，无乃阳动潜满盈。","南园桃李花乱发，北岸垂杨青载萌。","苦无坚冰与积雪，厉气方此疵穷氓。","书生怪此坐叹息，安得挟弹驱不平。","圣王在上律吕协，燮理况有皋夔英。","凤凰千仞览德下，雍喈或继箫韶声，肯使凡鸟漫纵横。"]},{"t":"题枯木图为王子启作","f":"七言古诗","c":["高堂展图飒寒景，古桧峨峨出苍顶。","坐上疑闻啄木声，空中忽落蛟龙影。","干株偃蹇势回薄，梢节盘撑气深猛。","寻常岩壑真有此，六月炎风为之冷。","密叶中含雷雨垂，危标上逼云霄迥。","悬猿清秋怯倒上，饥鸢落日愁相并。","浦口回舟望北林，原头立马瞻西岭。","刘郎此图昔所画，物色笔势生雄骋。","王君得此绮绣重，玉立阶墀见清挺。","经年烽火万山赤，赭伐还闻到条梗。","天寒荒野霜露白，萧瑟阴风助悲哽。","岂无千尺栋梁具，摧绝泥沙竟谁省。","深山大泽龙虎死，惨淡相看愁不醒。","海波万一解经天，亦欲乘槎掠参井。"]},{"t":"题春江忆别图","f":"七言古诗","c":["渝川故人黄子雅，天机深沈好挥洒。","往与范君别螺川，写图远寄螺川下。","螺川东偏呀石矼，呼吸万里之长江。","江流不返客行远，何以使我愁心降。","是时春风散杨柳，十里啼莺劝人酒。","肠断逢君复送君，买船夜下渝川口。","双凫俱飞今独还，为子一赋河梁篇。","向来照见惜别恨，惟有明月留青天。","断矶侧岛秋毫杪，肯信离愁是中少。","水生浦溆万舸集，日落天涯数峰小。","故人别来今几秋，落叶夜满城南楼。","至今展卷忆旧别，对之如见春江流。","嗟君久别何能返，霜雪惊心岁年晚。","一春尘土暗沾衣，千里松楸终在眼。","功名富贵复几时，林下閒人相见稀。","飞鸿远征碧海外，春至亦复思南归。","人生离别岂云暂，我亦临图伤梗汎。","便将高谊谢陈雷，从此深情见黄范。"]},{"t":"河之水赠草亭狄隐君归京城","f":"古风","c":["河之水，瀰而黄，十月北风吹大霜，送子欲往愁无梁。","斲冰嵯峨冻地裂，鸹鸧呼寒堕其翮。","单车匹马从南来，踣铁交蹄五花白，北渡河流望燕月。","初月剪剪如弯眉，征夫道上愁别离。","青峰石壁猿夜啼，橡粟寒落林头枝。","何年结亭海子隅，亭成祇爱西山住。","閒歌白石看秋云，却卧紫萝听暮雨。","门前十二杨柳株，可以坐钓秋江鲈。","画船丝发照碧水，风骨自是仙人徒。","人言京国求官好，君独辞官事幽讨。","西山白雪深于云，期子餐之以终老。"]},{"t":"寄赠张隐君","f":"古风","c":["仙人身著紫绮裘，昨者来自南陵州。","南陵之山高百尺，中有叠嶂之危楼。","烟光涌翠当碧落，石瀑飞嶂鸣清秋。","庾公谢朓招不起，至今山水令人愁。","飘然戏笙鹤，南过三湘去。","落日下洞庭，长歌揽巫楚。","楚王台榭杳霭间，青鸟飞去何时还。","三十六天朱陵洞，七十二峰南岳山。","娟娟绿萝裳，袅袅临流女。","倏忽如飘风，白波愁日暮。","重华之琴不复鼓，灵瑟年年泣秋雨。","仙人自是留侯徒，口诵黄石相传书。","左按钧天之广乐，右接奇肱之飞车。","鱼龙掀舞明月下，坐使千古成须臾。","我思仙人碧云里，再拜扬言惭仰视。","瑶草春香石洞霞，白榆夜浸天河水。","天河水流无尽时，织女秋鬓应成丝。","若过扶桑定相待，我欲乘槎浮东海。"]},{"t":"胡郎夺贼马歌","f":"七言古诗","c":["往年寇逼西昌门，寇来愈近人愈奔。","胡郎愤拥长戈出，三人同行一人逸。","贼驰高马先入城，胡郎扑贼绝马缨。","大呼陈郎急缚贼，自夺贼马归行营。","行营主将气如虎，献马俘囚万夫舞。","陈郎受赏胡郎辞，誓立奇功报官府。","时平事远名空存，主将身没功谁论。","猖狂扼腕诋时事，有身虽贫宁畏死。","武山落日金钲红，至今杀气蟠秋空。","东家得官金满带，叹息胡郎打牌卖。"]},{"t":"寄赠曾文祥","f":"七言古诗","c":["十年不见故人面，秋风吹云隔山县。","当时相遇潋江亭，感子哀吟泪如霰。","山川莽莽生风尘，道路东西长苦辛。","鬓毛萧索易成老，肝胆轮囷空向人。","金精洞前偶相访，一读新诗一惆怅。","短章孤韵破岑寂，长句雄辞入悲壮。","杜陵布衣日烦忧，闾阎小儿狐白裘。","文章有神足自托，富贵无分吾何求。","平原信陵骨已朽，折节好贤竟谁有。","苍苔茅屋双短屐，落叶离亭一樽酒。","丈夫意气未可摧，临汝田园须早回。","成名岂必在朝市，自古云林多异才。"]},{"t":"詹君行","f":"古风","c":["易君本姓詹，旧是宜春人，父因避祸窜本姓，市药海上终其身。","君独怀乡心未改，万里从亲衣斑綵。","东游曾过金精山，最爱峰峦蔚神采。","后来父死南海头，负骨返葬山之丘。","坟前螺石云五色，下有江水相交流。","结庐庐墓霜露宿，采山更筑城西屋。","娶妇生男乡井同，二十年来变音俗。","故藏只有岐黄书，种药南园时自锄。","刀圭白昼摄龙虎，灯火深夜笺虫鱼。","长沙不作医绝响，金匮玉函竟谁仿。","临川学士青城仙，感子钩玄重嗟赏。","我闻葛洪好鍊丹，海内名山多往还。","似君心性本清逸，服御元气良非艰。","大冠长衣玉雪质，岂以寻常混踪迹。","清秋乘月倒芳尊，却话当年泪沾臆。","我歌詹君行，歌短难为情。","昔人忧患勿复道，宜尔子孙歌太平。"]},{"t":"谭骧病目累日王以文进药愈之因诗柬谭仍以美王云","f":"古风","c":["城西谭骧诗最工，骨格瘦紧精神充。","??六月暑竟夕，烧烛读书双眼红。","迎风眵泪时簌簌，隔花烟雾方濛濛。","科头颦蹙谢过客，十日枯坐幽房中。","王君闻之惜英俊，走马来问为忧忡。","探囊试药启羞涩，惧彼白翳侵其瞳。","冷然沃以寒冰雪，眉睫洒洒生清风。","朝行犹眩阶下蚁，暮出已辨天边鸿。","只今豪吟饮大酒，青白顾盼何英雄。","吁嗟王君习静者，精艺乃尔能神通。","卜商张籍苦不遇，枉使千载称盲翁。","速令沽酒市肥羜，往谢昔者开明功。","谭骧谭骧慎尔明与聪，王君之德无终穷。"]},{"t":"曾君育骏马歌","f":"古风","c":["曾君好马有马癖，昔买骏马千金直。","一从徵刷上天衢，每见流星想行迹。","今年得马胜前马，八尺垂钩汗流赭。","落花风细草如烟，时控青丝出原野。","官中多马劳驰驱，得似此马闲且都。","朝行疑逐飞鸟没，昼浴恐与神龙趋。","逝兹太平麟凤从，此马自在此林中。","几人相马识神骏，骨骼卓荦真奇雄。","溪崖泥盘石角溅，戒尔圉人勿轻贱。","清刍黑豆未渠饱，锦障金羁竟谁荐。","君不闻幽并马群五色俱，北客长驱愁远途。","南来往往凋丧尽，似此骏骨一匹无。","似此骏骨一匹无，临风为尔增嗟吁。"]},{"t":"同张士敬姚超白炳文南宗上人饥别张怀德千户于大愚寺之松林赋柬诸君子","f":"七言古诗","c":["张侯早负熊虎姿，文雅羁穷人共知。","凌晨调笑出东郭，健步不烦鞍马骑。","茭塘蒲港明如画，风日萧萧动初夏。","寺门还抱碧溪流，石桥正度丛林下。","高原过雨不作泥，晚色乃尔寒凄凄。","草间移席僧共至，松下传杯莺正啼。","姚君玉立长九尺，谐谑倾筵须奋赤。","旷怀亦有张与白，总是君侯好宾客。","酒酣浩歌激清商，却望浮云思帝乡。","松花落雪愁日暮，拔剑起舞空徬徨。","知君袭武坐文癖，败壁有书无寸戟。","犹滞泥沙未得伸，在于楚也空嗟惜。","明朝闻买淮河舟，聚散萍蓬那可由。","即看丹凤楼前醉，还忆沙罗门外游。"]},{"t":"题李遵道石林秋思图为刘元善赋","f":"七言古诗","c":["李侯昔牧黄岩州，骑马日向黄岩游。","黄岩山下多水竹，五月海气凌清秋。","李侯为政百不忧，濯缨日寻南涧流。","兴来往往挥翰墨，点染毫末成沧洲。","此图精妙不易得，非子好怀谁见收。","卷舒不穷寻丈间，岂止百里盘绸缪。","青山欲尽乱石出，赤岸正隔重沙幽。","星芒堕地觉书立，玉气穿林疑夜浮。","枫楠偃蹇皮半蚀，丛灌苯尊枝相樛。","长松或拥翡翠幰，曲蔓亦罥珊瑚钩。","深岩欲雨雷电入，古路无人魑魅愁。","峰回坂折见修竹，万箨摇动寒萧飕。","仙娥鼓瑟环佩合，壮士临轩戈戟遒。","云巢隐隐出猿狖，雨叶渺渺啼钩辀。","天台雁荡日落外，湘水苍梧天尽头。","风烟满眼入惨淡，霜露在野行夷犹。","乃知托兴属幽远，苦心拂郁奋独抽。","当家父子风格好，似此更以神情优。","只今海内重寸纸，光价岂止琳与璆。","平生爱画少真迹，见此令我消烦忧。","秘书内府那得致，愿子慎藏思蓟丘。","乾坤浩荡文物远，呜呼李侯今罕俦。"]},{"t":"宴集洞山寺分韵得见字奉柬丁克诚颜中行王敬仲詹德裕枯林上人","f":"七言古诗","c":["洞山之阴郁葱茜，上日开筵集群彦。","入门已觉禅境旷，放怀且慰书佣倦。","石林秋风晚更急，山城野色寒初变。","长松挺拔各千尺，堕叶飞来时一片。","雨垂弱蔓当井角，泉引青苔入阶面。","移床曳屣各散漫，接句行杯自流转。","交挂卑枝白纻衣，叠欹细草轻纨扇。","云开绝壁霞隐明，风度危梢露惊溅。","楸梧莽苍谁氏冢，金碧辉煌梵王殿。","百年荒废自足惜，昔者荣华竟谁羡。","田园閒日思把耒，淮海经时尚传箭。","共嗟寇盗困徵发，深幸羁穷及谈宴。","感君相与重意气，使我顿欲忘贫贱。","天外清风似流水，林端落日如红茜。","岂知驱车复为别，愿得载酒频相见。","醉醒聚散安可常，悲吟怅望西飞燕。"]},{"t":"陪刘公权登戍楼","f":"七言古诗","c":["凤山东偏锦水头，独立缥缈之戍楼。","登楼览古意不极，芙蓉双轴悬清秋。","将军国初镇吉州，投戈论道皆清流。","藏书蓄画几千卷，缥帙紫锦珊瑚钩。","郭熙山水韩干马，生色芙蓉更潇洒。","霜涵雨浥姿态发，往往时人未能写。","筠州移镇七十年，遗物犹存今所寡。","看花把酒临秋风，我思将军安得同。","苍茫共惜千载意，磊落已见诸孙雄。","近者提兵入南中，号令不减前人风。","蛟鱼出没江海暮，一麾尽扫烟涛空。"]},{"t":"听左鍊师吹箫短歌","f":"七言古诗","c":["左师本是吹箫客，惯作浮云出洞声。","临川学士所最喜，华盖山中曾共听。","昨夜宫前看月明，玉箫零落难为情。","含宫引羽自倡和，蹙口吹作呜呜声。","回飙划然飞雾入，王母旗翻羽车集。","蛟龙倚柱亦潜听，鸿雁盘空更飞急。","古来乐府音调殊，师独得之心口俱。","何人喧閧杂蛙黾，急管狂歌增郁纡。"]},{"t":"题常棣鹡鸰图短歌为旷伯逵赋","f":"古风","c":["旷郎示我鹡鸰常棣图，冰石盘激花芬敷。","寻常林泽总惯见，何以令我增嗟吁。","知君有弟在乡邑，少小别离忧患集。","经年不省瘠与肥，却望南云泪沾臆。","曾不如常棣花，荣悴开落同根枝。","又不如鹡鸰鸟，飞鸣行摇侣相随。","我思古之人，无若周公旦。","安宁与急难，往往寓悲叹。","君独奚为长道途，胡不来归兄弟俱。","笾豆满筵酒满壶，兄醉弟舞歌呜呜。","歌呜呜，乐无央，堂前花开常棣香，鹡鸰来巢春日长。"]},{"t":"题唐子华江干幽居图为余子芳赋","f":"七言律诗","c":["山风不作众壑静，江雨初飞入寒暝。","绿浦迢迢碧草交，丹崖窈窈青林并。","金牛石前螺子冈，子行何时归故乡。","野航把钓秋水迥，江亭读书春昼长。"]},{"t":"颜明德自全椒避乱归安成道过瑞阳赋别","f":"七言古诗","c":["凤山山头日欲暮，北望风尘暗行路。","喜君近向全椒来，别我将返青原去。","仓皇面目带风日，颠倒衣裳杂霜露。","投身幸从异境脱，执手且慰同乡聚。","比闻冲斥剧豺虎，汝颍徵兵急救捕。","繻符严诘千里道，戈甲纷填九江戍。","主人念客苦留别，立马不发空愁顾。","归心早逐匡山云，愁思空迷锦江树。","驱车南出清江曲，三日风帆快驰溯。","远游无方古所戒，菽水怡亲窃终慕。","我贫未归不得意，感子于我今相遇。","未能呼酒一浇涤，秖以软语相温煦。","空山落叶慎行李，极浦苍葭但烟雾。","残年旧隐如可寻，思君更咏閒居赋。"]},{"t":"送李元忠归彭田歌","f":"古风","c":["自为筠州客，喜识同乡人。","颜君高迈杨子淳，李也俊逸迥绝尘。","令我一日思再亲，见之歘然愁恨深。","水边行吟月下坐，意度往往清而真。","昨者相携登凤山，酒楼正对桃花湾。","锦江西来春波碧，乃有鵁鶄鸂䳵荡漾当其间。","此时与子初为客，笑指青山归未得。","有约残年共汎舟，要看三洲雪花白。","雪花未飞冬又春，子行车马何辚辚。","姑苏公子自好客，况是东南贤主宾。","惜君掉头不肯住，送君却望城南路。","江雾寒深橘子林，吴霜夜满丹枫树。","今日何日朔风吹衣，子不我思翩其先归。","河梁携手行依依，筠州故人从此稀。","黄尘出没乌帽远，寒雁杳杳随人飞。","雁飞南北安可期，客行最忆重逢时。","高梅始花已烂漫，对酒不饮将奚为。","君不见古人抱才或未遇，亦复低徊叹迟暮。","不乘驷马独西归，岂信相如好词赋。","君才衮衮不可婴，毋以离别伤其情。","匣中干莫时时顾，即恐飞腾雷电惊。"]},{"t":"题平川雪霁图为张用可县丞赋","f":"七言古诗","c":["南天北风暗吹雪，川上遥峰互明灭。","云阴欲堕晓光迷，河流不动层冰结。","鱼龙下蛰深泽冷，鸿鹄啼饥眼流血。","千村万落连苍莽，惊沙枯树相凄切。","行人稍出皴手足，怅望林居总愁绝。","我家邈在武山东，屋前石岸多青枫。","野桥渡溪沙路远，皆与此图风景同。","穷年念此政欲返，寒色恍入虚庭中。","长镵斸药崖谷滑，短褐负薪环堵空。","闭门且尔暂投息，会见日出光昽昽。"]},{"t":"题杨奇琛所藏山水图歌","f":"古风","c":["我本白云人，爱住青山下。","五岳寻幽未忆归，穿岩历壑穷秋夏。","曾看绝壁明高霞，秀色照耀金莲花。","洞前远访丹泉井，谷口时逢白鹿车。","鹿车东渡溪流浅，瑶草春香绿如剪。","海门日出天鸡鸣，手接飞萝上层巘。","是时笙鹤从天来，径欲浮海观蓬莱。","云路微茫波浪阔，使我叹息空徘徊。","十年汨没尘埃里，却看丹青心独喜。","问君何处得此图，彷佛林峦烟雾起。","虽无秀绝凌衡岷，点染亦复穷其真。","深林修竹草亭静，似是水边修禊人。","苍苔白石临流路，亦欲相呼抱琴去。","晴天指点北飞鸿，应识云中旧行处。"]},{"t":"送别杨奇琛归洞江歌","f":"古风","c":["朝别李元忠，暮别杨奇琛。","各言故乡久离别，使我历乱空愁心。","愁心忽如江上风，不可凭御谁能穷。","南行浩荡一千里，吹雪径度青原峰。","我生少小轻乡井，独以羁穷寄形影。","经时负米未能归，何待他年愧裀鼎。","閒来思种东村田，青山欲买羞无钱。","携书强聒附童稚，客中相顾谁相怜。","杨郎杨郎本同郡，文水钟奇故才俊。","芳年初发春江长，劲气已逼秋崖峻。","读书东家不下楼，手写细字如蝇头。","长怀丹阙陈三策，独抱遗经穷九丘。","春风二月惊初见，伯劳东飞遇西燕。","凤山祠下月如眉，明绣楼前水如练。","看花把酒能几时，念子还乡从此辞。","城头乌啼北斗曙，飞霜已落青梧枝。","桐江东南符山岭，闻子幽居好林景。","千年古剑合神机，光射玄潭黑风冷。","子归何时当再逢，即恐睽隔劳忧忡。","江外风尘眯人目，我欲远寻麋鹿踪。"]},{"t":"题吴教授所藏黄大痴画松江送别图","f":"古风","c":["是何山莽莽以横，云水浩浩而生风。","天低江迥日欲落，别意乃在苍茫中。","问君此图作者谁，浙东老人黄大痴。","松江先生旧知己，眼明为写秋江姿。","重坡欹岸东南远，木末参差见层巘。","苍浦遥连楚泽深，石林尽带吴堤转。","是时先生从此归，把钓欲拂云中矶。","长风过雨蒲苇净，水色淡沲沾人衣。","只今又作筠州客，惆怅松江渺云隔。","离思犹迷雁荡烟，归心已历洪崖石。","我思大痴焉得从，笔墨往往遣奇踪。","草衣骑牛发如雪，吹笛忆过天台峰。","平生一笔不轻许，傲睨王侯笑尘土。","展图坐对凤山青，却想高情动千古。","君不闻功名利达能几何，长安离别日日多。","灞陵亭前春草碧，灞陵亭下春风波。"]},{"t":"卢仙坛歌","f":"七言古诗","c":["我思昔人有卢仙，冥栖乃在三顾巅。","后来乘云去不返，荒坛委绝成千年。","坛角峨峨石色古，上隔青天应尺五。","飙车笙鹤时下来，白日松梢度飞羽。","云霞东南五色开，当时旧宅安在哉。","林间驯虎去已久，池底神鱼呼不来。","我惭学仙苦局促，十日寻幽憩林麓。","月中缥缈见乘鸾，示我玄文不成读。","中峰积翠凌紫冥，下有流水声泠泠。","丹崖千仞不可陟，黄叶满山秋露零。"]},{"t":"题纨扇画景赠易茂才","f":"七言古诗","c":["故人高兴蟠云林，门对三山之碧岑。","却忆秋风相过日，溪口系船黄叶深。","石潭买鱼雨羃羃，松冈跃马烟沈沈。","翠屏千尺天上落，十日缥缈穷登临。","当时感激恋岑寂，常恐寇盗相凌侵。","落霞遥怜烽火赤，白云独拥高崖阴。","复忽山城五月暑，思挹风露清烦襟。","偶持纨素写秋树，已觉幽思回萧森。","天清遥见寒泽雁，日落如闻秋岸砧。","寄君重写千里意，感我惜别多愁心。","交交林间双鸣禽，临风忽来遗好音。","青松白石可娱老，从尔倡和山中吟。"]},{"t":"忆昔行美达监州","f":"七言古诗","c":["圣王端居总四夷，黄河妥帖东南驰。","明明政化若流水，祸乱之梗谁阶基。","咄哉事变异往昔，簧鼓邪说非寒饥。","嚣然挟兵起田里，诛杀长吏为妖魑。","绛缯烈火照山谷，摧陷焚劫何纷披。","绝淮渡江徇荆楚，千里一槩同倾危。","汉江宫树三月赤，黄鹤低逐南飞鸱。","达官贵人履霜露，宝玦夜堕珊瑚枝。","荒山日落骐骥病，极浦天寒鸿雁悲。","南平百里据平衍，岂有险阻当城池。","红尘一骑传警急，白日万口悲流离。","我侯世臣之子孙，出监兹郡贞而慈。","愤呼歘起艰危际，挥斥义勇如家儿。","指天出誓肝胆露，飒爽风吹玄武旗。","内防外拒张筹策，恩义结民民感之。","鼓声彻云战斗出，往有死志无生期。","坐开黄堂受俘馘，太守自拥将军麾。","风霆气震随阖辟，泰华壁立无偏欹。","旗旄不动晚色净，刀剑错出天光垂。","帐前眈眈立虎兕，府中矫矫趋熊罴。","苍茫杀气薄云汉，鹰隼奋击当其时。","龙洲沙平万马集，草中白骨高于坻。","穷冬霰雪自摧厉，晴日柳梅俱华滋。","此邦不随风景异，阖郡实荷贤侯私。","上连崆峒倚南极，下决淦水开东陲。","风尘岂止廿四郡，平原义士真吾师。","褒功会蒙天子诏，颂德早见邦人祠。","我瞻四方何蹙蹙，经济允藉英雄姿。","时平抚事增太息，再歌忆昔陈苦词。","意长歌短不自己，太史万一观民诗。"]},{"t":"战敖原美周公瑾","f":"古风","c":["寇初来，战宜田，烈火夜飞光照天。","青山跃马壮士出，一鼓转战清炎烟。","寇复来，战周岭，马上秋风动旗影。","重围突破散如云，部曲归来自雄整。","问之此战谁第一，吉水周郎本无敌。","报国宁论万死功，荡家笑却千金璧。","君不闻敖原之战尤所无，最后制胜真良图。","草间麾呼伏兵起，数万贼徒同日死。"]},{"t":"题曾氏所藏历代青微法师像图","f":"古风","c":["素阳真人仙者徒，示我列仙之画图。","霞冠云氅玉雪肤，一一神采浮双矑。","充如天府琳球腴，清如逸世山泽癯。","俨如佩玉当朝趋，矫如跨鹤凌天衢。","周流天地超有无，颜色不动精神俱。","最后幅巾疏眉须，云是真人昔者之所摹。","上穷元始下玄都，一本万派同而殊。","形随粉黑穷锱铢，气与风霆行八区。","我惭生晚堕儒迂，学道不解凌蓬壶。","拟从真人乞灵符，高飞愿逐云中凫。","前有作者邈已踰，欲往从之云何盱。","青城天台西南隅，云日光射金芙蕖。","三十六管吹笙竽，非君和之谁与娱。"]},{"t":"罗明远杀贼歌","f":"七言古诗","c":["至正壬辰闰三月，寇入庐陵肆猖獗。","城中火炎三日红，街市填尸港流血。","罗君闻之佯负薪，入城遇贼贼不嗔。","潜觇赤帻府中坐，乌合鸟散何踆踆。","归来裂衣揭竿尾，大呼杀贼招邻里。","麾前勇士忽如云，尽夺红幡逐妖子。","满城黑雾昼不开，大酋忽捲宜春来。","前锋出斗白旗合，列阵鼓噪如春雷。","庙前格战势转逼，援兵不来骑围急。","瞑目含创死不僵，犹拥长戈负墙立。","吁嗟罗君真可怜，壮节独在千人先。","骨枯血化功未录，有子食力家无钱。","庐陵忠义古无匹，太史他年有专笔。","纷纷跃马为何人，罗君倡义谁当陈。"]},{"t":"送刘子伟入赣谒参政","f":"古风","c":["拔剑击流水，浮云划中开。","长啸别亲故，悲风从天来。","问之行路谁为此，赵州太守贤孙子。","祖孙杀贼守泸江，父独先驱阵前死。","几年倡义不顾身，一日失援沦风尘。","家乡残荡骨肉散，空作穷途憔悴人。","至今悲愤肝胆裂，梦里惊呼宝刀折。","北风吹火乱山红，却望泸江泪成血。","赵州故人四海同，兵部卓有前贤风。","开筵倒履下奇士，豪杰奔走如游龙。","崆峒十月飞霜露，亦知青眼怜迟暮。","弓骑何时入羽林，勋名自合登天府。","赣江东流十八滩，滩石下激声潺潺。","忠臣孝子有苦志，为报飞书投九关。"]},{"t":"送颜用行归吉水并柬康隐君宗武","f":"七言古诗","c":["文昌进士颜夫子，昔在筠阳最知己。","春风携酒上坊楼，秋雨题诗洞山寺。","当时结交翰墨场，共言意气倾侯王。","岂知风尘各惊散，此地不得同翱翔。","君今只在泸源上，我亦南还窜林莽。","旧交零落海云空，梦里惊呼色悽怆。","往者山寇攻泸源，义门百口今谁存。","况闻亲庭抱永痛，妻子夜哭沙田村。","欲归无家出无仆，两年访我城东屋。","长林春暝风雨交，此日穷居转愁蹙。","柴门苦竹惟鸟啼，流水绕屋生春泥。","苦无一钱沽酒饮，坐据寂寞如枯藜。","鼓笳连江清夜永，短烛孤帷吊形影。","野麦陵陂老雁饥，寒风动竹枯萤冷。","知君豪宕轻黄金，感时亦复忧沈沈。","青云若负壮士志，白日难照愁人心。","谁能短衣事骑射，空遣悲歌泪盈把。","却望文昌从此归，东行定过匡山下。","匡山先生发如丝，十年不出真吾师。","便须晏岁荷短锸，共来山中寻紫芝。"]},{"t":"寄赠刘仲修","f":"七言古诗","c":["我昔东游紫瑶峰，手携仙人九节筇。","天宁讲师好静者，邀坐绝顶看云松。","是时君从槎溪来，石室相逢心眼开。","题诗忽满雪色壁，仙药昼下莲花台。","石桥流水听猿处，绝似天台赤城路。","不见山中王子乔，吹笙自入浮云去。","感君萍蓬无定居，几回寄我云中书。","缄藏怀袖不忍发，愁心炯炯明寒虚。","东南丧乱乘五载，昔者交游竟谁在。","清江碧嶂落日外，修竹啼莺久相待。","往闻亲庭阻归舟，书来可以宽离忧。","官船何日出川口，早晚相迎金凤洲。","凤洲萧条归未得，经年寄食江边宅。","早春舣棹忆曾过，行踏江沙雨中别。","君从二月来南平，我复鼓枻从东征。","城西王郎竹林下，怀我无限沧洲情。","如何相寻不相遇，空使愁心结烟雾。","春风吹尽碧兰花，愁满西轩绿筠树。","昨者临流别远人，忽忆旧游心更亲。","便当买船载歌舞，从尔烂醉江南春。"]},{"t":"马将军歌","f":"古风","c":["将军西北之英豪，二十飞骑能弓刀。","一官推荫恩独早，五载防边功最高。","庐陵缑山据岩洞，往者妖民歘惊閧。","将军出捕虎就缚，坐遣犬牙归制控。","去年杀贼文水湾，驰马猝遇深林间。","阴风吹沙白日暮，誓不返辔图生还。","督兵围寇寇穷蹙，逆箭飞来集其目。","据鞍顾盼色不动，拔箭目中遗断镞。","含创饮痛更发矢，泪眼模糊血蒙指。","红旗倒曳鼓声乾，格斗犹冲十馀里。","归来元戎亲问疾，部曲惊嗟勇无敌。","障塞争传烈士名，辕门早进中军秩。","君不闻将军事武仍好文，忠义持身真绝群。","乌东岭外寇如雨，南来只怕马将军。"]},{"t":"古松歌为泸江旷氏赋","f":"七言古诗","c":["旷君屋前古松树，亭亭上出青天外。","百年元气结云烟，十里行人望车盖。","君家旧物惟此松，谁其植者渔樵翁。","精神独立万文雪，枝叶犹含前古风。","东家主人好种柳，去年郁郁今年朽。","种花种柳事繁华，得似苍松屹孤秀。","我愿旷氏之子孙，戒尔斩伐勤培滋。","朝看松树砺气节，暮倚松树哦诗书。","泷山青青永无期，还念前人初种时。"]},{"t":"将归南平赋别罗斗明","f":"古风","c":["五月辞滕阁，南船遇北风。","故人一相见，乃在太湖东。","湖东无数垂杨柳，执手殊乡惊忽聚。","回舸沽酒豫章楼，且复维舟为君住。","忆我往年游潋川，城南日出花如烟。","龙王潭上钓秋水，太傅岩前听瀑泉。","洞门盘盘万松引，更爱灵山石如笋。","当时题句最思君，南海云涛隔飞隼。","何年海上却东归，栖息瑶冈掩素扉。","春雨歌残紫芝曲，秋风吹老绿萝衣。","南州萧瑟风尘起，跃马提兵从此始。","野狐不敢向南号，宝石峰前阵如蚁。","知君卓荦负奇才，离乱相逢心眼开。","绣衣使者入闽海，揽辔定觅君同来。","龙沙吹雪日欲落，旌阳仙居久寂寞。","人生富贵徒尔为，须把高怀付酣酌。","我有古剑青芙蓉，起舞莫惜千钟空。","明日开帆上江去，思君却望水西峰。"]},{"t":"题龚本立所藏燕文贵云岫图歌","f":"七言古诗","c":["豫章龚郎好文雅，锦轴牙签满书架。","示我春云出岫图，云是燕公之所画。","高堂惨淡开林丘，青峰赤谷烂不收。","长风浩浩起天末，万壑青云如水流。","松根石头伏羊虎，松顶垂萝绿如雨。","伊谁濯足望青天，绝似东归孔巢父。","匡庐巫峡相渺绵，三湘七泽俱可怜。","冥鸿萧条洲渚断，风帆杳杳归何年。","吁嗟燕公真绝笔，好手当时称第一。","残缣犹带汴京愁，墨色苍茫映寒日。","城楼六月烟尘黄，我亦看云怀故乡。","思君如忆图中景，应过水西寻姥冈。"]},{"t":"题边长文所画山水图歌为常伯敬赋","f":"七言古诗","c":["五月炎风扇长夏，黄埃扑面湖堤下。","山水娱人未拟归，撷兰轩里看图画。","中峰九叠开芙蓉，春云盘盘上高松。","苔径未逢秋雨屐，石楼似听霜晨钟。","飞鸿指点向何处，彷佛经行旧时路。","悬岩瑶草不知名，隔水桃花自千树。","问君此图作者谁，甬东边郎风格奇。","丹岩绿水照白雪，高兴如在钟山时。","钟山岧峣夹云起，六代繁华付流水。","芳草长怀北固游，啼莺曾识东山妓。","当时二谢声价同，登临到处遗高风。","钓鱼冲雪寒江上，骑马踏云空翠中。","只今南游归未得，日日临图看山色。","凤凰一去来何时，落日荒台暮江北。"]},{"t":"题边长文为黄子邕画雪舫斋图","f":"七言古诗","c":["箫峰隐者黄子邕，绿眉秀颊双青瞳。","雪中曾踏溪南石，坐听箫声云雾中。","悬崖路转愁独往，结屋溪边小于舫。","绝似山阴王子猷，夜半乘流入虚朗。","朝歌绿水怜芳春，暮歌黄竹哀时人。","长风远从海上至，划见六合无纤尘。","新城往年兵革起，林杪高轩化荆杞。","东湖湖上遇边郎，为写幽居雪山里。","千崖冻合凝夕光，江鸟不飞沙岸长。","别浦维舟初罢钓，深檐卷幕更传觞。","箫峰远在青天外，玉树萧森澹相对。","疑有飞軿驾白虬，飘摇下与群仙会。","仙人一去不可呼，此境欲往愁荒芜。","炎埃六月何由濯，日倚湖阴看画图。"]},{"t":"题余仲扬画山水图为余自安赋","f":"七言古诗","c":["金华仙人余仲扬，笔墨萧疏开老苍。","昨看新图湖上宅，烟雾白日生高堂。","层峰上蟠石皓皓，绝岛下瞰江茫茫。","长松并立各千尺，间以灌木相低昂。","松下上人坐碧草，秋影欲落衣巾凉。","囊琴未发弦未奏，已觉流水声洋洋。","赤城霞气通雁荡，巫峡雨色来潇湘。","谁能千里坐致此，欲往久叹河无梁。","风尘涨天蔽吴楚，六年怅望神惨伤。","玄猿苦啼岩北树，白雁不到江南乡。","赭山焚林绝人迹，如此山水非寻常。","此图本为自安写，亦感同姓悲殊方。","幽轩素壁泉声动，对此令我心为狂。","何由扪萝逐麋鹿，振衣直上云中冈。","登临一写漂泊恨，长啸清风生八荒。"]},{"t":"林森山水图歌","f":"七言古诗","c":["清江何人画山水，西村无传稚川死。","林生后出更清逸，笔法远师闽浙士。","深林大树交铁柯，远峰近巘分陂陀。","青天层峡见栈阁，落日平湖闻棹歌。","水边之亭绝潇洒，更看平桥度羸马。","千崖小径雪边分，百道飞泉雨中泻。","自言笔法由心运，墨色重敷看深润。","碧海春云动杳冥，泰华秋空入雄峻。","昨者相逢湖水上，闻筑幽居傍渔榜。","为君先赋采菱篇，答我新图迥幽旷。","图中好山千万重，还似闽中似浙中。","祇今欲往河梁绝，指点天末窥冥鸿。","我家茆屋珠林底，武姥仙坛两相峙。","何时为写看云亭，尽染西原雪华纸。"]},{"t":"梁孝子","f":"古风","c":["梁孝子，早孤而鳏惟养母。","有兄从军弃儿女，废姊寡居养无所。","孝子念母情所钟，迎姊就养来家中。","更携二侄共哺食，令母弄孙嬉笑同。","市尝大雪薪炭绝，起析舂具就炉爇，不令母知母心悦。","乱馀时果贵且珍，出买菱实先献新，母食甘之忘其贫。","梁孝子，行孝义，只不读书宁识字，天性真醇有如此。","吁嗟今之人，禄食往往肥其身。","同气乃异趋，肝胆如越秦。","孝子诚愧之，吁嗟今之人。"]},{"t":"题屏岫幽居图为万砯赋","f":"古风","c":["秋屏列岫之间，乃有万氏之圃，幽人之居。","门前青柳日系马，池上紫菱时钓鱼。","前年尘起龙沙北，万氏林居总萧瑟。","杨君好事惜奇胜，为写池亭寄秋色。","两松落落千尺长，高云不动江风凉。","谁能低头事权势，便思濯足歌沧浪。","东南连年困兵革，人生安居那可得。","向来华屋今谁在，忽忆旧游心惨恻。","君不闻王维别业孟城隅，亦有亭馆临欹湖。","当时胜迹逐云往，至今传得辋川图。"]},{"t":"题常伯敬撷兰轩歌","f":"楚辞体","c":["高人好幽栖，志不在华毂。","啸歌撷兰轩，俯仰无不足。","湖之水兮湘之山，怅余昔游始东还。","澧有兰兮沅有芷，言撷秋芳渡江水。","苍梧黯惨浮云重，帝子遗庙丹青空。","长洲极浦落日外，坐见千里生蒿蓬。","灵氛掩泪歌九歌，夫君不来愁奈何。","薋菉充帱艾盈佩，玉玦捐弃江之沱。","江沱隔绝秋风早，绿叶青青紫茎好。","露华香扑芙蓉裳，佩服从君可终老。","我有猗兰操，尘土混浊久不闻。","为君弹一曲，要使六合扬清芬。","扬清芬，觐九嶷，舞干羽，三苗来。","洞庭无波春草香，却棹木兰游三湘，毋使下女徒悲伤。"]},{"t":"题沙村江楼歌为刘方东赋","f":"古风","c":["朝游云亭夕憩凤冈，河水浩浩山苍苍。","白虹东来盘九曲，日出霞明见秋绿。","雕甍碧瓦歘飞翻，百尺层楼起林麓。","楼中仙人乌角巾，调笑日与云山亲。","满筵歌舞客如雾，中有万斛江南春。","昨来登临九月暮，落雁横江隐霜树。","锦袍夜冷烛花残，北斗欹斜挂琼户。","我欲援君绿绮琴，为君一鼓清愁心。","白沙翠竹自江路，金谷铜驼非故林。","吁嗟昔贤困羁旅，仲宣能赋终怀土。","何如对此日高歌，手挽松萝看烟雨。","东南豺虎日纷纷，几时书剑罢从军。","鹅鼻峰头望明月，鸡栖潭上钓寒云。"]},{"t":"赋白纻词赋赠旷伯逵归豫章","f":"古风","c":["吴姬十五鬟初结，白纻新裁光照雪。","手折芙蓉上彩舲，自唱吴歌送行客。","玉盘馔列鱼与凫，美酒丝络黄金壶。","江寒月出欢未极，城上霜飞啼晓乌。","唱吴歌，歌白纻，拂袖当筵为君舞。","井阑络纬方悲啼，还念寒机织成苦。","京城锦绣段，名都金缕衣。","一时服饰岂不华，岁晏漂落当何归。","朔风吹尘扑人面，敛袂褰裳泪如霰。","君行莫忘当别时，妾心皎皎难自持。"]},{"t":"题山水图赠兴国高多营将黄进贤","f":"七言古诗","c":["远山亭亭削苍玉，近山盘盘出平麓。","林生作此最奇绝，白日高堂坐空谷。","谷中出云云上天，深林曲涧回清妍。","绿萝初挂紫岩雨，碧树尽含秋浦烟。","北屯将军旧知己，看画寻幽心独喜。","为卷空间一片云，送君更渡蓝陂水。","蓝陂山前霜叶黄，乱峰刺天如剑铓。","何当尽扫豺虎穴，与子巢云歌凤凰。"]},{"t":"题胡典史所藏简天碧西山南浦图","f":"七言古诗","c":["草堂高人好奇古，手卷画图横尺五。","云是简君之所为，历历西山与南浦。","雁原鹤岭纷孱颜，春水乱入螺蛳湾。","章江杨柳绿如雾，滕阁正在苍茫间。","冥冥官舫北来远，风力渐纾帆渐捲。","天低白浪驿亭孤，云捩黄牛柂楼转。","城中酒楼喧管弦，歌女能舞花如烟。","菰蒲落日凫雁晚，风浪杳渺嗟何年。","反思往时寇围急，列舰旌旗半江赤。","官军血战龙沙屯，东北人家半荆棘。","为君指点寻旧踪，我思简君安得同。","高堂酌酒岁云暮，如见积雪明东峰。","只今风尘尚蒙翳，对此酣歌一歔欷。","丰城龙剑今有无，亦欲看云望奇气。"]},{"t":"赠杨抱一炼师短歌","f":"古风","c":["道人昔在白鹤山，羽服朝真居上班。","道人今居蛟湖口，雨褐云巾事林亩。","东南连年飞战尘，羌独远引栖其神。","天地清宁本于一，得此以抱宁非真。","吁嗟世之人，跨马而逐鹿。","衮衮驰风波，僛僛触岩谷。","岂知静者为有馀，不矜不竞游玄虚。","攀花行吟石上雪，扫叶坐看林间书。","白家桥东水如练，几度相寻不相见。","珠林月出听箫声，松尾天灯落瑶殿。","我有远意千万重，会骑竹枝双青龙。","明年洞口桃花发，与子踏云潭上峰。"]},{"t":"促促歌","f":"七言古诗","c":["弹刀作歌声促促，深林雀子黄鹯肉。","红船打泊大江心，口唱山前团阵曲。","短襦尽著妇人衣，彯缨如血凌风飞。","自矜主将重骁勇，扶醉当筵骑马归。","水营小军旧推奖，昨日新升万夫长。","掠地还牵农父牛，杀人更请官中赏。","帐前歌舞日纷纷，坐看隔江羊犬群。","传说山前多警报，无人说着大将军。"]},{"t":"送别傅奏差督军储却归吴都事水寨","f":"古风","c":["傅郎青云彦，文彩粲华组。","身骑五色马，出入将军府。","将军控扼水上城，连舻列舰如屯营。","昨朝令下急征饷，科帖星火来南平。","南平频年困供给，小麦秋荒禾未实。","私家何以办公输，流血呻吟更捐瘠。","兵储有程不敢稽，君独悯之增惨悽。","舣舟浦口坐荒寂，落日忍听饥乌啼。","五月香醪得倾泻，席上香蒲绿堪把。","过雨天低白浪中，隔江云出青山下。","豪来起舞情未终，为君感激歌秋风。","东南烽火万里赤，此乐茫茫安得同。","我惭栖遁相逢少，郁郁沉忧更昏晓。","别君三叹拂吴钩，注目云天决飞鸟。"]},{"t":"巢云歌为张彦升赋","f":"楚辞体","c":["君从匡庐来，啸歌白云乡。","白云千叠可揽结，九江秀色何苍苍。","云之来兮茫洋，云之去兮不可以将，触石而起随风飘扬。","问君结巢向何许，洞门遥架三石梁。","薜荔为藉兰为房，明月为佩青霓裳，飘然远在天中央。","手招云中君，为我吹笙簧。","朝日射五色，烂然成天章。","将西息乎昆崙之墟，南憩乎天台之阳。","于以卧八极游四方，锦屏倒照秋水光。","雪片吹落瑶花香，俯视六合中烟尘浩茫茫。","泰山忽破碎，海水成枯桑。","燕鸿越鸟无定栖，凤凰麒麟安可常。","我欲呼谪仙拾琼芳，援斗杓，酌桂浆。","却上匡庐望三湘，湘水深，九嶷长，云之巢，安可忘。"]},{"t":"送张知事之庐陵","f":"楚辞体","c":["忽不乐兮心惨悽，闻君移家当远暌。","手牵稚子候慈母，路出龙洲莺乱啼。","江烟冥冥江水绿，綵鹢班班照春服。","落花到处荡回风，杨柳人家并沙麓。","问君此别来何时，南平父老多遗思。","乱离欲定乃去此，念昔艰危亲见之。","茫茫江海悲游子，抱剑何因报知己。","狂心欲逐北飞云，夜下神冈渡江水。","江水深深愁人心，忆君安得穷登临。","我家茆屋珠浦曲，薜萝紫雾屯秋阴。","忆在竹林西，回船听江雨。","载酒看花醉不归，十里芙蓉烂晴屿。","浮云飘忽东北来，昔者嬉游安在哉。","岂知今年复远别，使我叹息青霞杯。","君持青霞杯，听我歌古调。","歌声激烈君不闻，手撚琪花向天笑。","向天笑，送飞鸿，我还山南君向东，出处悠悠安得同。","明日看君螺子浦，思君却上引龙峰。"]},{"t":"题钟元卿东皋读书处山水新图","f":"七言古诗","c":["闻君筑室在东皋，十年读书心目劳。","简编浩瀚照夜雪，歌声洒浙凌秋涛。","嗟哉古人不可作，行事心术照毫毛。","桓公徒闻理盐筴，轮扁岂识粕与糟。","唐虞制作烂如日，昧者何以识夔皋。","统传洙泗迨关洛，如绎独茧绝复缲。","厥今文胜道且熄，武弁侧目嗤蓬蒿。","何如酣饮事歌舞，而不车马驰轻豪。","胡为俛促事澹泊，岂有至乐堪陶陶。","飘吟一字至万卷，上薄文典旁风骚。","我时抱琴一来过，春色晴满城东濠。","堂前綵服候甘旨，座上巍冠延俊髦。","感君同岁复同志，饫我至理如餔醪。","我从前年返故里，投笔荷耒思遁逃。","昨观壁间画图好，此景可致车宜膏。","慎毋布衣事献纳，恐有使者来旌旄。","古云识字忧患始，孰谓椎鲁非吾曹。","山林便可谢尘滓，白云悠悠东望高。"]},{"t":"经武山下望虎鼻峰爱其峭拔赋诗一首过南溪柬萧鹏举","f":"七言古诗","c":["我行武山南向西，冈峦回伏当武溪。","孤标上撑出虎鼻，落日东射云中霓。","武山势高如卧几，后巘前峰互盘峙。","浮云独抗九千丈，异县相望百馀里。","金华越台方殿奔，大小尖星安足论。","武仙绿发挂琼树，手挹太白开天门。","乱来寻山苦嫌浅，石室何年閟苔藓。","明日南溪访故人，定接飞萝上层巘。"]},{"t":"题花竹脊令图","f":"七言律诗","c":["石崖春阴覆花竹，二鸟飞鸣以相逐。","人生兄弟乃类此，莫君写之最精熟。","吁嗟人为万物灵，急难相感非顽冥。","王风既远常棣废，尺布之谣安可听。"]},{"t":"题溪山春晓图寄赠萧翀","f":"七言古诗","c":["土山戴石石角倾，偃树杂出如幢旌。","青天微茫晓色动，雨气合沓千峰晴。","野桥西边有村路，之子鸣鞘踏云去。","重岩花发似闻香，隔水莺啼不知处。","东南连年飞战尘，如此山水何清新。","石田到处长荆棘，岂有荷耒春耕人。","我昨西游登武姥，手抉云霞望仙府。","把酒忽逢东海生，醉卧溪南紫萝雨。","紫萝阴阴覆岩扉，十日寻幽行未归。","云峰流泉半空落，六月飞雪沾人衣。","拂衣归隐知何日，却对画图心若失。","不闻流水渡溪还，时见浮云向山出。","怀哉桃花修竹林，江海秋高烟雾深。","岂无耕钓在田野，谁识悠悠沮溺心。"]},{"t":"莫君写鹰图","f":"七言古诗","c":["莫君写鹰如写生，毛翮嘴爪皆天成。","轩然缣素出奇骨，眼光上掣层云惊。","狠如猛士赴敌场，烱如愁胡望八荒。","屹如虎将坐戎阃，歘如雷电驱干将。","皂雕最大木鹞小，老鹘两翅森开张。","角鹰戴角下廖廓，海风飒飒天飞霜。","当时见画画搏击，突过陡捩捎平冈。","山禽塌翼雉碎首，仁者见之心惨伤。","知君才名重江海，攻画苦心三十载。","楚公绝笔见孤骞，太华峰尖见精采。","只今阴山谁复过，鸣鹘猎骑方森罗。","江南万里芳草绿，奈尔鹰隼飞扬何。"]},{"t":"寄曾郁文短歌","f":"古风","c":["澄江水，向东流，流向东昌江上头。","我有故人在江上，十年不见增烦忧。","白沙水声寒活活，黄岩云气凝清秋。","岂无沙棠枻吴女讴，可以载酒同遨游。","狂风吹山波浪恶，使我不得回轻舟。","翩翩云中双飞燕，衔书寄我频留恋。","书中展转道深情，但恨相思不相见。","春燕飞来秋复归，报书不遣壮心违。","碧兰紫蕙何由采，即恐萧条霜露稀。"]},{"t":"奉答彭进士晋怀祖诗","f":"七言古诗","c":["故人示我怀祖诗，文字郁郁含深悲。","昔贤遗恨骨已朽，前代风流谁见之。","云有张彭二老者，隐处乃在泸之湄。","当时忠义并感激，岂但词翰相追随。","苍茫甲子义熙后，寂寞朝士贞元时。","岂知清河已陈迹，彭氏孙子多文词。","明经继以甲乙荐，反顾已觉卑群儿。","春秋岩岩距邪诐，俎豆秩秩崇光仪。","伤哉时危事返驾，道在舒卷安其宜。","且辞青云卧碧草，更调白雪鸣朱丝。","壁藏似有鬼物护，先庐正在南山陲。","遗诗十首更馀一，事变恍惚传于斯。","风惊电灭八十载，君独感怆垂涕洟。","赓吟寄我歘满纸，浅才乏报空嗟咨。","吾宗珠林重三杰，作者已远伤颓隳。","故箧飘零澹庵帖，荒冢剥蚀平园碑。","承先未能欲谁过，有孙如子真吾师。","只今风尘哀仳离，泉麓来游嗟已迟。","萧郎东游定相见，为我道谢声吾私。"]},{"t":"题王楚皋墨梅歌","f":"七言古诗","c":["江西写梅谁最豪，近年亦数王楚皋。","一枝半蕊忽落纸，已觉酒兴生风涛。","醉来据案急挥扫，欹树崩崖杂枯槁。","乃翁白发苦吟诗，自是长沙风格老。","君藏此图何清奇，昔所未逢今见之。","横梢欲挂明月佩，冷蕊尽亚青琼枝。","是时七月苦炎热，恍惚当窗濯飞雪。","长疑素质梦中见，便拟临风向之折。","吁嗟王郎今已无，江南万木愁凋枯。","忽呼斗酒酬清赏，莫负当年冰玉图。"]},{"t":"别从兄本泉教授之南阳","f":"七言古诗","c":["我家兄弟犹联琚，四十年前无异居。","西头下市日来往，扫石共读林间书。","长成离隔风雨过，骨肉忧患何纷如。","老人大父忽已远，后者忽昧戚与疏。","南城府君子所祖，旧宅江上遗荒墟。","兄从往年住城郭，早有二子应门闾。","往从广西起荐辟，上隆职教腾清誉。","公侯子孙必复始，喜见仕版开其初。","衡州太守见旌节，设醴宾筵类左虚。","荆衡东南忽破碎，间道潜归惊崄㠊。","凄凉诸侯旧宾客，刺口论事从欷歔。","蛟湖流水清绕屋，灌溉可以勤菑畬。","寒风吹衣霜霰厉，子复南上辞林庐。","潮阳更在万里外，我欲遮道牵其裾。","安得乡园复聚处，带经跨犊随耕锄。","向来总角今老大，愧我寂寞如栖苴。","送行无酒不得醉，怀抱郁郁无能摅。","潮水有蛟山有虎，慎尔鞭策无驱车。"]},{"t":"夜出罗村","f":"七言律诗","c":["蛇矛捎云烟满溪，火光照山闻马嘶。","暴儿夜半打平寨，阳村岘头江路大。","梦中惊窜迷东西，十步九踣伤淤泥。","母号女哭不相顾，冥冥驱牛入山去。"]},{"t":"题曾郁文所藏山水小景","f":"七言律诗","c":["隔溪望见林间屋，沙溆阴阴俯群木。","溪流合处一桥孤，春雨来时万山绿。","江南此景真可怜，米家笔意谁能传。","却忆故庐珠浦上，短篱长系钓鱼船。"]},{"t":"庚子行","f":"古风","c":["庚子二月廿四日欲午，日有重环大盈堵。","居民惊走妇女怪，不敢喧传到官府。","一环赤黑晕日角，三环侧连白光络。","白光贯日日色惨，阳乌塌翼愁冲薄。","念此日是太阳精，昏祲重重竟安作。","吾闻古有日重光，明帝得之汉道昌。","长安非近日岂远，仰视低头泪如泫。"]},{"t":"题春江送别图赠谢可用归宁都","f":"古风","c":["我欲留君游武山，君不肯住从东还。","贡江盘回三百里，南望政在飞云间。","飞云岧峣蔚霞绮，似向金精洞前起。","老翁白发动春风，夜夜悲歌梦游子。","君从何时辞故家，江国飒沓愁风沙。","西里霜凋碧梧树，南国雨落青桃花。","知君惯作公侯客，五色文章振高翮。","南平江上一相逢，十日题诗楚王宅。","岂无东山屐，携子游云中。","锦袍飘然不可挽，惊雨夜逐南飞鸿。","江烟微茫江水绿，陈帝祠南树如簇。","画船东下双舻鸣，岸转沙回见林麓。","图画不可尽，送君从此归。","石苔已迷旧行迹，山色自满幽岩扉。","我登武山云，君弄贡江月。","重逢何处蹑飞仙，却望青天白云阙。"]},{"t":"赋澄江月送别","f":"七言古诗","c":["澄江江水清且深，明月下照愁人心。","浮澜浅浪惊不定，当空涌出千黄金。","此时使客宴高阁，坐爱流光入帘幕。","牛矶风定翠旗翻，蛟窟天寒宝珠落。","长洲菁菁杜若生，送君东下歌扬舲。","题诗若过旧游处，月色江声无限情。"]},{"t":"戏为友人干鱼苗","f":"七言律诗","c":["闻君凿池种鱼子，远注浔阳一泓水。","春风昨夜化灵苗，中有十万横波尾。","我惭枯涸生事疏，分致安得涔蹄馀。","风雷倘复化龙去，犹得江湖传尺书。"]},{"t":"夜宴王召南席上观黑厮旋舞胡瓶歌","f":"七言古诗","c":["绮筵烛艳歌停哢，春酒凝香碧霞重。","蕃童旋舞忽当前，头戴银瓶高不动。","银瓶花烂雪色新，俯仰之间如有神。","岂知头容自正直，欹侧愁杀旁观人。","拳毛蒙茸衬瓶底，宛转低徊舒四体。","眼看明月下昆崙，一片黑云飞不起。","使君好客酒漏卮，传令更舞君莫辞。","手中匕箸犹有失，头上银瓶高一尺。"]},{"t":"赠别钟举善游赣遂之汀州歌","f":"古风","c":["弹哀丝，喷双竹，四座佳人美如玉。","钟郎半醉起就别，杯行苦迟声转促。","高堂列筵当翠微，惜别更舞青萝衣。","云开日色酒中堕，风触歌尘梁上飞。","君行赣滩十八重，临眺可以登崆峒。","万山如浪压城郭，郁孤正瞰江流东。","两江盘盘石争长，东行入闽西入广。","盐花雪白荔子丹，天际船来海风响。","君家娟娟好弟兄，况有词翰齐清名。","出门相送一为别，感我无限幽居情。","山中香秫秋熟时，苦竹作笋池鱼肥。","我在南溪小楼上，调歌酦酒待君归。"]},{"t":"题萧鹏举所藏草虫杂图","f":"七言古诗","c":["鬼车团春米囊拆，萱竹缃桃红迫迮。","牵牛花碧露初坠，枸杞子红秋可摘。","青菘赤芥碧玉葱，攒英濯本当蒿蓬。","羽衣凄切自络纬，蜗角低昂方战攻。","蜻蜓头圆赤色尾，亦有纤纤绿罗袂。","草行蜥蜴金背烂，升竹盘拿更贪噬。","青蛙支颐目睅瞠，黑甲推车车倒行。","螳螂怒臂乃当辙，蜂蚁君臣谁敢争。","愁来对客看图画，似向芸窗笺尔雅。","丹青婉娈归动植，风日晴和到田野。","吾闻夏后德所形，昆虫草木皆清宁。","苕华芸黄星在霤，卷画歌诗双泪零。"]},{"t":"题云山图歌为武山胡炼师赋","f":"楚辞体","c":["山中之人兮云为徒，飘摇太虚中其迹安可拘。","朝溶溶兮山巅，夕泄泄兮山隅。","长风吹度山海上，遥见楼阁青模糊。","忆登武姥之高冈，遇仙人兮白霓裳。","方瞳绿鬓颜雪色，自挟凤竽吹洞章。","凌空欲度三石梁，中天北斗何苍苍。","俯视六合惊尘黄，金华玉华相渺茫。","浮云满地飞不起，但见白石磊磊如驱羊。","永丰刘郎称画手，为写仙山传不朽。","高堂白昼起烟雾，指点林峦辨窗牖。","图中如此两古松，岁久乘云应化龙。","弱水东浮会相见，长歌手把玉芙蓉。"]},{"t":"题幽居读书图为萧翀赋","f":"楚辞体","c":["吁嗟乎中谷把吾书，以归来兮于焉以读。","谷之阳兮云之麓，峰盘盘兮石如玉。","我居孔幽兮翳彼嘉木，遐思古人兮言抽其椟。","载咏载歌以悦我心，白云在天清风满林。","世昧昧以去古兮，礼乐散而莫寻。","探禹穴之窅窅兮，望龙门之高深。","林有鸟兮溪有鱼，尔飞尔潜兮我读我书。","以卷兮以舒，乐哉弗谖兮山中之居。"]},{"t":"题抱琴听泉图为萧翀赋","f":"楚辞体","c":["吁嗟乎空山抱余琴，以来归兮吾将以弹。","山之洼兮石之端，我其听之兮以写猗兰。","按余徽兮作复止，风冷冷兮触宫徵。","泉之流兮云中漱，鸣玉兮声淙淙，忽幽咽以下怆兮匪丝匪桐。","啼秋猿之袅袅兮，下南飞之双鸿。","山中之人兮不可遇，余徘徊兮中路。","九嶷蔚兮隔烟雾，我思南风兮噫其迟暮。"]},{"t":"赠吴生九成","f":"七言律诗","c":["吴郎去乱八载强，求友读书心不忘。","偶临白鹭看流水，却望紫鳞思故乡。","故乡湘南百馀里，明月千村照荆杞。","石桥山北多园田，花开会见归来年。"]},{"t":"安成王子文宝持其祖遗书与古今名公诗文于丧乱中甚不易也文廷刘先生哀其志为之叙其事因附以诗","f":"七言律诗","c":["金田王郎行蹙蹙，独抱遗书如宝玉。","往时奔窜亡一纸，十日山中望天哭。","王郎苦心真可怜，与书同食仍同眠。","如何浮薄心不古，世业弃捐如粪土。"]},{"t":"题刘孟文云林图","f":"楚辞体","c":["泄泄野服，峨峨云冠。","飘然而往，安可呼我欲致之青云端。","青云忽其渺绵，行深林兮望秋天。","抚瑶琴以叹息，拾春兰之紫鲜。","嗟哉若人志鸿鹄，伊谁写之在空谷。","向来腰间两龙剑，至今光截蓝田玉。","昨朝遇我城西曲，纵饮流霞动千斛。","醉歌李白董糟丘，三日惊风撼其屋。","我行驾鹿车，南游访名山。","绝顶见长松，世人安可攀。","水东天姥青孱颜，遥见洞岩烟雾间。","春风为报桃花发，与子其中叩石关。"]},{"t":"奉和王诚夫短歌一首","f":"七言古诗","c":["王君精神秋水清，作诗锵锵鸾凤鸣。","昨朝遗我长句好，感我无限沧洲情。","我从乱来少相见，阔绝朋游恍生面。","烟涛浩汹惊暝作，风叶纵横飒交战。","人间富贵多烦愁，海上神仙安可求。","不如高楼饮美酒，明日万事方悠悠。","羡君才名三十载，夕露黄花向谁采。","荒城满目尚荆榛，落日登临一长慨。","愁来忽听南山歌，袅袅归心悬绿萝。","江上月明今夜发，为君击楫舞泉阿。"]},{"t":"题竹石图歌奉赠周思廉思忠伯仲","f":"楚辞体","c":["周郎伯仲美且温，乃是南渡丞相之玄孙。","三朝书诏烂盈箧，旧物历世能俱存。","伯也从容端好文，仲也英气干青云。","芝兰晏岁在空谷，风露早已扬清芬。","吁嗟昔人邈千载，平园草木春先改。","衮绣坊前旧宅空，恩褒寺里遗祠在。","极知令德世所钟，矫如双凤骞云中。","为君挥翰写竹石，况有风节能相同。","嗟哉双凤世所奇，路远昆崙谁致之。","何如栖琅玕食竹实，乘清风翔八极。","烂文章兮耀云日，毋使山中之人空叹息。"]},{"t":"筑城叹","f":"古风","c":["君不见吉安城中十万户，往年筑城极辛苦。","城加百尺环两濠，日日程量深与高。","官长有号令，畚锸各自操，累然夫丁不敢告劳。","一朝楼船江上来，大开城门引旌旄。","城之石，高磝磝，濠之水，何滔滔。","今日之日为谁险牢，愧尔饥雀飞鸣嗷嗷。"]},{"t":"有虎行","f":"古风","c":["有虎有虎白额张，穴巢养子南山阳。","十年饥啸望城市，不食近山牛与羊。","乡民不知攫噬苦，叩首相呼拜神虎。","通衢白昼虎出入，从此乡民少防护。","一朝南行挟虎群，摇尾梢梢高入云。","长驱百里入城郭，神虎经过人不闻。","忽然凭怒风惨悽，赤手搏人如搏麑。","饮血血成河，啖肉肉作泥。","饫酣三日虎乃去，犹负犬豕归其栖。","可怜李将军，有弓不敢射。","却驱残卒守空城，更筑新围高百尺。"]},{"t":"雪中对酒短歌为萧翀赋","f":"古风","c":["南溪三日霰雪飞，千岩万壑含清晖。","萧郎扫雪辟虚馆，置酒张筵当翠微。","筵前翕翕香风起，金盘雪狮坐横尾。","嶷然顾盼色不动，眼光寒注清尊里。","清尊行酒如流虹，凿冰出鱼鱼尾红。","主人好客客尽乐，自挝大鼓声逢逢。","鼓声逢逢间鸣镯，乱来学得军中乐。","双吹龙管引吴歌，座上纷纷雪花落。","我不能拥雄剑鸣铁衣，驰入边城搴取五丈之长旗。","又不能挟大弓乘青骊，暮猎阴山赤手搏取虎与罴。","扁舟乘兴无所适，高卧閒门徒尔为。","何如烂醉千钟酒，更与迎春唱杨柳。","少年欢会能几时，莫遣朱颜成皓首。","愿携九节青玉筇，径上绝顶登云峰。","手招陶皮拾瑶草，却望三山银阙重。"]},{"t":"迁坛曲","f":"古风","c":["鼓鼕鼕，角呜呜，铜钲铮铮趋小巫。","小巫僛僛大巫舞，陈席开坛作神所。","坛前指画起楼殿，阴役鬼功人不见。","神来龙陂自有程，神马只向空中行。","大巫短袍红抹额，手携纸钱歌啧啧。","攒兵凿门分五方，置鞭坐坛横竹鎗。","牲肥酒香神尽乐，更聚童男捉牛角。","喝右即右左即左，旋转如风神降坐。","田禾好收牲畜多，官府不扰人安和。","主人再拜占珓卜，掷得中平喜如簇。","尽驱疠鬼置狱床，收兵回洞安此堂。","竹鎗衅血神送远，新岁阖门如所愿。","干戈早罢国无殇，年年迁坛神降祥。"]},{"t":"醉歌行赠曾举正","f":"七言古诗","c":["岁云逝矣不可留，空谷群木寒飕飕。","此时高堂对尊酒，非子何以宽离忧。","溪山苍茫延清望，瑶树琼林俨相向。","残雪初消薜荔墙，晴云忽拥芙蓉嶂。","杯行苦急歌转催，鼓声浩荡如春雷。","乱离飘散少欢聚，慎莫负此黄金罍。","平生结交遍江郡，晚得萧翀喜清俊。","人生最乐在知心，况尔才华更风韵。","当筵起舞相低昂，为子一饮空千觞。","功名富贵等腐鼠，底用龊龊空愁肠。","蛟龙何时起寒蛰，溪南昨夜春风入。","春风花开岩谷红，期子来游歌笑同。","高霄武姥好泉石，题诗却遍白云中。"]},{"t":"赋澄江赠友人别","f":"七言律诗","c":["澄江之水清如油，春澜漫漫光欲流。","微风忽动白鸥渚，明月正上金渔洲。","洲前美人綵舟发，起唱吴歌踏江月。","别愁深浅君自知，江流不断长相思。"]},{"t":"春宴曲","f":"古风","c":["大鼓作鼍鸣，美人花间相对行。","忽闻横吹座中起，吹出双双鸾凤声。","凤声微茫作复止，飞入青天綵云里。","当筵盛酒金屈卮，酌酒劝君君莫辞。","不见堂前桃李树，昨日花发今空枝。","东家作官闹车马，西邻从军能骑射。","一生长客边塞间，芳时不在乡国下。","何如载酒鸣云和，手折山花行唱歌。","少年有酒不痛饮，白发满头君奈何。"]},{"t":"啄木鸟","f":"古风","c":["啄木鸟，嘴长翼短栖木杪。","空山时时闻一声，木皮剥落非尔情。","此鸟不肥莫弹射，木中有蠹无人识。"]},{"t":"胡思齐逃酒潜归陷于淖中萧翀遣人追之不及而返赋此戏赠","f":"七言律诗","c":["胡君奇气不可束，掉头只怕杯中醁。","南溪三日醉如泥，昨夜潜奔似惊鹿。","横行冲雨踏麦畦，纵有绝足何由追。","归来主人怒骂仆，愁杀春衣泥漉漉。"]},{"t":"风筝曲","f":"七言古诗","c":["缉麻合线长百丈，要系风筝待晴放。","有风须及清明前，作得鲇鱼爱新样。","全身糊纸竹缚匡，两旗横张垂尾长。","手中缓放莫教卷，风力渐舒风渐远。","犹嫌平陇去不高，走上山头如掣鳌。","盘空一点正摇曳，欲坠更举何滔滔。","时人勿用旁惊睨，质薄材轻等儿戏。","乘时容易上云霄，失势终然在平地。","明日落花花雨寒，过却清明风力阑。","萧条断线挂虚壁，沟中破纸无人拾。"]},{"t":"布谷啼","f":"古风","c":["布谷啼，三月暮，麦老秧深时。","田头不见人耕布，家家丁壮起从军，更有中男筑城去。","布谷鸟，听我语，城中无田有官府。","莫向城市啼，官中人怒汝。"]},{"t":"题赵子深秋山风雨图","f":"七言律诗","c":["赵君大醉始作画，昔在清江常见之。","此图烂漫倒墨汁，木石满眼何瑰奇。","高堂苍茫风雨集，虎穴龙湫恍深入。","目断东南生远愁，雁鸿塌翼行云湿。"]},{"t":"掘冢歌","f":"古风","c":["富田筑城令期急，创起高围防外敌。","南山有石采凿难，尽掘坟茔取砖甓。","千夫万卒腾山丘，大斧长镵隳墓头。","子孙饮泣草间望，白骨纵横谁敢收。","高标木牌书姓字，只禁文家旧坟地。","将军为生不顾死，十日四门要城起。","石累累，城矗矗，昔锢黄泉深，今见白日速。","城中人欢，城外鬼哭。","哭声寄语城中人，尔移我居当作邻。"]},{"t":"虎食鸭谣","f":"古风","c":["虎婪馋，口嗒呷，夜入深山中，食人鸡与鸭。","念此鸡鸭非野生，人家经年养育成。","重檐月黑遽搪突，抉笼咥之良可惊。","十鸡宁满颐，百鸭不填口。","羸瘠无脂羽毛厚，长项细肋奚足取。","南山多犁牛，北山足麋鹿。","大者千斤小如毂，血如流泉肉盈谷，尔能攫之胡不足。","奈何长兽为山君，而乃下夺狐狸之食以充腹。","鸭能自呼鸡晓啼，上天诉汝魂不迷。","帝敕六丁拔尔牙，解尔皮，捣尔窟穴焚尔栖。","绝尔丑类为尘泥，深山莫生藿与藜。","依然万民中，咿咿喔喔鸭与鸡。"]},{"t":"南乡怨歌","f":"古风","c":["我家承平住城郭，自从乱来徙村落。","朝朝临河望烽火，只怕江船向南泊。","今年李寇打南乡，五更马蹄踏月光。","小船载军大船马，旗头直捣珠林下。","乡夫捲地散如烟，哨马已过前山巅。","尽杀丁男掳妇女，手麾牛羊雨中去。","前军出营后军续，昏夜抽刀草间宿。","缚人先问窖中金，放火还烧陇头粟。","先锋最说姚府军，火伴却是州城人。","全装尽作姚家扮，面目虽驯谁敢嗔。","人家兵过无遗物，万落千村总萧瑟。","室庐灰烬盆盎空，只有田园将不得。","君不闻东邻一老叟，向来家业馀升斗。","不论贱价卖花银，又向城中赎生口。"]},{"t":"采野菜","f":"古风","c":["采野菜，行且顾，野田雨深泥没路。","稚男小女挈筐笼，清晨各向田中去。","茫茫四野烟火绝，去年秋旱今年雪。","草根冻死无寸青，却揽苦荄泪流血。","水边蒲荇未作芽，甘荠出泥先放花。","长条大叶瘦且老，得似家园菘韭好。","枯肠暂满终易饥，酸苦螫人还自知。","采野菜，行且哭，贫家食菜苦不足，寨军掠人还食肉。"]},{"t":"二月十八夜辞屋叹","f":"七言古诗","c":["城狐暝嘷乌啄木，主人惊呼夜辞屋。","忽闻官军破城府，号令新传大都督。","火烧排栅照夜光，饶军奔溃人马伤。","快船直上春水发，明日军来安可当。","贫家无时走军马，少在家居多在野。","断垣未补棘遮门，败壁无泥雨飘瓦。","去年同行三十人，今年一妻兼病身。","弟兄飘散儿女丧，投杖欲往还逡巡。","人生辛勤理门户，暂去那能不回顾。","开花不得待人看，愤杀墙东旧桃树。"]},{"t":"东家叹","f":"七言古诗","c":["东家盛时厌卑促，拓地四邻起高屋。","乱来怕见门户大，还撤屋材作薪卖。","忆昔东家全盛时，伐材作屋穷工奇。","上捎云霞起觚角，下斲山石开垣基。","椎牛酾酒万夫集，华馆重楼事雕饰。","妆成明镜动春云，宴罢珠帘夜光入。","当阶血色射锦茵，门前骏马骄嘶春。","强奴悍竖拥轩盖，过客俛首方逡巡。","一朝乱离俱散走，大屋空令别人守。","近圃偷残旧种花，南池伐尽新栽柳。","风椽雨壁何披离，绮户白日横蛛丝。","昔人强作金石计，此日谩同蝼蚁悲。","全家远去无遗屧，日落鼪鼯啸飞叶。","离离烟草门巷空，时有邻儿拾檐铁。"]},{"t":"燕喽喽","f":"古风","c":["燕喽喽，羽缡徙，飞来飞去无休时。","主家门户已零落，泊向门前枯树枝。","枯树枝落多风雨，欲止还惊不能住。","一身投迹无所托，百口衔泥竟何补。","燕喽喽，羽扑簌，朝出愁飞暮愁宿。","杏梁暗逐綵云空，翠幕珠帘梦相逐。","社日欲过桃花稀，百鸟争巢春食肥。","池南华屋馀青草，落日时来掠地飞。"]},{"t":"告天鸟","f":"古风","c":["江南有小鸟，群飞上天入天杪。","黄茆岭头拾虫蚁，声声告天鸣不了。","山前山后春雨晴，啾啾千声连万声。","瞥然飞出不可见，失势一落犹哀鸣。","凤凰南飞顾之笑，何不远引为娱嬉。","谓尔躯体陋，羽毛无鲜奇。","径寸之茆可以营尔栖，一粒之粟可以充尔饥。","胡为踯躅苦抱愤，奋首上诉鸣声悲。","劝尔勿多言，多言生间危。","吻弊吭绝徒尔为，天门九重深不知。"]},{"t":"虎逐狼","f":"古风","c":["野狼据山作巢穴，连年呼群食人血。","一朝猛虎入山来，虎自凭陵狼迹绝。","山中久厌狼害人，乍得猛虎惊良驯。","岂知残毒乃本性，鼓吻磨牙更雄骋。","一鸟死，百鸟哀，一狼逐，十虎来，山藏泽薮胡为哉。","吾闻周公驱猛兽，不用长戈并劲弩，政教修德施溥。","人民欣欣乐含哺，麒麟来游凤凰舞。","上天甚明民甚苦，更万万古莫生豺与虎。"]},{"t":"后掘冢歌","f":"七言古诗","c":["岘冈西北龛村路，近郭家家葬坟墓。","富家尽栽松柏林，葬时装敛帛与金。","百年太平人事好，时时子孙来拜扫。","祭馀列宴画亭深，细马香车入青草。","墓门碑石高峥嵘，界水连山谁敢争。","枯枝堕地无人拾，牧竖驱牛山下行。","乱兵西来人散走，青野荒荒绝鸡狗。","丘坟已见遭掘伐，棺椁还闻被椎剖。","锦衾绣袂颜色新，玉珥金环光照人。","千年幽鬼窖中物，去作谁家富贵春。"]},{"t":"养牛叹","f":"七言古诗","c":["田家养牛如养子，爱惜皮毛少鞭箠。","一冬霜雪无青草，还喂盐羹龁糠秕。","全家性命系一牛，牛肥即喜瘦即愁。","木阑土屋护乾煖，出入更防人夜偷。","乱来买牛如买马，典尽春衣酬买价。","寸田尺土未得耕，军来牵牛谁敢争。","拦街号哭送牛去，青草空馀旧眠处。","君看新来山寨军，前日亦是耕锄人。","即今打粮不耕土，身着牛皮食牛脯。"]},{"t":"莫逐燕","f":"古风","c":["莫逐燕，莫逐燕，燕子清高不寒贱。","一生自在食飞虫，不啄稻粱看人面。","常年托巢城市中，文杏梁深杨柳风。","乱来华屋已尘土，还访茆檐新主翁。","主翁村居事耕作，种树绕庐延鸟雀。","朝朝驱燕出门去，怕见衔泥座中落。","燕子驱去还复来，喽喽告诉声低回。","巢成不碍主门户，年年去来解相顾。","不如林间雀与鸟，养成众雏剧如鼠，食汝场上禾与黍。"]},{"t":"剥苧词","f":"七言古诗","c":["江南人家多种苧，烧土壅畬筑围护。","老苗刈尽还再生，一岁收成看三度。","东家女儿颜貌稀，爱织白苧裁春衣。","侵晨入园捎乱叶，采剥苍皮连抱归。","归来临池濯苔发，轻管圆刀事拢戛。","修蛇委蜕鳞鬣翻，入手春云惊腻滑。","一月绩成催上机，官中科布星火飞。","恤寒敢计皮与肉，伐骨犹堪代明烛。"]},{"t":"寄赠陈侯短歌并柬项性高陈宗舜二进士","f":"七言古诗","c":["陈侯昔尹兴国时，为政喜尚清而夷。","讼庭无人山鸟下，蒲鞭日挂甘棠枝。","闻君佳誉喧两耳，玉树亭亭照秋水。","至今父老称诵之，满县春风散桃李。","锦袍羽箭乌角弓，身骑官马如飞龙。","只今出入宰相府，帐下貔虎皆骁雄。","羡君多才仍好武，轻骑能冲阵如雨。","酒酣肝胆向人倾，起拂吴钩坐中舞。","我有狂客陈村民，为言昔者长相亲。","幕宾况有项文学，安得一见清心尘。","潋江沙晴秋草绿，却望崆峒歌伐木。","王郎定棹酒船过，我行不归将奈何。"]},{"t":"题马元善所藏松庵墨菊歌","f":"七言古诗","c":["松庵道人写墨菊，幽兴宛在山岩中。","轩然苍石立苔藓，枝叶掩冉生秋风。","石傍扶疏出三本，土润根肥气深稳。","彤霞匝地铸黄金，白露漙空湿香粉。","马君好古天趣真，昔年省郎吾故人。","升堂把酒对图画，使我意与南山亲。","君家旧宅龙沙北，荒圃经年归未得。","何当斸地种千株，日倚湖亭看秋色。"]},{"t":"赠别彭伯圻由兴国归赣郡长歌","f":"古风","c":["瑶草不可折，良友不可别。","握手出东门，商歌动凄切。","问君此别何当逢，异县去留安得同。","锦江诸峰列烟雾，云日正射晴芙蓉。","君才英英美于玉，谁遣东游向空谷。","邑中令尹旧知名，折屐开筵夜停毂。","孟尝好客安在哉，麋鹿亦上黄金台。","清风满庭丝竹动，使我感激空愁怀。","唱吴歌，催赵舞，击筑回觞泪成雨。","十年下邑困风尘，肝胆轮囷向谁吐。","世无鲁连子，谁能谈笑却秦军。","夷门日出客如雾，岂识监者非常人。","我惭学书晚闻道，憔悴衡门落秋草。","片言合意山岳轻，况尔多才足倾倒。","闻君有古剑，血色斑驳青蛇鳞。","几时出匣试锋锷，手抉云翳开星辰。","言苦不可尽，君行安得留。","江中横石如卧兕，彩鹢下照空潭秋。","君归暂向崆峒住，我亦南还匡岭去。","山中见月定相思，愁杀啼猿满烟树。"]},{"t":"题薛克恭金陵竹西堂","f":"楚辞体","c":["若有人兮怀竹西，乃在钟山之下秦淮之湄。","十年道阻风浪恶，东望但恨归来迟。","当时种竹堂西畔，新绿扶疏出窗半。","手招鸾鹤下风云，日送蛟龙上霄汉。","豫章南游消息疏，却眺钟山思旧居。","女墙月昏潮水落，万玉濯濯今何如。","怜君清修好风格，漂落经年归未得。","安得相携招八公，载酒来游竹西宅。","上元周祯吾故人，别来五见桃花春。","昨朝卷中诵题句，使我感慨怀清真。","我家珠林小江口，弃置频年事奔走。","乱馀斩伐丛竹废，败屋空馀数株柳。","闻君竹堂心眼开，陶令何时归去来。","清泉白石有贞操，六代繁华安在哉。"]},{"t":"五月十八日挈家避兵由里良入西坑作猛虎吟","f":"古风","c":["猛虎前啸，毒蛇后驱。","烈火被原，荆榛塞途。","悲风摵摵日欲晡，山石摧裂魑魅呼，令我有足不得趋。","蹶竭频踣犹在罦，嗟嗟我人曾不如。","青天之飞禽，局促木石底而多畏心。","伤哉唐虞远，干戈苦侵寻。","云胡有生适丁斯，今口不能言泪下沾襟。"]},{"t":"道逢老叟行","f":"七言古诗","c":["道逢老叟行且泣，背项罹伤血沾腋。","全家骨肉散风烟，眼暗肠枯少筋力。","自言生长太平多，州县不到无徵科。","老去常促邻里会，醉来还唱古时歌。","粤从东南兵乱起，乡井流离经一纪。","不似今年乱较长，九十日来窜荆杞。","赣兵自沮北军强，大船如山攒白樯。","水南东岸十馀里，列开七府屯兵场。","七府兵来掳生口，一旗入山万夫走。","跳溪越堑剧猿猱，猎草搜林到鸡狗。","最后招安尤可怜，中道要夺何纷然。","攘牵牛羊掠囊襆，杀戮老丑俘少年。","我从出山被抄掳，一室俄分两三部。","大男山中草缚行，幼女城边马驮去。","孙男呼母妇哭夫，风惊雨散何须臾。","分飞忽作异枝鸟，离逝还同别水鱼。","男健胜犊女如玉，全换新衣与装束。","湖南转卖得金多，主人无金不能赎。","近闻州尹收遗民，毒疠死者无晡晨。","独行三日迷所向，不见当时乡里人。","茫茫荒草江南路，归已无家死无所。","山背时时夜捉人，城中又报新招户。"]},{"t":"出自东门","f":"楚辞体","c":["出自东门，言越广阡。","飒彼惊风，郁其飞烟。","锵金铁兮昼鸣，市无人兮草芊芊。","后有摩牙鼓吻之虎狼，前有冲波百折之奔川。","上茫茫兮不能附乌鸢之飞骞，下渊渊兮惧蛟龙之纠缠。","累然踧踖不可以径度，况有白刃挥霍交其前。","龙头兮溅溅，佛原兮绵联。","雨冥冥兮雷阗阗，羌独后济此兮嗟苍天。"]},{"t":"题牛熙百猿图歌","f":"七言古诗","c":["石崖盘空截飞岚，万木丛薄秋风酣。","野猿呼群出山南，什什伍伍旁交参。","黑毛黄毳长毵毵，白面碧眼很以耽。","联拳踯躅睨且含，接足照影垂虚潭。","去君相逐聚若谈，背侧俯仰意各贪。","或行或据或引探，抱者六七悬者三。","攀枝挟蔓缘松楠，危不畏险乃所湛。","蜀门峡阴云水涵，啼霜叫月客不甘。","三声已觉生忧惔，如此三百宁能堪。","嗟哉牛熙笔如锬，苦心貌此何精覃。","瑶池飘忽空八骖，君子所化乃不惭。"]},{"t":"题汤子敏松石山房歌","f":"古风","c":["苍苍云松，磊磊白石，层冈盘盘二水隔，君从何年此卜宅。","茆茨窈窕通柴关，屋前正对宣华山。","苍苔满地人迹绝，但见群木紫翠交其间。","禾川西来抱山脚，主簿潭空日光薄。","石面青烟薜带垂，叶间晴雪松花落。","采山钓水皆清风，胡为汨没尘埃中。","看君有子如玉树，觉我憔悴成衰翁。","愁来颇亦耽幽趣，安得携家就君住。","忆在花阴把卷时，黄鹂啼满青楸树。","江鱼秋肥山果红，有酒莫放金尊空。","人生适意在深隐，富贵时来安所蒙。"]},{"t":"石火篇为萧樵葬母作","f":"古风","c":["石火与草露，人命恒若斯。","昨朝言笑坐高堂，奄忽敛衽閟灵輀。","哀歌出中野，浮云惨且驰。","邻里来引绋，亲戚各衔悲。","念此柩中人，生存孝其姑。","生儿九岁父不顾，此母鞠之劳且劬。","禄养乃弗逮，寿不登百年。","仓皇兵戈中，子能负土营坟阡。","送者莫叹息，自古运尽归黄泉，惟有令德名永传。","孟母岂不死，世人至今诵其贤。","寄言后来者，视此石火篇。"]},{"t":"题进马图","f":"七言古诗","c":["拳毛赤騧初来进，西人自控中官引。","虎气深腾紫禁门，龙光暗掣青丝靷。","玉鞭金镫调马时，天子亲御和鸾宜。","香街十二柳如雾，太液宫前花满枝。","神物飞腾那可测，电扫风驰周四极。","时来顾影只长嘶，太仆圉人骑不得。"]},{"t":"墨竹短歌为萧志行赋","f":"七言律诗","c":["羃羃历历生崇冈，洒洒淅淅含秋霜。","平生念子抱素节，感慨写此当高堂。","钓台仙潭忆所历，石洞云垂翠光滴。","夜寒月白听龙吟，瘦影离离上虚壁。"]},{"t":"两相惜行赠别吴仲伦归白沙并柬曾自升","f":"古风","c":["江上霾雪阴雨积，野径荒荒断行迹。","故人东来忽过我，把臂惊呼两相惜。","十年东南兵甲频，豪杰往往沦风尘。","躯干轩昂力如虎，观子岂是寻常人。","忆曾同作匡山客，醉上层峰看秋色。","流水空明龙子潭，碧桃尽绕仙人宅。","中坛欲上心力摧，惊风怒雹从空来。","却携短剑问卜筴，乘槎径欲窥蓬莱。","时移事异髦鬓改，白璧泥沙閟光彩。","青鸟高飞竟不回，消息微茫堕云海。","君从何年堕白沙，我亦归种珠林瓜。","青山闭户宜落日，一水只隔城东霞。","感君远来当此夕，露牖风灯暗虚席。","一杯浊酒千斟感，忽忆原尝泪沾臆。","由来变化纷龙鱼，老我无成空学书。","西行定遇曾文学，为问朗溪石笋今何如。"]},{"t":"牛虎行","f":"七言古诗","c":["田家牧牛野田里，虎来伺牛草间起。","腾跃骑牛扑牛耳，虎上啮牛牛下奔，戴虎直过前山村。","牧童惊散人叫吼，遂虎救牛牛更走。","虎惊势迫还弃牛，牵牛归来血满头。","可怜踉蹡空四足，有角峨峨不得触。","裂皮绝顶那可续，田夫抱牛顿足哭，猛虎还山食人肉。"]},{"t":"今日行二月十四日赋","f":"古风","c":["今日何日天气清，江干雨晴花柳明。","清晨手持一杯酒，再拜有泪如何倾。","我不及庭前乌，朝夕返哺鸣呜呜。","又不如坟上草，霜露结根永相保。","一从南郡飞旌旗，频年死徙伤流离。","先畴荒弃稂莠集，故宅荡析风烟悲。","小时开口咏诗句，投果倾堂动诸父。","岂知长大罹百凶，事绪茫如堕烟雾。","只今四十逾八年，有子孩痴方可怜。","霜蓬渐入明镜里，菽水不到黄泉边。","我家一门联桂籍，四十年馀声赫奕。","每惭末路向人低，独抱遗书竟奚适。","姆源之山高入云，钟岭亦有慈亲坟。","清明欲近风雨恶，野鸟啼春安可闻。","大兄今年会昌去，季也雩阳更流寓。","山斋此日倍相思，却恨从前少欢聚。","东家西家燕子飞，桃花乱落扑人衣。","明朝何处寻芳去，肠断故园消息稀。"]},{"t":"江上对月歌","f":"楚辞体","c":["明月初出云间时，炯如金盆光陆离。","驻影疑遮青桂树，飞光直射碧桃枝。","枝间烂烂花如雪，风力高寒吹欲折。","便持玉案紫琼杯，还酹青天白银阙。","白银阙，几千文，九州四海遥相望，一年十二度圆缺，惟有春时最和朗。","我从抱病滞故园，十夕九雨增忧烦。","此时朋游少欢聚，谁与共倒林中尊。","只今玩月流江浒，却忆兄行弟游处。","湘水天青路口云，雩山雪照罗岩树。","独不见兮心惨伤，举头看月怜异乡。","华山老鹤歘起舞，龙门流水横秋霜。","人生富贵复何有，笑折花枝劝行酒。","未须秉烛向西园，更与回尊唱杨柳。"]},{"t":"题杨郎所制五采匹笺歌赠自明杨徵士","f":"古风","c":["杨郎手持一匹笺，邀我放笔题长篇。","自言新制三百幅，忍贫不博黄金钱。","浣花濯锦何绚烂，湘渌凝春起波澜。","晶荧色夺赤石髓，腻滑光浮青玉案。","人言杨郎此笺真可传，岂知綵笔炼墨尤精坚。","云窗朝拔霜兔颖，石室夜扫松花烟。","一生攻苦事文墨，长恨科名收不得。","穷年白发侍甘旨，负米升堂更愉色。","杨郎杨郎莫漫沽，古人岂必今人殊。","由来绝艺可名世，况尔世叶当文儒。","益州十样今复见，糜角松纹炯成片。","苍龙腾雾起勺水，紫凤衔图出深殿。","我惭世好百不谐，学书局促空寒斋。","霜馀柿叶不可拾，但觉枯砚在尘埃。","感君孝养怜君苦，会且蜚声群玉府。","自掞玄云答远情，江风飒飒鸣秋雨。"]},{"t":"寄答夏仲寅","f":"七言古诗","c":["宜春才子清时望，精神峭紧才疏放。","野服不游城市间，扁舟秖在江湖上。","往年访我珠林湾，草屋榛溪相往还。","是时八月十五夜，明月东上仙槎山。","君船政系湾头树，玉瓶双倒金陵酒。","满洲风露听歌呼，水面寒光碎星斗。","别来鸿燕邈相疏，宋郎忽寄云中书。","碧笺丽句细作字，秋水掩冉生芙蕖。","东南转战几千里，白云在山招不起。","使者空寻颜阖庐，神仙还入东吴市。","今年五月劳远寻，快阁矶头江水深。","手持轻箑忽赠我，使我披拂清烦襟。","如何相逢即相别，回首音尘忽超越。","松桂早已见清贞，云月何由比高洁。","知君惯作汗漫游，扬帆鼓枻春江流。","重湖烟雨葭菼绿，我亦飘飖随白鸥。"]},{"t":"秋日承陈子相寄示送别诗并录登武山及往年武溪相忆之作比兴清远兼有思致所以爱我者深矣能无报乎辄赋长歌以答远意并柬南溪萧翀诸子","f":"古风","c":["西登宣华，东眺武山。","崒其孤青，邈矣难攀。","虎鼻岋嶪，戴石何班班，风门宛开双翠鬟。","云峰上出九千仞，六月飞瀑声潺潺。","我有故人冰玉颜，欲往从之路险艰。","长松吹雨日色冷，曾倒绿醑夜醉溪亭间。","别来几时秋树殷，寄我好句错落明月连金环。","摇光发彩荡心目，使我叹息开昏顽。","忆昔与数子，乘月相往还。","泛舟晓出越台下，吹笛夜渡青泥湾。","每思黄虞世，礼乐日以瘝。","仲尼浮海去已远，古诗三千谁与删。","曹危桧偪黍离废，乃有哀怨兴荆蛮。","后来作者百四五，鱼目蝘蜓愁嘲讪。","石岩夜寒不可且，落叶如雨惊栖鹇。","感君高谊朗如月，愧我绿鬓今成斑。","君才磊砢世所稀，高价岂止千万锾。","由来天马绝御辔，岂有芝兰低草菅。","秖今黄尘浩浩弥人寰，长弓犀角纷驰弯。","金洞老仙卧烟草，顾我清泪流潸潸。","九天崇严烟雾杳，中有玉色都而閒。","待余服食金光草，来扣清都龙门关。"]},{"t":"会亭山歌为安成周孝廉赋","f":"古风","c":["吾闻会亭之山高插天，上有千章森郁之乔林，下有百顷云雾之芝田。","伊谁筑室青山前，云是周氏有子孝且贤。","十年乱定还乡土，奉母安居仍守墓。","池鱼供馔冬笋白，把酒升堂更欢舞。","时登半山亭，却望山上坟。","手攀坟树抚驯鹿，泪洒深谷不断之飞云。","我愿种桃绕其室，瑶池花开照云日，此母应能食其实。","由来和气兆物先，水生连理山出泉。","会亭有石良可镌，母慈子孝俱千年。"]},{"t":"赠泉上人弹琴","f":"七言律诗","c":["慈恩上人好弹琴，昨者相遇龙门阴。","琅然为我拂苍玉，写作幽涧寒泉吟。","奔腾千丈瀑布落，忽转岩坳漱松壑。","流声渐远人莫闻，飒飒天风起寥廓。"]},{"t":"题华阳彭玄明所画秋山图","f":"古风","c":["我不识华阳彭炼师，见画云山想句曲。","数峰暝色入遥浦，六月泉声动虚谷。","紫霞观楼当落日，似有幡幢出林木。","海边鳌首戴云红，天际峨眉拂秋绿。","昔闻天台雁荡相钩连，云气来往驾飞仙。","断桥溪涧路如棘，嗟尔策蹇归何年。","秋风湖曲波如烟，我思东泛吴江船。","买鱼沽酒绿荷渚，吹笛夜下松门前。","便寻炼师觅玄鹤，却访华阳窥洞天。"]},{"t":"奉题墨竹为西阳萧先生赋","f":"七言古诗","c":["西阳先生风节高，蚤以文翰驰英豪。","兴来为之写苍玉，便觉满纸生风涛。","长身劲气欲千丈，复有孙枝俨相向。","曾闻鸾凤下云霄，会见蛟龙起春浪。","先生静掩林中居，眼明秋水笺虫鱼。","他年东海访奇古，定载小车求竹书。"]},{"t":"流江八景歌","f":"楚辞体","c":["望龙门，渺飞雪，皎若三山白云阙。","仙人踏岩石，石上迹欲灭。","恍惚重楼珠幢夜腾结，北风吹沙江水裂。","望西山，愁暮雨，青屏冥冥龙出舞。","真僧入定石卧虎，遥见绝壁中开露。","祗树邅予游兮江之南，月皎皎兮浸汪涵。","素娥抱玉骑紫蟾，冯夷缩手不敢探，但见光采烂烂千丈摇虚潭。","招予舟兮石浦，春涛浩兮不可以渡。","风轰铿兮雷怒，忽中流以回顾，闻阗阗之戍鼓。","宣华屹其云中，天鸡鸣兮咽霜钟。","耿疏星之光曙，见十二之青峰。","复忽兮将夕，落景飞兮乱山赤。","眺长洲兮汎珠湖，棹木兰兮拾明珠。","山有松柏兮水有芙蕖，高可樵兮深可渔。","乐哉江南兮伊美人之所居。"]},{"t":"登王氏承庆楼歌","f":"古风","c":["谁能白日骑鹤缑山头，谁能赤手钓鳌沧海陬。","长空千里望不极，爱此江上缥缈之飞楼。","楼成宛在河中洲，排轶雾雨盘深幽。","后有白塘百叠之丹崖，前有石浦万丈之龙湫。","炎霄飞雪洒栋藻，清晓落月窥帘钩。","可以招飞仙延浮丘，龙门宣华郁相缪。","手翻天瓢倒海水，一洗万古兴亡愁。","昂藏溪南翁，飒沓紫绮裘。","平生友爱无与俦，倚栏思共梅川游。","惊风吹雁去不返，徒使猿猱吊月鸣啾啾。","梅川神游不可见，喜见令子如琳璆。","前年入山伐群木，构此径欲追前修。","三槐当户青不休，两江之水何浏浏。","晚烟近渚栖钓石，春雨满皋看绿畴。","已闻万卷积书史，况有坐客皆公侯。","忆我重来停小舟，门前绿波飞白鸥。","乔林倚天万竹稠，下有驯鹿声呦呦。","云阳老仙翰林伯，十日坐此成淹留。","醉摇綵笔发奇思，雄文钜篇凌高秋。","至今光怪动斗牛，四壁恍怆腾蛟虬。","林花如锦烂不收，猗兰娟娟春叶抽。","何不载酒相劝酬，为君满酌黄金瓯。","起招秦娥作妙舞，更换越女回清讴。","洞霞绚烂可以列锦屏，涧水嘈杂可以鸣箜篌。","但期天河远抱石，不记海屋曾添筹。","功名时来安可求，过眼何异春云浮。","谁能东山问安石，我欲剡中从子猷。"]},{"t":"题葛洪移家图","f":"七言古诗","c":["前行白羊四角羸，谁骑驱者鬅鬙儿。","狰狞一犬嘷而驰，举鞭护羊呵止之。","背有囊琴结墨絁，妪后负画策以追。","少妇驰牛牛步迟，两儿共载兀不欹。","大者坐拥斑文狸，小者索乳方孩嬉。","母笑不嗔还哢咿，复有鬅者肩童羁。","引手向翁如反僛，蹇驴嘷地行欲疲。","两耳逆竖愁风吹，老翁庞眉方颔颐。","顾瞻妻子色孔怡，似语前行路向夷。","尔兄在前尔勿痴，汝母正念尔弟饥。","高帻髯奚荷且持，药瓢囊襆何垂垂。","有救者柄相参差，傍有二卷一解披。","趁行苦忙奚不知，我观此画喜复疑。","问翁为谁莫可推，或云葛令之官时。","移家勾漏乃若兹，人生多累在侈靡。","如此行李胡不宜，骨肉在眼无馀资。","非有道者焉能为，陈岩作图真画师。","笔迹缥缈如飞丝，中有妙意世莫窥。","我吟将为仕者规，如不见画当求诗。"]},{"t":"美人撚绵线歌","f":"七言古诗","c":["吴姬坐捲芙蓉裙，玉纤参差挼白云。","绮窗日高花气熏，摇光弄影何纷纭。","春蚕茧尾雪花白，澼得吴绵爱柔泽。","殷勤罥挂珊瑚枝，一挽琼丝落千尺。","宝珰下镇悬飞琼，宛转不闻缲络声。","春风吹花扑帘入，倦倚象床还叹息。","愿因双织紫鸳鸯，与郎被服生辉光。","郎心百年终绾结，莫学柔丝中道绝。"]},{"t":"题桃花珍禽图","f":"七言古诗","c":["山桃花开红满枝，珍禽啄花光陆离。","袅袅欲立不自持，吴堤十里锦作帷。","忆昔半醉倒接䍦，走马挟弹归来时，还见踏翻红雪飞。"]},{"t":"赋金精山寄赠王使君","f":"古风","c":["金精之山高入云，丹崖黑石相纠纷。","灵泉千尺天上落，仙乐缥缈空中闻。","我昔南游出其下，池上莲花已堪把。","使君访古此寻幽，洞口云萝系骢马。","激清流，坐高林，排白石，鸣清琴。","石以拟君之壮节，泉以比君之素心。","爱而不见心恻恻，云岑历乱烟波深。","题诗远向山中去，木鹤西飞凭寄音。"]},{"t":"石潭渔者歌","f":"古风","c":["吾慕东海生，垂钓潭上石。","潭水飏春风，桃花艳云日。","知君远志不在鱼，濯足时时还读书。","秖应豹隐藏深雾，肯学鹰扬载后车。"]},{"t":"题赋金银山送萧茂才之遂江并柬周用性","f":"七言古诗","c":["金银两山蔚参差，我昔西游曾见之。","石台照耀落日紫，下映流水光离离。","干戈苍茫隔烟雾，清秋送子山中去。","沦落同悲雁塔人，登临更赋龙门句。","水北山人须鬓苍，十年寄书不得将。","君去相寻定相得，却望两山心恻恻。"]},{"t":"题王若水画松石高人图","f":"七言律诗","c":["盘松如龙石如虎，傍有高人须发古。","千年海上忆安期，一日山中见巢父。","龙变乘云虎可骑，四海逍遥随所之。","桃花源里有路到，莫遣时人先得知。"]},{"t":"题帖监县所藏唐人画马图","f":"七言律诗","c":["髯奚并控天闲马，回鞭齐立垂杨下。","毛骨疑从汉苑来，衣冠自是唐人画。","东南百战良马空，安得致此真骁雄。","为君电扫清八极，归来立仗明光宫。"]},{"t":"和答谢子方","f":"七言律诗","c":["东昌高人谢子方，前日寄我新诗章。","文章变化合经纬，律吕开阖含宫商。","乱来正音邈寂寞，令我把诵坐仍作。","独不见之情惨伤，云月娟娟上江阁。"]},{"t":"四斤桃子歌","f":"七言古诗","c":["四斤桃子世所珍，雕盘献客誇轮囷。","海霞红点王母颊，玉团中涵秋水色。","东方娇儿偷不得，美人惜香笑怀核。","由来物性系所宜，荃茆橘枳安可期。","种成三年苍玉枝，开花结实君始知。"]},{"t":"东园有梅一株为野棘蒙罥有年未有奇之者暇日因命童竖刊除之赋长短句一首","f":"古风","c":["东园有梅蜷不直，茨蔓罗生错如织。","东风岁岁满园青，不见梅花见荆棘。","横丛恶棘何纷然，蒙密离纚将十年。","坐令盘窣不得展，纵有花开谁与怜。","我昨买东园，爱为此梅主。","忿然嫉狂横，急集斤与斧。","先诛恶根次伐干，挥拉剔攘到全树。","便教风疏舒彼郁，要令雪袪起其俯。","此时老梅筋力苏，手足轻旋眉目都。","枝如取璧相如头上直指发，柯如归汉苏卿手中落旄节。","色如买臣弃薪怀绶上会稽，气如望之入见堂堂谢挟持。","豁如晋公掀淖出泥涂，矫如淮阴释缚当万夫。","兀如萧何脱械佩剑趋，勃如范叔出箦载秦车。","异材终离魑魅宅，正气似有神明扶。","下视茨棘无遗馀，斩伐割截靡完肤。","蹴踏狼藉泥土俱，或焚爇之罪不逋。","遂有过者侧目惊相顾，寒鸟游蜂亦来聚。","清风濯濯群萼敷，晴日鲜鲜万枝露。","极知摧恶植善天所嘉，从有此卉木分正邪。","野夫穷年不出家，但携冻笔煮苦茶，日日来看东园梅树花。"]},{"t":"鸬鹚曲","f":"古风","c":["芦花断港腥风起，鸬鹚船来泊沙嘴。","联翩满艓黑如云，载入寒江猎潭水。","渔家自来养鸬鹚，不畜网罟兼缗丝。","年深驯狎识情性，举手呼名相应随。","船头鸣榔杂喧閧，黔喙玄裳歘飞哢。","乱石深掀锦鬣翻，惊波暗掣金鳞动。","忽然抛掷向空中，衔戴巨鱼争力雄。","渔郎惊救誇敏捷，承络叉挺无遗功。","小鱼倒吞森似束，终然入口不到腹。","充胡塞吭却归飞，吐向蓬窗动盈斛。","欢呼携负入城府，委玉倾银贱于土。","饱同水鸟沙上眠，醉共海鸥月中舞。","雌雄生小常相依，得食后人偏得肥。","杨柳矶头时聚立，桃花潭上却翻飞。","往年布种沔湖里，近日船中亦生子。","不惜今年教养成，死时却葬沙头地。","我怜此鸟义且驯，供养渔家秋复春。","鸟中岂无鹈鸪与白鹭，一饱贪馋便飞去，形貌虽奇焉足数。"]},{"t":"石炭行","f":"古风","c":["君不见庐陵周原上山兀，草木无根尽童突。","何年下掘得石炭，劫灰死凝黑龙骨。","十年兵兴铸鍊多，千包万秤严征科。","乡夫如鬼入地道，鞭血哭泪交滂沱。","斸深掘远不知返，土囊砑空忽崩反。","十人同入几人归，接绠篝灯出牵挽。","舟输担负入公家，连屋委积如泥沙。","霞蒸风吼入炉韛，但见刀戟锋镞烈燄闪闪飞银花。","我愿天公悯民苦，尽敕石煤化为土，随穴湮填永无取。","便令四海歌升平，烧山铸镈销甲兵，民绝横死无苛征。"]},{"t":"石膏行","f":"古风","c":["君不见太和钟步江水边，土山㞦嵔相钩连。","何年下凿石膏出，黄壤深蟠白龙骨。","篝灯掘隧不计深，前者方压后复寻。","问之此人何为尔，皆云得之可牟利。","自从岭外南盐通，糅炼和之颜色同。","贩夫重多不较味，舟车四走如奔风。","晨输夜挽尽筋力，官有禁刑私不息。","蒸溲药食能几何，十有八九归馘鹾。","我叹天公生此亦何补，掘尽终当变为土。","又愁地脉郁积还更生，万古奸利滋不平。","安得神人蹴之尽崩溃，民乐真淳永无害。"]},{"t":"铁十字歌","f":"古风","c":["庐陵江边铁十字，不知何代何岁年。","何人作之孰置此，何名何用何宛然。","形模交横出四角，三尺嵯牙偃锥槊。","雨淋日炙黑色滑，土中鮀鳞见斑驳。","人言南唐竹木场所都，铸此罥硾筏与桴。","一沉江中一路隅，是耶非耶焉得虞。","或云此古厌胜法，水怪奔冲赖排压。","雌雄相顾走光芒，神物护呵谁畚锸。","所以往代鼓铸虔州城，此物千载为英精。","舁铁过之铜乃成，精化气感理莫明。","世人往往疑根植，下触每愁风雨殛。","近时暴卒破盲惑，掘地出之誇胆力。","终然弃置不敢匿，我时见之考其式，赤乌之年乃妄饰。","吾闻天生五行中，惟金可革亦可从。","何不为刀为错通商工，为耜为镈利九农。","斩犀刺虎为剑锋，不然行雨极变化为蛟龙。","胡独汨没在泥滓，断甓遗株等沦弃。","铜仙不来秦鐻废，坐阅兴亡一流涕。"]},{"t":"不涉风波亭歌为糜朝英赋","f":"古风","c":["烈烈北风，汤汤横波，大船乘危小船覆，公独不涉留山阿。","赤鳅鬐，黑龙尾，长鲸峨峨撑白齿，偶一触之命如纸。","滟滪云深自有堆，海门黑月元无底。","我昔见公南浦之龙沙，知公作亭非不华。","上砻翠石凿户牖，下列琴策开烟霞。","客如流云酒如海，枣已如瓜菊堪采。","醉歌白雪扬清风，独立东南三十载。","历观古贤达，孰不恋閒居。","后有栗里之陶氏，前有东门之二疏。","公乎公乎又何羡乎鼎食而禄秩，驷马而高车。","登公亭，酌公酒，风波于公果何有。","酌公酒，听我歌，风波风波奈我何。"]},{"t":"黄蜀葵歌","f":"古风","c":["君不见园中黄蜀葵，去年一尺长，今年始作花，即见倾太阳。","朝朝与暮暮，东西逐飞光。","天清白露下，秋气忽已凉。","蟏蛸篱落瓠叶黄，支离委绝同秋霜。","荫根卫足野人语，岂知物性本有常。","空山无人日色薄，能不念子增烦伤。","中天北斗何苍苍，千秋万岁临冀方。","清夜起瞻夜未央，车轮确确回中肠。"]},{"t":"林之乌美建昌黄节妇","f":"古风","c":["林之乌，尾毕逋，雌雄在树声相呼。","一朝雄死雌不去，衔食自哺巢中雏。","雏成生羽翼，教之慎出入。","出巢不似依巢安，上有鹰鹯下沾湿。","林阴阴，风颵颵，东家火起焚其巢。","巢空叶枯霜露冷，覆翼其子鸣咬咬。","雏今老苍自飞止，慈乌端居为雏喜。","衔草作巢巢更高，白头未遍慈乌死。","见者共叹息，羡尔林之乌，妇中贞节谁与俱。","独不见海昏罗田都黄氏，一子之母旌门闾。"]},{"t":"赠袁鍊师弹琴","f":"楚辞体","c":["袁鍊师，好弹琴，不作江南曲，解琴中古音。","七轸削玉徽裁金，焦桐黑尾朱弦心。","对之如大宾，宝之甚璆琳。","时来为予肃危襟，拂拭顾盼愁不禁。","六月一鼓之，秋风飕飕起云林。","十月一再抚，凌厉白云开重阴。","老君坛高夜色迥，神人下听寒萧森。","口中六律祇自和，头上三花谁与簪。","忽起抱琴去，振衣度遥岑。","手援北斗为我斟，独不乐兮忧骎骎。","苍梧虞舜不复返，帝子佩沈湘水深。","不尽千古意，别君清夜吟，遥想相思江之浔。"]},{"t":"送孙伯刚之仪真","f":"古风","c":["孙侯庙廊具，特达古豪俊。","十年出禁闼，往往事州郡。","苍髯玉立秋风高，南浮烟海东云涛。","中朝更化重守令，似尔简擢非贤劳。","淮东诸郡临淮道，共说仪真风物好。","万家歌吹动春云，十里楼船压江岛。","海有盐错水有鱼，白露红霞春满壶。","候人出郭鸣马集，日望使君来下车。","岂无穷困民，所重民父母。","税赋出鞭笞，伊谁肆苛虎。","长淮之水何悠悠，行矣不可以久留。","便令南阳得召父，坐见淮水回清流。","愿持万古心，送君以千里。","由来贤达士，感激在知己。","筼筜谷，金精山，吾独胡为淹留于其间。","云霄浩荡白日近，飞翰冥冥倘可攀。"]},{"t":"己亥三月歌","f":"古风","c":["己亥三月尾，大麦小麦黄欲起。","风从北来雨不止，野雀漫天水漫地。","高田雀飞可网罗，低田水来将奈何。"]},{"t":"水啮古墓歌","f":"古风","c":["河水啮高丘，丘中墓门崩作洲。","可怜墓中人，不见河水向南流。"]},{"t":"题青阳行乐图歌为黄允中赋别","f":"楚辞体","c":["使君临湘人，旧住青阳里。","一从游宦之江郡，长忆青阳好山水。","梅池之水深瀰瀰，晴绿酿涨青玻瓈。","蛟龙夜擘山石裂，下注湘水衮衮而东驰。","群山插天削寒碧，大云嵯峨几千尺。","苍烟尽覆紫芝岩，日光却射青萝壁。","图中茸帽紫绮裘，使君行乐何风流。","长松过雨晓色净，抱琴来此吟清秋。","琴中有声传太古，振羽流商动林莽。","淳风已变知者寡，却望苍梧叹脩阻。","我欲起扫石上苔，为君更置青螺杯。","手攀琼枝拂明月，骑取白鹤径欲归。","蓬莱蓬莱微茫不可以度，嗟我民昔捐瘠兮孰遗以哺。","民今有子兮穫有稌，挽之不留兮君盍予。","顾思使君兮不可忘，泛澄江兮望临湘。","临湘山高兮水长，允怀使君兮乐哉青阳。"]},{"t":"题江村秋兴图为萧性存赋","f":"七言古诗","c":["我昔棹船过横月，醉唱吴歌夜中发。","鹅公岭头月东出，百尺清潭写毛发。","买鱼溪口烧荻烟，回首旧游今惘然。","萧君此图自新制，风物何得犹当年。","两松童童立江浒，松下人家好楼宇。","雁沈极浦秋水阔，僧入游峰晚钟度。","伊谁闭户事书史，白发满头心未已。","岂知扬雄老执戟，万言不如一杯水。","幅巾美髯行者谁，潇洒似有岩壑姿。","便思携酒共佐酌，更约入山寻紫芝。"]},{"t":"渔栖辞","f":"楚辞体","c":["苍林兮碧溪，我渔兮我栖。","朝鸣榔于中泽兮，夕余济于澨西。","波洄沿兮不可以倏迷，路窈窕兮风凄凄。","反予遵兮故蹊，云鳞鳞兮不可以隮。","漱白石兮藉芳荑，悄空谷其无人兮，见翩翩之凫鹥。","志逸而嬉兮得丧以齐，纶不必施兮彼笭箵又焉足赍。","乐哉洋洋兮，吾乌知尔之为鲦鲿为鲸鲵。"]},{"t":"至赣入西江","f":"五言律诗","c":["奉诏趋南越，乘舟上赣津。","脩程兼水石，晴景际冬春。","海食人多诈，山行马有神。","谁能轻陆贾，吾已愧涓人。"]},{"t":"出蒲岭晚投钟寨","f":"五言律诗","c":["乱石閟岩扃，苍烟拥翠屏。","稻田宜晚赤，山木自冬青。","客去冲蛮雾，人来睹使星。","秪惭过冀北，犹拟泛沧溟。"]},{"t":"南海逢萧氏妹","f":"五言律诗","c":["流落怜吾妹，艰难在海隅。","偶然馀见日，早已绝归途。","日落苍波阔，天寒碧屿孤。","失群兼委羽，忍泪更相呼。"]},{"t":"包公井","f":"五言律诗","c":["止饮端州水，犹为凿地谋。","在官真不负，于世果何尤。","光抱一泓月，清涵万古秋。","尘怀思一涤，欲去复迟留。"]},{"t":"渡绣水取道赴高州","f":"五言律诗","c":["日出城乌起，风高驿马鸣。","山从云际起，人在树间行。","溪罟穷深捕，畬刀废薄耕。","见人茆屋好，浑欲愧平生。"]},{"t":"憩金鸡驿亭","f":"五言律诗","c":["缘云上驿亭，春色正冥冥。","千树棠梨白，满山蕉叶青。","碧潭开匣镜，秀壁拥帷屏。","尚说客州远，舟行未可停。"]},{"t":"下马","f":"五言律诗","c":["下马度嵚崟，千溪复万林。","含沙疑鬼箭，飞草畏蜞针。","火种通猺俗，山歌杂獠音。","逢迎暂投息，起坐剧愁心。"]},{"t":"出雷阳初渡东洋沟","f":"古风","c":["南出雷阳郭，东洋第一沟。","气蒸通海润，味苦杂潮流。","蜃垩涂舟遍，蒲茅覆屋稠。","还闻?风起，飘卷到城楼。"]},{"t":"至沓磊驿初见海水","f":"五言律诗","c":["南海天光白，东洋水气昏。","汐潮通浦口，涛浪漱山根。","浩淼涵千古，虚明汇众源。","平生万里志，临眺豁飞翻。"]},{"t":"琼府与广东佥宪潘牧户部主事元伯常相见于琼台驿作此奉柬","f":"五言律诗","c":["元子经邦赋，潘郎执法公。","宁知万里外，相见一亭中。","潮退沙痕白，春还海气红。","愿言各努力，归奏大明宫。"]},{"t":"题陈赞府山水画赠萧伯循","f":"五言律诗","c":["忆在清江上，开轩望远林。","莺啼双树绿，人静一窗深。","远道劳行役，芳期阻啸吟。","如何垂钓者，万事不关心。"]},{"t":"题钓鱼图","f":"五言律诗","c":["潇洒玄真子，超遥好容颜。","放船烟树下，把钓水云湾。","鱼没萍翻石，鸟啼花满山。","惟应江月上，遥听棹歌还。"]},{"t":"题雪景山水画","f":"五言律诗","c":["万木皆冰树，千崖尽玉山。","精神添去马，毛羽失栖鹇。","客路微茫外，人家烟水间。","忆曾登虎鼻，徒步月中还。"]},{"t":"题毛泽民云山图","f":"五言律诗","c":["水国通吴会，茆堂背楚皋。","树含春雨润，云挟晚风高。","幽想栖文豹，深疑叫绿猱。","谁能招小隐，吾欲棹轻舠。"]},{"t":"题方壶寄黄郎中渭云红树图并书","f":"五言律诗","c":["春树重重绿，江云冉冉生。","图传龙虎客，书寄凤凰城。","花底趋琼佩，松阴奏玉笙。","何时骑两鹤，方驾上蓬瀛。"]},{"t":"题挟弹图","f":"五言律诗","c":["骏马青丝络，联翩挟弹来。","山疑经洛浦，路似出章台。","鸟散红花落，莺啼碧树开。","啼时端听汝，好在莫相猜。"]},{"t":"题赵鸣所画林下看云图","f":"五言律诗","c":["何地好幽栖，青林带碧溪。","藤垂猿共挂，叶暗鸟频啼。","避俗还衣褐，看云只杖藜。","几时真不负，归问武山西。"]},{"t":"题山水画轴","f":"五言律诗","c":["瀑布双垂下，屏风九叠张。","波光混彭蠡，山势似浔阳。","松坞栖茆屋，枫林带石梁。","扁舟如可具，吾意在沧浪。"]},{"t":"题古木苍鹰图","f":"五言律诗","c":["旷野澄秋气，雄姿肃武威。","林端方攫立，云外已惊飞。","秉政乘金令，摧奸顺杀机。","喜闻阿阁上，鸣凤际春晖。"]},{"t":"赠松江周道士","f":"五言律诗","c":["自得游仙术，偏多济世才。","檄龙行雨去，呼鹤下天来。","功熟黄金鼎，名登绿玉台。","还闻从此别，入海访蓬莱。"]},{"t":"十月一日至临濠点驿将归南京赋此奉酬德瑜萧虞部","f":"五言律诗","c":["淮水绕濠城，东流不尽情。","秋光馀客路，云气满神京。","下马逢仙堠，回舟问水程。","遥怜一尊酒，持此向谁倾。"]},{"t":"题画扇","f":"五言律诗","c":["雪裂齐纨素，天开楚甸图。","丹崖禅阁并，红渚钓船孤。","亭晚连松桂，沙明问柳蒲。","短琴如可抱，清醑得频沽。"]},{"t":"十四夜对月柬子彦有怀子中兄","f":"五言律诗","c":["月出白杨端，乌啼清夜阑。","絺衣初淅淅，草露已漙漙。","共喜灯花密，宁辞酒盏乾。","有兄怀二弟，应自倚楼看。"]},{"t":"夜坐二首 其一","f":"五言律诗","c":["叶落风连树，乌啼月满庭。","把书双鬓白，呼酒一灯青。","霜露惊残岁，关河忆旧经。","职思方在圉，未敢叹飘零。"]},{"t":"夜坐二首 其二","f":"五言律诗","c":["更声引迢递，海气合空濛。","乌鹊枝枝月，青杨叶叶风。","山河百战后，城阙五云东。","往事成炊黍，吾生独转蓬。"]},{"t":"寄酬长兴知县萧德瑜四首 其一","f":"五言律诗","c":["有美长兴宰，曾为工部郎。","冶金精范器，制锦动成章。","客鬓何曾白，乡心故自长。","永怀明月夜，送酒过濠梁。"]},{"t":"寄酬长兴知县萧德瑜四首 其二","f":"五言律诗","c":["山泽通虞部，图书限职方。","向来嗟共事，此别更殊乡。","羸马燕山远，红船霅水长。","各言思奋励，未可惜参商。"]},{"t":"寄酬长兴知县萧德瑜四首 其三","f":"五言律诗","c":["近见湖洲客，因传三月书。","关河千里外，霜露九秋馀。","作县能知事，携家想定居。","几时苕霅上，相见采芙蕖。"]},{"t":"寄酬长兴知县萧德瑜四首 其四","f":"五言律诗","c":["五十今逾四，惊添白发多。","遭逢嗟已盛，报答欲如何。","边月明山驿，沙冰带塞河。","远凭南乡雁，一寄北行歌。"]},{"t":"观北平城陌栽树有感","f":"五言律诗","c":["本是山中物，移来近市尘。","分根烦野客，留荫待行人。","意接风烟远，光承雨露新。","闾阎小儿女，攀弄亦何频。"]},{"t":"退食","f":"五言律诗","c":["退食还西舍，单居少四邻。","入门惊落叶，振席愧流尘。","狞犬偏嘷客，饥猫亦恋人。","自怜仍自慰，俯仰向谁陈。"]},{"t":"东园秋雨野苋旅生日采供厨喜而成韵","f":"五言律诗","c":["旅苋无人种，生来自满畦。","童童承晓露，濯濯迸秋泥。","瓜蔓虫偏食，茄科草共齐。","欣然供采摘，亦足慰羹齑。"]},{"t":"西馆积雨","f":"五言律诗","c":["西馆门长掩，青樗自满林。","土垣秋后塌，泥泞雨中深。","案检秋巡牍，囊馀月俸金。","君亲恩未报，搔首一长吟。"]},{"t":"雨歇感事","f":"五言律诗","c":["雨歇孤城晓，风惊万叶秋。","晴窗走蝎虎，阴壁上蜗牛。","抚事惭疏阔，承恩叹谬悠。","若为裨海岳，未敢问林丘。"]},{"t":"即事","f":"五言律诗","c":["吏牍常堆案，官居不近邻。","阶庭归去晚，鸡兔坐来亲。","市酒何曾醉，囊诗未是贫。","秖惭公禄厚，犹恐负儒巾。"]},{"t":"感俗","f":"五言律诗","c":["衮衮牛车急，纷纷鲋瓮频。","井咸知苦水，风恶骇奔尘。","土炕炊烟旧，坭头送酒新。","总怜边俗恶，牢落异乡人。"]},{"t":"北平十二咏 其一 胡桃","f":"五言律诗","c":["碧露枝枝重，青苞颗颗匀。","叶深初覆夏，花弱不禁春。","核隐龟筒小，浆凝密枳新。","向来谁致汝，吾欲恨平津。"]},{"t":"北平十二咏 其二 榛子","f":"五言律诗","c":["君国充笾实，闺门重贽仪。","物微将礼意，名重著歌诗。","错落鸡头小，晶荧鬼目奇。","欲尝怜病齿，把玩独多时。"]},{"t":"北平十二咏 其三 马蔺子","f":"五言律诗","c":["蔺草何人种，丛生故近兰。","叶长书带小，根瘦彗芒乾。","牛马何曾食，樵苏自不干。","遥怜南郡客，更作水仙看。"]},{"t":"北平十二咏 其四 香水梨","f":"五言律诗","c":["香水传嘉号，轮囷碧玉团。","刀场惭误拟，饤坐喜同欢。","崖蜜清心润，壶冰溅齿寒。","宣城空斗大，气味敢同看。"]},{"t":"北平十二咏 其五 红瓤瓜","f":"五言律诗","c":["皮绿何曾别，瓤红故异常。","晶荧丹玉片，滴沥紫霞浆。","云落盘杅冷，冰馀齿颊香。","青门誇五色，见此不能忘。"]},{"t":"北平十二咏 其六 御黄子","f":"五言律诗","c":["本是中园李，多因杏接成。","喜传希世味，因锡御黄名。","圆瑩含秋色，甘香注露英。","只今玉食俭，远物未曾徵。"]},{"t":"北平十二咏 其七 盘松","f":"五言律诗","c":["最爱青松树，盘盘偃势奇。","一擎张羽盖，四面走虬枝。","引手探巢鹤，低头触兔丝。","寻常三尺里，赤日未曾知。"]},{"t":"北平十二咏 其八 偃槐","f":"五言律诗","c":["勃窣撑孤柱，婆娑偃一株。","长条垂带厉，细叶挂流苏。","暮鹊从争起，秋蜩秪谩呼。","移床怜美荫，何止蔽千夫。"]},{"t":"北平十二咏 其九 巴丹","f":"五言律诗","c":["自是山桃子，蕃名故尔殊。","皮肤怜外腊，香味爱中腴。","磊落珠盘石，修圆碧海珠。","南归思种汝，土性恐难迂。"]},{"t":"北平十二咏 其十 韭黄","f":"五言律诗","c":["都人卖韭黄，腊月破春光。","土室芳根暖，冰盘嫩叶香。","十金酬好价，一箸惬初尝。","何以江南种，青青雪里长。"]},{"t":"北平十二咏 其十一 慈乌","f":"五言律诗","c":["塞北慈乌好，群飞长子孙。","争巢偏挟势，反哺独知恩。","秋树霜前绕，寒枝月下蹲。","往来随候雁，此理竟谁论。"]},{"t":"北平十二咏 其十二 黄鼬","f":"五言律诗","c":["黄鼬雄于鼠，萧骚散尾毛。","窥檐林雀噪，出穴屋鸡号。","攘攘缘高树，踆踆伏浅蒿。","惟馀管成子，犹得利霜毫。"]},{"t":"防微馆","f":"五言律诗","c":["高馆人难到，层阶草漫生。","野蒿深没马，高树静啼莺。","问俗时询野，防微早计程。","自无尘土近，况有柏风清。"]},{"t":"七夕次吕佥宪韵","f":"五言律诗","c":["华月丽秋天，寒光瑩若泉。","星移银汉节，花合绮楼烟。","鹊影浮珠贝，蛛丝罥藕莲。","人间与天上，安得两团圆。"]},{"t":"心清一首奉柬吕徐二佥宪","f":"五言律诗","c":["心清馀白日，地迥隔红尘。","马渴时窥井，乌驯不畏人。","衣冠更异俗，书律在同寅。","辽海通东北，应知服化淳。"]},{"t":"独归","f":"五言律诗","c":["吏散独归迟，西庭欲暮时。","猫戏风捲叶，鸡坐雨横枝。","白雪谁能和，清觞谩自持。","故园秋色早，回首意兼悲。"]},{"t":"晓起","f":"五言律诗","c":["楼笳低塞雁，邻火起庭鸦。","城歇征人柝，门喧过客车。","风枝涂白露，霜叶覆黄沙。","底事边隅梦，经时不到家。"]},{"t":"题李居中山水画二首为孟彦忠掾史赋 其一","f":"五言律诗","c":["日出清江迥，云生翠壑重。","楼台山上下，车马路西东。","松瀑晴崖雨，茆茨古木风。","向来度桥处，曾见抱琴翁。"]},{"t":"题李居中山水画二首为孟彦忠掾史赋 其二","f":"五言律诗","c":["山崦朝阴薄，野桥秋水深。","人家住不远，杖策去相寻。","水口分危石，山腰控远林。","苍茫何处景，迢递故园心。"]},{"t":"纪俗","f":"五言律诗","c":["古来燕赵地，遗俗至今存。","曲和膏糜冷，烟烧土炕温。","主宾通坐卧，婿女异卑尊。","四海今同化，移风在所敦。"]},{"t":"铜城驿遇雪","f":"五言律诗","c":["晨起驱双犊，前行挟两辀。","偶冲寒雪去，如驾玉麟游。","草树千章列，川原一色浮。","几时还入觐，趋拜凤凰楼。"]},{"t":"再赋","f":"五言律诗","c":["惨淡暗长空，低回逐急风。","榆林珠错落，蓬草玉珑松。","野屋无炊火，川原有去鸿。","遥怜异乡客，枯坐小车中。"]},{"t":"过沛县水驿","f":"五言律诗","c":["水驿前年到，归船复此过。","人家住来久，岸柳种成多。","泗水通遥海，砀山隔大河。","千年陈迹在，回首飒悲歌。"]},{"t":"守冻二首立春后二日 其一","f":"五言律诗","c":["风雾捲惊尘，河冰限去津。","客程方守冻，天意欲争春。","去雁鸣犹急，浮鸥近若驯。","香醪如可问，吾欲酹江神。"]},{"t":"守冻二首立春后二日 其二","f":"五言律诗","c":["风急牵樯涩，冰坚下楫难。","一程残雪里，三日大江干。","近渚时登眺，遥山只坐看。","到京犹十驿，谁与送飞翰。"]},{"t":"夜雪","f":"五言律诗","c":["黄昏初淅淅，深夜故翩翩。","野白惊连水，窗明觉满船。","天低寒月下，河断北风前。","旅泊成淹滞，孤樯未可牵。"]},{"t":"舟次遇卖獐者","f":"五言律诗","c":["野猎卖山獐，提携趁客航。","山林便性逸，罗网堕机张。","价索青钱足，膏凝白玉香。","平生藜藿味，对此不能忘。"]},{"t":"夜梦亡兄中翁以家事相语觉而感泣因追赋二诗以寄予衷 其一","f":"五言律诗","c":["老去频年别，书来百感非。","痛心须一见，皓首竟先归。","夜冷姜肱被，天寒康伯衣。","只今嗟莫及，惟有泪长挥。"]},{"t":"夜梦亡兄中翁以家事相语觉而感泣因追赋二诗以寄予衷 其二","f":"五言律诗","c":["晚岁家居日，逢人忆弟时。","谁知万里意，竟作九原悲。","苦惜分符远，尤嗟上冢迟。","惟馀清梦在，款款慰深思。"]},{"t":"青阳店晓泊忆往年点水驿过此","f":"五言律诗","c":["寂历临流岸，苍茫向暮天。","关河淹远客，风雪送残年。","宿雁时惊火，饥乌欲趁船。","昔年来往地，回首一茫然。"]},{"t":"遣闷","f":"五言律诗","c":["舟子呼不起，高眠烟浪中。","苦云愁积雪，犹欲候天风。","倥偬羁怀剧，萧条岁事穷。","几时东夹道，骑马听晨钟。"]},{"t":"岁暮舟中有感","f":"五言律诗","c":["岁纪聿云暮，客程殊未央。","大风吹旷野，积雪满河梁。","城远难沽酒，瓶空欲问粮。","何当转晴景，长啸下山阳。"]},{"t":"夜宿宿迁","f":"五言律诗","c":["城雾初明火，江风只撼船。","春还犹有雪，夜过欲无眠。","来往怜吾老，登临记昔年。","桃源如可问，乘月下前川。"]},{"t":"除夕","f":"五言律诗","c":["冻雪初晴夜，残年欲尽时。","居人竞节物，行客信程期。","酒重屠苏感，诗深棠棣悲。","团圞儿女坐，应说鬓成丝。"]},{"t":"夜宿枣林闸闻雁","f":"五言律诗","c":["迢递来何处，苍茫叫此时。","夜深犹去远，春近独归迟。","江上烟波阔，山前塞月低。","十年来往地，回首意兼悲。"]},{"t":"题李时画山水图寄赠罗修已","f":"五言律诗","c":["雪拥莲花嶂，霞明枫树林。","江侵沙屿阔，泉落洞门深。","柳色催移棹，松阴带抱琴。","新亭无限好，何日共登临。"]},{"t":"过桃源县别黄仲篪","f":"五言律诗","c":["野市栖民舍，河堤带县衙。","长年对流水，无处问桃花。","旧别三年久，新愁两鬓华。","相逢那可住，风雪满星槎。"]},{"t":"十月朔日蒙御史台颁至洪武九年历日十六喜而有赋","f":"五言律诗","c":["洪武九年春，仪台宝历新。","远从乌府送，如见凤图陈。","万国同正朔，千官仰北辰。","彤廷先进早，犹忆侍班晨。"]},{"t":"吕梁洪","f":"五言律诗","c":["飞瀑过双碛，横梁亘一洲。","时清自失险，石出更安流。","客棹依洄洑，人家带坌丘。","为谁含怨怒，呜咽下邳州。"]},{"t":"河上农家","f":"五言律诗","c":["河上居人少，兵前草树繁。","牛羊还识路，鸡犬自成村。","衣夹绵花絮，盘分苜蓿飧。","可能无长物，容易足晨昏。"]},{"t":"答吴生仲琰来韵","f":"五言律诗","c":["英英吴氏彦，文采动儒绅。","不惮荒山晚，远投佳句新。","云天开意气，秋水瑩精神。","励志勤修业，终当继古人。"]},{"t":"和子与王徵君中秋律诗一首","f":"五言律诗","c":["对月怜今夕，看云忆往年。","秋光连武姥，诗兴在禾川。","花底吹箫坐，松根枕石眠。","如何继清好，高咏赏团圆。"]},{"t":"题耕乐亭","f":"五言律诗","c":["园圃带城居，知君乐有馀。","韭菘连疃绿，柿橘映窗虚。","自酿浇花酒，閒观种树书。","如何车马客，忧患日相于。"]},{"t":"题唐人马图","f":"五言律诗","c":["天马何年贡，远从西北来。","月支回汉使，风骨走龙媒。","白日轩墀近，青云道路开。","高秋看图画，歘使壮心哀。"]},{"t":"题陈敬则书室","f":"古风","c":["一室梧桐下，秋阴覆近檐。","古琴?腹断，新竹凤毛鲜。","酒熟从人醉，诗成只自编。","月明溪水绿，更拟泛渔船。"]},{"t":"过丹塘访云从罗隐君不遇","f":"五言律诗","c":["绿竹溪流外，丹山夕照边。","入门双桂古，绕屋数峰圆。","烟暖吹藜阁，云寒穫稻田。","如何不相见，怅望故悽然。"]},{"t":"出鸡鸣岭憩白竹院将入双仙省先墓","f":"五言律诗","c":["晓出鸡鸣岭，东望马田山。","喷薄流淙下，回环紫翠间。","地幽千竹净，院古一僧閒。","郁郁松楸暮，归迟秪厚颜。"]},{"t":"望白竹岩","f":"五言律诗","c":["窈窕缘苔涧，逶迤带草堂。","松桥通石径，竹栅间山塘。","远树晴烟白，落花春水香。","几时游白竹，应踏石为梁。"]},{"t":"清明对酒","f":"五言律诗","c":["榆火报清明，云天霁景澄。","麦花愁夜雨，桑叶爱春晴。","燕说兴亡恨，蛙占水旱声。","可能忘世虑，呼酒听流莺。"]},{"t":"题山水画四首 其一 韩昌黎送李愿序","f":"五言律诗","c":["隔水问樵童，青山深几重。","岩歌闻雪瀑，谷转见云松。","野服乘秋制，山田力岁供。","徒令尘土客，挥汗仰高踪。"]},{"t":"题山水画四首 其二 柳子厚送薛存义序","f":"五言律诗","c":["驰策长林下，停舟野水浔。","旌旄行处路，樽俎别时心。","山晚松阴薄，江晴柳色深。","殷勤言赠意，千古重官箴。"]},{"t":"题山水画四首 其三 欧阳永叔秋声赋","f":"五言律诗","c":["群木飒萧萧，虚堂坐寂寥。","秋声方永夜，月色自中宵。","目倦青编过，眠迟绛蜡消。","平生江海志，及此叹飘摇。"]},{"t":"题山水画四首 其四 苏子曕赤壁赋","f":"五言律诗","c":["清夜放船好，长江正渺如。","风行流水上，月出远山初。","飞鹤盘空迥，潜蛟隐浪虚。","英雄有遗恨，临泛独踌躇。"]},{"t":"和子与王先生夏日途中望武山二首 其一","f":"五言律诗","c":["日高南涧午，云度北岩阴。","坐石依行树，听泉醒渴心。","遥望西华观，微闻钟磬音。","烟霞石磴晚，谁与共清吟。"]},{"t":"和子与王先生夏日途中望武山二首 其二","f":"五言律诗","c":["野寺临溪古，方桥驾石牢。","云车停远盖，风树隐虚涛。","赤日南天迥，青岩北斗高。","却思燕地冷，雪椀送冰桃。"]},{"t":"七月十四日同王徵君萧国录游云峰寺观壁间旧画墨龙有感","f":"五言律诗","c":["梵宇凭虚构，僧房隐树开。","窗间时见虎，山下或闻雷。","路绕岩腰上，泉通石骨来。","凄凉馀画壁，风雨半莓苔。"]},{"t":"西华望月和竹庭韵二首 其一","f":"五言律诗","c":["山远绝纷华，天虚引望赊。","南风当户正，北斗傍岩斜。","路转风泉合，岩分雾树遮。","若非闻玉磬，谁信在仙家。"]},{"t":"西华望月和竹庭韵二首 其二","f":"五言律诗","c":["秋清深谷里，月照大江滨。","此夜同游客，当时远别人。","白发催年老，青灯照夜频。","陶皮如可问，游此欲寻真。"]},{"t":"问胡山人坟","f":"古风","c":["偶寻康道士，因问故人坟。","满地生秋草，何年閟白云。","松楼秋梦断，竹浦夜吟分。","狂饮犹怜我，?泉拟酹君。"]},{"t":"宿西华有怀萧鹏举并柬同游者","f":"五言律诗","c":["山光上寥阒，海气接鸿庞。","月近全当户，天垂半入江。","买泉苍石洞，送酒白云窗。","却忆滁阳客，东游滞短艭。"]},{"t":"项烈妇唐氏挽诗","f":"五言律诗","c":["寇截新林渡，风惊下濑船。","死能同母逝，生或愧身全。","抱石云漂海，沈珠月在渊。","义门重光烈，千古照龙泉。"]},{"t":"赠廖山人月山","f":"五言律诗","c":["问讯青囊客，来游衣锦乡。","几年寓禾水，何日过茆堂。","古墓沉凫海，高门散鹿场。","平生双短屐，登览意何长。"]},{"t":"过小孤山","f":"五言律诗","c":["万丈临无地，苍然不可攀。","九江争赴海，一柱独当关。","水族朝珠阙，仙娥拥翠鬟。","平生登览兴，及此慰南还。"]},{"t":"入湖口喜见庐山","f":"五言律诗","c":["鄱阳湖上路，来往愿多违。","往事那能问，今年始是归。","乡田新梦熟，京国旧游稀。","稚子能携酒，应先候竹扉。"]},{"t":"阻风坐湖阴石上","f":"五言律诗","c":["江石平如砥，江芜散若丝。","偶来临水坐，浑似在山时。","月上涵金镜，风来弄绿漪。","那无一樽酒，来此共幽期。"]},{"t":"学钓","f":"五言律诗","c":["偶有临流兴，因之驻木兰。","呼儿供钓饵，问客觅鱼竿。","小立怜幽树，深投爱弱湍。","惟应待明月，长啸下前滩。"]},{"t":"过南昌有怀旷伯逵知事","f":"五言律诗","c":["生来虞乱极，身后见时清。","每叹多才累，翻怜一死轻。","慷慨论交契，沈酣托酒名。","至今江草绿，犹似别时情。"]},{"t":"过新淦樟口欲访检校谢叔宾不果赋此遥谢","f":"五言律诗","c":["五月辞京阙，曾期共泛舟。","蹉跎嗟后至，怅望失前游。","樟口风湍急，山中云木稠。","寄书谢猿鹤，欲往惜淹留。"]},{"t":"忆舍弟子彦相望","f":"五言律诗","c":["前月辞京阙，因风问桂枝。","秖缘书到早，应怪客行迟。","失学怜宗武，迎门想阿宜。","林塘新酿熟，烂醉不须疑。"]},{"t":"过峡江","f":"五言律诗","c":["乡路犹三驿，逢人问水程。","昼愁江上住，凉爱月中行。","白发思乡里，青灯忆弟兄。","那能即相见，把酒慰深情。"]},{"t":"秋日宴集钟氏西楼鹏举有诗依韵奉答仍示启晦","f":"五言律诗","c":["望月上西楼，纤纤白玉钩。","晚山檐外出，秋水席边流。","还乡初握手，恋阙屡回头。","竟夕成欢宴，感激讵云休。"]},{"t":"往游流江坐溪南追忆如川隐君感赋三首 其一","f":"五言律诗","c":["尚忆京城别，旋闻旅榇归。","宁知垂老际，翻觉故人稀。","江晚沙鸥集，庭春海燕飞。","佳儿如玉树，相顾烂生辉。"]},{"t":"往游流江坐溪南追忆如川隐君感赋三首 其二","f":"五言律诗","c":["兰玉照庭除，松楸掩墓墟。","人犹思挂剑，孙已解摊书。","独往青山在，重来白发疏。","平生知己恨，下马更踟蹰。"]},{"t":"往游流江坐溪南追忆如川隐君感赋三首 其三","f":"五言律诗","c":["白白新梅树，青青旧桂林。","碧云幽巷晚，残雪小斋深。","客去犹悬榻，人亡欲绝琴。","凄凉风雨夕，灯影照华簪。"]},{"t":"和萧用文寒夜闻风之作","f":"五言律诗","c":["汹汹松涛合，潺潺竹溜分。","已怜寒夜入，况是客窗闻。","月黑乌号子，天高雁失群。","凄凉江海意，对酒正思君。"]},{"t":"宫体四时词答和欧阳原之 其一","f":"五言律诗","c":["春色满长杨，花枝出建章。","莺啼知禁苑，辇过识天香。","度曲调鹦䳇，吹笙引凤凰。","可怜庭草色，浑欲上罗裳。"]},{"t":"宫体四时词答和欧阳原之 其二","f":"五言律诗","c":["太液清无暑，承恩得泛船。","飞帷缘绿水，团扇夹晴烟。","日暮犹移辇，风来欲上仙。","池边荷叶小，个个似青钿。"]},{"t":"宫体四时词答和欧阳原之 其三","f":"五言律诗","c":["金屋秋风起，铜盘夕露深。","水花红冉冉，宫树碧沉沉。","却望鸾旌影，微闻凤吹音。","月明瑶殿冷，香梦杳难寻。"]},{"t":"宫体四时词答和欧阳原之 其四","f":"五言律诗","c":["晓色冻铜池，寒光上玉墀。","天低九重阙，雪满万年枝。","阁道垂帘密，宫门放钥迟。","春风别殿早，若个画蛾眉。"]},{"t":"登石华山遇雨","f":"五言律诗","c":["西候浮丘伯，东瞻石华峰。","林阴初歇马，云气已乘龙。","急雨沾崖谷，长风下桧松。","殷勤两仙女，持赠玉芙蓉。"]},{"t":"夏日同谢可用丁文甫黄立本丁昌祖戴伯渊宴集西园池亭","f":"五言律诗","c":["今日南园好，超然欢笑同。","谁知林塘幽，有此路径通。","脱巾芳树下，行酒青草中。","既饮亦径醉，高歌答林风。"]},{"t":"题周伯宁梅溪图","f":"五言律诗","c":["月出青溪上，云生翠壁间。","流辉方绕涧，散影已腾山。","闻有梅初发，兼怀桂可攀。","怅言寻芳者，曳杖不知还。"]},{"t":"赋水作玉虹流送子启之赣","f":"五言律诗","c":["赣江不可极，双注碧云中。","出峡几千丈，青天垂玉虹。","系船沙碛雨，挂席石潭风。","八月寻源去，相思秋树红。"]},{"t":"再赋岚气昏晨树","f":"五言律诗","c":["晨光暧众壑，岚气嘘重雾。","遥闻山下钟，微辨岩前树。","花落空复春，鸟啼不知处。","木末带飞帆，行人望中去。"]},{"t":"寒夜感兴和廖子所二首 其一","f":"五言律诗","c":["浦月初沈后，林霜欲下时。","空馀清夜永，不尽故园思。","旅雁惊寒惨，邻鸡戒晓迟。","床帷怜稚子，此意未能知。"]},{"t":"寒夜感兴和廖子所二首 其二","f":"五言律诗","c":["未赋潘安兴，仍怀宋玉悲。","溪山百里道，雨雪暮年期。","儒术真何济，农书竟不知。","临晨增感激，一谢故人思。"]},{"t":"次胡琴所韵","f":"五言律诗","c":["旅舍生芳草，书帷映古槐。","共怜春意入，况值客愁开。","隔屿花如雾，哄堂笑似雷。","杯行嫌太缓，故遣短歌催。"]},{"t":"送人赴南安推官","f":"五言律诗","c":["横浦西江上，君行驾短艭。","客程花拂帽，官舍鸟窥窗。","远别轻千里，高名重一邦。","辉辉东海日，偏照画旗杠。"]},{"t":"复出东原寓舍","f":"五言律诗","c":["渐喜故园近，况闻征旅稀。","草间寻旧径，江上问柴扉。","晓霁泥沾屐，春寒雪满衣。","东皋须种豆，从此荷锄归。"]},{"t":"戏题钓台石","f":"五言律诗","c":["拳石立崔嵬，何年控凿开。","险应非滟滪，奇欲似离堆。","云气缠高蔓，波光漾紫苔。","长竿吾欲试，叹息棹歌回。"]},{"t":"秋暮候家僮不至","f":"五言律诗","c":["少日疏狂惯，中年感慨同。","梦啼惊泪雨，坐久怯头风。","把酒嗔浮蚁，看书惜过鸿。","故园归渐近，凭问菊花丛。"]},{"t":"达上麓访吴孟勤不遇二首 其一","f":"五言律诗","c":["杳杳天河路，苍苍暮色寒。","千峰引云树，孤棹入风湍。","旧别嗟谁在，新诗忆共看。","怜君好毛羽，何处觅琅玕。"]},{"t":"达上麓访吴孟勤不遇二首 其二","f":"五言律诗","c":["忆过山中路，都无半日程。","如何不相见，从此又南征。","江海时舟楫，边隅尚甲兵。","相思摇落景，回首飒心惊。"]},{"t":"张氏溪亭杂兴四首 其一","f":"五言律诗","c":["草阁经秋净，柴扉近水开。","霜林收橘柚，风磴坐莓苔。","钓艇寒初放，樵歌晚独回。","城南车马地，欲往更徘徊。"]},{"t":"张氏溪亭杂兴四首 其二","f":"五言律诗","c":["水落沈菰米，亭深暗女萝。","捲帘秋雾薄，倚杖白云多。","点点流萤下，翩翩宿鸟过。","秋高摇落近，幽兴欲如何。"]},{"t":"张氏溪亭杂兴四首 其三","f":"五言律诗","c":["寒雾依山敛，晴沙与岸颓。","林塘无路入，窗户有时开。","野客抄书去，邻翁送酒来。","幽期在萝薜，莫遣暮钟催。"]},{"t":"张氏溪亭杂兴四首 其四","f":"五言律诗","c":["鸟径缘沙小，鱼梁叠石高。","细流通乱屿，杂树带平皋。","白鹭怡心性，青禽惜羽毛。","由来林下客，偃仰愧尘劳。"]},{"t":"题阳灵洞二首 其一","f":"五言律诗","c":["窅窅青牛峡，荒荒白鹤坛。","石山元少树，阴洞故多寒。","帝子非秦女，将军自汉官。","乘云知不返，叹息万人看。"]},{"t":"题阳灵洞二首 其二","f":"五言律诗","c":["仙宇何年辟，灵泉尽日闻。","石门通别殿，木栈倚高云。","鸾凤时来下，猕猴近作群。","春风城郭暮，烟雾正纷纷。"]},{"t":"下苍山西麓将问道过金精是日赵伯友与客先赴山中闻已出谷口相候喜赋","f":"五言律诗","c":["上马愁将夕，题诗念友生。","苍茫惊独往，迢递愧相迎。","崖涌青莲色，溪流碧玉声。","登临馀我辈，应不负高情。"]},{"t":"伯友夜半酒醒戏举一首","f":"五言律诗","c":["对酒不能饮，高人方醉眠。","衣裳侵石冷，冠帻挂云偏。","地迥星联户，风澄露满天。","冥冥清夜过，惊起问初筵。"]},{"t":"题雪景画","f":"五言律诗","c":["山阁雪初暝，石床天正寒。","亦愁江上听，秪益坐中看。","竹树低仍压，茅茨湿未乾。","谁能添小艓，来把钓鱼竿。"]},{"t":"送夏定夫归进贤","f":"五言律诗","c":["从师劳远涉，归兴及清秋。","即此催还觐，相看动别愁。","天垂阴洞碧，云入暮山稠。","犹忆谈经夜，松亭月色幽。"]},{"t":"赋石龙山","f":"五言律诗","c":["柳氏堂前石，崭岩故似龙。","泥沙排异质，烟雾失奇踪。","槛竹秋阴覆，阶苔夕雨封。","鳌溪未能往，凝想最高峰。"]},{"t":"淮甸 其一","f":"五言律诗","c":["淮甸今焚掠，纷纷日异闻。","远侵三楚地，近隔九江云。","邻省围边将，亲王进卫军。","由来王国内，不在策奇勋。"]},{"t":"淮甸 其二","f":"五言律诗","c":["始报修城障，仍闻铸甲兵。","关河原阻滞，宇宙划经营。","不谓时当尔，终然法再更。","边圉岂忘备，万一向清平。"]},{"t":"题米元晖山水小景","f":"五言律诗","c":["江上见青峰，亭亭三四重。","雨沾金翡翠，云拥玉芙蓉。","桂屿閒秋馆，枫林隐暮钟。","苍茫图画意，欲赏惜无从。"]},{"t":"赋碧梧","f":"五言律诗","c":["庭前碧梧叶，秋至总离离。","不记远移处，忽惊初落时。","色分云际石，影乱月中池。","凤鸟几时至，凄凉青玉枝。"]},{"t":"杏园观赤文挹射弓","f":"五言律诗","c":["公子杏园中，邀人射角弓。","张弦惊满月，鸣镝应长风。","力倚千钧重，心期一中工。","清秋鞍马健，莫谩拟飞鸿。"]},{"t":"晚出西关","f":"五言律诗","c":["戈戟重门固，风尘过客稀。","飞禽愁战格，屯卒怪儒衣。","野旷北风劲，天高西日微。","苍茫愁满眼，欲往惜心违。"]},{"t":"江阁晚望次严焕韵","f":"五言律诗","c":["落日明秋燧，江空生夕波。","阁前歌吹少，城下战船多。","望眼悬飞檄，愁心倚太阿。","王师犹驻马，谁遣问如何。"]},{"t":"赋战旗得营字","f":"五言律诗","c":["疾风吹大旗，西出洛阳城。","鸢鸟并飞动，熊虎歘纵横。","披拂中军帐，飘扬列骑营。","万人回首处，太白独分明。"]},{"t":"奉同孔元月赤文挹王子启严焕宴集闻公房得新字","f":"五言律诗","c":["跨牛庵下路，秋日往来频。","何处无芳草，多应有故人。","座分禅榻旧，门拥戟旗新。","且复临尊酒，微吟远世尘。"]},{"t":"夜坐","f":"五言律诗","c":["江浦低云雁，墀阶起露萤。","一灯寒炯炯，乱叶夜冥冥。","城迥闻征柝，檐虚见落星。","时来对尊酒，亦足慰飘零。"]},{"t":"登易氏山后小亭","f":"五言律诗","c":["乱石危峰下，孤亭众木间。","藤萝深结络，阑槛极跻攀。","啼鸟青烟隔，游丝白日閒。","风尘满城市，怅望不知还。"]},{"t":"红缨白帽","f":"五言律诗","c":["白帽缀红缨，军容喜称情。","兜鍪知较古，贝胄比还轻。","上马秋风动，归营夜雪明。","少年趍幕府，岸帻尽谈兵。"]},{"t":"示刘生","f":"五言律诗","c":["林塘子故物，风景最宜诗。","暂去还相见，閒吟亦自奇。","冰霜惊岁晏，戎马惜时危。","雅道今如此，古人端可师。"]},{"t":"快阁春望次王子启","f":"五言律诗","c":["使者徵兵去，居民避地回。","南风犹鼓角，北岸自楼台。","白水晴云动，青山暮雨来。","百年旧城郭，临眺独兴哀。"]},{"t":"坐子启竹林","f":"五言律诗","c":["爱尔幽栖处，门前青竹林。","石床三伏冷，池水一春深。","野鸟来窥户，溪鱼出听琴。","无因谢羁束，携酒日相寻。"]},{"t":"六月十六日观内省使臣传诏到州","f":"五言律诗","c":["闻道京华使，南从海上来。","丁宁深激义，沈痛欲兴哀。","远道经年达，华筵尽日开。","灵槎万里外，飘泊几时回。"]},{"t":"美梁太守总兵大洲","f":"五言律诗","c":["太守威名重，中军节制专。","城池百战里，藩屏数州先。","兵帐江云动，戈船野雾连。","时危仗经济，感激万人传。"]},{"t":"戏柬子启","f":"五言律诗","c":["高怀清似鹤，谁遣谩多忧。","药裹家人问，诗篇过客求。","江连王子宅，山入仲宣楼。","且复临尊酒，高歌慰远游。"]},{"t":"答项可成怀遂江故宅","f":"五言律诗","c":["亭馆西南胜，清含山水姿。","偶因看诗处，却忆旧游时。","落日千峰隔，孤城百战危。","相逢江海暮，回首意兼悲。"]},{"t":"题山水画","f":"五言律诗","c":["数骑阴崖雪，孤帆碧屿风。","行人万里意，远在杳茫中。","雁下雪湍急，乌啼霜树空。","遥山青一点，疑是洞庭东。"]},{"t":"送友人还赣","f":"五言律诗","c":["南国犹防寇，春城尚鼓鼙。","乱山愁落日，积水畏横霓。","失木猿呼子，巢林燕择栖。","送君增感慨，花发赣江西。"]},{"t":"感事二首 其一","f":"五言律诗","c":["何地驻王师，南驱定几时。","疲氓思一战，妖寇倚群疑。","江汉三年急，云霄万里思。","孤城烟雾里，惨淡望旌旗。"]},{"t":"感事二首 其二","f":"五言律诗","c":["野战曾无赖，民生遂不支。","仓皇轻反侧，狼藉尚倾危。","夕路豺狼横，春山鸟雀悲。","时时瞻北极，光耀注南陲。"]},{"t":"兵乱二首 其一","f":"五言律诗","c":["兵乱连三载，年荒馀几家。","久闻人食草，仍报盗如麻。","忧国愁心死，伤时泪眼斜。","平田栖白骨，千里见飞鸦。"]},{"t":"兵乱二首 其二","f":"五言律诗","c":["群盗犹相煽，官军且未来。","四山烟雾塞，一水道途开。","近郭多豺虎，春田半草莱。","时时消息异，呜咽壮心哀。"]},{"t":"奉和梅南刘府推题萧氏隐居","f":"五言律诗","c":["野雉晴初雊，溪鱼冻可叉。","山中好风物，洞口是仙家。","竹径空流水，茆堂侣浣花。","他年记行役，林下见兵衙。"]},{"t":"寄范实夫主廪赣先贤书院三首 其一","f":"五言律诗","c":["乱后今谁在，愁来想鬓华。","公侯能好客，风土足为家。","翠玉春携酒，廉泉夜煮茶。","相思一回首，烽火暗天涯。"]},{"t":"寄范实夫主廪赣先贤书院三首 其二","f":"五言律诗","c":["赣水来天上，江边足定居。","梦寻疑有路，恨别竟无书。","坐石调琴处，临池弄墨馀。","清才与殊调，空忆旧游疏。"]},{"t":"寄范实夫主廪赣先贤书院三首 其三","f":"五言律诗","c":["杨子旧精舍，全侯新学宫。","百年遗往躅，一旦振高风。","日月冠裳会，春秋俎豆崇。","游歌未能往，叹息羡飞鸿。"]},{"t":"寄旷知事伯逵四首 其一","f":"五言律诗","c":["昔别已千里，新愁复四年。","风尘不可见，江海一凄然。","才想群公荐，名因过客传。","东南藩镇重，独觉省郎贤。"]},{"t":"寄旷知事伯逵四首 其二","f":"五言律诗","c":["抱檄诉邻饥，开关破贼围。","近随兵帐出，远送米船归。","吴水波涛恶，西山草树稀。","艰危知共济，莫遣壮心违。"]},{"t":"寄旷知事伯逵四首 其三","f":"五言律诗","c":["闻说移居地，还依孺子亭。","对门湖共白，一路柳长青。","仕已沾恩露，庭应聚德星。","谁能远车马，况不异郊坰。"]},{"t":"寄旷知事伯逵四首 其四","f":"五言律诗","c":["郡邑溪山在，风尘寇盗馀。","长怀管宁去，未卜屈原居。","计拙忧虞剧，閒多礼法疏。","柴门春草满，惊捧故人书。"]},{"t":"即事","f":"五言律诗","c":["此日螺山下，春深草谩多。","官船依近郭，寇垒隔长河。","市缺新年酒，田荒旧种禾。","忧危仍寂寞，回首飒悲歌。"]},{"t":"承曾子硕自洪归赣道次太和以故人旷伯逵书问见及临别怅然诗以送之","f":"五言律诗","c":["阁下帆初落，江干雨正疏。","感君千里意，远致一封书。","旧宅蓬蒿遍，新愁瘴疠馀。","冥冥更南上，烟浪满寒虚。"]},{"t":"过王氏南园看竹刘以和携酒至共酌林间 其一","f":"五言律诗","c":["王子时相见，刘郎晚共携。","邀人竹林下，沽酒石桥西。","林绚甜椔发，畦深苦藚齐。","徘徊未能饮，着意鸟频啼。"]},{"t":"过王氏南园看竹刘以和携酒至共酌林间 其二","f":"五言律诗","c":["禁得南园笋，新成数百竿。","何年通一径，长有客来看。","露叶沾重席，烟梢拂小冠。","风湍听不定，况复近江干。"]},{"t":"过王氏南园看竹刘以和携酒至共酌林间 其三","f":"五言律诗","c":["磊磊苍苔石，娟娟翠筱林。","圃畦分晓色，邻屋借秋阴。","日转游丝细，天寒聚雀深。","独无三亩地，种汝伴清吟。"]},{"t":"过王氏南园看竹刘以和携酒至共酌林间 其四","f":"五言律诗","c":["节下题诗遍，林间送酒迟。","亦愁春雨里，共爱晚晴时。","斩玉嗔初见，移根任所为。","长令扫苔石，来此赴幽期。"]},{"t":"次颜用行留别韵二首 其一","f":"五言律诗","c":["昔避乌仙洞，归来又六年。","乡园各奔散，寇盗竟缠连。","愁共将零叶，身如不系船。","艰危惊再见，未有买山钱。"]},{"t":"次颜用行留别韵二首 其二","f":"五言律诗","c":["叹息泸源上，何时寇盗平。","凄凉惊往事，浩荡怯孤征。","世乱欢娱少，时危出处轻。","送行频惜别，落日最伤情。"]},{"t":"仲秋八日赴洪都应试夜宿盐堆头","f":"五言律诗","c":["花石耀寒星，盐头隐暮汀。","风沙开漠漠，烟浪入冥冥。","战鼓秋初急，羁愁夜不醒。","故园西岭外，渐隔两长亭。"]},{"t":"桐江","f":"五言律诗","c":["残垒带江沙，荒祠集暮鸦。","客行桐水市，人采木绵花。","山掩飞烟直，江浮落日斜。","旧游那可问，依约见人家。"]},{"t":"阑泊口","f":"五言律诗","c":["一岸危于削，群山隐似围。","豺狼前日盛，市井近来非。","古屋蓬蒿遍，荒村鸟雀稀。","还闻覆巢日，烈火照天飞。"]},{"t":"新淦","f":"五言律诗","c":["乱山淦水上，雨气白如烝。","古塔遗孤表，荒壖散百层。","贾船初放桨，鱼屋稍悬罾。","近有官军守，科征恐未能。"]},{"t":"过峡江","f":"五言律诗","c":["石峡閟苍烟，江流似昔年。","戈船犹自守，草市稍相连。","白骨青山下，黄蒿古道边。","石桥携酒处，风雨一凄然。"]},{"t":"题春山烟雨图","f":"五言律诗","c":["崖溜下林陂，春云带雨垂。","不知村远近，惟见树参差。","柳巷闻莺早，桃溪放犊迟。","乱馀宁有此，愁绝辋川诗。"]},{"t":"送张子明归武夷","f":"五言律诗","c":["东去渡沙关，宁辞道里艰。","云连闽海郡，家近武夷山。","腊酒鹅儿碧，春衣稚子斑。","徘徊南浦上，别恨不能攀。"]},{"t":"题云林别墅图为黄子邕赋","f":"五言律诗","c":["云薄黎川水，月明萧曲峰。","寒沙闻落叶，绝顶见长松。","别墅携壶兴，深林蹑屐踪。","秋江愁不渡，谁共采芙蓉。"]},{"t":"再赋","f":"五言律诗","c":["种树萧峰下，结茅黎水滨。","疏星澹将夕，众草忽已春。","遭乱去故里，临图忆高人。","怅言赴归日，从子理荒榛。"]},{"t":"送省掾刘宗弼之岭南买官马","f":"五言律诗","c":["烽火暗崇江，官船发豫章。","千金求骏马，万里入南荒。","倚剑看明月，停杯问故乡。","相臣忧国意，注目倚腾骧。"]},{"t":"十五夜赋","f":"五言律诗","c":["素月流天外，华灯出树间。","美人吹凤管，秋水落龙湾。","清露缘萝坠，凉风傍竹还。","远怀当此夕，载酒过西山。"]},{"t":"沙村道中","f":"五言律诗","c":["隔水望东绵，看云忆阆川。","人行秋草里，雁落夕阳边。","败屋犹依砦，荒村少种田。","征徭浑未已，野哭更凄然。"]},{"t":"九日感事三首 其一","f":"五言律诗","c":["山寇能骑马，官军解掠人。","徒然縻国赋，何以净边尘。","周雅歌三捷，苗顽格七旬。","又闻宽诏下，谁忍负深仁。"]},{"t":"九日感事三首 其二","f":"五言律诗","c":["钟步时传警，新安久被围。","乡山孤垒在，戍卒几人归。","夜月喧鸣柝，秋霜裂战衣。","艰危依主将，羽檄夜频飞。"]},{"t":"九日感事三首 其三","f":"五言律诗","c":["闻道泸江破，伤心却复疑。","六年犹力抗，群盗竟猖披。","壮士乘危数，官军出援迟。","几人全骨肉，夜走哭荒陂。"]},{"t":"虞检校奉省相命南迓王御史十月舟过珠林承寄佳作依韵奉答","f":"五言律诗","c":["瓜熟东湖日，长怀别故人。","忽传舟楫近，先寄墨题新。","远候轻千里，幽居少四邻。","几时持使节，来赏菊花春。"]},{"t":"画鹰","f":"五言律诗","c":["自是飞腾物，仍兼画作殊。","英姿风飒爽，苍翮锦模糊。","云雾终当击，轩楹未可呼。","海天秋万里，回首独踌蹰。"]},{"t":"吕焕文挽诗","f":"五言律诗","c":["叹息瑶冈下，斯人不可寻。","故床芸帙在，新冢蔓丛深。","有弟求哀诔，无人续苦吟。","宁知风雪夜，回首独沾襟。"]},{"t":"题彭氏背郭茆堂图","f":"五言律诗","c":["日薄金华岭，云深白石塘。","茆茨元背郭，水竹自成乡。","图画看逾好，登临兴不忘。","门前双杏树，叶叶是秋霜。"]},{"t":"送雩都吴文学","f":"五言律诗","c":["长忆吴文学，居官近十年。","俗随风土变，诗入瘴乡传。","晓郭寻山屐，春江出峡船。","乱离愁复别，况是落花天。"]},{"t":"暮归至江口无舟投宿洲上田家","f":"五言律诗","c":["野渡初维楫，林居早闭门。","陂塍交白水，灯火向黄昏。","问客安行李，呼儿具酒樽。","艰难昧生理，深愧老翁言。"]},{"t":"出郭","f":"五言律诗","c":["出郭念农事，渡江仍涉溪。","城边愁落日，林下趁幽栖。","紫椹交萝径，红花间豆畦。","学耕心未已，冲雨看锄犁。"]},{"t":"江口汎舟得船字","f":"五言律诗","c":["凉露青天下，繁星白水边。","歌呼仍劝酒，起坐忽欹船。","喧已非尘境，清疑是水仙。","沙头灯火起，飞鹭亦翩翩。"]},{"t":"过龙湾五王阁访友人不遇","f":"五言律诗","c":["野桥秋水落，江阁冥烟微。","白日又欲午，高人犹未归。","青林依石塔，虚馆净柴扉。","坐久思题字，翻怜柿叶稀。"]},{"t":"闻赣已被围而东固大坑又欲兵攻兴国有怀伯氏子中寓赣县之礼原阻乱不得归 其一","f":"五言律诗","c":["叹息荆花树，今年好远游。","路从兵后断，书是乱前收。","漂泊从谁问，艰危信自谋。","时时惊梦见，不解说离愁。"]},{"t":"闻赣已被围而东固大坑又欲兵攻兴国有怀伯氏子中寓赣县之礼原阻乱不得归 其二","f":"五言律诗","c":["江口移兵日，山中散砦时。","一家俱念尔，孤客定依谁。","秋早衣裳薄，时危去住疑。","故园久残落，犹恐未全知。"]},{"t":"怀王子启寓赣在兵围中已兼月矣 其一","f":"五言律诗","c":["南上记乘涛，千峰一郡高。","共言坚可托，讵想战频鏖。","危急输群策，艰虞倚二豪。","亦知城有窦，柴也若为逃。"]},{"t":"怀王子启寓赣在兵围中已兼月矣 其二","f":"五言律诗","c":["行李今何在，兵围飒暮秋。","定依故人住，谁慰老亲忧。","远道乖鱼素，孤城抗虎头。","伤心对明月，莫谩赋鄜州。"]},{"t":"再怀伯兄子中时有同客兴国者从间道先归兄以道阻后期不果","f":"五言律诗","c":["贫贱轻离别，艰危昧死生。","独违同里伴，仍阻异乡程。","爱想深山憩，愁闻间道行。","几时秋树下，慰此泪纵横。"]},{"t":"送医士归豫章","f":"五言律诗","c":["落叶满城隅，南归感岁徂。","海边曾种玉，市上忆悬壶。","山近烟岚薄，江寒岛屿孤。","惜无黄犊卖，从子住东湖。"]},{"t":"题真上人幽居图","f":"五言律诗","c":["岂有人知处，千峰拥翠岚。","背林通药径，隔水见茆庵。","说法鱼应听，栖禅鹤共参。","经秋忘出户，落叶满岩龛。"]},{"t":"寓翁","f":"五言律诗","c":["问翁何所寓，非寓亦非真。","落落林泉迹，悠悠天地身。","弹琴忘雅俗，饮酒信醨醇。","千载蒙庄叟，相看意独亲。"]},{"t":"夜宿道德坛柬胡山人袁炼师萧鹏举 其一","f":"五言律诗","c":["月色下金銮，鸡鸣出紫坛。","不眠惊地迥，相语向更阑。","酒过怜初醒，琴疏忆再弹。","永怀栖遁乐，亦欲挂吾冠。"]},{"t":"夜宿道德坛柬胡山人袁炼师萧鹏举 其二","f":"五言律诗","c":["解剑旌阳宅，吹笙萧史台。","惊看龙跃出，疑有凤飞来。","窗曙浮青桂，庭深散紫苔。","翛然心迹静，谁更问蓬莱。"]},{"t":"送友人入韶口山中","f":"五言律诗","c":["问客买乌犍，去耕韶口田。","地饶无恶草，山近有流泉。","过雨听春鸟，寻墟望晓烟。","野人应避席，莫遣识遗贤。"]},{"t":"赋清江送廖子谦之临江","f":"五言律诗","c":["清江清见底，千尺下沈沈。","白鸟晴飞远，石龙云卧深。","遥知在泮乐，好听濯缨吟。","念此登临地，因之见夙心。"]},{"t":"春日次萧鹏举二首 其一","f":"五言律诗","c":["野客愁无赖，春来常晏眠。","有时携美酒，独酌向青天。","种豆珠林下，看花石屋前。","故人不可见，佳句乃联翩。"]},{"t":"春日次萧鹏举二首 其二","f":"五言律诗","c":["闻说南溪上，乱馀春可怜。","花开愁落日，草长记流年。","赋拟传金谷，茶应记玉川。","寻常西郭路，思尔隔风烟。"]},{"t":"玉华山","f":"五言律诗","c":["翠巘千峰合，丹崖一径通。","楼台上云气，草木动天风。","野旷行人外，江平落雁中。","伤心俯城郭，烟雨正濛濛。"]},{"t":"题达监州草庵在金华之左","f":"五言律诗","c":["云气随轩盖，飘飘日往来。","茆茨元自葺，窗户有谁开。","棠茇歌仍在，桐乡事可哀。","星袍五花马，犹想月中回。"]},{"t":"赋秋水送友人之豫章","f":"五言律诗","c":["秋水碧盈盈，无波似镜平。","渚云低不渡，江月照偏明。","色映群鸥净，光涵一雁横。","望中征棹发，应过豫章城。"]},{"t":"送宋国宾往宁都求父丧","f":"五言律诗","c":["野哭求亲冢，南循贡水濆。","招魂当落日，负骨出寒云。","驯鹿穿崖送，慈乌隐树闻。","残年候归楫，风雪定纷纷。"]},{"t":"舟夜次杳口柬萧鹏举","f":"五言律诗","c":["扁舟沿绿屿，双橹拆苍波。","秋气水边早，月明江上多。","鱼龙今夜冷，鸿雁几时过。","去住关幽兴，欹眠听棹歌。"]},{"t":"触目","f":"五言律诗","c":["到处草离离，重城秋暮时。","荒园交兔径，残屋带荆篱。","自倚城如铁，谁怜命若丝。","诛求方未已，富庶定何期。"]},{"t":"南涧夜雪怀子启前东塘雪中寄诗未答","f":"五言律诗","c":["昨夜南溪雪，故人安可期。","欲寻行处履，长忆寄来诗。","龙蛰沧江水，乌啼冻树枝。","武山千丈玉，思尔共游时。"]},{"t":"题墨鹰","f":"五言律诗","c":["莫氏写翎毛，精神故自豪。","轩然苍隼立，郁彼北林高。","急想追星火，轻疑掣旋绦。","向来飞动意，感激使心劳。"]},{"t":"忆萧翀","f":"五言律诗","c":["闻尔去南溪，移船驻水西。","家人应共载，书帙得同携。","道在隆污定，时危去住齐。","风尘嗟两地，何处觅封题。"]},{"t":"哭七弟","f":"五言律诗","c":["季也伤愚戆，林间第七枝。","生尝劳父训，死竟重兄悲。","缚兔工何益，囊萤计已迟。","虎儿应迈尔，教养待来兹。"]},{"t":"题田舍壁","f":"五言律诗","c":["门巷带青枫，村西有路通。","鸟鸣高竹上，水落乱藤中。","耕凿常时惯，招游旧俗同。","寄言城市客，未可薄田翁。"]},{"t":"题山水小景","f":"五言律诗","c":["倚石群松秀，横江五柳繁。","水侵陶令宅，山掩谢公村。","浴鹭依晴桨，啼莺近晚尊。","乱馀宁复此，展卷一消魂。"]},{"t":"寄周伯宁二首 其一","f":"五言律诗","c":["交友今谁在，东游最忆君。","清尊澄夜月，綵笔动春云。","楚甸烽烟合，秦淮树色分。","相思愁日暮，花落正纷纷。"]},{"t":"寄周伯宁二首 其二","f":"五言律诗","c":["江雨何时歇，淮云尽日飞。","谁知千里别，还作故园归。","露草侵棋局，风花上钓矶。","徒令南浦上，山水忆清辉。"]},{"t":"经亡友故宅","f":"五言律诗","c":["草没门前路，葵荒井畔园。","乱泉通废沼，败屋露颓垣。","已觉鸡豚散，空馀鸟雀喧。","欲行还复止，寒日向黄昏。"]},{"t":"舟次樟镇","f":"五言律诗","c":["匝地闾阎盛，缘江雾雨稠。","舟航通百粤，征税出南州。","故里谁从问，修程且自由。","携壶初问酒，移棹已惊秋。"]},{"t":"闻萧尚志抱病次韵奉寄","f":"五言律诗","c":["山路兼泥潦，其如怅望何。","浮云低近树，细雨暗长河。","城晚乌鸢少，沙寒雁鹭多。","似闻抱微恙，来问愧蹉跎。"]},{"t":"题竹石图","f":"五言律诗","c":["为爱筼筜竹，苍苔节节封。","低枝兼雨重，密叶与烟浓。","丹穴终栖凤，沧溟未化龙。","几时裁紫玉，吹上白云峰。"]},{"t":"奉寄孔监县","f":"五言律诗","c":["宝匣动龙泉，纶巾拂紫烟。","酣歌明月下，起舞落花前。","野雉红襦短，溪鱼白锦鲜。","亦怜春似海，安得酒盈船。"]},{"t":"赠别李子翀之金陵七首 其一","f":"五言律诗","c":["之子金陵去，秋风飒暮江。","西维流大火，南纪奠雄邦。","鱼落波涛市，鸟啼烟雾窗。","登临闻伐木，未得此心降。"]},{"t":"赠别李子翀之金陵七首 其二","f":"五言律诗","c":["南北舟车会，公侯地宅多。","百年新雨露，六代旧山河。","夜月铜驼陌，秋风玉树歌。","昔人遗感嘅，不必问如何。"]},{"t":"赠别李子翀之金陵七首 其三","f":"五言律诗","c":["凤凰去千载，城曲尚崇台。","落日台前下，长江天际来。","锦袍随梦远，玉笛与秋哀。","定有骑黄鹤，凭高日往回。"]},{"t":"赠别李子翀之金陵七首 其四","f":"五言律诗","c":["龙蟠梵王宅，钟阜出南东。","一水天光限，诸峰雾气通。","幡幢低晚树，钟磬下晴空。","茆屋如堪赋，能忘讯已公。"]},{"t":"赠别李子翀之金陵七首 其五","f":"五言律诗","c":["独往堪谁语，沈歌秪自怜。","才名三十著，诗律几人传。","凉幕惊巢燕，炎波看站鸢。","荆南有刘表，把剑故凄然。"]},{"t":"赠别李子翀之金陵七首 其六","f":"五言律诗","c":["往昔庐陵掾，监仓出万安。","白鱼供日馔，红腐足朝盘。","云暝千峰雨，江喧十月滩。","向来栖息地，三见菊花残。"]},{"t":"赠别李子翀之金陵七首 其七","f":"五言律诗","c":["相知仍少聚，即别转多怀。","用世悲才忌，乘时贵俗谐。","江声通巨蜀，云气尽长淮。","亦有南淮志，何由与子偕。"]},{"t":"送萧同可之肇庆","f":"五言律诗","c":["端州萧幕府，五十老能文。","命秩乡人羡，诗名朝士闻。","石门明夜雪，铜鼓暗春云。","暂尔鲲鹏运，终然鹓鹭群。"]},{"t":"杨待制挽诗","f":"五言律诗","c":["郡邑徵循吏，词林忆侍臣。","青云嗟濩落，白首见清真。","论秀终裨国，锄奸肯避人。","百年文物尽，愁绝故山春。"]},{"t":"杨州判挽诗二首 其一","f":"五言律诗","c":["浩荡孤飞迥，从容万敌麾。","仕方觇命达，清已畏人知。","白璧泥涂近，朱弦雅奏迟。","春风江海思，萧艾故离离。"]},{"t":"杨州判挽诗二首 其二","f":"五言律诗","c":["万里秦中役，前年渝上官。","长才沦判牍，多病促归鞍。","山雨孤坟暝，江风十月寒。","萧条前辈远，双泪落汍澜。"]},{"t":"戏呈庐陵李司曹","f":"五言律诗","c":["羡尔城阴屋，居来颇类村。","竹枝斜点地，松树直当门。","稚子青衣短，慈亲白发繁。","客愁仍满眼，骑马雨昏昏。"]},{"t":"泊蓼州登岸寻旷氏馆","f":"五言律诗","c":["江雨冷萧萧，维舟近画桥。","不愁春烂漫，故恐浪漂摇。","溆口明花树，城阴散柳条。","故人高馆近，未觉旅魂销。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其一","f":"五言律诗","c":["上日之官去，东门祖帐开。","青云明淑景，朱绂称清才。","花乱雏莺啭，江晴旅雁回。","倘逢孙学谕，为报寄书来。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其二 渡江","f":"五言律诗","c":["二月风涛壮，渡江愁远人。","舟航那可恃，童仆转须亲。","日射黄牛渚，天低石马津。","向来临眺地，及此故伤情。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其三 送靖安教谕王贤卿归南安","f":"五言律诗","c":["千里王文学，南寻庾岭归。","诸生供祖帐，吾道有光辉。","野树重重合，林花日日飞。","茆堂漳水近，莫遣信音稀。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其四 溪上","f":"五言律诗","c":["溪路出南港，野林依古原。","偶行桑树曲，颇似桃花源。","茅屋居人遍，晴滩稚子喧。","依依耦耕者，相对已忘言。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其五 赠葛希亮","f":"五言律诗","c":["丰城龙化远，湛湛墨池深。","每爱葛希亮，亲承邓蔚林。","紫云腾瀚海，香雾袭书林。","胶法亲前辈，清贞见尔心。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其六 千叶黄杨","f":"五言律诗","c":["黄杨一尺许，千叶更千枝。","秪益阶庭玩，能忘云汉思。","雨荒承碧藓，风定注游丝。","伤极偏多感，南归得共移。"]},{"t":"赠赵录判之九江兼柬孙伯虞 斋前黄棠棣生于山茶两株之间春花夏条扶疏可爱兹始及秋而萎黄日见矧后此霜霰交积之时乎感赋一首 其七","f":"五言律诗","c":["弱质不自植，扶疏故满林。","繁英春后尽，病叶雨中深。","斩伐非吾意，匡持见夙心。","山茶亦何事，晏岁足清阴。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其八 秋夕怀大兄及四舍弟时俱客兴国县山川阻修音问邈然","f":"五言律诗","c":["岂谓无家别，三人各远方。","已嗟甘旨薄，翻作道涂长。","潋水风湍白，瑶冈雾树苍。","书来定早晚，莫遣雁相将。"]},{"t":"赠赵录判之九江兼柬孙伯虞 其九","f":"五言律诗","c":["好在程溪上，月高愁掩扉。","也应念行客，独自对清辉。","细草露初白，高河云正稀。","庭前紫荆树，归梦故依依。"]},{"t":"七月得廖子所书闻目疾复作感怀奉寄","f":"五言律诗","c":["辟馆延青佩，升堂奉綵舆。","羡君能养志，愧我在离居。","入夏愁新涨，过时得远书。","秋风决明发，目疾定何如。"]},{"t":"寄李子翀","f":"五言律诗","c":["之子青云器，频年困县曹。","能令官长爱，未觉簿书劳。","委璧宁终弃，鸣弦且学操。","何时倚长钓，沧海掣鲸鳌。"]},{"t":"过李黄罗茅堂五首柬克正茂才 其一","f":"五言律诗","c":["幽居仍近郭，高隐即深山。","草径经年合，茅堂尽日閒。","检书青竹映，倚杖白云还。","远愧南游客，逢人秪厚颜。"]},{"t":"过李黄罗茅堂五首柬克正茂才 其二","f":"五言律诗","c":["茅堂子故物，归意定何如。","学道亲先辈，清心远俗书。","藤稍垂石乱，瓠叶上檐虚。","日有南溪叟，能来送鲤鱼。"]},{"t":"过李黄罗茅堂五首柬克正茂才 其三","f":"五言律诗","c":["水碓时时急，秋山岸岸阴。","偶来看野客，浑欲托云林。","乌石寒松暝，香田雨稻深。","幽栖宁避世，暂去已关心。"]},{"t":"过李黄罗茅堂五首柬克正茂才 其四","f":"五言律诗","c":["何年远城市，来此寄高情。","客有求书札，谁从隐姓名。","茅茨寒更湿，花竹晚初成。","江海尊前意，依依见弟兄。"]},{"t":"过李黄罗茅堂五首柬克正茂才 其五","f":"五言律诗","c":["伏雨日潇潇，寒风断柳条。","居然怀契阔，何以谢招邀。","把酒销银烛，披图出绛绡。","由来文物异，况乃自前朝。"]},{"t":"蜀人师季则自临川来靖安省其姑于李氏岁暮将归辱贻铜刻赋此答赠","f":"五言律诗","c":["有美趋庭服，来寻李氏姑。","终然思㝢县，复此戒长涂。","篆刻铜章古，精神玉树孤。","峨眉烟雾隔，何日上成都。"]},{"t":"对月","f":"五言律诗","c":["落尽东门柳，辞家又一年。","浮云千里外，明月九秋前。","席近花香润，楼当桂影偏。","思乡意未已，鸿雁已翩翩。"]},{"t":"赠帖有道进士自成都之官舒城","f":"五言律诗","c":["进士之官去，真成万里游。","白云淮水暮，红叶蓟门秋。","瓜戍随春入，公田按月收。","殷勤念民隐，外秩近来优。"]},{"t":"访周叔用不遇","f":"五言律诗","c":["归近意不怿，独行寻故人。","岁年浑欲暮，心迹转相亲。","水入苍葭乱，霜侵碧树匀。","终然不可见，但讶往来频。"]},{"t":"题舒君彦幽居","f":"五言律诗","c":["自有幽居趣，人来不厌频。","叩门过日晏，移坐见情亲。","涉圃从沾屐，穿林屡折巾。","寻常混尘俗，到此澹心神。"]},{"t":"柬舒中立","f":"五言律诗","c":["城僻苍山古，天寒落叶稀。","细流通石涧，斜日带林扉。","柳外青凫乱，松阴白鸟微。","看君携稚子，把酒惜牵衣。"]},{"t":"送友人南归","f":"五言律诗","c":["岁晏各言别，君还先赋归。","悠悠遵道路，渺渺问庭闱。","江阔行舟远，天寒过雁稀。","城南风雪里，惆怅把征衣。"]},{"t":"访廉泉亭拜赵清献苏文忠胡忠简三先贤遗像","f":"五言律诗","c":["古寺青芜里，东风夕照馀。","阶除流水过，井甃白云虚。","遗迹今何似，清心只自如。","高亭烟雾色，惨淡昔人书。"]},{"t":"夜宿曾氏馆赋赠子元子硕昆季","f":"五言律诗","c":["袅袅丛兰秀，娟娟双凤雏。","馨香元是早，毛羽固应殊。","夕雨沾书帙，春风散酒壶。","承家仍好客，于我惜欢娱。"]},{"t":"雨坐江亭候宁都船不至","f":"五言律诗","c":["不见南帆上，凄然对水窗。","疾风吹大木，积雨暗横江。","远道何由达，愁心苦未降。","徒闻鸣鹳起，东渡正双双。"]},{"t":"晚次雩都县","f":"五言律诗","c":["寂历春江上，城门对县安。","人家依水竹，云塔倚风湍。","问酒林花落，维舟浦树寒。","欲眠愁向夕，渔火下长滩。"]},{"t":"月出","f":"五言律诗","c":["月出光初发，客行烟水中。","船头当北斗，竿尾信南风。","蛟室侵崖黑，渔灯照岛红。","飘飘今夕缆，何处系青枫。"]},{"t":"雷鸣砌上对雪","f":"五言律诗","c":["谁能思更往，暝入楚江空。","捲席听春雪，移船避北风。","依人汀树绿，着意渚桃红。","触景成孤寂，悠悠去住同。"]},{"t":"黄坊","f":"五言律诗","c":["风色愁将夕，离人欲断魂。","云深知积水，烟淡识孤村。","钓艇遥相并，沙鸥故不喧。","忽思携稚子，踏雪过南园。"]},{"t":"送罗尚德之赣州","f":"五言律诗","c":["此日垂杨树，维舟惜远行。","水生羊角渡，春尽虎头城。","学律宁无术，飞书早有声。","十年趋幕府，憔悴愧高情。"]},{"t":"五日池亭燕集","f":"五言律诗","c":["草阁飞雨集，高人清宴同。","壶觞且终日，襌袷已惊风。","客舍清林下，故园芳草中。","榴花亦何好，烂漫向人红。"]},{"t":"斋前青蒿特盛或请薅除之惜其生意森蔚青翠可玩也谩赋一首","f":"五言律诗","c":["向来谁种汝，入夏总青青。","幸不妨禾稼，犹能映户庭。","惊风萦乱蝶，微雨下流萤。","自是幽栖物，随时任悴零。"]},{"t":"复酌呈郑同夫是夕宿李舍","f":"五言律诗","c":["复酌临清夜，幽怀故不群。","高林风鹊定，暗壁露蛩闻。","把烛嗔残炬，移尊惜半醺。","不眠看月上，松桧白纷纷。"]},{"t":"对月","f":"五言律诗","c":["海月三更白，江风七月寒。","久知行客惯，强作故园看。","菜疃依壖辟，茆亭傍水安。","萧条南戍里，独自戴儒冠。"]},{"t":"寄旷伯逵","f":"五言律诗","c":["一月三寄书，故人湖上居。","浮沈知不定，报答竟何如。","杨柳清风弱，蒹葭白露疏。","槎头秋水落，谁钓九江鱼。"]},{"t":"题山水画","f":"五言律诗","c":["旅游常见画，偏爱浙江山。","日上云霞动，天清紫翠閒。","秋林时自落，春雁不知还。","隐者茆庐好，何年此扣关。"]},{"t":"十一月二十八日晚予与赵伯友登舟将归既夜舟未开忽将军送诗至舟次则刘侯惜别之作因与伯友奉和一章以答其意","f":"五言律诗","c":["放船惊雨过，下马报诗成。","不拟当深夜，犹能念别情。","梦随书帐远，寒入缊袍轻。","明发辞滩口，乘危敢计程。"]},{"t":"赠陈野仙相士","f":"五言律诗","c":["旅怀仍病酒，那有好容颜。","感子远来意，罢书相对閒。","风澄梅涧水，雨过石华山。","惆怅昔贤远，修名谁可攀。"]},{"t":"宁都曾三省自京师得危应奉为作其先人埋铭一通归以示予敬题其后","f":"五言律诗","c":["寂寂先人宅，煌煌太史铭。","飞霜中夜白，宿草隔年青。","未试干时策，空传相地经。","伤心行役者，万里哭苍冥。"]},{"t":"送别高安黄宰","f":"五言律诗","c":["春日宾曹盛，骊歌发县关。","眼看朱绂去，心折画辕攀。","垄麦连云细，江花过雨斑。","筠阳真大郡，犹迟一年还。"]},{"t":"赠蓝山赵教谕","f":"五言律诗","c":["闻说蓝山县，宫墀暗薜萝。","频年虞盗寇，长日罢弦歌。","使者先驰檄，诸生暂负戈。","终然陈俎豆，失喜问如何。"]},{"t":"题平洲小景图","f":"五言律诗","c":["锦水西流远，沧洲逸兴长。","晚晴杨柳暗，春雨杜蘅香。","沙渚通凫鹤，江潭集鱮鲂。","几时携短棹，载酒问茆堂。"]},{"t":"近闻三首 其一","f":"五言律诗","c":["近闻河上卒，掘地未通流。","何以酬饥渴，终然起怨雠。","干戈应满地，畚锸漫成丘。","禹迹谁能复，悠悠远大谋。"]},{"t":"近闻三首 其二","f":"五言律诗","c":["近闻淮海地，寇盗各纵横。","城邑传新破，舟车绝远行。","朝廷初问将，阃府渐移兵。","思见欃枪息，秋来江汉清。"]},{"t":"近闻三首 其三","f":"五言律诗","c":["近闻杨主簿，翰墨上京都。","徵责缘新令，驰驱戒远途。","炎蒸犹未濯，寇盗若为虞。","即此伤多难，山林未可迂。"]},{"t":"奉和崔州判仁卿山长克诚夏日同游开善寺","f":"五言律诗","c":["路转溪仍合，沙平水屡侵。","放船思极浦，下马得高林。","却望烟霞色，微闻钟磬音。","虚堂白日静，于此见初心。"]},{"t":"李知事廉辅得奇石如雪因命名雪石","f":"五言律诗","c":["西岭千秋白，山阴六月寒。","终然天外远，宜尔座中看。","映日光相射，含云气独完。","惟馀苔藓色，彷佛似青峦。"]},{"t":"送邹明道归吉水","f":"五言律诗","c":["令尹方兴学，先生乃赋归。","清秋辞俎豆，白首望庭闱。","云薄千峰出，江深一雁飞。","溶溶墨潭日，偏照老莱衣。"]},{"t":"感赋七首 其一","f":"五言律诗","c":["闪闪一星赤，西林夜色高。","乾坤自空阔，景物故萧骚。","庭迥栖凉叶，门深翳雨蒿。","狐狸浑不见，竟夕向人嘷。"]},{"t":"感赋七首 其二","f":"五言律诗","c":["中郡秋防寇，边亭夜筑关。","遥闻大军出，定向几时还。","粟仰南船运，弓从北骑弯。","侵寻寒落景，何处问溪山。"]},{"t":"感赋七首 其三","f":"五言律诗","c":["岛屿通群盗，风尘动六州。","苍茫淮海暮，摇落楚荆秋。","城垒从堕废，弓刀竟隐收。","向来经国意，徒重腐儒忧。"]},{"t":"感赋七首 其四","f":"五言律诗","c":["传闻南寇盛，惯捷海中船。","兵甲今如此，风涛正渺然。","鱼龙秋气外，貔虎暮云边。","自倚皇威震，谁为赤子怜。"]},{"t":"感赋七首 其五","f":"五言律诗","c":["壮士今忘战，愚民乃弄兵。","风霜工杀戮，雨露惜生成。","未扫屯云蚁，犹遗拔海鲸。","闾阎思倚伏，回首歘心惊。"]},{"t":"感赋七首 其六","f":"五言律诗","c":["白发前朝叟，偏伤丧乱频。","泣逢南上卒，惊问北来人。","老大心情异，艰危世变新。","眼前怜稚子，萧飒向风尘。"]},{"t":"感赋七首 其七","f":"五言律诗","c":["飞檄时时急，防边事事虞。","度关频阅验，鸣柝递传呼。","干羽终来格，豺狼得尽诛。","皇恩自远溢，何以慰民痡。"]},{"t":"九月九日将赴豫章夜发瑞州城下二首 其一","f":"五言律诗","c":["天末云霞暝，城隅烟水深。","维舟呼不见，渔火坐相侵。","夜下芙蓉渚，秋高橘子林。","不眠催解缆，鸣柝正沈沈。"]},{"t":"九月九日将赴豫章夜发瑞州城下二首 其二","f":"五言律诗","c":["未卜西昌返，还寻南浦行。","清秋千里外，永夜一舟轻。","风急高河动，星浮积水明。","苍苍江雾合，起坐怅心惊。"]},{"t":"过松湖闻熊氏往时有花圃特盛","f":"五言律诗","c":["寂历松湖市，人家际水烟。","平沙皆种树，枯港不通船。","旧隐真堪托，名园已盛传。","青春花竹丽，载酒定何年。"]},{"t":"过郑氏隐居承二子之纯之纪留宿赋赠一首","f":"五言律诗","c":["流水西山麓，层轩夏木凉。","昔闻书带草，今过郑公乡。","展席传诗帙，张灯列酒浆。","佳儿真好客，倾倒意何长。"]},{"t":"寓铁柱怡真堂柬左德昭","f":"五言律诗","c":["自有幽栖志，长嫌俗境喧。","喜寻高士宅，得共故人论。","古井波围柱，深檐石作垣。","焚香足危坐，清咏五千言。"]},{"t":"题隐皋亭","f":"五言律诗","c":["晚树连虚壁，秋花隐画檐。","林交风瑟瑟，池迥雨纤纤。","把酒频移席，翻书欲近帘。","由来有真趣，出处若为兼。"]},{"t":"早泊蓼洲时徵乃颜将军赴淮夜捉送途者","f":"五言律诗","c":["微火明高碛，危樯倚近城。","舟人惊暝窜，戎卒问晨征。","牢落闻鸡犬，喧呼度甲兵。","江淮方警急，行客倍含情。"]},{"t":"送尧举监税赴进贤","f":"五言律诗","c":["送尔司征去，江干秋雨馀。","由来设关市，不在算舟车。","客路通城邑，人烟集里墟。","西风摇落近，回首独踟躇。"]},{"t":"送友人之赣州司幕","f":"五言律诗","c":["江合城楼迥，秋高幕府清。","之官宁惮远，论法正须平。","寒濑鸣砂浅，晴岚隐石横。","凄凉为客处，浩荡送君情。"]},{"t":"归次杨林","f":"五言律诗","c":["汀树重重转，江船稍稍移。","浅沙惊欲荡，逆浪故相欺。","风起占鸦浴，云飞信马蹄。","凤山明月好，应怪客归迟。"]},{"t":"题空翠楼为东山湛上人赋","f":"五言律诗","c":["碧嶂飞甍合，青林画栱高。","晴天引苍翠，凉月见纤毫。","木榻飘金磬，春壶净玉醪。","东山有支遁，临眺使心劳。"]},{"t":"春山伐木图","f":"五言律诗","c":["伐木春山里，千峰复万峰。","蛟龙回别涧，麋鹿引行踪。","风落崇冈桂，云开绝壁松。","怀人咏鸣鸟，欲往愧无从。"]},{"t":"题山水画二首 其一","f":"五言律诗","c":["远树层层出，高崖面面开。","谷深云欲动，江白雨初来。","楚佩遗仙浦，吴航近钓台。","故人浑不见，秋暮思悠哉。"]},{"t":"题山水画二首 其二","f":"五言律诗","c":["绝壁芙蓉秀，悬崖薜荔高。","天清闻夕籁，木落见秋毫。","仙赏谁能继，荣名自可逃。","时来倚图画，怅尔渺烟涛。"]},{"t":"寄赠翠岩泰上人","f":"五言律诗","c":["兰若倚西冈，年深松桂长。","似闻葛洪井，还近赞公房。","挂衲云林净，翻经石榻凉。","下方一回首，烟雾日苍苍。"]},{"t":"旅夕","f":"五言律诗","c":["乡梦灯初破，寒窗雨渐疏。","已愁秋向夕，况苦雁无书。","异郡危新战，沧江倚旧庐。","老亲应散疾，藜杖到阶除。"]},{"t":"十月","f":"五言律诗","c":["十月惊雷动，千林急雨来。","民情欣利泽，春令恐为灾。","暄日犹催杏，清霜不杀荄。","王师渡淮浦，定遣几时回。"]},{"t":"南溪","f":"五言律诗","c":["溪树绿阴阴，林居夏向深。","青山谢朓宅，流水伯牙琴。","采药怀孤往，看花惜共吟。","北岩如可问，于此息尘心。"]},{"t":"题松下行吟图","f":"五言律诗","c":["松下行吟者，翛然不可呼。","影临秋水迥，兴与暮云孤。","石角栖书帙，花阴散酒壶。","青山招隐去，应是笑泥涂。"]},{"t":"题萧伯高西冈读书处在唐杜审言故居之右","f":"五言律诗","c":["萧子读书处，昔年曾一过。","郭外西原好，门前修竹多。","雪深犹独卧，日晏亦高歌。","况近参军宅，清明奈尔何。"]},{"t":"定上人屡约游山不果近承寄示送孙景贤诗未及和答因刘进士仲炯游青原山赋此奉寄 其一","f":"五言律诗","c":["孙宰游山日，僧房赋别时。","有诗还念我，何处定逢师。","云甃虫书叶，霜林鹤满枝。","来游知不厌，空负数幽期。"]},{"t":"定上人屡约游山不果近承寄示送孙景贤诗未及和答因刘进士仲炯游青原山赋此奉寄 其二","f":"五言律诗","c":["送客青原路，思君白下城。","雨花曾听法，贝叶旧知名。","学道耽幽趣，忧时累俗情。","莲峰几百丈，霜月想泉声。"]},{"t":"宿东山下","f":"五言律诗","c":["夜宿东山下，人家隔板桥。","泉声霜下起，雾气月中飘。","芋子兼皮煮，松枝带节烧。","老翁年九十，起坐说前朝。"]},{"t":"送李掾还吉水","f":"五言律诗","c":["霜草马蹄寒，晨趋别上官。","吏推文牍简，民忆会期宽。","水浅鱼梁出，沙晴雁碛乾。","青云冠盖盛，似尔惜才难。"]},{"t":"和答杨公平题具翕堂","f":"五言律诗","c":["故里荒芜地，新堂燕鹊群。","昔人如昨日，此意向谁论。","樽酒欣时具，歌诗惜夜分。","雄文兼雅韵，感激愧诸昆。"]},{"t":"令公岩送钟庭亨归兴国","f":"五言律诗","c":["令公读书处，归去又残冬。","潭冷鱼依石，岩深鹤护松。","穿云穷望眼，踏雪记行踪。","明日平川道，相思隔万峰。"]},{"t":"溪上","f":"五言律诗","c":["渡溪日已暮，回首见青峰。","风起岩前树，霞明天际松。","佳人期未果，幽径偶相逢。","语语投寒暝，孤村起夕舂。"]},{"t":"游临溪寺和钟学正韵","f":"五言律诗","c":["涧束西流水，门临北向山。","渡桥惊鸟散，扫石爱僧閒。","雾薄林花紫，春深石笋斑。","云峰如可问，杖策未须还。"]},{"t":"承郭奉奎夜过溪上言北岩杜鹃花盛开手数枝相赠明日赋此为别","f":"五言律诗","c":["故人夜相赠，手折杜鹃花。","掩冉带华月，参差出绛霞。","来从仙岭路，分赠野人家。","我有游山兴，因之起叹嗟。"]},{"t":"廖伯容自南溪别余将栖于武山之云峰寺明日寄此","f":"五言律诗","c":["子爱云峰寺，幽栖得自便。","朝吟还对石，夜坐更听泉。","久住应忘客，无言或近禅。","时时采药去，长啸白云边。"]},{"t":"夏旱","f":"五言律诗","c":["五月那无雨，今年岂有秋。","伤时思乏食，失路竟还忧。","圭璧闻周祀，尪巫笑野谋。","亦怜生事拙，不见满瓯窭。"]},{"t":"看雨","f":"五言律诗","c":["惨淡连遥岭，萧条入近林。","随风初作势，度水忽成阴。","垄穗占新沐，池荷掩旧沈。","西楼濯冰雪，暂尔豁烦襟。"]},{"t":"挽钟谨独先生","f":"五言律诗","c":["挥泪过东门，怀哉德义尊。","新阡哀榇出，旧屋古书存。","修竹仍深巷，幽花自小园。","儒林有知己，好在立真言。"]},{"t":"谷云","f":"五言律诗","c":["冉冉复离离，秋云出谷时。","偶然随雨散，忽谩被风吹。","岩润龙先觉，林阴鹤未知。","何人为招隐，吟断小山诗。"]},{"t":"山茶","f":"五言律诗","c":["闻说真常观，山茶兀老苍。","根盘千古盛，干拔五枝长。","翠羽团秋色，丹砂注夜光。","神仙谁种此，又见海成桑。"]},{"t":"仙竹","f":"五言律诗","c":["坛上竹珊珊，秋风六七竿。","至今含雨色，长夏拂云寒。","神女金丝佩，仙翁锦箨冠。","建标应有待，曾此下青鸾。"]},{"t":"石仙","f":"五言律诗","c":["仙子何年化，空馀石像存。","沈沦时已异，坚朴道弥尊。","云舄飞难去，风裾冷不翻。","何如致云雨，从此洗乾坤。"]},{"t":"牡丹","f":"五言律诗","c":["千叶鹤翎红，仙姿自不同。","名传李唐后，根托帝坛中。","霞佩分王母，金盘送玉童。","异香留不得，长是逐天风。"]},{"t":"题溪南幽异图","f":"五言律诗","c":["谁写溪南景，幽深隔翠微。","钓船沙际出，杨柳雨中稀。","倚竹翻书坐，穿花载酒归。","故人浑不至，苔色满林扉。"]},{"t":"十九日至二十二日雪作不止客有言是雪十馀年不见者固可喜也因赋五言一律","f":"五言律诗","c":["莽莽初横野，涔涔忽满城。","低迷浑欲暗，空阔固能明。","积水蛟鼍伏，荒山鸟雀惊。","十年愁不见，北望正含情。"]},{"t":"雪中会饮分韵得花字","f":"五言律诗","c":["洗盏注晴霞，张灯散暮鸦。","残年今夕会，远道故人家。","春入山中树，雪吹天上花。","当筵有长袖，醉舞看欹斜。"]},{"t":"山矾","f":"五言律诗","c":["本自托山谷，年年春暮开。","野人不爱惜，折送满城来。","皓雪千枝积，香风十里回。","故人坟上路，见尔独兴哀。"]},{"t":"渡江","f":"五言律诗","c":["莽莽出轻艘，纷纷竟渡江。","天宁残乐土，人欲愤遗邦。","豺虎方雄斗，蛟龙正怒撞。","南村愁岌岌，何处望旌幢。"]},{"t":"兵破江口途趋东原挈妻子入山道次相失复聚","f":"五言律诗","c":["仓卒还相失，艰危独后来。","乱山当日暮，长路入风埃。","攘攘从谁问，沈沈只自摧。","逢迎忽惊喜，相顾歘兴哀。"]},{"t":"寻人家至石岭下冲雨入大村夜宿罗坑","f":"五言律诗","c":["石岭重攀跻，罗坑及暝栖。","不辞冲暮雨，政恐踏秋泥。","亲老愁多病，儿痴睡更啼。","艰虞戒前路，不敢候鸣鸡。"]},{"t":"午憩石鼓坑严复亨寓舍问米过灌塘寻康氏姊","f":"五言律诗","c":["书在馀三策，钱空罄一囊。","问人求食米，随客度山庄。","影怯飞鸿后，啼惊猛虎旁。","远寻康氏姊，感激意何长。"]},{"t":"忆故庐消息","f":"五言律诗","c":["故里何人到，野堂今是非。","毁伤宁壁立，焚荡恐灰飞。","书帙从人把，囊琴只谩挥。","谁怜失巢者，飘散欲何依。"]},{"t":"秋旱井涸致水为劳有浚而得泉者喜而赋诗","f":"五言律诗","c":["井涸仍秋旱，徒劳抱瓮人。","偶缘淘得净，但讶汲伤频。","欹石盘根古，寒泉积渫新。","渴心端赖尔，回首飒风尘。"]},{"t":"南岳祠前古松","f":"五言律诗","c":["偃蹇何年种，青苍暮色酣。","半身犹直上，全势欲倾南。","古壁龙鳞合，空巢鹤影参。","岁寒终见尔，霜雪老能堪。"]},{"t":"出社下岭望九洲流陂稻田可爱","f":"五言律诗","c":["渡岭望平田，人家隐翠烟。","村墟自鸡犬，风物似神仙。","晚树依沙立，秋粳带水眠。","几时驱两犊，投迹此安廛。"]},{"t":"初游长兴寺","f":"古风","c":["一路萦纡入，群峰迤?开。","树连山路合，溪带石桥回。","烟火依农屋，云霞隐佛台。","如何千载下，不见一人来。"]},{"t":"入百记望王岭诸峰","f":"五言律诗","c":["何许龙移宅，犹传鹤驻骖。","山连王子洞，水落圣官潭。","结屋蟠虚壁，烧畬上翠岚。","十年厌奔走，吾意托东南。"]},{"t":"山中","f":"五言律诗","c":["岂有人知处，白云连上层。","入深疑遇虎，爱净欲依僧。","风磴鸣樵斧，岩烟翳佛灯。","如何江浦上，杀气苦凭陵。"]},{"t":"蒲涧奉次长兄子中韵","f":"五言律诗","c":["蒲涧来何处，鸣声应谷虚。","清宜和野饭，翠可织仙裾。","陇近秋常灌，潭空夜不渔。","毋令洗尘耳，吾意恋溪居。"]},{"t":"再游蒲涧与子中子彦题名于涧右之嵌壁因赋诗而归","f":"五言律诗","c":["自扫涧边叶，閒通石上泉。","绿蒲向深处，幽响忽琤然。","题字扪青壁，长歌入紫烟。","日长山更静，来此弄潺湲。"]},{"t":"观蜜房","f":"五言律诗","c":["戴主心无二，趋朝度必三。","一衙兵卫肃，万鼓战声酣。","事夥还分济，功成始共甘。","伊谁失维系，荡荡纵残贪。"]},{"t":"九月三日由长坑入南山寺将过里良暂憩合龙寺闻饶兵已逼新安二日矣","f":"五言律诗","c":["三宿那容恋，孤征自可惊。","已闻虎穴斗，复道鸟巢倾。","战鼓寒初急，烽烟晚更明。","问程投野寺，日暮最含情。"]},{"t":"至里良之明日闻抄兵已入长兴因赋以自慰","f":"五言律诗","c":["谁遣飘然去，真成率尔来。","吾宁工避地，天似解怜才。","行李从萧瑟，飘蓬任转回。","时时看短剑，心折未全灰。"]},{"t":"感事五首 其一","f":"五言律诗","c":["已闻新安破，复道富田围。","力抗犹隳逐，全收果是非。","主将婴城急，居民在野稀。","徒劳淦水上，羽檄夜频飞。"]},{"t":"感事五首 其二","f":"五言律诗","c":["兵老匡山北，师移赣水滨。","一行宁助桀，三户或亡秦。","气压长蛇阵，魂消战马尘。","纷纷犹杀掠，谁与吊遗民。"]},{"t":"感事五首 其三","f":"五言律诗","c":["闻说虔兵下，前茅次九洲。","一烽深照夜，群马飒惊秋。","劲气方全蓄，沉机岂共谋。","似传终左次，失喜敢忘忧。"]},{"t":"感事五首 其四","f":"五言律诗","c":["主将何时出，行人此日归。","退盟惊左次，迎附识先机。","四野何烦掠，孤城不再围。","文山青万丈，回首一沾衣。"]},{"t":"感事五首 其五","f":"五言律诗","c":["义战今谁有，完师众所安。","从容隳巀嵲，谈笑却凶残。","攘攘持牛酒，纷纷跃马鞍。","东南馀赤地，万一慰饥寒。"]},{"t":"得舅氏消息","f":"五言律诗","c":["亲戚今谁在，兵戈卒未休。","忽传消息异，徒重别离忧。","老大原多病，飘零谁见收。","依依梦中路，泪洒石江头。"]},{"t":"雨坐下郛田舍阅案上道书","f":"五言律诗","c":["临涧一茆亭，连山万竹青。","微风閒听鸟，细雨坐看经。","愤极思吴剑，饥来忆楚萍。","野人能好客，犹足慰飘零。"]},{"t":"晚兴次圭上人韵","f":"五言律诗","c":["何地可幽寻，南方多翠岑。","水流村涧远，树拥石门深。","事感升沉迹，愁牵去住心。","终然恋禅寂，十日坐林阴。"]},{"t":"离里良别寺僧则师","f":"五言律诗","c":["羁旅谙空寂，高秋感去留。","谁能弃妻子，世已换王侯。","故里肠朝断，荒山血夜流。","敢违桑下戒，誓作海东游。"]},{"t":"闻江上兵退挈家稍出村至三坳岭适从弟懋和亦自蓝田陂归同门久离喜遂复聚","f":"五言律诗","c":["即返非吾计，相逢幸汝归。","山中茅屋在，江上故园非。","泪应啼猿落，心随断雁飞。","十年伤骨肉，飘散复相依。"]},{"t":"悼女侄端","f":"五言律诗","c":["已谓生还遂，谁知死病仇。","畏途携共远，故室返无由。","弄果啼时掷，遗䙀葬后收。","重泉应见母，汝父正多忧。"]},{"t":"谢李克贞送盐","f":"五言律诗","c":["食淡怜吾病，分盐感子情。","解苞惊落雪，进饭惜含英。","远道枫初陨，閒门草屡生。","艰难愧滋味，幽兴在藜羹。"]},{"t":"遭乱","f":"五言律诗","c":["遭乱无完物，还家有病躯。","夜眠愁枕席，晚食愧盘盂。","败壁狐狸入，虚檐鸟雀呼。","犹传征敛急，倚杖一长吁。"]},{"t":"食无菜","f":"五言律诗","c":["岂有膏粱想，仍无食菜缘。","馑荒宁绝物，枯旱已经年。","青忆冰盘送，香怀雪椀传。","喜闻春意动，荠麦满山田。"]},{"t":"闻赣兵已驻万安","f":"五言律诗","c":["自有重滩险，还屯外邑兵。","江春舟楫便，城晚旆旌明。","蚁聚方连势，鲸吞竟败盟。","悠悠岐路叹，万一慰民情。"]},{"t":"社日","f":"五言律诗","c":["社日那无酒，时危不见春。","闭门防过卒，烧纸赛田神。","已叹耕锄废，终伤杀掠频。","鸡豚久萧索，未敢怨风尘。"]},{"t":"重游长兴寺","f":"五言律诗","c":["重到长兴寺，青山四面同。","鸟啼花竹暗，人散户庭空。","蒲涧千年雨，松门午夜风。","旧游悲往日，回首各西东。"]},{"t":"哭元卿","f":"五言律诗","c":["南郡连烽火，连皋掩素扉。","犹闻避地去，不见渡江归。","家废藏书散，山深吊客稀。","同庚几人在，空遣泪沾衣。"]},{"t":"哭韦缵","f":"五言律诗","c":["一死嗟谁托，馀生苦自怜。","已悲形吊影，竟觉夜如年。","野哭沉山月，新坟閟陇烟。","杳无重见日，徒有泪潸然。"]},{"t":"刘氏西楼小集和吕仲善韵","f":"五言律诗","c":["清风缘幔起，疏雨傍城过。","酒急禁愁得，楼高奈暑何。","卷书思共隐，学剑愧殊科。","且可捐秋佩，无劳问晓珂。"]},{"t":"重过梁塘访郭与恭","f":"五言律诗","c":["一水鸣苍峡，千峰引白云。","时危还作客，岁晏却寻君。","事往诗仍在，愁来酒易醺。","野桥寒日下，霜雁远初闻。"]},{"t":"题彭伯圻芹寓","f":"五言律诗","c":["采采芳芹去，溶溶泮水滨。","长歌心不厌，偶寓迹非真。","吾道伤羁旅，乡山落战尘。","十年戎马际，独立见斯人。"]},{"t":"闻鹧鸪","f":"五言律诗","c":["尔本越中鸟，何年来此啼。","羽毛浑自媚，言语使人迷。","隐隐穿松障，萧萧渡竹溪。","断肠听不得，归路日平西。"]},{"t":"题刘诚本为子彦弟作山水图","f":"五言律诗","c":["画者有远意，寓之山水间。","野航当晚急，江阁与秋閒。","嘉树团丹壑，幽花照绿湾。","何年谢尘鞅，杖策此中还。"]},{"t":"由雀儿岭入阆川青梁尾 其一","f":"五言律诗","c":["历险非吾意，临危信此生。","一家微命在，百里畏途轻。","草屋怜蜂聚，松崖愧蚁行。","喧喧豺虎急，向晚慎前征。"]},{"t":"由雀儿岭入阆川青梁尾 其二","f":"五言律诗","c":["路折千湾水，天垂四面山。","野人初问战，过客乍投关。","地僻烧畬遍，溪深采葛閒。","时时听鼙鼓，怅望不知还。"]},{"t":"夜渡溪水见月忆流江诸友","f":"五言律诗","c":["片月出东岭，野禽相应啼。","归人爱清景，乱月渡平溪。","草露忽已集，洞霞犹未隮。","流江向西远，归梦使人迷。"]},{"t":"对月","f":"五言律诗","c":["今年十五夜，看月在流江。","谁遣遗乡邑，犹疑接澒泷。","水光浮战舰，山翠隐蓬窗。","倾影那能寂，含悽对酒缸。"]},{"t":"尝山药","f":"五言律诗","c":["谁种山中玉，修圆故自匀。","野人寻得惯，带雨斸来新。","味益丹田暖，香凝石髓春。","商芝亦何事，空负白头人。"]},{"t":"山楼即事","f":"五言律诗","c":["楼出青峰上，檐栖碧树端。","雨窗晨易白，云榻夜多寒。","微醉时欹枕，閒愁独倚栏。","纷纷犹战夺，托迹敢求安。"]},{"t":"寄萧翀","f":"五言律诗","c":["九十九顿岭，归来又几时。","时危愁不见，岁晏最相思。","天远惊鸿断，山空病鹤饥。","长怀霜月夜，一笛向人吹。"]},{"t":"奉次吴县丞兵后见寄韵","f":"五言律诗","c":["长愁怜杜子，多病愧相如。","避地风尘里，还家瘴疠馀。","春随南国雁，书滞北溟鱼。","故里劳相问，于今未定居。"]},{"t":"夜晏次王伯衢","f":"五言律诗","c":["王氏多才彦，青云玉树林。","金尊瑶席满，银烛画堂深。","风雨残年梦，江湖千里心。","感君情似海，欲醉且停斟。"]},{"t":"宣溪饯李提举一初席中和王子让韵","f":"五言律诗","c":["客有东归思，维舟向浦桥。","江声翻石面，云气拥岩腰。","怅饮淹泥潦，归程问野樵。","骊歌莫催发，晴景在明朝。"]},{"t":"西岭","f":"五言律诗","c":["西岭往来疏，茆茨散漫居。","月明人逐虎，水暗獭偷鱼。","万木风霜里，千村战伐馀。","昔年桑柘地，鸡犬满村墟。"]},{"t":"和萧汉高归省水东","f":"五言律诗","c":["雪意满乡山，宁亲复此还。","腊前见梅蕊，江上候柴关。","入馔鲜鱼白，升堂舞袖斑。","别君增永感，飘泊愧愁颜。"]},{"t":"双溪","f":"五言律诗","c":["春风西岭下，表里爱双溪。","江雨时时落，山禽夜夜啼。","蔷薇花欲乱，榉柳叶初齐。","南陌谁相问，愁来路欲迷。"]},{"t":"四月苦雨次郭吟翁","f":"五言律诗","c":["羃羃云粘水，厌厌雨断林。","千山尚寒色，四月更春阴。","望怯舟航绝，居愁井灶沉。","如何开霁景，空有济时心。"]},{"t":"九月一日泛舟赴上麓拟简刘子琚","f":"五言律诗","c":["初日轻舟发，高秋访友行。","云沙低石浦，风露满山城。","物外看豪俊，尊前忆老成。","菊花应共把，还得慰高情。"]},{"t":"过仙女钓台石","f":"五言律诗","c":["仙女一片石，九郎江水边。","何年此持钓，遗迹尚依然。","绿发明秋渚，长竿拂紫烟。","仙期如可托，引手接飞軿。"]},{"t":"郎湖","f":"五言律诗","c":["何年秋望远，落日晓妆新。","垂钓闻仙女，回舟见石人。","青烟松嶂晚，红叶柿林春。","独觉容华变，空伤羁旅频。"]},{"t":"见有畜鹚?于庭者因赋一首","f":"五言律诗","c":["自有云霄迹，那虞罗网机。","鸣声犹自厉，羽翮未全挥。","槛逼回翔窄，庭荒啄食稀。","低头羞燕雀，容易往来飞。"]},{"t":"家犬为虎所毙诗以致悼","f":"五言律诗","c":["闻说于蒐横，群行不畏驱。","公然入江市，半夜取韩卢。","委肉怜轻敌，防奸忆应呼。","忠良死残暴，悲恨若为图。"]},{"t":"闻子规","f":"五言律诗","c":["羽族尔无奇，南飞怨别离。","殷勤如向我，漂泊定依谁。","绝岸云深处，空林月落时。","到今车马客，穰穰不曾知。"]},{"t":"酬友人见问","f":"五言律诗","c":["野人初识面，旧友渐忘名。","长日惟窥圃，经年不到城。","借书山路远，洗药石泉清。","近喜林间鸟，相看故不惊。"]},{"t":"咏金鸭炉","f":"五言律诗","c":["铸得黄金鸭，焚兰伴夕眠。","中心灰未得，煖火自生烟。","独立思浮海，双飞欲上天。","那能长拂郁，吐出向君前。"]},{"t":"送吴太守之韶阳 其一","f":"五言律诗","c":["已报新移郡，犹闻不下堂。","买舟辞快阁，度岭问韶阳。","晚驿江云白，寒潮海日黄。","使君行五马，南徼有辉光。"]},{"t":"送吴太守之韶阳 其二","f":"五言律诗","c":["白下东门柳，当年手种成。","行行当别路，叶叶是离情。","解缆惊秋雨，扬镳送晚晴。","春风榕馆静，好在听啼莺。"]},{"t":"水精葱","f":"五言律诗","c":["芳烈齐山茗，清名重水精。","生成推土物，誇大著乡评。","鸣齿冰丸脆，通神雪汁清。","茗瓯端有助，疏浅愧吾生。"]},{"t":"忆平原","f":"五言律诗","c":["在昔提携惯，于今学语喧。","未能觅邻果，已解到盘飧。","岁弱怜吾老，时危幸汝存。","谁从托诗礼，亦欲信乾坤。"]},{"t":"哭胡思齐","f":"五言律诗","c":["野战日纷纷，飘零最念君。","故园知不返，客路竟长分。","道士来看病，邻人为起坟。","百年精爽在，应化武山云。"]},{"t":"忆萧一诚","f":"五言律诗","c":["万里潮阳道，经年独尔思。","海边为客久，兵后到家迟。","恋阙心犹割，伤时发欲丝。","荆南非旧日，剩赋七哀诗。"]},{"t":"赠黄孝子庭端","f":"五言律诗","c":["南陔嗟久废，素韠幸犹存。","风变干戈际，人称孝友门。","云山藏旧宅，烟草翳寒原。","谁续黄香传，当为薄俗敦。"]},{"t":"荅龙北池求诗","f":"五言律诗","c":["古剑千金得，还丹九转成。","天宁轻至宝，人苦累虚名。","避俗聊栽菊，锄荒欲刈荆。","诗来问题墨，展转愧高情。"]},{"t":"寒日","f":"五言律诗","c":["寒日闭门早，荒村落木齐。","昆虫霜后蛰，豺虎草间啼。","碧海终难涉，青云未可梯。","鹿门早晚去，妻子定相携。"]},{"t":"寄青原福上人","f":"五言律诗","c":["闻说靖居寺，莲花峰最奇。","几年增怅望，何日是来时。","晓刹蟠丹壁，春泉注玉墀。","塔前荆树好，应长向南枝。"]},{"t":"九日雨离流江","f":"五言律诗","c":["何意今朝雨，偏伤远客情。","黄花低径湿，白鸟渡江轻。","吾道成漂泊，天机戒满盈。","林居有馀地，聊欲任浮生。"]},{"t":"咏早禾溪水","f":"五言律诗","c":["闻有王相洞，龙潭决石开。","远从高碛下，尽绕乱山来。","续续筒车灌，喧喧桨筏催。","海门如可到，东赴敢迟回。"]},{"t":"夜宿东原同子彦弟食楂梨示侄觯","f":"五言律诗","c":["东原山馆夜，灯下食楂梨。","共看团圆子，因怀连理枝。","轩昂怜汝大，辛苦愧吾痴。","历历嬉游事，于今鬓欲丝。"]},{"t":"览镜","f":"五言律诗","c":["颇恨青铜镜，能添白发丝。","不知岁年换，犹忆丱童时。","戎马惊尘暗，风波惜世危。","仙山有灵药，老去欲谁师。"]},{"t":"遇邻人道旧","f":"五言律诗","c":["废井生新草，荒村失旧邻。","独行迷远道，相见益酸辛。","逐戍馀千里，还家止一身。","终然未可住，投杖飒沾巾。"]},{"t":"题楚地山川图","f":"五言律诗","c":["落日二妃浦，青天五老峰。","莲华深郁郁，草色净溶溶。","去雁低寒树，归人带暝松。","向来水西寺，欲往似闻钟。"]},{"t":"南溪山上赏月","f":"五言律诗","c":["凉露经秋白，华筵向夕开。","笛声山上起，月色海边来。","花隐千峰合，松排一径回。","直愁星汉曙，莫遣醉歌催。"]},{"t":"至日","f":"五言律诗","c":["为客何时了，迎长此日同。","江湖战伐里，岁月往来中。","雁断沾沙雨，虫鸣落叶风。","书云从太史，曝日且南翁。"]},{"t":"秋怀七首 其一","f":"五言律诗","c":["百里渔樵外，频年战斗馀。","感时聊作客，乘兴即安居。","碧涧横松几，青林映竹书。","避人吾岂敢，乐性此何如。"]},{"t":"秋怀七首 其二","f":"五言律诗","c":["大村江忽转，西岭路俱迷。","山木阴阴合，沙橖冉冉齐。","鱼潜知旧穴，虎迹见新泥。","此日荆榛里，何年桃李蹊。"]},{"t":"秋怀七首 其三","f":"五言律诗","c":["日下田田草，霜馀岸岸沙。","江喧闻激硙，烟白望烧畬。","耕凿宁无术，徵科苦未涯。","吾宁甘食蕨，子莫恋栽茶。"]},{"t":"秋怀七首 其四","f":"五言律诗","c":["羁愁长少睡，墟落自多虞。","里布晨输税，江船夜送徒。","曙星寒共照，野鸟暗相呼。","王事谁能却，年华浩欲徂。"]},{"t":"秋怀七首 其五","f":"五言律诗","c":["溪筏乘流驶，山棚隐石高。","树交藤共络，峡转浪争号。","夜雨洗山骨，秋霜落涧毛。","桃源如可问，蓬海径须邀。"]},{"t":"秋怀七首 其六","f":"五言律诗","c":["把卷临溪溜，开帷俯石林。","浮烟通市白，斜日半庭阴。","卉服频催裂，松醪暂废斟。","孤怀伤断梗，寒影愧栖禽。"]},{"t":"秋怀七首 其七","f":"五言律诗","c":["石壁湖边路，蒲田江口村。","乱馀通草市，愁破忆柴门。","屐许邻翁借，书怜稚子翻。","因思两梅树，花发满东园。"]},{"t":"赋壁煤","f":"五言律诗","c":["窗下煮茶久，烟煤半壁生。","君看太玄者，此岂一朝成。","光可敌玈玉，坚疑铸铁城。","未黔嗟孔突，恋恋愧吾情。"]},{"t":"十二月十日晚同吟所郭光辈奉陪溪南隐君与其诸郎群从观舍傍蔬畦仍出山后临眺江上周览林麓追念旧游抚余羁怀益深感慕因赋五言近体六诗柬同游诸君亦以识嘉会也 其一","f":"五言律诗","c":["背岭溪流合，穿林石路高。","连甍依嵽嵲，百堵见周遭。","扫叶看畦韭，搴萝出涧桃。","极知幽兴熟，来往未云劳。"]},{"t":"十二月十日晚同吟所郭光辈奉陪溪南隐君与其诸郎群从观舍傍蔬畦仍出山后临眺江上周览林麓追念旧游抚余羁怀益深感慕因赋五言近体六诗柬同游诸君亦以识嘉会也 其二","f":"五言律诗","c":["林下戏秋千，中流奏管弦。","看花还旧赏，抚树惜流年。","白发金台客，青云玉署贤。","后来文物盛，此事会俱传。"]},{"t":"十二月十日晚同吟所郭光辈奉陪溪南隐君与其诸郎群从观舍傍蔬畦仍出山后临眺江上周览林麓追念旧游抚余羁怀益深感慕因赋五言近体六诗柬同游诸君亦以识嘉会也 其三","f":"五言律诗","c":["古庙依苍麓，穷林俯绿潭。","石台交野祭，画壁拥朝参。","云送千林雨，烟飞隔水岚。","向闻灯火夕，歌吹足沉酣。"]},{"t":"十二月十日晚同吟所郭光辈奉陪溪南隐君与其诸郎群从观舍傍蔬畦仍出山后临眺江上周览林麓追念旧游抚余羁怀益深感慕因赋五言近体六诗柬同游诸君亦以识嘉会也 其四","f":"五言律诗","c":["喜有连云树，仍多近水村。","偶来随杖屦，浑欲托丘樊。","山暝寒初落，滩低水自喧。","终然远城市，何用觅桃源。"]},{"t":"十二月十日晚同吟所郭光辈奉陪溪南隐君与其诸郎群从观舍傍蔬畦仍出山后临眺江上周览林麓追念旧游抚余羁怀益深感慕因赋五言近体六诗柬同游诸君亦以识嘉会也 其五","f":"五言律诗","c":["日落风犹起，江寒鱼正肥。","鸬鹚下水急，舴艋出滩稀。","旅食劳行李，归栖念采薇。","已惊残岁迫，犹恐壮心违。"]},{"t":"十二月十日晚同吟所郭光辈奉陪溪南隐君与其诸郎群从观舍傍蔬畦仍出山后临眺江上周览林麓追念旧游抚余羁怀益深感慕因赋五言近体六诗柬同游诸君亦以识嘉会也 其六","f":"五言律诗","c":["欹树共维楫，高崖可构亭。","沙呈桥外白，山漾水中青。","别洞通仙境，何年閟地灵。","时来及登眺，亦足慰飘零。"]},{"t":"题旷子西山读书图","f":"五言律诗","c":["旷子耽幽僻，西山住五年。","读书秋树下，蹑屐乱峰前。","酒忆邻僧送，诗从野客传。","临图怀往事，丘壑故清妍。"]},{"t":"赠定参政自南海抽分还省三十韵","f":"古风","c":["天堑山河壮，皇图日月开。","鹓鳞登汉阙，玉帛上燕台。","民赋中邦出，蛮艘海外来。","货源恒混混，禁网自恢恢。","粉署参元佐，金闺著彦才。","江湖资保障，台阁挺奇瑰。","凤诏优南徙，鹏风得远培。","节分东广会，春动海南隈。","厉瘴驱山雾，惊潮隐地雷。","水光浮溟涬，宝气出蓬莱。","机杼鲛绡结，楼台蜃气摧。","鲸鲵谢唐突，雕鹗且徘徊。","众水通洪汇，三山据绝垓。","雪舻衔浩淼，云舸驾崔嵬。","错落青鼍甲，弯环紫鳄腮。","珊瑚红的皪，孔雀翠毰毸。","花角裁犀定，明珠割蚌胎。","荔浆翻翠杓，蔗沈冻螺杯。","压轴龙香重，崇箱海错该。","牙筹劳永夜，鞭算积微埃。","市价曾无贰，宽征信有推。","夷商歌岂弟，硐獠慕嬉孩。","河汉张骞入，江淮刘晏回。","几时淹去佩，及此送归桅。","寥落山城暮，微茫水驿洄。","野人瞻衮绣，中使拥鞍{革雋}。","早应云间瑞，行膺日下催。","赏褒增玉秩，迎劳锡琼醅。","禹服终成赋，虞廷可阜财。","明堂抡柱石，元鼎赖盐梅。"]},{"t":"大官供宿膳分韵送友人中书掾","f":"五言古诗","c":["紫閤趋朝夕，彤庭直禁时。","内官调玉馔，中使奉珍奇。","绛节传宣近，雕盘馈食迟。","星河联绣户，云月上芝楣。","夜入华灯转，春随刻漏移。","露晞应待旦，献纳好陈诗。"]},{"t":"挽杨学录安吾先生","f":"五言古诗","c":["遭乱临川郡，归来已二年。","清羸惊病后，哀些落兵前。","刻表新阡出，藏书旧业传。","清心悬夜月，直气掩寒烟。","谷迥松声合，庭虚桂影偏。","修文从阁老，应数仲容贤。"]},{"t":"题刘善初草意亭十二韵","f":"五言古诗","c":["庶草含生意，高人秉性灵。","十全推药物，千古重图经。","畦掩霜芽绀，林团雾叶青。","苍根蟠石罅，柔蔓络岩扃。","煖火时蒸术，长镵亦斲苓。","香浮苏井橘，甘绝楚江萍。","饮圣谙殊味，传奇识异形。","远应探北岳，幽合泛南溟。","辽曼同三岛，芳鲜自一庭。","悬壶花底市，捣臼竹间棂。","瞑眩怀祛疾，从容冀引龄。","早苏民瘵剧，兼慰客愁醒。"]},{"t":"乙巳闰十月十五日闻永新破诸凶就戮无遗喜赋三十二韵","f":"五言古诗","c":["鼓乱雄诸郡，凭凶跨十年。","荆湖延毒雾，汉沔注妖躔。","鸟兽宁殊类，龙蛇自一川。","羽毛初景附，苞蘖忽根连。","掠野时乘间，攻城亦破坚。","践攘蝼蚁甚，累系犬羊然。","里录先锋籍，家亡世业田。","鲸吞那有间，席卷欲无前。","割夺封疆盛，依乘节制专。","公侯凄丧狗，奴隶歘登仙。","白日惊雷破，炎天积雪悬。","存亡觇货贿，喜怒信刀鋋。","诛责穷糠秕，需求到甓砖。","寡妻牵雨筏，尪子负冰椽。","徭役家家急，科徵处处煎。","田庐久焚落，衣履极穷穿。","惨矣生民祸，居然爵土煽。","积金明别坞，陈粟閟荒烟。","列地朱甍壮，层城画堞鲜。","椎牛酾玉醴，跃马铸金鞭。","事楚终怀谲，盟邾或挠权。","郊端兵屡挫，城下檄虚传。","苟不罹勍敌，能无感彼天。","假名徒虎负，就縳竟蝉联。","夜谍披心膂，晨登夺旆旃。","刳肠剧狐鼠，啄脑任乌鸢。","崛强嗟何在，繁华总弃捐。","扫除应假手，覆败已骈肩。","野昔耕无犊，民今坐有毡。","飞霜收杀气，清旭丽居廛。","禾水春前绿，屏山雪后妍。","遗氓喜相劳，早晚赋东旋。"]},{"t":"观涨二十四韵","f":"五言古诗","c":["积雨阴淫日，双溪晓涨初。","冥冥低鼓浪，滟滟细通渠。","触岸声齐斗，盘山势渐摅。","微茫穿窈窕，浩荡入空虚。","石抉漂岩鼠，防崩溃沼鱼。","掉头堤柳曲，破面渚萍疏。","荇泛纡残绶，芦漂偃败旟。","二仪看动荡，八表听吹嘘。","蛭蚓无安穴，蛟龙有定居。","深疑掀巨壑，猛欲撼盘岨。","出峡喧雷鼓，经天浸日车。","凝光净罗縠，跳沬碎珩琚。","涌屋初浮栋，循阶忽闯除。","人疑歌瓠子，世欲祀鶢鶋。","禾步偏愁决，三江未可疏。","皋田沦细麦，场圃溷嘉蔬。","升屋呼号急，登临盼望如。","云犹浮井邑，烟已断林庐。","远想天河落，空怀黄埧潴。","龙门动迫迮，梅演混舒徐。","昏霭迷行筏，凄风冷客袪。","沉浮惊浴鸟，漂转叹栖苴。","汇想经彭蠡，朝终赴尾闾。","扁舟如可具，吾欲理畋鱼。"]},{"t":"陪溪南隐君入山玩竹十二韵","f":"五言古诗","c":["涉溪弄芳鲜，临岸得嘉荫。","始缘一径微，稍入万壑深。","建戈直如刺，攒幄密方纴。","杀青脱工削，镵笋出庖禁。","翠怜秋雨洗，碧爱寒水浸。","草柔地堪席，苔净石宜枕。","沉沉惊瞑合，洒洒觉凉沁。","歌风便鸟憩，垂露惬蝉饮。","鸣笙虚可窍，扶老坚足任。","延秋思纵揽，占地欲豪赁。","一区聊有营，千亩得无甚。","愿从此君咏，请斥俗士闯。"]},{"t":"邹母萧夫人挽诗","f":"五言古诗","c":["白马引涂车，青鸾护板舆。","霞明丹旐远，雾暗琐窗虚。","苦味思丸胆，珍鲑忆馈鱼。","荒原移旅榇，冻雨洒灵裾。","玉树春云表，瑶华夕露初。","他年徵显秩，命服贲泉居。"]},{"t":"奉和孙真州伯刚南轩种竹十二韵","f":"五言古诗","c":["闻种南轩竹，亲携斸地童。","覆根深宿土，护叶背惊风。","籊籊看双干，潇潇自一丛。","雨愁崖响挫，晴爱树阴笼。","低映横窗北，深连别坞东。","春林期尽植，秋径得傍通。","散帙琅玕润，移尊翠黛空。","商音凉瑟瑟，海气夜濛濛。","习隐兼松菊，摅材并梓桐。","清怀二子上，名混七贤中。","自附幽栖兴，能忘长养功。","终言拂霄汉，高节倘齐同。"]},{"t":"赋玉笥山送杨主簿公望之清江","f":"五言古诗","c":["主簿才名盛，之官万里遥。","登临当别地，感慨欲行朝。","稍离金华界，还瞻玉笥标。","天光浮巀嶪，云气上岧峣。","紫盖麒麟府，青莲翡翠翘。","覆箱看雪积，法乐听风飘。","近侍丹台耸，尊居绛节朝。","彤霞秋闪闪，太白夜迢迢。","汉帝传金箓，秦娥奏玉箫。","子真元自隐，公远更谁招。","夕雾栖寒谷，春风动泬寥。","烟云千壑转，宇宙一岑超。","此去期应及，来游趣自饶。","避人骑瘦马，留客解金貂。","山术宜秋煮，炉丹足夜烧。","题诗黄叶嶂，携手白云椒。","静倚迎晨旭，长歌激暮飙。","终言眷官府，未可狎渔樵。","野迥齐桃叶，沙晴暗柳条。","赋题惊草率，饯迈愧萍薸。","疏雨沾行李，飞云逐去桡。","清江百里外，东望极旻霄。"]},{"t":"送况吏目归西山","f":"五言古诗","c":["南郡城如铁，西山翠作屏。","六年佐州幕，千里望亲庭。","簿领仍相绊，干戈苦未停。","晓衙冲暗曙，夕骑戴明星。","故里烟尘隔，澄江风浪宁。","赋归花苒苒，送别柳青青。","断港移兰桨，晴沙注玉瓶。","东南烽火后，几处短长亭。"]},{"t":"题江亭春望图为刘仲章赋","f":"五言古诗","c":["山暖锦云香，江晴翠黛光。","烟林交翡翠，风槛舞鸳鸯。","路转川原迥，潮通浦溆长。","落花沿石溜，芳草限河梁。","离客回兰桨，幽人结蕙纕。","年年望远意，春色满衡湘。"]},{"t":"陪练伯上同饮王氏南园樱桃花下得巾字","f":"五言古诗","c":["斜日樱桃下，高亭野水滨。","草生遥浦暗，花发近林春。","移席无馀地，停车有故人。","登山携谢屐，漉酒问陶巾。","芝岭元通汉，桃源自隔秦。","莫辞终夕醉，世已净风尘。"]},{"t":"题雪庵","f":"五言古诗","c":["浊世尘千劫，高人雪一庵。","风烟飞不到，冰柱矻相参。","鹤映水光润，龙腾剑气酣。","题诗霜拂颖，载酒月浮骖。","宇宙澄元气，溪山失瘴岚。","由来高洁士，不独重东南。"]},{"t":"腊月朔日纪怀十八韵","f":"五言古诗","c":["衮衮閒愁集，堂堂急景迁。","残冬惟一月，旅寓向三年。","霜入丝莼美，风掀锦树鲜。","义山通鸟道，禾水涨蛟涎。","雨泣鸣蛩地，云愁过雁天。","川光寒不动，兵气惨相缠。","海上霞生燧，城边月应弦。","疮痍浑未息，疾疠恐相煽。","陇亩迟三白，山林负一廛。","感时何及矣，抚事独凄然。","瞻落传新令，家贫食旧编。","依人惭野燕，恋子剧饥鸢。","席破门悬雨，庖空井閟烟。","种山仍畏虎，蹐地秪怜蚿。","出感关途梗，居愁赋调煎。","鹿门那可问，桃水径须沿。","未必弦真绝，虚疑笔可捐。","东风如解冻，南客且栖玄。"]},{"t":"冬日同诸友访萧国录登西楼复会宿山房分韵得连字因怀往昔夜过监学访萧国录会宋学士周员外诸公赋诗旧事明日赋柬鹏南伯仲并分韵诸作者","f":"五言古诗","c":["昔在兵曹日，长怀胄监贤。","退朝先解佩，扣户即登筵。","沽酒尊频倒，移灯句共联。","白头推翰相，綵笔会蓬仙。","醉夺青绫被，寒分白氎毡。","闻鸡愁夜雨，骑马爱春天。","改秩俄南北，还家乃后先。","西楼初看竹，南涧复听泉。","神剑惊重合，蠙珠得再连。","莫辞烧烛坐，且复对床眠。","窥户来雏鹤，蹲枝啸冻鸢。","窗虚风淅淅，檐迥雪翩翩。","旧赏随云散，新愁共月悬。","清才属群彦，高咏信残年。"]},{"t":"八月三日晚圣驾夕月清凉山上陪祀礼成喜赋","f":"五言古诗","c":["丹禁天光切，重城夕景饶。","太常陈祀秩，御史肃官僚。","自北移天仗，从西望斗杓。","神麾齐秉翿，仙路俨扬镳。","风磴传宣近，云林驻跸遥。","方垓开地埒，圆帐翼山椒。","初月澄娟媚，青天湛泬寥。","光浮金魄应，影动玉娥飘。","彩旆排飞虎，峨冠映珥貂。","异香初焫鼎，雅奏已鸣韶。","献奠罗尊斝，周旋协琫瑶。","礼徵周典序，文轶汉仪迢。","虎踞严更柝，龙骧引夕轺。","望舒呈朗素，玉烛度丰调。"]},{"t":"进甘露诗十六韵","f":"五言古诗","c":["甘露从天降，由来集帝垣。","霏微先禁苑，散漫遍郊园。","乳结虬枝重，膏凝翠叶繁。","泬寥澄夜气，璀璨耀晨暾。","味比香饴滑，光疑霁雪翻。","侍臣分碧盌，内使出金盆。","丹陛传天语，千官肃骏奔。","草堂联佩绶，钟阜拥蹄辕。","引蔓惊初见，修条喜共扪。","缘崖收沆瀣，采玉上昆崙。","醲泽流芳甸，嘉祥溢厚坤。","策书严荐庙，颂献蔼临轩。","不待金茎得，徒闻宝瓮存。","愿言歌蓼湑，四海锡便蕃。"]},{"t":"楮巢诗为彝仲赋","f":"古风","c":["豪贵金为埒，高人楮作巢。","一区通?窱，四壁绝{穴泒}坳。","煖爱风威隔，寒惊雪色交。","调琴延舞鹤，挥笔看腾蛟。","径小缘松入，门幽傍竹敲。","寄言尘土迹，未可漫相淆。"]},{"t":"咏雪","f":"古风","c":["飘忽来何处，纷纭势不齐。","漫空翻上下，著地遍东西。","冻合松林重，声闻竹屋低。","嵚崟缘石壁，烂漫布山溪。","曲直循绳矩，方圆应璧圭。","寒辉偏照户，素质不沾泥。","附垤俄惊厚，填洼迥觉澌。","伴吟栖近阁，随舞入青闺。","猎往踪先得，樵归路欲迷。","谷深愁侧入，桥滑怯危跻。","林暝蹲千鹄，沙寒散万羝。","缀衣侪玦瑀，集树混梅梨。","堤港增新堰，田园失旧畦。","马驰惊逸辙，兔过识奔蹄。","行客重装襺，居人缩拥烓。","积檐朝未扫，压轴晚犹?。","赏胜思图画，驱寒问酒椑。","冻僵怜野狖，光眩误邻鸡。","晏岁应多遇，严程未可稽。","停鞭呵冻笔，聊与寄新题。"]},{"t":"大赦恩诏和李子翀二首 其一","f":"七言律诗","c":["清朝祀事崇三礼，绝域衣冠走百蛮。","卤簿晓移通紫禁，箾韶春奏下彤关。","炉烟欲动螭头暗，旗影斜开豹尾閒。","自是郊坛敦汉典，谁论玉检上秦山。"]},{"t":"大赦恩诏和李子翀二首 其二","f":"七言律诗","c":["紫泥朝下五云端，朝野欢呼动百官。","养老已沾周德厚，赐租仍沐汉恩宽。","边庭天远颁龙节，台阁风清肃豸冠。","草野小臣何以报，远怀河颂愧艰难。"]},{"t":"题画松","f":"七言律诗","c":["巫峡荆门不可寻，坐怜孤嶂动云林。","夜寒或与蛟龙斗，秋暝应闻虎豹吟。","千岁茯苓山下老，一时丝蔓雨中深。","野桥寂寞云根冷，最忆停骖弄晚阴。"]},{"t":"送王石泉之金陵","f":"七言律诗","c":["金陵千古帝王州，送尔东南万里游。","卖药有时来海市，烧丹何处觅神丘。","钟山日落回龙虎，淮水天清入斗牛。","石底黄精能驻景，重来短镵定相求。"]},{"t":"题快阁和万德躬","f":"七言律诗","c":["快阁西南引兴长，高城落日晚苍凉。","江通牛吼疑巴峡，山入龙门似太行。","季子敝裘终相国，长卿驷马未还乡。","登临日对芳樽酒，莫遣秋风近绿杨。"]},{"t":"送周德刚归九江并柬其兄仲常","f":"七言律诗","c":["君家伯仲才名盛，贱子东南道路穷。","往昔永怀千里别，秪今谩想一尊同。","苍葭水驿青凫雨，落木山城白雁风。","岁晏林居定相忆，九江消息若为通。"]},{"t":"承家兄自石城南归消息述赋五首 其一","f":"七言律诗","c":["书来展转见艰危，南望徒令涕泗垂。","六县久闻残戍长，一州犹迟进王师。","潜依舍主惊相失，寄食野僧恒苦饥。","正是草间愁落日，石崖那更啸熊罴。"]},{"t":"承家兄自石城南归消息述赋五首 其二","f":"七言律诗","c":["荒村日日不逢人，上砦依人愁远身。","猺獠潜通南岭路，官军误信北风尘。","糇粮给饷山车困，牛酒祈安野庙神。","敢恨兵戈残赤子，极知帷幄有忠臣。"]},{"t":"承家兄自石城南归消息述赋五首 其三","f":"古风","c":["稍出蓝田见暮烟，徐坊迤?下雩川。","防夫夜筑缘山寨，逻卒时遮下水船。","风急妖尘侵岭外，日斜戍鼓起楼前。","出滩行李从萧索，愧尔长年剩一钱。"]},{"t":"承家兄自石城南归消息述赋五首 其四","f":"七言律诗","c":["出岭喜离豺虎群，下滩惊触怒龙龈。","浪抛飞雪船头见，石挟奔霆柂底闻。","心折已迷前日路，神消徒望故山云。","舟人相吊还相贺，南上征帆半是军。"]},{"t":"承家兄自石城南归消息述赋五首 其五","f":"七言律诗","c":["风尘面目困支离，奔走归来已后期。","且慰家人乌鹊喜，徒劳汝弟鹡鸰悲。","檐花深夜频沾席，瓠叶清秋谩绕篱。","直待南征捣巢穴，林皋种豆尽相宜。"]},{"t":"秋林图题赠旷伯逵","f":"七言律诗","c":["回风萧萧吹北林，行云冉冉生夕阴。","天寒雁去洲渚净，秋雨龙吟波浪深。","飘泊共怜今日兴，画图因见古人心。","几时螺子青枫下，深结茆堂更远寻。"]},{"t":"次韵一首奉寄孟浩彦弘二友","f":"七言律诗","c":["县北诸峰秀不群，桥南二水划中分。","寒星夜动蛟龙窟，斜日春明翡翠文。","照眼溪花浑烂漫，呼名山鸟自殷勤。","长怀吊古空多感，荒草离离太史坟。"]},{"t":"对雨有赋柬萧篪","f":"七言律诗","c":["栀子经年未着花，飘飘风雨到山家。","当楼烟薄锁不断，隔竹风高吹更斜。","村巷门深低宿草，石窠盆小涨微沙。","下帷不出愁泥潦，江上何人驻小车。"]},{"t":"忆廖氏池亭牡丹因寄文英友兄并约同饯范实夫","f":"七言律诗","c":["忆昔池亭同啸咏，秪今扶病少过从。","石阑花好几时发，林径苔深尽日封。","转觉春风愁见雁，可堪夜雨坐闻钟。","豫章归客能来别，乘取东城柳色浓。"]},{"t":"寄题黄氏竹所","f":"七言律诗","c":["闻说山人种竹多，秋风萧飒意如何。","浮云不尽夏西谷，落日遥连淇上波。","起舞蛟龙金错落，飞来丹凤锦婆娑。","何时白日清江路，乞与渔竿理钓蓑。"]},{"t":"寄赠马良卿归九江","f":"七言律诗","c":["尚忆临仙琪树秋，故人经岁独淹留。","千峰雨色侵林屋，十里滩声绕县楼。","王粲早应怀北返，马卿未必困南游。","江亭杨柳青如染，谁遣朝来重别愁。"]},{"t":"次韵奉寄孟浩彦弘二友","f":"七言律诗","c":["幽人共爱溪边住，舍北舍南春水声。","开径不嫌时独往，到城应许日同行。","乱云长共青山黑，白鸟偏依绿树明。","无限客愁谁断送，携壶长拟就君倾。"]},{"t":"舒君彦许送菊未至","f":"七言律诗","c":["故人许送南园菊，可趁重阳十日开。","谩拟客愁能暂醒，岂缘秋雨故迟来。","山含雾气通书幌，云涌川光落酒杯。","寂寞西斋林下路，新诗惆怅为君裁。"]},{"t":"寄赠周德刚自万安归九江","f":"古风","c":["惶恐滩声日夕哀，故人令弟独能来。","岭南盗寇经时出，江上舟?几日回。","客路西风桑叶落，故园细雨菊花开。","县公留别应相惜，白藕黄橙照酒罍。"]},{"t":"赠黄近贤自宜春过青原上赣州访周录事 其一","f":"七言律诗","c":["京国曾为万里游，祗将书剑谒王侯。","天门晓气瞻龙虎，银汉秋槎近斗牛。","贾傅才华终济世，庾郎词赋独惊秋。","断肠异县风烟晚，乱石孤帆入赣州。"]},{"t":"赠黄近贤自宜春过青原上赣州访周录事 其二","f":"七言律诗","c":["即遣北风吹上滩，且令飞雪压回澜。","沙头走马醒午醉，石里买鱼供晓餐。","传签亭长迎水鹢，击桨巴童歌木兰。","故人青眼望吾子，晏岁莫辞行路难。"]},{"t":"赠黄近贤自宜春过青原上赣州访周录事 其三","f":"七言律诗","c":["东风好在郁孤台，二月乘流又下来。","江上啼莺留客醉，岭南征雁逐人回。","故交天府音书绝，田父邻庄农事催。","题遍虔州山水胜，他时南土著雄才。"]},{"t":"题曾氏筠西小隐","f":"七言律诗","c":["城西亭子筠竹幽，竹光草色净人愁。","一帘山雨当白昼，五月水风吹早秋。","款段行穿杨柳径，鹧鸪啼近木兰舟。","青原南望隔烟雾，令我日夕怀林丘。"]},{"t":"五月十日雨宴集周氏亭子适溪水暴至不得归因留夜宴乐甚后数日叔用将之豫章次韵赠答以识感也 其一","f":"七言律诗","c":["杨柳河桥维客舟，送君此去忆重游。","青霄双阙连云起，五月沧江带雪流。","岭外简书前日至，湘南兵革几时收。","羁怀早已无聊赖，凭寄新诗过石头。"]},{"t":"五月十日雨宴集周氏亭子适溪水暴至不得归因留夜宴乐甚后数日叔用将之豫章次韵赠答以识感也 其二","f":"七言律诗","c":["忆昨过从思洒然，南溪亭子石桥边。","荷花解语偏宜醉，蒲叶堪书渐可编。","歌罢綵云疏雨外，坐看流水画堂前。","可能清夜仍留客，入馔溪鱼个个鲜。"]},{"t":"寄旷伯逵 其一","f":"七言律诗","c":["豫章市南风日清，楼阴轇轕俯层城。","孔融意气偏多客，司马文章岂近名。","候雁不来天正远，鲥鱼欲上雨初晴。","无因夜醉湖堤酒，不放芳尊卧月明。"]},{"t":"寄旷伯逵 其二","f":"七言律诗","c":["吴憩峰前看夕阳，浮云东渡思茫茫。","双林春入烟霞古，百谷波回雾雨黄。","草色经年侵客舍，莺声长夏满垂杨。","亭西见月遥相忆，五月南风早已凉。"]},{"t":"晚兴","f":"七言律诗","c":["高馆沉沉当翠微，晚凉幽兴莫相违。","乱萤出草光不定，独鸟渡溪风乍稀。","北港泉声喧野碓，东家月色净柴扉。","遥怜儿女当窗小，忆我经年行未归。"]},{"t":"寄王希颜二首 其一","f":"七言律诗","c":["故人哭母南归后，闻在云居湖水西。","綵服凄凉悲日暮，素冠欹侧任风低。","山中驯鹿时时见，林上慈乌夜夜啼。","丘垄旧栽松树子，秋来应得与人齐。"]},{"t":"寄王希颜二首 其二","f":"七言律诗","c":["靖安县北望修江，尺素无因寄鲤双。","对月谩劳清梦远，看云未得壮心降。","青春花发芙蓉嶂，白日乌啼烟雾窗。","待取秋高沙渚净，便将艇子下晴泷。"]},{"t":"闻赣江泛溢冲决金鱼寺有怀敝庐感赋","f":"七言律诗","c":["五月水生牛口矶，客子独怜行未归。","荡决已闻冲野寺，漂流故恐失柴扉。","鱼虾小市舟航集，鸡犬深林烟火稀。","且可登楼避泥潦，无由缩地问庭闱。"]},{"t":"栖霞观","f":"七言律诗","c":["青湖岭下入栖霞，缥缈玉清仙子家。","宫殿春移九芝盖，云烟昼下五华车。","冥冥古柏含溪雨，短短青蒲隐岸沙。","药臼丹瓢那可问，高原残日散桑麻。"]},{"t":"寄赠旴江郡教刘公稷","f":"七言律诗","c":["十年不见刘文学，白发新来几许长。","官舍晓清槐叶暗，泮林春雨杏花香。","听泉定过麻姑洞，看月还寻华子冈。","山屐酒壶从倒载，昔贤高咏故难忘。"]},{"t":"秋夕","f":"七言律诗","c":["月出乌啼城上台，台前梧竹净尘埃。","凉风夜发星辰动，白露秋垂河汉回。","在户莎鸡终日听，随阳鸿雁几时来。","绛衣八月南邻曲，拚对寒灯送酒杯。"]},{"t":"忆邓子益","f":"七言律诗","c":["城北高楼子所居，百年文物此何如。","清秋对酒看题画，细雨升堂闻读书。","短褐犹劳慈母线，閒门偏枉故人车。","临风玉树何时倚，怅望南天白雁初。"]},{"t":"九月廿二日承钟元卿六月二十日书且有卜邻之约未知能遂否也赋答意","f":"七言律诗","c":["九月初承六月书，过时不敢问何如。","故园早已黄花后，南国相将白雁初。","直以亲情能数问，可缘贫贱转相疏。","卜邻预喜过从近，远愧江湖未定居。"]},{"t":"赠别屈悠然归豫章二首 其一","f":"七言律诗","c":["云松轩馆净林扉，十日寻幽且未归。","坐对清秋桑落酒，行褰高树薜萝衣。","石栏度曲凉风动，竹屋吹灯夕漏微。","自是使君能好客，故人何事苦相违。"]},{"t":"赠别屈悠然归豫章二首 其二","f":"七言律诗","c":["山堠鸡鸣出翠烟，苍苍北斗县楼边。","一年为客岁将暮，此日别君殊可怜。","数里枫林过驿路，谁家橘柚照归船。","綵衣蓉褥看多喜，坐想江云乱管弦。"]},{"t":"送脱因州判之新淦","f":"七言律诗","c":["陶母祠前山郭西，临流官舍似幽栖。","平原樟树通南镇，流水桃花隔故溪。","春入华筵承宴早，日高画鼓报衙齐。","时清无复劳巡警，随意东风散马蹄。"]},{"t":"承瑞州万户刘公衡移镇宁都道出南平枉顾敝庐以故人书问邀致其塾赋赠一首","f":"七言律诗","c":["将军出镇上虔州，江閤喧传驻綵舟。","陋巷已烦纡辔入，不才敢辱致书求。","花边玉节明铜虎，户外金鞍簇紫骝。","勿讶承平劳远戍，极知文雅足怀柔。"]},{"t":"过万安憩达观寺坐对水西芙蓉诸峰与客谈旧游久之是日得风船先上滩因步至神潭登舟","f":"七言律诗","c":["达观寺前春水深，维舟汀树一登临。","坐怜旧日经行路，愁绝新年怅望心。","苍峡雨声寒㶁㶁，白沙云气暮沉沉。","不缘南上风帆急，犹拟凭高挹翠岑。"]},{"t":"大蓼滩","f":"七言律诗","c":["向午上滩当北风，扬帆绝险似惊鸿。","青山乱出云日下，黑石漫浸波涛中。","欹眠估客耳目眩，捎撇棹郎心胆雄。","江流喷薄不自极，人生艰难安可穷。"]},{"t":"登郁孤台","f":"七言律诗","c":["石面层滩似虎牢，盘涡束峡见周遭。","背城二水合流远，隔岸五峰相对高。","神阙紫烟栖鹳雀，浮梁白日偃鲸鳌。","来游最爱西洲上，千树东风散碧桃。"]},{"t":"谒古石固祠因观宋高宗御赐遗物","f":"七言律诗","c":["乱山盘束五龙堆，万木萧森一径开。","白涧滩声兼地动，崆峒云气度江来。","柘袍鸾凤辉寒日，宝带山河拱上台。","古庙丹青犹赫奕，百年遗物使人哀。"]},{"t":"将发舟承曾自道留宿舟中临别赋赠","f":"七言律诗","c":["一上南船独怆神，感君留宿见情亲。","城头桃李春愁客，水上星河夜近人。","自古文章关气运，祗今道路昧风尘。","从知即别频回首，烟树鸡鸣已达晨。"]},{"t":"由会昌江口分路之宁都赋别五弟 其一","f":"七言律诗","c":["湘水梅州共路分，东风杳杳惜离群。","扁舟逆上几时到，独雁哀鸣何处闻。","积雨已生三峡浪，乱山仍隔万重云。","眼前漂泊谁能奈，犹恐亲庭念远勤。"]},{"t":"由会昌江口分路之宁都赋别五弟 其二","f":"七言律诗","c":["青山黄叶几时归，南上独怜音信稀。","老大庭闱终在念，艰难弟妹且相依。","荒凉野日行人泪，缥缈山风游子衣。","力学承家应赖汝，暂时分手莫相违。"]},{"t":"题山水画","f":"七言律诗","c":["山冈盘盘多树林，江水湛湛愁人心。","赤云楼观落日外，白日溪涧长松阴。","啼猿虚疑近翠壁，飞鸟剧恐回高岑。","野亭春色苦无赖，忽忆故人思远寻。"]},{"t":"春日奉次罗肇简郑同夫","f":"七言律诗","c":["不见故人心惘然，也应无赖枕书眠。","閒寻碧草日又暮，落尽桃花春可怜。","云隔双峰归雁后，水生三峡乱帆前。","客怀慰藉思倾倒，冲雨能来白马鞯。"]},{"t":"斋前隙地列三石峰因植丛竹其下小雨隐映可爱","f":"七言律诗","c":["南园旧竹困支离，移过墙阴雨更宜。","落落出群看两个，萧萧交翠待千枝。","荒苔古石清閒地，细草虚庭隐士诗。","即此尽堪消永日，鸣驺陌上欲何为。"]},{"t":"自京师归至家园春欲暮矣晨兴登一乐亭喟然有感漫成一律","f":"七言律诗","c":["解罢朝衫及暮龄，閒拈竹杖过茅亭。","山明隔岸腾初日，雾下高林带落星。","萱草叶齐春冉冉，紫荆花发晓冥冥。","向来万里京华梦，犹记吹笙踏凤翎。"]},{"t":"南山寺夜憩柬郑同夫罗孟文 其一","f":"七言律诗","c":["南山寺前夏已凉，北斗天半夜相将。","楼台参错临高市，钟磬萧条出上方。","独宿屡移林鹊影，双飞初散水萤光。","客情物态浑无那，暂息尘喧亦不忘。"]},{"t":"南山寺夜憩柬郑同夫罗孟文 其二","f":"七言律诗","c":["南城城楼高且雄，下有长壕水气通。","次第荷花先着露，无多杨柳最宜风。","府中能事称罗掾，马上酣吟爱郑公。","自是南游相见好，疏狂祗觉愧飞蓬。"]},{"t":"感怀四首寄呈李子翀邓子益 其一","f":"七言律诗","c":["异县南归忆旧年，潇潇风雨楚江船。","相看一别成愁绝，可待相逢已惘然。","巴蜀偶依严武去，成都未报长卿还。","川途日有经行便，何事音书不漫传。"]},{"t":"感怀四首寄呈李子翀邓子益 其二","f":"七言律诗","c":["邓郎心性蚤聪明，李子才华更老成。","应着綵衣奉慈母，还看鸿雁忆难兄。","遗书独抱谁相问，佳句新题人尽惊。","自合鶱腾齐远举，敢将憔悴托高情。"]},{"t":"感怀四首寄呈李子翀邓子益 其三","f":"七言律诗","c":["将军屯戍落秋风，客子离思逐暮鸿。","书剑远投烟瘴外，鼓笳凄断月明中。","野猿引子溪藤绿，山麝眠香石竹红。","凉气萧森盘两峡，直愁华露陨高枫。"]},{"t":"感怀四首寄呈李子翀邓子益 其四","f":"七言律诗","c":["绣谷峰前濯冷泉，金精洞口望飞仙。","东南奔走祗自厌，岁月飘零谁与怜。","风细柳营秋瑟瑟，日高花馆露娟娟。","短衣荷锸应吾事，欲向邻村种石田。"]},{"t":"寄韩希说","f":"七言律诗","c":["磊落旴江韩掾史，十年不调滞江城。","登山短屐自意远，近水小楼偏眼明。","梧桐深巷围金井，杨柳小窗调玉笙。","且可林泉投野逸，莫持文采动公卿。"]},{"t":"奉和刘侯对月一首","f":"七言律诗","c":["深沉鼓角动重关，迢递星河近暮山。","卧匣宝刀鹇尾白，悬门弓䩨虎文斑。","石林寒落鞲鹰急，原草秋肥厩马閒。","忽忆海天南讨日，月中飞箭下黎蛮。"]},{"t":"至谷口亭下闻伯友久候不至复归山中矣再赋","f":"七言律诗","c":["两岸参差当赤曛，走马直度千溪云。","入门不见赵公子，过峡还同郑广文。","桃林地涌金银气，仙掌霞明锦绣文。","铁锁高攀定何处，玉箫疑向夜深闻。"]},{"t":"寄赠广昌盛县尹","f":"七言律诗","c":["郡邑劳劳困茧丝，喜闻令尹政平夷。","中朝奏最宜增秩，南国观风定采诗。","百里不知持牍吏，三年祗似下车时。","微生敢恨循廉远，摇落秋山有所思。"]},{"t":"赠戴武子","f":"七言律诗","c":["曾骑官马下青云，又驾仙鸾戏紫氛。","朝客总称奇道士，野人犹识旧将军。","城门卖卜时相见，石室谈玄世罕闻。","中夜起瞻华盖近，五云何处是奎文。"]},{"t":"秋日燕集郑广文呈赵伯友","f":"七言律诗","c":["直谊清名夙所闻，乱山深处一逢君。","寒莎蟋蟀谩相语，碧梧凤凰终不群。","南浦他年书共寄，西城此夜席频分。","相逢更有关情甚，又拟河桥别广文。"]},{"t":"答刘诚本寄画","f":"七言律诗","c":["故人昔别能相忆，远寄新城水墨图。","木叶尽含春雨润，石根犹带晚云孤。","啼猿远过盘陀岭，归雁忽沉彭蠡湖。","已办鹅溪玉色绢，南归问子写蓬壶。"]},{"t":"赠郑子素迎父东归","f":"七言律诗","c":["郑郎身着五綵衣，千里将车迎父归。","不愁江浦寒枫落，即恐林园秋菊稀。","令弟已能官邑校，高才终见拔经闱。","到家调膳趋庭后，坐想书声出翠微。"]},{"t":"题引翠楼简元善张兄","f":"七言律诗","c":["尽道楼居思不群，满楼山色翠纷纷。","高崖斜日含丹雾，碧嶂清秋起暮云。","江上捲帘通雨气，月中看剑动星文。","来游定觅张公子，载酒题诗过夜分。"]},{"t":"张仲良燕饯郑子素于黄竹径之梵閤时天气暖甚桃花盛开后四日为重九矣得携字","f":"七言律诗","c":["行客系船黄竹西，江晴石出少沙泥。","背崖李子寒初落，近水桃花暖欲迷。","何日登楼思共倚，清秋载酒惜分携。","接䍦倒着从人笑，直过南街散马蹄。"]},{"t":"曾氏蕙花","f":"七言律诗","c":["闻说新安处士家，萧萧兰蕙照晴沙。","翠交庭户三千本，玉立风霜一万花。","帝子带纕承白露，仙人旌旆散晴霞。","为君细读灵均赋，安得携壶载小车。"]},{"t":"孙景武从赵伯友先生游宁都兹归省豫章诗以赠之并柬知己者 其一","f":"七言律诗","c":["渝州进士才名盛，此地相逢愿不违。","喜子能随青佩至，思亲还望白云归。","长风出峡衣裳薄，乱石横滩舟楫稀。","亦有故园秋草里，旅魂空逐断鸿飞。"]},{"t":"孙景武从赵伯友先生游宁都兹归省豫章诗以赠之并柬知己者 其二","f":"七言律诗","c":["豫章城头山色青，深烟疏雨昼冥冥。","谩怀把酒当飞阁，谁与题诗上翠屏。","云外仙人无旧宅，湖边高士有新亭。","故交相见应相问，为说漂流愧转萍。"]},{"t":"赠董宗文归乐安","f":"七言律诗","c":["董生读书赤岭西，寻常闭户足幽栖。","云中沙雁惊寒落，江上野禽愁暝啼。","为养何由沾禄秩，旅游终日愧涂泥。","老翁望子行不至，日日看云携杖藜。"]},{"t":"赠魏伯谅归豫章","f":"七言律诗","c":["十月清霜逐雁飞，旅游空复叹多违。","野林寒色催黄落，石室秋阴近翠微。","聚散总怜今日异，登临徒感故人稀。","将军宴客偏愁别，更换歌辞看舞衣。"]},{"t":"送吴德茂归崇仁","f":"七言律诗","c":["黄州城西子所家，春来杨柳满汀沙。","几时载酒出东郭，到处看山行小车。","解拄仙人九节杖，去觅安期五色瓜。","云中华盖可揽结，迟子归来餐夕霞。"]},{"t":"送詹守仁归乐安","f":"七言律诗","c":["感子抱书还故丘，丁丁伐木念相求。","不愁此别当炎夏，即恐重逢是异州。","绝涧雨深垂螮蝀，乱山日落叫钩辀。","南归定足三冬学，听尔鸣鞭赋远游。"]},{"t":"赠慧上人","f":"七言律诗","c":["仙楂江口楂溪寺，几度停舟访未能。","颇恨频年为远客，喜从异郡识高僧。","云霞色动禅房衲，星月光涵古殿灯。","何日却飞真锡返，故山苍木翳寒藤。"]},{"t":"送曾茂文归乐安并柬其兄祥文","f":"七言律诗","c":["秋风落叶思纷纷，北固桥南一送君。","行李又从今日别，寄书定向几时闻。","长亭月白鸡鸣曙，绝嶂天清雁入云。","最忆难兄工赋咏，即看竞爽振斯文。"]},{"t":"送董国贤归乐安","f":"七言律诗","c":["董家伯仲总明经，仲也萧閒似管宁。","暇日过从南北巷，穷年送饯短长亭。","金精橘子霜前赤，华盖芙蓉雨后青。","此地怆然成一别，沉浮江海信流萍。"]},{"t":"过度门寺访隐上人","f":"七言律诗","c":["度门寺前溪最幽，亦有群木依崇丘。","时时清磬落云雁，个个轻舟并水鸥。","已公茆屋真堪赋，季子郭田那可求。","眼前即恐易为别，安得杖藜时一游。"]},{"t":"题唐氏苍然亭","f":"七言律诗","c":["苍然之亭湖水西，青松万个与云齐。","秋声惨淡雾雨集，夜气萧森牛斗低。","野人问字每载酒，老翁哦诗还杖藜。","南归感子不尽意，上有慈乌终夕啼。"]},{"t":"送慧上人之九顿岭 其一","f":"七言律诗","c":["九顿岭头愁夕曛，高人南去礼寒云。","白牛露地秪自见，玄鹤出林终不群。","神锡行空风瑟瑟，钵衣挂树月纷纷。","松崖总是经行路，出定哀猿何处闻。"]},{"t":"送慧上人之九顿岭 其二 送杜九皋之金华","f":"七言律诗","c":["公子华年思远征，浙山千里入脩程。","筵开候馆林花落，柂转官河春水生。","健马长风朝挟箭，惊鸿凉月夜鸣筝。","旧游寂寞筠阳道，芳草离离寄远情。"]},{"t":"送慧上人之九顿岭 其三 奉次王子启寄叙春初别时事","f":"七言律诗","c":["忆我城南春可怜，湖山长近别愁边。","扣门惊见漏将夕，把炬送行江满烟。","遽喜春深传秀句，能忘岁晏接归船。","向来风雨河桥路，肠断杨花白似绵。"]},{"t":"送慧上人之九顿岭 其四 送王监生以就试归浙未获荐仍赴太学","f":"七言律诗","c":["东吴乡贡昔多贤，太学诸生最少年。","董子尚迟三策对，夏侯终见一经传。","宫花晴覆金河水，御柳春浮紫禁烟。","遥想桥门冠带盛，时时听讲出宫筵。"]},{"t":"送慧上人之九顿岭 其五 送喻仲渊归省东吴","f":"七言律诗","c":["明秀楼前雨满沙，石榴花发客思家。","水通赤岸西流浅，路入青山北向斜。","归省可能忘夏凊，传经还解惜年华。","寻幽若过双溪去，为觅秋风旧钓槎。"]},{"t":"送慧上人之九顿岭 其六 刘元善弹琴","f":"七言律诗","c":["忆尔弹琴天藻亭，秋风飒飒近帷屏。","仙人飞佩去不远，学士杖藜来细听。","兰叶临池惊坠露，松枝出石带流星。","只今遗意谁能赋，犹想钧天奏洞庭。"]},{"t":"送慧上人之九顿岭 其七 赠刘元善","f":"七言律诗","c":["故人东去维扬日，学士亲题送别诗。","一代风流嗟已矣，十年漂泊更何之。","久传大府承簪笔，犹滞沧江理钓丝。","寂寞旧游临汝曲，秋风雕鹗起遐思。"]},{"t":"送慧上人之九顿岭 其八 送胡明初自西涧归省柳山","f":"七言律诗","c":["秋雨萧萧度翠微，西南无数白云飞。","极知衣綵趋庭乐，况是从师学道归。","江浦星流鸡叫早，石林霜远雁来稀。","送君不尽丘园思，独倚城楼看落晖。"]},{"t":"送慧上人之九顿岭 其九 戍楼燕集呈熊子庄常子中岳维高并怀公衡万户","f":"七言律诗","c":["戍楼百尺跨崔嵬，公子华筵向晚开。","城上秋风低鼓角，江间烟浪入樽罍。","登临谩作怀乡赋，感慨深怜济世才。","自是将军勤结构，海天旌节几时回。"]},{"t":"送何天碧归龙虎山","f":"七言律诗","c":["道人九月江东去，二十四岩烟雾深。","落日横峰看雁度，清霜碧树听猿吟。","山中紫朮堪为酒，灶底丹砂可化金。","淮海风尘愁复别，重寻还许托云林。"]},{"t":"舟次樵墩忆故人郑文学同夫","f":"七言律诗","c":["浦口维舟日欲晡，柳村桑坞带萦纡。","独寻古道黄埃满，忽忆故人秋兴孤。","螺蚌尽供溪女拾，鸡豚偏称野人呼。","西山隔水青如玉，谁与题诗送酒壶。"]},{"t":"春同旷伯逵周叔用徐仲孺登秋屏阁是日闻淮郡有警风沙黯然赋呈万德躬孙伯虞诸君子","f":"七言律诗","c":["古刹萧条隐石根，荒城高下带沙墩。","断云南雁日初出，旷野北风天正昏。","羽檄屡传淮甸急，龙艘犹滞海门屯。","湖山不尽登临兴，回首乡园独怆魂。"]},{"t":"罗巡检一中由袁府告籴于赣道阻留西昌久之将归袁州诗以为别","f":"七言律诗","c":["快阁西偏寺最幽，江风渚月净如秋。","竹间久挂将军剑，柳外初回使者舟。","痛哭秦庭惊晏岁，独持汉节望南州。","日斜戍鼓连山急，杳杳冥鸿慎所投。"]},{"t":"送刘掾归赣","f":"七言律诗","c":["王事劳劳信有馀，时危经济定何如。","兵戈未报东南息，仓廪遥怜郡邑虚。","荒草断城春寂寂，落花归骑雨疏疏。","野人实少干时策，犹掩衡门学著书。"]},{"t":"次项可臣感怀","f":"七言律诗","c":["玉华峰下碧溪流，曾向南城赏素秋。","明月远从湘右出，好山如在越中游。","伤心丧乱云千变，过眼韶华水一沤。","此日飘零豺虎外，为君愁倚仲宣楼。"]},{"t":"匡山砦中奉和梅南刘府推韵呈公望杨主簿","f":"七言律诗","c":["万里旌旗在眼中，千崖寒色待春风。","愁来自少登临乐，乱定谁论战伐功。","桂岭天长云似马，槎滩波净月如弓。","白头幕府忧时切，此日题诗感慨同。"]},{"t":"春日过薛益书舍小酌得春字","f":"七言律诗","c":["二月飞花独怆神，几家归燕不逢人。","偶因看竹寻幽径，愧尔移尊出近邻。","赤地蒹葭淮甸雨，画船杨柳楚江春。","薛华歌调从来好，愁绝新声泪满巾。"]},{"t":"云亭萧氏园池杂兴次韵四首 其一","f":"七言律诗","c":["日日西园载酒来，好花深映洞门开。","水涵香雾空青湿，山拥晴云紫翠堆。","林径微风看燕度，石桥细雨听莺回。","酣歌却望双峰近，落日松声万壑哀。"]},{"t":"云亭萧氏园池杂兴次韵四首 其二","f":"七言律诗","c":["竹底雏莺尽日啼，水风凉动小池西。","麝香眠起残花落，蛱蝶飞来碧草齐。","二水风鸣湘佩合，三山云压楚鬟低。","冰盘宴客晴阴里，次第诗成石上题。"]},{"t":"云亭萧氏园池杂兴次韵四首 其三","f":"七言律诗","c":["小小窗轩溪水头，石门古路转斜丘。","野林丹碧风初起，山橘青黄露未收。","鸟下平原飞雨夕，猿啼孤嶂断云秋。","读书台近招提境，思见当年隐者流。"]},{"t":"云亭萧氏园池杂兴次韵四首 其四","f":"七言律诗","c":["露下庭皋锦树残，霜融溪路白沙乾。","浮云万壑天光暝，流水孤村暮色寒。","有客求鱼朝拥棹，何人载酒夜停鞍。","风流最好梁园赋，拟向山中对雪看。"]},{"t":"送丁惟中弃家入五峰脩道","f":"七言律诗","c":["五峰山上晓钟声，羡子中年出世情。","有发总缘诸相幻，无家始悟一身轻。","溪边洗钵鱼初识，林下传经鹿共行。","遥想神螺光彻夜，几时来听说无生。"]},{"t":"忆鼎儿","f":"七言律诗","c":["鼎子别来忽复春，可缘多病少精神。","最怜得饱坐终日，更鲜牵衣啼向人。","长大他年从涉世，艰难此日莫辞贫。","重闱怜汝应长健，白发时来引笑频。"]},{"t":"晚集舒氏山楼有戏予不饮者赋此寄怀","f":"七言律诗","c":["近郭青山故满楼，登临犹及送清秋。","干时虚拟扬雄赋，对酒真成王粲愁。","水国冥鸿寒历历，林梢白鹭晚悠悠。","谩将强饮酬清赏，已觉归心屈壮游。"]},{"t":"三月会宴城南花圃分赋石榴","f":"七言律诗","c":["城南花圃谁频到，几树石榴亭子西。","三月未看花乱发，丛柯偏爱叶初齐。","舞裾尚忆佳人醉，使节还怜远客迷。","一色深林烟雾里，黄莺故意近前啼。"]},{"t":"寄赠瑞金曾尹","f":"七言律诗","c":["县城深隐乱山围，令尹能官愿不违。","硐客输租前月至，邮胥报事近时稀。","庭边花发幽禽下，垄上桑阴野雉飞。","早见循良归汉记，穷荒犹得借馀辉。"]},{"t":"题古木幽篁图","f":"七言律诗","c":["山中古木无春冬，根结怪石相盘冲。","烟云有时伏玄菟，风雨尽日唫苍龙。","幽篁出涧倚寒玉，细草临坡被紫茸。","不是画图当户见，丈人巾屦久相从。"]},{"t":"送陈仲宝之南雄府掾","f":"七言律诗","c":["山城细雨熟蒲萄，公馆题诗送郡曹。","总喜风云培健翮，谁怜法令析秋毫。","水生东浦临江近，路入南荒庾岭高。","亦拟乘槎望沧海，还思投笔钓神鳌。"]},{"t":"同可用文甫孟文昌祖过连氏池亭观网鱼复酌丁氏别墅","f":"七言律诗","c":["连家庭榭倚溪阴，七月林塘秋意深。","已觉经时违眺望，独将暇日费追寻。","尊移别墅黄花近，网集寒潭翠荇沉。","今夜酒醒山上月，可堪鸣角间清砧。"]},{"t":"赠天与熊炼师归阁皂山","f":"七言律诗","c":["阁皂高居好炼真，清秋何日下嶙峋。","金丹夜气成龙虎，宝录玄文动鬼神。","兰蕙深悬青组佩，芙蓉斜拂紫纶巾。","南归定住仙岩侧，自扫寒云礼玉宸。"]},{"t":"至正乙未秋九月宪司潘郎以巡历来吉省掾马郎以徵籴过赣于其归各赋赠一首 其一","f":"七言律诗","c":["水驿苍茫道路开，州人争看宪郎来。","简书消息通江海，车马光华注草莱。","晏岁王程伤远涉，时危幕府见奇才。","绣衣坐镇东南郡，日望新年报政回。"]},{"t":"至正乙未秋九月宪司潘郎以巡历来吉省掾马郎以徵籴过赣于其归各赋赠一首 其二","f":"七言律诗","c":["何日南州寇盗平，省臣经济最关情。","年荒外郡仍移粟，岁晏中原更调兵。","落日荒林馀鸟道，青山白骨少人耕。","风帆历历经行处，万一咨诹慰远氓。"]},{"t":"喜水退过南园问劳子与伯仲兼怀水东别业","f":"七言律诗","c":["城隅水落两沟浑，犹见泥痕上井垣。","昨日岂无鱼入市，今朝始有客敲门。","芙蓉别港船初渡，筼竹深林榻谩存。","禾黍未收沙垄没，无端愁杀水东村。"]},{"t":"早春寄谭若骥时寓居桐林","f":"七言律诗","c":["珠林南上是桐林，愁绝閒居怅望心。","蚤岁风涛嗟独往，残年雨雪忆相寻。","鸟啼独树荒村晚，雁度重云极浦阴。","石上梅花飘欲尽，拟携尊酒答春吟。"]},{"t":"西楼晚兴","f":"七言律诗","c":["独上西楼看夕阳，遥峰暮色正苍苍。","原边落叶秋风早，城上归人古道荒。","流水只今通汉沔，白云何处望荆襄。","丽谯依旧沧江上，笳鼓凄清独断肠。"]},{"t":"访罗允道值出城晚归","f":"七言律诗","c":["已出三华离蕊宫，还过栗里访陶公。","寻幽独恨芳春暮，对酒空怀此日同。","蒲柳回塘新雨绿，松杉横阁晚霞红。","可能城市归来早，犹及酣吟紫翠中。"]},{"t":"十月二日假馆下径罗氏庄予兄弟所寓相距若东西家喜赋一首柬子中子彦","f":"七言律诗","c":["畏途暂喜出深山，僻地初便候野关。","逖矣风尘千嶂外，依然兄弟一堂间。","共寻绝涧樵薪去，相望空村负米还。","斜日频来看稚子，满庭霜树叶斑斑。"]},{"t":"过清节先生故居废址遇野老谈旧事","f":"七言律诗","c":["云亭小径青山下，清节当年故址存。","野老尚能收谱牒，邻人还解识田园。","乔林鹤去枝柯改，古井龙移窟穴翻。","千载高风知不泯，拳拳经辩著王尊。"]},{"t":"卧病山中承如川王侯寄赠青绫被","f":"七言律诗","c":["劳君远寄青绫被，愧我仍烹紫朮汤。","已幸甘香分药裹，复经温暖到藜床。","乡园摇落黄花雨，江海飘零白雁霜。","归日病躯堪料理，便迎锦障送飞觞。"]},{"t":"赠别龙非池","f":"七言律诗","c":["黄岐龙氏多才俊，喜见长沙旧校官。","乡国十年犹客舍，风尘四海只儒冠。","山中采药无人识，石上题诗有客看。","西望禾峰青万丈，为君长啸送飞翰。"]},{"t":"书所怀","f":"七言律诗","c":["二月欲半风日清，林居幽事总关情。","椒条旧剪愁先蠹，竹笋新栽想乱生。","承霤若为防夜雨，荷锄应及趁春晴。","谁将稚子花前戏，几误閒车出户迎。"]},{"t":"舟中与叶尧有丘弘道同载和韵一首","f":"七言律诗","c":["秋入天河雨满津，水光山色共清新。","船头杨柳参差晚，木末芙蓉掩冉春。","又向异乡寻远客，可缘同载得高人。","似闻下邑喧豺虎，犹拟垂纶寂寞滨。"]},{"t":"感兴次刘以和二首 其一","f":"七言律诗","c":["烟火清明有几家，楚天三日雨黄沙。","城南莺燕青春暮，江上旌旂白日斜。","征马萧萧愁积雨，客帆隐隐送飞霞。","绝怜憔悴乡园里，江海经年眺望赊。"]},{"t":"感兴次刘以和二首 其二","f":"七言律诗","c":["溪上偶寻杨子宅，雨中还过习家池。","那无胜地堪携酒，喜有同宗足咏诗。","江草青青愁远别，林花寂寂笑归迟。","白鸥自是忘机物，莫遣南邻野叟知。"]},{"t":"答王孟极过访荷山书馆不遇之作","f":"七言律诗","c":["王氏才华擅世传，临潨文物故依然。","山中夜雪明书帙，溪上春云压钓船。","深港鸟啼花似雨，平原人去草如烟。","荷峰亭馆能来数，怅望高车落照边。"]},{"t":"送李敬之赴广西帅府","f":"七言律诗","c":["帅府西开控百蛮，故人捧檄上遥关。","春回桂海云垂地，夜入榆溪月满山。","客路独行青嶂外，人家多在白云间。","南征定有诗千首，凭寄秋来驿使还。"]},{"t":"七月十一夜宿蓼洲","f":"七言律诗","c":["众星撒沙烂欲堕，北斗西挂独分明。","征帆暗落水边驿，更柝静鸣江上城。","风低岸草露萤急，月出浦林沙鸟惊。","羁栖复此当深夜，漂泊谁能断此生。"]},{"t":"题刘道士杏林图","f":"七言律诗","c":["白鹤观前红杏林，高人习隐契玄心。","悬壶通市天光近，采药乱山云气深。","微雨独携松下屐，清风时动壁间琴。","望中疑是旌阳宅，车马萧萧费远寻。"]},{"t":"题山水画","f":"七言律诗","c":["绝壁芙蓉四面开，中天积翠郁崔嵬。","苍烟尽捲秋光去，飞雨欲随云气来。","丹井绿萝通石穴，紫霞碧树映琼台。","那无九节仙人杖，直拟寻真绝顶回。"]},{"t":"题邓汉英所藏山水图","f":"七言律诗","c":["白云杳杳冠青山，翠石盘盘倚碧湾。","野岸亭台随地出，江沙舟楫几时还。","鸟冲烟树愁孤往，猿挂云萝学并攀。","最爱桃花流水处，寻源亦拟扣林关。"]},{"t":"寄罗明道","f":"七言律诗","c":["曾过溪南访草庭，绝怜高隐静仪型。","雨沾竹色侵书帙，云拥岚光落座屏。","松径晓开岩雪白，稻田冬护水烟青。","何由跨犊閒来往，日听先生讲道经。"]},{"t":"陪同年刘霖刘鹤皋欧阳铭题三德院","f":"七言律诗","c":["宝地登临一惘然，故家乔木寺南边。","铭钟犹记甘泉里，题壁重看至正年。","万里风云通北极，五湖烟浪隔南天。","同游况有同宗好，事业应期久远传。"]},{"t":"和答万讱","f":"七言律诗","c":["家住云亭河水东，乱来门巷往还空。","避时犹拟寻秦洞，献赋虚怀谒汉宫。","松坞乍晴乌啄雪，桑林欲暮鸟呼风。","感君晏岁能相顾，尊酒谁知寂寞同。"]},{"t":"题沧洲书舫图送张子明归武夷","f":"七言律诗","c":["沧洲远在武夷西，九曲寻源路恐迷。","潭面晚晴花苒苒，岩腰春暝草萋萋。","何年对月思朋好，此日看云信杖藜。","安得从君棹书舫，酒壶诗帙镇相携。"]},{"t":"题糜朝英园居","f":"七言律诗","c":["城东园居隐者家，五亩十疃连桑麻。","老人自浴丹井药，稚子重种青门瓜。","花边酌酒惊雨过，湖上吟诗愁日斜。","昔贤高蹈可同调，莫遣风尘侵鬓华。"]},{"t":"题芝草图","f":"七言律诗","c":["五色灵芝见者稀，画图叶叶动光辉。","草间白雪明可掇，石上紫云愁欲飞。","幽人已喜咏伐木，归士多劳歌采薇。","湘南三秀思并荐，汉武斋房今是非。"]},{"t":"题张彦辅枯木坡岸画轴","f":"七言律诗","c":["秋宇道人画枯木，纵笔所至皆天成。","瘦蛟出石云气润，独鹤横江霜影清。","荆门送客愁欲暮，澧浦怀人伤远情。","望中秋意入惨淡，何处青枫闻雁声。"]},{"t":"奉寄辛检校好礼总兵进贤之北山","f":"七言律诗","c":["省郎何处屯兵久，彭蠡湖西是北山。","飞箭定穿蹲虎石，放船时过落星湾。","五年鱼鸟知营阵，百里樵苏绝塞关。","闻说啸台高百尺，题诗频寄故人还。"]},{"t":"题定元帅清江横槊亭","f":"七言律诗","c":["将军亭子蔚峥嵘，高压清江百尺城。","马上铙歌来献捷，幕中尊俎坐谈兵。","石龙鳞甲眠秋雨，金凤云沙照晚晴。","南望葛峰同岘首，他年遗老寄雄名。"]},{"t":"晚酌胡守中湖亭同旷伯逵赋二首 其一","f":"七言律诗","c":["杨柳中间一草亭，石桥流水带回汀。","日含细雾明丹阁，雨逐凉风入翠棂。","萍底霞翻鱼漾鬣，竹间雪堕鹤梳翎。","楼台北渚催残景，烽火西山隐落星。"]},{"t":"晚酌胡守中湖亭同旷伯逵赋二首 其二","f":"七言律诗","c":["公子幽居湖水西，苇篱莎径踏春泥。","门前车马有谁到，池上犁锄还自携。","当槛柳枝垂叶短，出畦瓜蔓引花齐。","几时载酒从栖隐，日坐林阴听鸟啼。"]},{"t":"题珠林江口谢公庙与旷伯逵同赋","f":"七言律诗","c":["倒石源头野庙开，乱馀临眺独兴哀。","晚山隔岸云霞出，秋水满江凫雁来。","王气已消陈帝垒，客愁长绕越王台。","烽烟西北犹传警，击节酣歌首独回。"]},{"t":"秋日同旷掾史诸友会饮文溪道院时王子启不果至分韵得深字","f":"七言律诗","c":["夹径苍松十丈阴，落花仙馆昼沉沉。","林间风定晚烟白，江上月明秋水深。","梧叶小窗怜醉卧，芙蓉别院忆行吟。","南园王子来何晚，遥想吹笙度碧岑。"]},{"t":"奉和李府判行华九日游三华山","f":"七言律诗","c":["仙居远在三华顶，使节真成九日游。","别洞幡幢通上界，乱山烽火隔南州。","雕弓隐月啼猿晚，玉帐连云断雁秋。","闻说岩扉题句后，綵霞长护殿西头。"]},{"t":"陪虞管勾幼悦坐王子启南园竹林同赋","f":"七言律诗","c":["王子宅前千个竹，拂檐当户总萧萧。","土垣近出青相映，池水下通寒不凋。","上客频留苍玉佩，佳人时度紫鸾箫。","重寻载酒题诗处，记取龙湾第二桥。"]},{"t":"题友兰堂文丞相所书为子沂赋","f":"七言律诗","c":["友兰堂近古槐边，自昔王家表世贤。","晓露寒沾苍玉佩，秋风香满白云篇。","同心有待成三益，异代相看已百年。","相笔辉辉华匾在，好勤忠孝答皇天。"]},{"t":"罗明道载酒出江寺与旷伯逵痛饮经夕而去因共赋诗为别得江字","f":"七言律诗","c":["白发罗含偏好客，冲泥载酒出林矼。","来寻僧子烟霞地，醉卧山人云雾窗。","薜荔晴沙深晚径，芙蓉疏雨满秋江。","独怜此去青峰隔，城府何由更识庞。"]},{"t":"寄题麾羽轩","f":"七言律诗","c":["诸葛南征且未回，城头华构立崔嵬。","手麾白羽当轩坐，目送晴云度水来。","士马合围鱼贯出，旌旗分队雁行开。","极知裘带从容地，笳鼓时时送酒杯。"]},{"t":"送别虞管勾幼悦上赣迎候御史却还省中","f":"七言律诗","c":["郎官迎候绣衣归，十月清霜傍马飞。","省署总推容礼盛，边隅人报简书稀。","星横野戍乌啼早，日落江城雁影微。","千里严程当晏岁，驱驰莫遣壮心违。"]},{"t":"题草堂","f":"七言律诗","c":["胡君旧宅龙江上，五月清风一草堂。","雾隐松萝分晓荫，雨翻兰杜浥秋香。","连峰当户明书幌，流水交渠映笔床。","此日从公趋幕府，能忘高咏向沧浪。"]},{"t":"送萧子所之九江谒刘太守楚奇 其一","f":"七言律诗","c":["嗟子频年事远游，又携书剑谒邦侯。","浔阳乱后多公馆，樵舍新来有客舟。","野树尽含山雨润，江花初结渚云愁。","钓耕得似归来好，甘竹溪南有故丘。"]},{"t":"送萧子所之九江谒刘太守楚奇 其二 别淮南帅府戴照磨因使还乡复赴淮南","f":"七言律诗","c":["丞相提兵阙下来，淮南幕府一时开。","从军王粲应能赋，草檄相如独擅才。","万里关河通驿骑，五云楼观接蓬莱。","乡山寂寞兵尘里，愁绝征人奉使回。"]},{"t":"送萧子所之九江谒刘太守楚奇 其三 出西郊登山望城中感赋","f":"七言律诗","c":["双塔金光隐夕阴，孤城寒气日萧森。","山围叠嶂黄牛耸，水落回塘白石深。","凉日松杉空苒苒，秋风禾黍自沉沉。","东南千里兵尘合，愁绝春时怅望心。"]},{"t":"送萧子所之九江谒刘太守楚奇 其四 答定上人将归青原","f":"七言律诗","c":["上人伐木东乡去，城下渡江秋水深。","百里云山还独往，几时烟寺却重寻。","衲衣尚想南军送，贝叶应同西祖吟。","回首青原峰上月，相随应解照归心。"]},{"t":"送萧子所之九江谒刘太守楚奇 其五 送别陈宜归龙兴","f":"七言律诗","c":["豫章城阙倚晴虹，公子东归道路通。","表里湖山烽火后，东西楼观画图中。","谁家杨柳秋霜落，何处芙蓉暮雨红。","锦带吴钩看腾踏，临岐呼酒别青骢。"]}]};